export const wikiSummaries = {"brand:Q177054":{"text":"Burger King Corporation (сокр. BK) — американская компания, владелец глобальной сети заведений быстрого питания Burger King, специализирующейся на гамбургерах (главным образом на вопперах). Штаб-квартира располагается в округе Майами-Дейд (штат Флорида, США). Главными основателями сети Burger King являются Джеймс МакЛамор (James McLamore) и Дэвид…","title":"Burger King","revision":155641676,"qid":"Q177054","license":"CC BY-SA 4.0"},"Q4229068":{"text":"«Коляда́-теа́тр» — российский авторский драматический театр, основанный режиссёром и драматургом Николаем Колядой в Екатеринбурге в 2001 году. Зарегистрирован как некоммерческое партнёрство, существует за счёт собственных средств. Первой постановкой была «Персидская сирень» (2002) на малой сцене Свердловского драмтеатра. С 2004 года работал в арендованном…","title":"Коляда-театр","revision":155488482,"qid":"Q4229068","license":"CC BY-SA 4.0"},"Q4410152":{"text":"«Свердло́вский госуда́рственный академи́ческий теа́тр дра́мы» — российский драматический театр Свердловской области, основанный 2 октября 1930 года в Свердловске. С 1977 года носит почётное звание «академический». Награждён орденом Трудового Красного Знамени (1980). Полное наименование — «Государственное автономное учреждение культуры Свердловской области…","title":"Свердловский театр драмы","revision":156043164,"qid":"Q4410152","license":"CC BY-SA 4.0"},"Q4174311":{"text":"Екатеринбу́ргский госуда́рственный академи́ческий теа́тр о́перы и бале́та (также Ура́л О́пера Бале́т) — стационарный театр оперы и балета в Екатеринбурге, основанный в 1912 году. Здание построено по проекту инженера В. Н. Семёнова. Именно здесь 8 ноября (26 октября) 1917 года на экстренном заседании Екатеринбургского Совета рабочих и солдатских депутатов…","title":"Екатеринбургский театр оперы и балета","revision":155789330,"qid":"Q4174311","license":"CC BY-SA 4.0"},"Q4463552":{"text":"Свято-Троицкий собор (Рязановская церковь) — православный храм в Екатеринбурге, кафедральный собор Екатеринбургской митрополии и епархии Русской православной церкви. Здание представляет собой характерный образец культовой архитектуры русского классицизма первой половины XIX века.","title":"Троицкий собор (Екатеринбург)","revision":147333602,"qid":"Q4463552","license":"CC BY-SA 4.0"},"Q4504106":{"text":"Центральная городская библиотека им. А. И. Герцена — центральная муниципальная библиотека Екатеринбурга, расположена в исторической усадьбе Давыдовых в центре города (ул. Чапаева, 5). Относится к Муниципальному объединению библиотек Екатеринбурга (порядковый номер 1).","title":"Центральная городская библиотека имени А. И. Герцена (Екатеринбург)","revision":150769722,"qid":"Q4504106","license":"CC BY-SA 4.0"},"Q4306294":{"text":"Музей истории Екатеринбурга расположен в нескольких старинных зданиях в историческом центре города. Основное здание — так называемый Дом Качки на улице Карла Либкнехта, 26. В 1905 году здесь находилась нелегальная школа партийных пропагандистов, организованная Я. М. Свердловым. Музей был основан в июне 1939 года; открылся для посетителей 3 июля 1940 года…","title":"Музей истории Екатеринбурга","revision":155658838,"qid":"Q4306294","license":"CC BY-SA 4.0"},"Q4534623":{"text":"МБОУ ДО ДЮСШ «Юность» — спортивная школа, расположенная в Екатеринбурге. Школа готовит в том числе спортсменов в сборные команды России. Среди участников и выпускников спортшколы есть победители российских и международных соревнований, чемпионы Европы и мира, призёры Олимпийских игр.","title":"Юность (спортивная школа, Екатеринбург)","revision":146300790,"qid":"Q4534623","license":"CC BY-SA 4.0"},"Q4174318":{"text":"Екатеринбу́ргский музе́й изобрази́тельных иску́сств (сокр. ЕМИИ) — крупнейший художественный музей Урала, имеет четыре здания — главное расположено на берегу реки Исети в Екатеринбурге, в Историческом сквере, второе — на улице Вайнера, 11, где в 2021 году открылся культурно-выставочный центр «Эрмитаж-Урал», третье здание — Музей наивного искусства на ул.…","title":"Екатеринбургский музей изобразительных искусств","revision":153042863,"qid":"Q4174318","license":"CC BY-SA 4.0"},"Q4174320":{"text":"Екатеринбу́ргский муниципа́льный теа́тр ю́ного зри́теля — театр юного зрителя в Екатеринбурге. В афише представлены спектакли для всех возрастных групп. Девиз театра: «С детства — и на всю жизнь!»","title":"Екатеринбургский театр юного зрителя","revision":155789222,"qid":"Q4174320","license":"CC BY-SA 4.0"},"Q4174324":{"text":"Екатеринбу́ргский муниципа́льный теа́тр ку́кол — кукольный театр в Екатеринбурге, в репертуаре которого спектакли разных жанров для детей и взрослых.","title":"Екатеринбургский театр кукол","revision":150507457,"qid":"Q4174324","license":"CC BY-SA 4.0"},"Q4410151":{"text":"Свердло́вский госуда́рственный академи́ческий теа́тр музыка́льной коме́дии — музыкальный театр в Екатеринбурге, основан в 1933 году, с 1986 года — академический (после возвращения городу исторического имени театр не изменил своего названия). Один из ведущих театров России, многократный обладатель Национальной театральной премии «Золотая маска» (в том числе…","title":"Свердловский академический театр музыкальной комедии","revision":155487991,"qid":"Q4410151","license":"CC BY-SA 4.0"},"Q4211518":{"text":"Ка́мерный теа́тр Объединённого музе́я писа́телей Ура́ла — театр, в репертуаре которого классика и современная драматургия, спектакли, созданные по произведениям уральских писателей. Расположен в Литературном квартале Екатеринбурга на Пролетарской улице, 18.","title":"Камерный театр (Екатеринбург)","revision":155487804,"qid":"Q4211518","license":"CC BY-SA 4.0"},"Q4227893":{"text":"Колизе́й — кинотеатр в Екатеринбурге и старейший зал города. Располагается в здании первого городского театра, на проспекте Ленина, 43.","title":"Колизей (кинотеатр, Екатеринбург)","revision":155268482,"qid":"Q4227893","license":"CC BY-SA 4.0"},"Q16714939":{"text":"Художественный музей Эрнста Неизвестного — государственный музей в Екатеринбурге, посвященный творчеству скульптора и художника Эрнста Неизвестного, уроженца города. Это первый в России музей Э. Неизвестного, открытый в его 88-й день рождения, 9 апреля 2013 года, по инициативе ряда общественных деятелей Екатеринбурга и при поддержке губернатора…","title":"Художественный музей Эрнста Неизвестного","revision":147617110,"qid":"Q16714939","license":"CC BY-SA 4.0"},"Q19915379":{"text":"Свердловская государственная детская филармония — российская детская филармония. Входит в Союз концертных организаций России и ежегодно проводит порядка 250 концертов.","title":"Свердловская детская филармония","revision":154875351,"qid":"Q19915379","license":"CC BY-SA 4.0"},"Q24938043":{"text":"Музей архитектуры и дизайна УрГАХУ — расположен в Историческом сквере Екатеринбурга (на Плотинке) по адресу: ул. Горького, 4а.","title":"Музей архитектуры и дизайна УрГАХУ","revision":146659041,"qid":"Q24938043","license":"CC BY-SA 4.0"},"Q30890681":{"text":"Манеж «Урал» — крытый футбольный манеж в Екатеринбурге вместимостью 3 000 человек. Является частью спорткомплекса «Уралмаш», состоящего также из футбольного стадиона, баскетбольных, футбольных, волейбольных площадок, малого футбольного поля, большого легкоатлетического комплекса и лыжной базы. Кроме того, данная площадка входит в инфраструктуру Уральской…","title":"Урал (футбольный манеж)","revision":146838234,"qid":"Q30890681","license":"CC BY-SA 4.0"},"Q97344509":{"text":"Синара Центр — культурно-выставочный комплекс в Екатеринбурге, открытый в сентябре 2019 года в зданиях бывшего госпиталя Верх-Исетского завода.","title":"Синара Центр","revision":152270750,"qid":"Q97344509","license":"CC BY-SA 4.0"},"Q105486673":{"text":"Музей истории и археологии Урала — краеведческий музей в Екатеринбурге, представляющий экспозиции и выставки об истории Урала с древнейших времен до современности. Основан 10 января 1871 года Онисимом Клером. Входит в структуру Свердловского областного краеведческого музея. Расположен в здании Дома культуры имени Дзержинского Городка чекистов, куда…","title":"Музей истории и археологии Урала","revision":138059098,"qid":"Q105486673","license":"CC BY-SA 4.0"},"Q2491112":{"text":"«Салю́т» (Екатеринбургское муниципальное унитарное предприятие «Кинотеатр „Салют“», ранее Муниципальное унитарное предприятие «Детский специализированный Кинотеатр „Салют“») — один из старейших кинотеатров Екатеринбурга. Прекратил работу в феврале 2020 года. В январе 2025 года объявлено о создании на базе бывшего кинотеатра «Салют» молодёжного кластера,…","title":"Салют (кинотеатр, Екатеринбург)","revision":153650269,"qid":"Q2491112","license":"CC BY-SA 4.0"},"Q1381934":{"text":"Дом Ипа́тьева или Ипа́тьевский дом — несохранившийся частный дом в Екатеринбурге на углу улиц Карла Либкнехта и Клары Цеткин (ранее именовавшихся как Вознесенский проспект и Вознесенский переулок), в подвале которого в ночь с 16 на 17 июля 1918 года расстрелян вместе с семьёй и прислугой бывший российский император Николай II. В 1991 году найдены останки…","title":"Дом Ипатьева","revision":156245032,"qid":"Q1381934","license":"CC BY-SA 4.0"},"Q185568":{"text":"Благовещенский собор Казанского кремля (собор Благовещения Пресвятой Богородицы, тат. Ару хәбәр чиркәве) — православный храм в Казани, памятник русской архитектуры XVI века. С 1552 по 1918 год собор был кафедральным храмом Казанской епархии Русской церкви (в настоящее время кафедральным является Казанский собор Богородицкого монастыря), здесь веками…","title":"Благовещенский собор Казанского кремля","revision":155827838,"qid":"Q185568","license":"CC BY-SA 4.0"},"Q2389728":{"text":"«Ура́льская» — 4-я станция Екатеринбургского метрополитена, расположена на 1-й линии между станциями «Машиностроителей» и «Динамо». Станция открыта 23 декабря 1992 года в составе второго пускового участка Екатеринбургского метрополитена «Машиностроителей» — «Уральская». Станция расположена рядом с железнодорожным вокзалом и Северным автовокзалом.","title":"Уральская (станция метро)","revision":156020812,"qid":"Q2389728","license":"CC BY-SA 4.0"},"Q4365321":{"text":"Плоти́на Городско́го пруда́ на реке́ Исе́ть — гидротехническое сооружение на реке Исеть в Екатеринбурге. Построена в 1723 году с образованием пруда, снабжавшего водой Екатеринбургский завод. Впоследствии плотина многократно перестраивалась. Среди местных жителей за плотиной и прилегающей территорией Исторического сквера закрепилось название «Плотинка».…","title":"Плотина Городского пруда на реке Исеть","revision":154131833,"qid":"Q4365321","license":"CC BY-SA 4.0"},"brand:Q524757":{"text":"Kentucky Fried Chicken (с англ. — «Жареная курица из Кентукки»), аббрев. KFC («Кей-эф-си») — международная сеть ресторанов общественного питания, специализирующаяся на блюдах из курятины. Штаб-квартира компании располагается в городе Луисвилле, Кентукки. KFC — вторая по торговому обороту сеть кафе в мире, уступающая лишь компании McDonald's. По…","title":"KFC","revision":156312066,"qid":"Q524757","license":"CC BY-SA 4.0"},"brand:Q3442874":{"text":"«Ро́стикс» (Rostic’s) — российская сеть ресторанов быстрого питания, специализирующаяся на блюдах из курицы. Основана предпринимателем Ростиславом Ордовским-Танаевским Бланко, первая точка открылась в 1993 году в Москве. В 2005 году сеть заключила соглашение о стратегическом партнёрстве с американской корпорацией Yum! Brands, владельцем бренда…","title":"Ростикс","revision":155488180,"qid":"Q3442874","license":"CC BY-SA 4.0"},"Q4165394":{"text":"Дом Севастья́нова (также в разные периоды здание Окружного суда, Дом профсоюзов, Дворец Труда) — здание в Екатеринбурге, расположенное на берегу городского пруда по адресу проспект Ленина, 35. Одна из наиболее узнаваемых достопримечательностей города. Уникальное в архитектуре Урала здание в формах эклектики XIX века, носит имя Николая Ивановича…","title":"Дом Севастьянова","revision":154937047,"qid":"Q4165394","license":"CC BY-SA 4.0"},"Q4343452":{"text":"Памятник воинам Уральского добровольческого танкового корпуса — памятник на Привокзальной площади города Екатеринбурга, открытый 22 февраля 1962 года. Монумент посвящён героизму воинов Уральского добровольческого танкового корпуса. Со временем место «под варежкой» пользуется популярностью среди встречающих и отъезжающих, именно здесь они договариваются о…","title":"Памятник воинам Уральского добровольческого танкового корпуса","revision":154651148,"qid":"Q4343452","license":"CC BY-SA 4.0"},"Q4114839":{"text":"Вознесе́нская го́рка — историческое место Екатеринбурга, представляющее собой возвышенность в центре города. Названо по имени Вознесенской церкви, расположенной в верхней точке холма.","title":"Вознесенская горка","revision":154940751,"qid":"Q4114839","license":"CC BY-SA 4.0"},"Q4343382":{"text":"Памятник Василию Татищеву и Вильгельму де Геннину расположен в Екатеринбурге на Площади Труда.","title":"Памятник Татищеву и де Геннину","revision":154779396,"qid":"Q4343382","license":"CC BY-SA 4.0"},"Q4314821":{"text":"ГБУК РТ «Национа́льная библиоте́ка Респу́блики Татарста́н» (тат. Татарстан Республикасы Милли китапханәсе) — главное книгохранилище Татарстана для национальных, республиканских, русских и зарубежных изданий. Она содержит более трех миллионов двухсот тысяч документов, в том числе более 100 тысяч документов на татарском языке и еще 100 тысяч на иностранных…","title":"Национальная библиотека Республики Татарстан","revision":146422618,"qid":"Q4314821","license":"CC BY-SA 4.0"},"Q4315032":{"text":"Национальный музей Республики Татарстан (тат. Татарстан Республикасы Милли музее) — научно-исследовательское и культурно-образовательное учреждение, ведущий музейный центр Татарстана и один из крупнейших культурно-исторических музеев в Поволжье.","title":"Национальный музей Республики Татарстан","revision":154609626,"qid":"Q4315032","license":"CC BY-SA 4.0"},"Q4291705":{"text":"Ме́теого́рка (прежние названия: Плешивая, Обсерваторская горка) — историческая местность в Екатеринбурге, выполняет функцию городской смотровой площадки. Метеогорка расположена в левобережной части города между улицами Декабристов (южный склон) и Народной Воли (северный склон).","title":"Метеогорка","revision":146476668,"qid":"Q4291705","license":"CC BY-SA 4.0"},"brand:Q55662627":{"text":"Coffee Like — франчайзинговая сеть формата «кофе с собой» в России и странах СНГ, основанная в 2013 году. Торговые точки представлены в 136 городах.","title":"Coffee Like","revision":154818188,"qid":"Q55662627","license":"CC BY-SA 4.0"},"brand:Q112406961":{"text":"«Вкусно — и точка» — российская сеть предприятий быстрого питания, созданная на базе сети McDonald’s после её закрытия в России в связи со вторжением России на Украину и полной продажи всего российского бизнеса предпринимателю Александру Говору. Открытие первых ресторанов сети состоялось 12 июня 2022 года.","title":"Вкусно — и точка","revision":156345178,"qid":"Q112406961","license":"CC BY-SA 4.0"},"Q114023393":{"text":"Парк Турбомото́рного заво́да расположен в Орджоникидзевском районе Екатеринбурга, в прямоугольнике, ограниченном улицами Бабушкина (с запада), Стачек (с востока) и Фронтовых Бригад (с юга). С севера парк ограничен площадкой стадиона «Изумруд». Парк существует с 1930-х годов, занимает площадь в 4,4 га и является охраняемым памятником природы России.","title":"Парк Турбомоторного завода","revision":140013753,"qid":"Q114023393","license":"CC BY-SA 4.0"},"ekb-obd94b204fc34":{"text":"Свердло́вская киносту́дия — советская, а позже российская киностудия в Екатеринбурге, была создана 9 февраля 1943 года. Всего на Киностудии снято более 200 художественных и 500 документальных картин, сотни научно-популярных фильмов, около 100 мультипликационных работ.","title":"Свердловская киностудия","revision":151967640,"qid":"Q1971240","license":"CC BY-SA 4.0"},"ekb-o0724a8618b8f":{"text":"Па́мятник клавиату́ре — первая в Екатеринбурге ленд-арт-скульптура, посвящённая компьютерной клавиатуре. Открыта 5 октября 2005 года. Автор — Анатолий Вяткин.","title":"Памятник клавиатуре","revision":155591107,"qid":"Q2037145","license":"CC BY-SA 4.0"},"ekb-o3772ab2bc3df":{"text":"«Литерату́рная жизнь Ура́ла XIX ве́ка» — литературный музей в городе Екатеринбурге. Входит в состав Объединённого музея писателей Урала.","title":"Литературная жизнь Урала XIX века","revision":147590425,"qid":"Q4306075","license":"CC BY-SA 4.0"},"ekb-od97e295e5468":{"text":"Доходный дом купца Чувильдина (косой дом) — бывший доходный дом в Екатеринбурге, принадлежавший купцу Василию Ивановичу Чувильдину. Является памятником истории и архитектуры регионального (областного) значения с 2015 года. Входит в туристический маршрут «Красная линия» Екатеринбурга.","title":"Доходный дом купца Чувильдина","revision":154981312,"qid":"Q27921892","license":"CC BY-SA 4.0"},"kzn-o90140f3efe0e":{"text":"Казанское театральное училище имени Ш.Х. Биктемирова — государственное автономное образовательное учреждение среднего профессионального образования Республики Татарстан расположенное в Казани. Одно из старейших художественных учебных заведений Российской Федерации. Постановлением Кабинета Министров Республики Татарстан № 203 от 29.03.2024 училищу…","title":"Казанское театральное училище","revision":155899389,"qid":"Q20583105","license":"CC BY-SA 4.0"},"kzn-o9e5e77e4a2ce":{"text":"Казанский зооботанический сад (тат. Казан зооботаник бакчасы) — старейший зоопарк в России и один из старейших зооботсадов в Европе. Находится в центре, Вахитовском и Приволжском районах Казани между улицей Хади Такташа и протокой между озёрами Нижний (Ближний) и Средний (Дальний) Кабан, а также у начала озера Средний Кабан.","title":"Казанский зооботанический сад","revision":153441910,"qid":"Q2034194","license":"CC BY-SA 4.0"},"kzn-o3fe93f499bef":{"text":"Парк Тысячелетия — парк в Вахитовском районе Казани. Встречается также альтернативное название парка — «парк Миллениум».","title":"Парк Тысячелетия","revision":148422744,"qid":"Q4345271","license":"CC BY-SA 4.0"},"kzn-o2d862e613bf3":{"text":"Литературный музей Габдуллы Тукая (тат. Габдулла Тукайның әдәби музее) — мемориальный музей, расположенный в здании дома Шамиля по улице Габдуллы Тукая, 74 в городе Казани. Является филиалом Национального музея Республики Татарстан.","title":"Литературный музей Габдуллы Тукая","revision":154773658,"qid":"Q42173063","license":"CC BY-SA 4.0"},"kzn-oad0d3c0bd647":{"text":"Дом Зинаиды Николаевны Ушковой (тат. Зинаида Ушкова йорты) — здание в Казани, перестроенное в начале XX века в эклектичном стиле. Дом Ушковой является достопримечательностью центра города, объектом культурного наследия федерального значения. С 1919 по 2020 год служил центральным зданием главной республиканской библиотеки.","title":"Дом Ушковой","revision":155191571,"qid":"Q4165421","license":"CC BY-SA 4.0"},"kzn-o8fdc2b9d925e":{"text":"Алексе́евский райо́н (тат. Алексеевск районы) — административно-территориальная единица и муниципальное образование (муниципальный район) в составе Республики Татарстан Российской Федерации. Находится в центральной части региона, на левом берегу реки Кама. Административный центр — посёлок городского типа Алексеевское. Район был образован 10 августа 1930…","title":"Алексеевский район (Татарстан)","revision":155598088,"qid":"Q2603517","license":"CC BY-SA 4.0"},"kzn-ob66dfcfb1bb5":{"text":"Фуксовский сад (тат. Фукс бакчасы) — сквер в Вахитовском районе Казани, названный в честь ректора Казанского университета Карла Фукса.","title":"Фуксовский сад","revision":143912156,"qid":"Q4493322","license":"CC BY-SA 4.0"},"msk-odc0c4a6e5f68":{"text":"Са́ввинское подво́рье в Москве — подворье звенигородского Саввино-Сторожевского монастыря; построено в 1907 году по проекту архитектора Ивана Кузнецова в неорусском стиле с элементами модерна и барокко (внутренние дворики).","title":"Саввинское подворье","revision":149497024,"qid":"Q4403757","license":"CC BY-SA 4.0"},"msk-o49a0728e36df":{"text":"Музей Вади́ма Сиду́ра — музей современной скульптуры на востоке Москвы, расположенный в Новогирееве. Был основан в 1989 году, с 2011 по 2017-й входил в состав музейно-выставочного объединения «Манеж». С 2018 года является филиалом Московского музея современного искусства. Основная экспозиция состоит из работ художника Вадима Сидура разных периодов…","title":"Музей Вадима Сидура","revision":151387313,"qid":"Q48953878","license":"CC BY-SA 4.0"},"msk-of3df2a56700c":{"text":"Карти́нная галере́я Ильи́ Глазуно́ва (Государственное бюджетное учреждение культуры города Москвы «Московская государственная картинная галерея народного художника СССР Ильи Глазунова») — художественная галерея народного художника СССР Ильи Глазунова, расположенная по адресу улица Волхонка, дом 13. Образована 31 августа 2004 года.","title":"Картинная галерея Ильи Глазунова","revision":156137792,"qid":"Q4303892","license":"CC BY-SA 4.0"},"msk-o419ccb1bcd91":{"text":"Особняк Шехтеля на Большой Садовой — городская усадьба, построенная русским архитектором Федором Осиповичем Шехтелем в 1910 году. Здание известно как третий и последний дом, который он построил для себя. Находится по адресу: Москва, Большая Садовая улица, дом 4, строение 1. После революции особняк занял Роберт Эйдеман — советский деятель. В начале 1940…","title":"Особняк Шехтеля на Большой Садовой","revision":153641854,"qid":"Q19915792","license":"CC BY-SA 4.0"},"msk-o6c8b43b7601a":{"text":"Галерея Беляево — государственное бюджетное учреждение культуры города Москвы Государственный выставочный зал «Галерея „Беляево“». Многофункциональный культурно-просветительский центр.","title":"Галерея Беляево","revision":146675914,"qid":"Q28052706","license":"CC BY-SA 4.0"},"msk-o4720492c095e":{"text":"Дом-музе́й Бори́са Пастерна́ка — мемориальный музей Бориса Пастернака, расположенный на бывшей даче писателя в Переделкино. В этом здании Пастернак проживал с 1939 по 1960 год, после его смерти в доме был организован неофициальный общественный музей памяти писателя. В 1990 году по инициативе друзей и родственников Пастернака музей получил официальный…","title":"Дом-музей Бориса Пастернака","revision":154996654,"qid":"Q60852043","license":"CC BY-SA 4.0"},"msk-o595d29b9ae93":{"text":"Клуб Алексея Козлова (англ. Kozlov Club) — российский концертный клуб с четырьмя независимыми сценами, самый большой джазовый клуб России. Основан в 2012 году в Москве, в 2017 году сменил место дислокации и с этого момента был расположен на улице Маросейка, дом 9/2, в помещении ресторанного комплекса «Left Bank» (ближайшие станции метро — «Китай-Город»,…","title":"Клуб Алексея Козлова","revision":155323045,"qid":"Q43441631","license":"CC BY-SA 4.0"},"msk-o120d5ca3028e":{"text":"Федеральное государственное бюджетное учреждение культуры «Российский национальный музей музыки» (Музей музыки), музейное объединение, включающее в себя филиалы по всей Москве. Главное здание расположено на улице Фадеева, д. 4. В начале 1995 года указом Президента Российской Федерации музей был включён в Государственный свод особо ценных объектов…","title":"Российский национальный музей музыки","revision":155659074,"qid":"Q3329181","license":"CC BY-SA 4.0"},"msk-o165b438df1d1":{"text":"Уса́дьба «Сви́блово» — бывшая дворянская усадьба, расположенная в одноимённом районе на северо-востоке Москвы, близ Останкино на высоком берегу Яузы.","title":"Свиблово (усадьба)","revision":156107705,"qid":"Q3506346","license":"CC BY-SA 4.0"},"msk-o020b6e0e3f2c":{"text":"Це́нтр Гиляро́вского — филиал музейного объединения «Музей Москвы», основанный в 2017 году к 162-летию со дня рождения беллетриста Владимира Гиляровского и 121-летию Музея Москвы. Центр представляет собой открытое выставочное пространство без постоянной экспозиции, в котором помимо временных выставок проходят кинопоказы, а также работает лекторий.","title":"Центр Гиляровского","revision":154185715,"qid":"Q60851335","license":"CC BY-SA 4.0"},"msk-ob031ecffc526":{"text":"Филармония-2 — концертный комплекс Московской государственной академической филармонии, расположенный на Юго-Западе Москвы в Олимпийской деревне.","title":"Филармония-2","revision":153934552,"qid":"Q60851844","license":"CC BY-SA 4.0"},"msk-o36f138dc6ee0":{"text":"Пала́ты Аве́ркия Кири́ллова — здание в Москве, редкий образец частного жилого строительства второй половины XVII — самого начала XVIII веков. Находится по адресу: Берсеневская набережная, дом № 20 (ныне в здании расположен Российский научно-исследовательский институт культурного и природного наследия имени Д. С. Лихачёва).","title":"Палаты Аверкия Кириллова","revision":152214970,"qid":"Q4342475","license":"CC BY-SA 4.0"},"msk-od7307d0af0dc":{"text":"Всеросси́йский музе́й декорати́вного иску́сства — музей декоративно-прикладного искусства, основанный в 1981 году. Расположен в дворцовом комплексе XVIII века, построенном графом Иваном Остерманом. По состоянию на 2018-й, музейная коллекция состоит из более чем 120 тысяч предметов и включает в себя изделия из художественного металла, камня, стекла и ткани.","title":"Всероссийский музей декоративного искусства","revision":153576813,"qid":"Q4127499","license":"CC BY-SA 4.0"},"msk-od637aecfe105":{"text":"Храм Спа́са Преображе́ния на Болва́новке — православный храм в районе Замоскворечье Центрального административного округа Москвы. Принадлежит к Москворецкому благочинию Московской епархии Русской православной церкви.","title":"Храм Спаса Преображения на Болвановке","revision":142669891,"qid":"Q4501032","license":"CC BY-SA 4.0"},"msk-oef267e3d23e7":{"text":"Центр документального кино (ЦДК) — некоммерческий социальный проект, направленный на популяризацию документального кино в России. Открывшийся в июне 2013 года независимый кинотеатр неигровых фильмов ЦДК, стал первым подобным центром в стране и, по состоянию на 2019-й, оставался единственным.","title":"Центр документального кино","revision":154185860,"qid":"Q110319213","license":"CC BY-SA 4.0"},"msk-oedb28ff1b8ef":{"text":"Музей истории евреев в России — частный музей, основанный в 2011 году в Москве бизнесменом и общественным деятелем Сергеем Устиновым, один из крупнейших еврейских музеев на постсоветском пространстве. В своей деятельности музей стремится реконструировать целостную картину еврейской жизни на территории Российской империи и СССР во всём многообразии её…","title":"Музей истории евреев в России","revision":153057370,"qid":"Q109750310","license":"CC BY-SA 4.0"},"msk-oaba673c70a70":{"text":"Музей предпринимателей, меценатов и благотворителей — негосударственный музей и исследовательский, учебный и просветительский центр по истории российского предпринимательства, меценатства и благотворительности. Основан в 1991 году в Москве при активном участии потомков предпринимателей дореволюционной России: Морозовых, Рябушинских, Прохоровых и других.","title":"Музей предпринимателей, меценатов и благотворителей","revision":150297539,"qid":"Q111418085","license":"CC BY-SA 4.0"},"msk-o6a8cc763a9b3":{"text":"Дюссельдорфский парк (прежнее название — Парк 10-го микрорайона Марьинского Парка) — парк в Юго-Восточном округе Москвы, в районе Марьино. Расположен на пересечении Перервинского бульвара, улиц Белореченской и Новомарьинской.","title":"Дюссельдорфский парк","revision":155103239,"qid":"Q4172358","license":"CC BY-SA 4.0"},"msk-oc795fd28d952":{"text":"Старый Английский двор — архитектурно-историческая достопримечательность Москвы (ул. Варварка, 4А). Памятник гражданской архитектуры XV—XVII веков, резиденция английской торговой Московской компании, а во время посольских миссий — Английский посольский дом. Считается первым официальным представительством иностранной державы, сохранившимся в Москве. Здание,…","title":"Старый Английский двор","revision":154285100,"qid":"Q4441169","license":"CC BY-SA 4.0"},"msk-o25aa1103b074":{"text":"Парк Дру́жбы или парк «Дружба» — городской парк на территории района Левобережный на севере Москвы. Назван и основан в честь VI Всемирного фестиваля молодёжи и студентов 1957 года. Разбит в свободном пейзажном стиле, изначальная планировка отражала символику фестиваля — дружбу народов пяти континентов. Парк несколько раз расширяли и благоустраивали, в нём…","title":"Парк Дружбы","revision":150471887,"qid":"Q4345224","license":"CC BY-SA 4.0"},"msk-ofb4c2b175ca1":{"text":"Политехни́ческий музе́й (Полите́х) — один из старейших научно-технических музеев мира, расположен в Москве на Новой площади. Образован в 1872 году по инициативе Общества любителей естествознания, антропологии и этнографии при активном участии профессоров Московского университета Григория Щуровского, Анатолия Богданова и Августа Давидова. В основу фондов…","title":"Политехнический музей","revision":154327005,"qid":"Q1577987","license":"CC BY-SA 4.0"},"msk-o2964c6765aa7":{"text":"Храм Успения Пресвятой Богородицы в Архангельском-Тюрикове — православный храм в Северном районе Москвы. Принадлежит к Сергиевскому благочинию Московской епархии Русской православной церкви. Находится в Архангело-Тюриковском переулке.","title":"Храм Успения Пресвятой Богородицы в Архангельском-Тюрикове","revision":147582881,"qid":"Q4501075","license":"CC BY-SA 4.0"},"msk-o51e8cfec706e":{"text":"Особня́к Рябуши́нского — городская усадьба, построенная архитектором Фёдором Шехтелем для предпринимателя Степана Рябушинского в 1900—1903 годах. Является одним из наиболее репрезентативных примеров раннего модерна в русской архитектуре. С 1965 года в здании располагается музей-квартира Горького.","title":"Особняк С. П. Рябушинского","revision":153641848,"qid":"Q4338224","license":"CC BY-SA 4.0"},"msk-ob4f723927ad9":{"text":"Парк Северного речного вокзала, Парк Северного Речного вокзала — парк в Левобережном районе Северного административного округа Москвы. Расположен вдоль Ленинградского шоссе у Химкинского водохранилища. В парке находится здание Северного речного вокзала. В основе планировки — три аллеи, идущие параллельно шоссе и одна перпендикулярно. Площадь парка вместе…","title":"Парк Северного речного вокзала","revision":146626124,"qid":"Q20279500","license":"CC BY-SA 4.0"},"msk-o2bf038f218e7":{"text":"Totibadze Gallery — московская галерея современного искусства, основанная Константином и Георгием Тотибадзе, Георгием Ташкером и Мариной Цурцумия 28 января 2016 года. Располагается на территории Центра современного искусства «Винзавод».","title":"Totibadze Gallery","revision":155000345,"qid":"Q50191940","license":"CC BY-SA 4.0"},"msk-o93c29069b7be":{"text":"Дом Ярошенко — жилое здание в центре Москвы, в Подколокольном переулке. Объект культурного наследия регионального значения, внесён в реестр под названием: «Торговые ряды П. В. Степанова — ночлежный дом Е. П. Ярошенко. 1860-е — 1880-е гг., палаты стольника Е. И. Бутурлина. 1660-е гг.» Дом Ярошенко находится на исторической территории Белого города урочища…","title":"Дом Ярошенко","revision":152217066,"qid":"Q13668656","license":"CC BY-SA 4.0"},"msk-o2a607aa29b9e":{"text":"Театр Терезы Дуровой (ранее — Московский театр клоунады под руководством Терезы Дуровой (1993—2010), Театриум на Серпуховке под руководством Терезы Дуровой (2010—2020 гг.)) — учреждение культуры г. Москвы. Официальное полное (зарегистрированное) наименование — Государственное бюджетное учреждение культуры города Москвы «Театриум на Серпуховке под…","title":"Театр Терезы Дуровой","revision":152731852,"qid":"Q120262590","license":"CC BY-SA 4.0"},"msk-o0cb9587e7421":{"text":"Музей землеведения МГУ — учебный музей по наукам о Земле и землеведению, для студентов МГУ и организованных групп посетителей. Является подразделением МГУ. Экспонаты музея охватывают науки географического и геологического цикла. Экспозиция также раскрывает историю развития естественнонаучных знаний и представлений о Земле. В музее постоянно проводятся…","title":"Музей землеведения МГУ","revision":152603147,"qid":"Q21641924","license":"CC BY-SA 4.0"},"msk-o1f929ad01990":{"text":"Староки́рочный переу́лок (до 1922 Ки́рочный переу́лок, Ста́рый Ки́рочный переу́лок) — переулок в бывшей Немецкой слободе, нынешнем Басманном районе Москвы. Проходит от Бауманской улицы до Лефортовской площади, нумерация домов — от Бауманской улицы. К западу от Бауманской улицы трассу Старокирочного переулка продолжает Аптекарский переулок.","title":"Старокирочный переулок","revision":151425979,"qid":"Q4440421","license":"CC BY-SA 4.0"},"msk-oeba77c79593b":{"text":"«Мосфи́льм» — советская и российская киностудия, основанная в 1924 году. Одна из крупнейших, на базе которой осуществляется производство большей части российской кино-, теле- и видеопродукции. Расположена на Воробьёвых горах, площадь территории составляет 34,5 га. По состоянию на 2020 год на киностудии было создано более 2500 полнометражных кинофильмов.…","title":"Мосфильм","revision":155380765,"qid":"Q141336","license":"CC BY-SA 4.0"},"msk-o47c0e64f3d4e":{"text":"Музей морского и речного флота — музей истории российского мореплавания и морского и речного флота. Расположен в центре Москвы на улице Большая Ордынка, дом 19, строение 1. С 2005 года музей находится в ведении Федерального агентства морского и речного транспорта.","title":"Музей морского флота","revision":153082221,"qid":"Q28791841","license":"CC BY-SA 4.0"},"msk-ofa871313a50b":{"text":"Джамгаровский парк (также парк «У Джамгаровского пруда») — парк в Лосиноостровском районе на северо-востоке Москвы. Находится у Джамгаровского пруда (Нижний Джамгаровский пруд) на реке Ичке. С запада парк ограничен Джамгаровской улицей, а с юга — Стартовой. Общая площадь — около 38 га, из которых 13,5 га — площадь пруда. Парк относится к ГАУК города Москвы…","title":"Джамгаровский парк","revision":146918569,"qid":"Q111286960","license":"CC BY-SA 4.0"},"msk-ob98b7da7ceb9":{"text":"Джамгаровский парк (также парк «У Джамгаровского пруда») — парк в Лосиноостровском районе на северо-востоке Москвы. Находится у Джамгаровского пруда (Нижний Джамгаровский пруд) на реке Ичке. С запада парк ограничен Джамгаровской улицей, а с юга — Стартовой. Общая площадь — около 38 га, из которых 13,5 га — площадь пруда. Парк относится к ГАУК города Москвы…","title":"Джамгаровский парк","revision":146918569,"qid":"Q111286960","license":"CC BY-SA 4.0"},"msk-o77da47e08cce":{"text":"Особня́к Ке́кушевой (дом Смецкого/Сми́тского) — московское здание, возведённое архитектором Львом Кекушевым в начале XX века для своей семьи. Формально участок принадлежал жене архитектора Анне Ионовне Кекушевой, но вскоре был продан. О доме существуют некоторые легенды и недостоверные сведения. Неизвестность связана во многом с судьбой самого Кекушева.…","title":"Особняк Кекушевой","revision":154195654,"qid":"Q19753357","license":"CC BY-SA 4.0"},"msk-o9fafb3eef971":{"text":"Московский дом композиторов (МДК) — концертная площадка Союза композиторов, а также место проведения музыкальных фестивалей, конференций и конкурсов. В МДК выступали симфонические оркестры под руководством Евгения Светланова, Кирилла Кондрашина, Геннадия Рождественского; струнные квартеты имени Бородина и Бетховена; солисты Святослав Рихтер, Мстислав…","title":"Московский дом композиторов","revision":147342285,"qid":"Q21641853","license":"CC BY-SA 4.0"},"msk-o261aab110506":{"text":"Дом В. В. Маяковского в переулке Маяковского — дом, в котором проживал Владимир Маяковский с Лилей и Осипом Брик в период с 1926 по 1930 год. Прежний адрес — Гендриков переулок 15/13 (переименован в переулок Маяковского в 1935 году). Объект культурного наследия федерального значения.","title":"Дом Маяковского в переулке Маяковского","revision":155534280,"qid":"Q20018462","license":"CC BY-SA 4.0"},"msk-o87ea52227c80":{"text":"Мемориа́льный дом-музе́й акаде́мика Серге́я Королёва — московский мемориальный музей, посвящённый жизни и деятельности Главного конструктора космической техники Сергея Королёва. Официальное открытие состоялось в 1975 году по инициативе жены Нины Ивановны Королёвой, передавшей во владение музея около 19 000 предметов, ставших экспонатами. Учреждение…","title":"Мемориальный дом-музей академика С. П. Королёва","revision":147200368,"qid":"Q4290219","license":"CC BY-SA 4.0"},"msk-o8aadf23039be":{"text":"Старосырово — деревня в Новомосковском административном округе Москвы (до 1 июля 2012 года в составе Подольского района Московской области). Входит в состав поселения Рязановское.","title":"Старосырово","revision":153346302,"qid":"Q4440700","license":"CC BY-SA 4.0"},"msk-of96f9d8573ce":{"text":"Большо́й Каре́тный переу́лок (ранее в XVII—XVIII веках Тележный ряд, до 1922 — Большой Спасский переулок, в 1956—1993 — улица Ермоловой) — переулок в Тверском районе Центрального административного округа города Москвы. Проходит от 2-го Колобовского переулка до Садовой-Самотёчной улицы. Нумерация домов ведётся от 2-го Колобовского переулка.","title":"Большой Каретный переулок","revision":146248659,"qid":"Q4092652","license":"CC BY-SA 4.0"},"msk-o83f4b5f93b2e":{"text":"Ботанический сад ВИЛАР — ботанический сад в Москве при Всероссийском НИИ лекарственных и ароматических растений. Расположен на юге города в районе Северное Бутово. Основан в 1951 году. Площадь сада составляет около 30 га (или 45 га, считая территорию института). Ботанический сад ВИЛАР имеет статус особо охраняемой природной территории федерального значения.","title":"Ботанический сад ВИЛАР","revision":155969895,"qid":"Q55438181","license":"CC BY-SA 4.0"},"msk-oa7f29e35a63b":{"text":"Эта статья про Центральный дом культуры железнодорожников, вы могли искать статью про Центральный дом детей железнодорожников. Центральный дом культуры железнодорожников (ЦДКЖ) — театрально-концертный зал в Красносельском районе Москвы, входящий в комплекс Казанского вокзала. Основан в 1927 году. Центральный дом культуры железнодорожников находится по…","title":"Центральный дом культуры железнодорожников","revision":153632874,"qid":"Q20011384","license":"CC BY-SA 4.0"},"msk-oef476862407b":{"text":"Гончаро́вский парк — небольшой парк в северной части Москвы, филиал Лианозовского парка.","title":"Гончаровский парк","revision":152598120,"qid":"Q107616872","license":"CC BY-SA 4.0"},"msk-o8bf7e3ac7ffe":{"text":"Парк 70-летия Победы — парк на юго-западе Москвы, расположенный на территории муниципального округа Черёмушки. Площадь парка — 13,4 га.","title":"Парк 70-летия Победы","revision":146675589,"qid":"Q28666774","license":"CC BY-SA 4.0"},"msk-o6807a23a7bb8":{"text":"Берсе́невская на́бережная — набережная на правом берегу Москвы-реки в районе Якиманка Центрального административного округа города Москвы. Проходит от стрелки острова до Большого Каменного моста. Выходит на улицу Серафимовича.","title":"Берсеневская набережная","revision":150157948,"qid":"Q4085185","license":"CC BY-SA 4.0"},"msk-obb24552bf185":{"text":"Чистопру́дный бульва́р — бульвар в Басманном районе Центрального административного округа города Москвы. Проходит от площади Мясницкие Ворота до площади Покровские Ворота, нумерация ведётся от Мясницких ворот. На бульваре расположены Чистые пруды (фактически, пруд — один). Чистопрудный бульвар — самый большой по площади и второй по протяжённости (после…","title":"Чистопрудный бульвар","revision":154749988,"qid":"Q2922062","license":"CC BY-SA 4.0"},"msk-o3144cd1ed774":{"text":"Детский парк «Фестивальный», встречается также Детский парк «Марьина роща» — парк в Центральном административном округе Москвы, в Мещанском районе, общей площадью 12,6 га.","title":"Фестивальный парк","revision":153931905,"qid":"Q4483274","license":"CC BY-SA 4.0"},"msk-oe6b3b8aaecd3":{"text":"Алту́фьево — село, существовавшее на севере от Москвы, на нынешней территории районов Лианозово и Бибирево.","title":"Алтуфьево (село)","revision":146474378,"qid":"Q19906994","license":"CC BY-SA 4.0"},"msk-o9a03d8330238":{"text":"Теа́тр С. А. Д. (Театр Содружества Артистов Драмы) — московский драматический театр, образованный в 2011 году. Основатель и руководитель театра — Кирилл Рубцов.","title":"Театр С.А.Д.","revision":147813979,"qid":"Q16705088","license":"CC BY-SA 4.0"},"msk-o5327861d2bf2":{"text":"Росгосцирк — российская федеральная государственная организация, управляющая цирковой деятельностью, в её подчинение стационарные цирки и цирки-шапито. Росгосцирк имеет поддержку из государственного бюджета и осуществляет внутрироссийскую и зарубежную гастрольную деятельность. В существующем виде создан постановлением Правительства Российской Федерации от…","title":"Росгосцирк","revision":156215283,"qid":"Q4397743","license":"CC BY-SA 4.0"},"msk-o2d04c0ec1159":{"text":"Ело́ховский прое́зд — небольшая улица в центре Москвы в Басманном районе между Елоховской площадью и Нижней Красносельской улицей. Здесь расположен Елоховский собор, кафедральный собор Московского Патриархата.","title":"Елоховский проезд","revision":154520664,"qid":"Q4175105","license":"CC BY-SA 4.0"},"msk-o20615e8c1d08":{"text":"Ильинский сквер (ранее известный как Лубянский сквер) — сквер в центре Москвы, расположен внутри прямоугольника, образованного проезжими частями площади Ильинских Ворот, Старой и Славянской площадей, и Лубянского проезда. Является памятником садово-паркового искусства.","title":"Ильинский сквер","revision":148444199,"qid":"Q21639907","license":"CC BY-SA 4.0"},"msk-o85a57ec9f593":{"text":"Сквер Бунина — сквер в Центральном административном округе Москвы между Борисоглебским и Большим Ржевским переулками, выходящий на Поварскую улицу. Сквер образовался после сноса особняков XIX века в начале 1980-х годов и получил название в 2015 году — в год 145-летия со дня рождения поэта и писателя Ивана Бунина.","title":"Сквер Бунина","revision":150429768,"qid":"Q48940629","license":"CC BY-SA 4.0"},"msk-o7ba239be2b7c":{"text":"Но́вая Третьяко́вка — второе здание Третьяковской галереи, расположенное в Москве на Крымском Валу в парке «Музеон». Построено к 1983 году по проекту архитекторов Юрия Шевердяева и Николая Сукояна в стиле советский модернизм. Открытие первых выставок состоялось в 1986 году, в музее представлены художественные направления XX и XXI веков: русский авангард,…","title":"Новая Третьяковка","revision":154818432,"qid":"Q55654333","license":"CC BY-SA 4.0"},"msk-ob0f9b28c5eba":{"text":"Электродепо́ «Се́верное» (ТЧ-1) — старейшее электродепо Московского метрополитена, обслуживающее Сокольническую линию с 26 апреля 1935 года. Расположено на территории Красносельского района Центрального административного округа Москвы. Первый поезд был выдан из депо 15 октября 1934 года. Регулярное пассажирское движение по Сокольнической линии начато 15…","title":"Северное (электродепо, Москва)","revision":154913788,"qid":"Q4412170","license":"CC BY-SA 4.0"},"msk-oe44cf21bd21e":{"text":"Княжнина́ у́лица (официально — у́лица Княжнина́; ранее — Княжни́н переу́лок, Кня́жевский переу́лок, Кня́зевский переу́лок, Бабары́кин переу́лок, Ву́льфов (Гу́льфов) переу́лок) — улица в Юго-Восточном административном округе города Москвы на территории района Лефортово.","title":"Улица Княжнина","revision":155525825,"qid":"Q4472475","license":"CC BY-SA 4.0"},"msk-odff77f596032":{"text":"Храм Димитрия Солунского, что у Тверских ворот — утраченный православный храм, находившийся в Москве, в Белом Городе, на Страстной площади (ныне Пушкинская площадь). Разрушен коммунистами в 1934 году.","title":"Храм Димитрия Солунского у Тверских ворот","revision":156249776,"qid":"Q1814646","license":"CC BY-SA 4.0"},"msk-o53b4a0306949":{"text":"Птичья башня — глухая башня (полубашня) Китайгородской стены, расположенная на северной стороне крепости, на берегу реки Неглинной. Построена была в 1535—1538 годах Петроком Малым Фрязином, как и вся стена. Из всех башен Китай-города является единственной сохранившейся до настоящего времени. Как башня называлась в Средневековье, неизвестно, равно как и…","title":"Птичья башня","revision":149485094,"qid":"Q21393993","license":"CC BY-SA 4.0"},"msk-o57325b948ed8":{"text":"Электродепо́ «Вы́хино» (ТЧ-11) — электродепо Московского метрополитена, обслуживающее Таганско-Краснопресненскую линию с 12 декабря 1966 года. До 13 января 1989 года называлось «Жда́новское».","title":"Выхино (электродепо)","revision":146211975,"qid":"Q4129882","license":"CC BY-SA 4.0"},"msk-o6ad3af06b625":{"text":"Братисла́вский парк — один из пяти парков в районе Марьино Юго-Восточного административного округа Москвы. Расположен на пересечении Новомарьинской улицы и Мячковского бульвара.","title":"Братиславский парк","revision":156131722,"qid":"Q4095899","license":"CC BY-SA 4.0"},"msk-o3ebabb8ce492":{"text":"Якиманский сквер — сквер в Москве, расположенный в районе Якиманка на пересечении улицы Большая Полянка и Якиманского проезда.","title":"Якиманский сквер","revision":139741845,"qid":"Q123484607","license":"CC BY-SA 4.0"},"msk-ofce8d5f226ce":{"text":"Переде́лкино — дачный посёлок, не имеющий статуса населённого пункта, входящий в состав посёлка ДСК «Мичуринец». Расположен на территории района Внуково в Новомосковском административном округе Москвы, рядом с платформами Переделкино и Мичуринец. В 1933 году в Переделкине был создан писательский посёлок, в котором в разное время проживали Борис Пастернак,…","title":"Переделкино","revision":155510571,"qid":"Q593888","license":"CC BY-SA 4.0"},"msk-oc7f82ee539aa":{"text":"Арка Главного входа ВДНХ — парадный вход на Выставку достижений народного хозяйства, расположенный со стороны проспекта Мира и станции метро «ВДНХ». Арка построена в 1951—1954 годах.","title":"Арка главного входа ВДНХ","revision":154414009,"qid":"Q50808667","license":"CC BY-SA 4.0"},"msk-oac0279576d53":{"text":"Памятник Надежде Крупской — памятник жене и соратнице В. И. Ленина на площади Сретенских Ворот в Москве. Памятник выполнен в виде стоящей женской фигуры, задрапированной тканью, позади фигуры установлены два 10-метровых пилона, на которых нанесены даты жизни и цитаты из её выступлений. На одном пилоне: 1869 26 февраля Марксизм — дал мне величайшее счастье,…","title":"Памятник Надежде Крупской","revision":148116080,"qid":"Q19907058","license":"CC BY-SA 4.0"},"msk-o3fbd347fdebc":{"text":"Сквер Булгакова — сквер в Пресненском районе Москвы на пересечении Спиридоньевского и Большого Козихинского переулков. Ранее безымянный сквер близ Патриарших прудов получил имя писателя Михаила Булгакова в 2015 году. Инициатором именования выступил заместитель мэра Москвы по вопросам социального развития Леонид Печатников. Решение было принято 20 октября…","title":"Сквер Булгакова","revision":147830361,"qid":"Q48940648","license":"CC BY-SA 4.0"},"msk-o266e4dbc025d":{"text":"«Ту́шинский машинострои́тельный заво́д» — бывшее российское предприятие авиакосмической промышленности. Предприятие было основано в 1932 году с целью освоения новейших образцов авиационной промышленности (самолёт «Сталь-2»). С 1936 года — Государственный союзный завод № 81 Наркомтяжпрома.","title":"Тушинский машиностроительный завод","revision":154651068,"qid":"Q4466787","license":"CC BY-SA 4.0"},"msk-ob3c7e8f9dbd0":{"text":"Московский комбинат хлебопродуктов (МКХ) — мукомольное предприятие в Москве, основанное в 1936 году как база для хранения государственных запасов зерна. Включало два мукомольных завода мощностью 1 тыс. тонн переработки зерна в сутки, пять элеваторов общей ёмкостью 180 тыс. тонн, вспомогательные цеха, склады, собственную техническую базу обслуживания,…","title":"Московский комбинат хлебопродуктов","revision":146298561,"qid":"Q4304169","license":"CC BY-SA 4.0"},"msk-oedcc2edd6b9d":{"text":"Чапа́евский парк — небольшой парк в Хорошёвском районе Северного административного округа Москвы. Расположен у Ленинградского проспекта на пересечении с Чапаевским переулком. Площадь парка составляет 6 гектаров. Чапаевский парк является объектом культурного наследия (произведением садово-паркового искусства) регионального значения.","title":"Чапаевский парк","revision":154226372,"qid":"Q4345210","license":"CC BY-SA 4.0"},"msk-oce3104d85e30":{"text":"Памятник основателям МХТ им. А. П. Чехова К. С. Станиславскому и Вл. И. Немировичу-Данченко установлен на пересечении Тверской улицы и Камергерского переулка в Тверском районе Москвы.","title":"Памятник Станиславскому и Немировичу-Данченко","revision":147704190,"qid":"Q56310145","license":"CC BY-SA 4.0"},"msk-o8c4ba7e0ee30":{"text":"Пречи́стенский переу́лок (в 1937—1993 годах — переулок Н. А. Островского) — улица в центре Москвы в Хамовниках между Пречистенкой и Большим Власьевским переулком. В переулке располагаются посольства Австрии, Дании и Марокко.","title":"Пречистенский переулок","revision":154122158,"qid":"Q4377551","license":"CC BY-SA 4.0"},"msk-od1ab08664997":{"text":"Здание Ссудной казны — здание-достопримечательность в Настасьинском переулке города Москвы. Выполнено в неорусском стиле, является объектом культурного наследия федерального значения. С 1941 года в здании находился Госбанк СССР, в настоящее время там расположено хранилище Центробанка России. Здание Ссудной казны изображено на коллекционной монете 2016 года…","title":"Здание Ссудной казны","revision":146612175,"qid":"Q19857945","license":"CC BY-SA 4.0"},"msk-o1005bae972a3":{"text":"Сквер Шмелёва — сквер в Москве, названный в честь русского писателя Ивана Сергеевича Шмелёва и расположенный в районе Якиманка, на пересечении Большого Толмачёвского и Лаврушинского переулков.","title":"Сквер Шмелёва","revision":144897221,"qid":"Q115549335","license":"CC BY-SA 4.0"},"msk-ofdd76a72ad73":{"text":"Мерзляко́вский переулок (ранее Мамстрюков переулок, Мастрюков переулок) — переулок в Центральном административном округе города Москвы. Проходит от улицы Новый Арбат до Большой Никитской, лежит параллельно Никитскому бульвару, слева от него. Нумерация домов ведётся от Нового Арбата.","title":"Мерзляковский переулок","revision":146219738,"qid":"Q4290882","license":"CC BY-SA 4.0"},"msk-o3a127fd27e65":{"text":"Страстно́й бульва́р — бульвар в Тверском районе Центрального административного округа города Москвы, один из бульваров Бульварного кольца, объект культурного наследия регионального значения. Проходит от Пушкинской площади до площади Петровские Ворота. Слева к бульвару примыкает улица Малая Дмитровка. Нумерация домов ведётся от Пушкинской площади. Бульвар…","title":"Страстной бульвар","revision":156010810,"qid":"Q2922035","license":"CC BY-SA 4.0"},"msk-oa1ee1e3f0dcf":{"text":"Храм святителя Николая в Сабурове — православный храм Даниловского благочиния Московской городской епархии. Храм расположен в районе Москворечье-Сабурово, Южного административного округа города Москвы (Каширское шоссе, дом 59, корпус 4).","title":"Храм Святителя Николая в Сабурове","revision":135131395,"qid":"Q401590","license":"CC BY-SA 4.0"},"msk-ob04679d8240c":{"text":"Дом Моссельпрома в Москве — памятник русского конструктивизма и авангарда, расположенный на углу Калашного и Нижнего Кисловского переулков. Историческую и культурную ценность представляет как само здание, построенное по проекту архитектора Н. Д. Струкова, так и панно, выполненное художниками А. М. Родченко и В. Ф. Степановой, а также воспроизведённый на…","title":"Дом Моссельпрома","revision":156104664,"qid":"Q646940","license":"CC BY-SA 4.0"},"nn-o45bbfa82abfe":{"text":"Светлоярский парк — парк в Нижнем Новгороде, расположенный в Сормовском районе между улицами Светлоярской, Мокроусова и Гаугеля вокруг Светлоярского озера. Площадь парка более 9 га.","title":"Светлоярский парк","revision":147832185,"qid":"Q124758613","license":"CC BY-SA 4.0"},"nn-o578eee28a355":{"text":"Нижегородский район — один из восьми внутригородских районов в составе Нижнего Новгорода, исторически центральная его часть. Район располагается в Нагорной части города и граничит с Советским, Канавинским и Приокским районами города, а также с Кстовским районом Нижегородской области. Площадь района: 67 км² (13,7 % городской территории), численность…","title":"Нижегородский район (Нижний Новгород)","revision":155529392,"qid":"Q4318671","license":"CC BY-SA 4.0"},"nn-oe2f3761f9bff":{"text":"«Кра́сное Со́рмово» — судостроительное предприятие в Сормовском районе Нижнего Новгорода, одно из старейших предприятий в данной отрасли. Основано в 1849 году компанией «Нижегородская машинная фабрика и Волжско-Камское буксирное и завозное пароходство», как многопрофильное предприятие для выполнения ответственных государственных заказов. 18 июня 1918 года…","title":"Красное Сормово","revision":156152743,"qid":"Q839979","license":"CC BY-SA 4.0"},"nn-o629413a18bfd":{"text":"Нижегородский острог — бывшая тюрьма в историческом центре Нижнего Новгорода. Острог представляет собой комплекс из тюрьмы и административного здания. Построен в виде прямоугольника с четырьмя башнями по углам. Вся территория обнесена кирпичной стеной. В настоящее время используется как музей. Расположен по адресу: Нижний Новгород, пл. Свободы, 2а.","title":"Нижегородский острог","revision":155315377,"qid":"Q4318666","license":"CC BY-SA 4.0"},"nn-odade41df09fc":{"text":"Нижегоро́дский экзота́риум (открыт 19 мая 1996 года) — экзотариум, располагающийся в Нижнем Новгороде, является одной из достопримечательностей города. Экзотариум Нижнего Новгорода является крупнейшим в Поволжском регионе и известен за его пределами. Посещаемость выставки составляет примерно 15000 человек в год. Организация также занимается разведением…","title":"Нижегородский экзотариум","revision":155945735,"qid":"Q4318676","license":"CC BY-SA 4.0"},"ru-02e9c019ab4d-o5d36968416b1":{"text":"Белгородский государственный художественный музей — художественный музей в Белгороде, открытый 26 июля 1983 года.","title":"Белгородский государственный художественный музей","revision":147560559,"qid":"Q4081721","license":"CC BY-SA 4.0"},"ru-06d7a6d68f57-o75fa299502a8":{"text":"Чайковский историко-художественный музей —— историко-художественный музей, расположенный в городе Чайковском Пермского края. В коллекции музея хранится около 7 000 предметов, отражающих историю, духовную и материальную культуру г. Чайковского, а так же произведений русского изобразительного искусства конца XVIII—начала XXI века.","title":"Чайковская художественная галерея","revision":151077176,"qid":"Q21645288","license":"CC BY-SA 4.0"},"ru-0d8a246f6446-oe85b71d383b5":{"text":"Дмитровский кремль — частично сохранившаяся древнерусская крепость XII века в городе Дмитров, расположенном севернее Москвы. Резиденция удельных князей Дмитрова. На территории кремля размещается музей-заповедник «Дмитровский кремль». Экспозиция состоит из остатков крепостного вала и рва, Успенского собора начала XVI века, ряда зданий XIX—XX века,…","title":"Дмитровский кремль","revision":153750306,"qid":"Q21638916","license":"CC BY-SA 4.0"},"ru-0d8a246f6446-o3b7e4ff65e2b":{"text":"Дом-музей П. А. Кропоткина – отдел музея–заповедника «Дмитровский кремль», посвящённый жизни и деятельности русского революционера-анархиста Петра Алексеевича Кропоткина, располагается в Дмитрове в доме, где учёный прожил свои последние годы жизни (с 1918 по 1921 г.). Открылся для посетителей 6 сентября 2014 года.","title":"Дом-музей П. А. Кропоткина","revision":146946458,"qid":"Q106677866","license":"CC BY-SA 4.0"},"ru-140e31da27bf-of3f45c8afef2":{"text":"О́мский госуда́рственный цирк — стационарный цирк, находящийся на проспекте Маркса в Омске. Вместимость — 1500 мест. Планируется, что после реконструкции цирк будет использоваться для проведения разнообразных мероприятий (симпозиумов, фестивалей), в том числе кинофестиваля «Движение». При этом цирковая деятельность останется основной.","title":"Омский государственный цирк","revision":147837197,"qid":"Q4334722","license":"CC BY-SA 4.0"},"ru-df679694d505-o0ca9c87a7d63":{"text":"Музей-заповедник «Музей Мирового океана» — первый в России комплексный маринистический музей-заповедник, расположенный в Калининграде. Имеет филиал «Ледокол „Красин“» в Санкт-Петербурге. В музее располагаются экспозиции, посвящённые судоходству, морской флоре и фауне, геологии и гидрологии Мирового океана, открытое морское фондохранилище, маринистическая…","title":"Музей Мирового океана","revision":155447786,"qid":"Q3330754","license":"CC BY-SA 4.0"},"ru-1b04dfd77752-oa4e1d28ecc58":{"text":"Хитровщина — село в Кимовском районе Тульской области России. В рамках административно-территориального устройства является центром Хитровщинского сельского округа Кимовского района, в рамках организации местного самоуправления входит в сельское поселение Новольвовское.","title":"Хитровщина","revision":155789802,"qid":"Q23883430","license":"CC BY-SA 4.0"},"ru-242e87c1584d-o952053131684":{"text":"Куйбышевазот (ПАО «КуйбышевАзот») — российское предприятие химической промышленности в городе Тольятти, Самарской области. Основано в 1966 году. Основной продукцией завода являются капролактам, полиамид-6, техническая нить, аммиачная селитра, карбамид, сульфат аммония, аммиак, слабая азотная кислота.","title":"Куйбышевазот","revision":156103733,"qid":"Q130420","license":"CC BY-SA 4.0"},"ru-2858811e448a-o7889e8e233e6":{"text":"Покровская башня находится в юго-западном углу оборонительных сооружений Окольного города Псковской крепости, на берегу реки Великой. Памятник истории и культуры федерального значения. Является мощной крепостной башней Пскова, ёе наружная длина в окружности 90 м, пять ярусов. Возведена псковскими каменщиками в конце XV — начале XVI в., неоднократно…","title":"Покровская башня (Псков)","revision":152216156,"qid":"Q4369237","license":"CC BY-SA 4.0"},"ru-292c0a6a47ce-o5917bfca896f":{"text":"ПАО «Судостроительный завод „Вымпел“» — российская судостроительная компания, расположенная в городе Рыбинске Ярославской области. Предприятие входит в АО «Объединённая судостроительная корпорация» (ОСК).","title":"Вымпел (судостроительный завод)","revision":155827905,"qid":"Q4129026","license":"CC BY-SA 4.0"},"ru-2a1c7bdb05ea-oa17d50d5fcab":{"text":"Ставропольский академический ордена «Знак Почёта» театр имени М. Ю. Лермонтова — драматический театр в Ставрополе, старейший русский театр на Кавказе, основан в 1845 году.","title":"Ставропольский академический театр драмы","revision":155951032,"qid":"Q4439037","license":"CC BY-SA 4.0"},"ru-2abed4d95565-ocdcc522192d0":{"text":"Орловский краеведческий музей — один из старейших музеев в Орле и области.","title":"Орловский краеведческий музей","revision":154993361,"qid":"Q24932657","license":"CC BY-SA 4.0"},"ru-32747c72c08b-od10568eb5a7c":{"text":"Северодвинский городской краеведческий музей — музей истории Северодвинска. Один из крупнейших муниципальных музеев Архангельской области. Экспозиционно-выставочная площадь музея — 698,2 м²; площадь фондохранилищ — 137,8 м².","title":"Северодвинский городской краеведческий музей","revision":146281375,"qid":"Q4412565","license":"CC BY-SA 4.0"},"ru-3bbda77dba3f-o0e278d2fb7b7":{"text":"Курганский областной художественный музей им. Г. А. Травникова — государственный художественный музей, основной центр комплектования, изучения и пропаганды изобразительной культуры Зауралья. Открыт 14 августа 1982 года. В декабре 2019 года присвоено имя Г. А. Травникова. С 30 апреля 2020 года музей входит в ГАУК «Курганское областное музейное объединение».…","title":"Курганский областной художественный музей","revision":146254434,"qid":"Q4248081","license":"CC BY-SA 4.0"},"ru-3bbda77dba3f-odec6e8c4ac42":{"text":"Курга́нский госуда́рственный теа́тр дра́мы — театр драмы в городе Кургане Курганской области. Основан в 1943 году.","title":"Курганский театр драмы","revision":155415031,"qid":"Q4248070","license":"CC BY-SA 4.0"},"ru-40c6863e2a5f-o37f686fcbeef":{"text":"Ива́новский областно́й худо́жественный музе́й — музей изобразительного искусства, расположенный в городе Иванове. Принадлежит к редкому типу провинциальных музеев России, обладая уникальным тематическим диапазоном собрания, включающим крупные коллекции древнего мира, искусства Востока, западноевропейского и русского искусства XVI—XX веков, русского…","title":"Ивановский областной художественный музей","revision":154971743,"qid":"Q13668685","license":"CC BY-SA 4.0"},"ru-42a02e11a337-o40130880aaf1":{"text":"Абака́нская карти́нная галере́я и́мени Ф. Е. Пронских — единственный художественный музей в Хакасии. В настоящее время собрание галереи охватывает 2609 произведений русского искусства XX—XXI вв., среди которых живопись, скульптура, графика, декоративно-прикладное искусство, фотография.","title":"Абаканская картинная галерея","revision":155475896,"qid":"Q110259698","license":"CC BY-SA 4.0"},"ru-45eea4e72977-o7144b232dad1":{"text":"Сара́товская ГЭС (имени Ленинского комсомола) — гидроэлектростанция на реке Волге в Саратовской области, в городе Балаково. Входит в Волжско-Камский каскад ГЭС, являясь седьмой ступенью каскада ГЭС на Волге. Отличается нестандартной конструкцией — отсутствием водосбросной плотины, самым длинным в России машинным залом, имеющим к тому же разборную кровлю.…","title":"Саратовская ГЭС","revision":154900636,"qid":"Q1542516","license":"CC BY-SA 4.0"},"ru-52f876f6cb1d-o85d7336baa8f":{"text":"Энергостройдеталь - Бийский котельный завод (ЭСД - БиКЗ) — промышленное предприятие в Бийске, Алтайский край. Занимается производством паровых и водогрейных котлов средней и малой мощности, котельно-вспомогательного оборудования для промышленной и коммунальной энергетики. Основано в 1942 году. Официальной датой основания Государственного Союзного Бийского…","title":"Бийский котельный завод","revision":137420646,"qid":"Q4086550","license":"CC BY-SA 4.0"},"ru-53e6ddd5a1fb-oae786c53bbbd":{"text":"Ва́тега — недостроенный военный аэродром вблизи одноимённого посёлка Онежского района Архангельской области. Известен также под названием А́ндозеро. В 13 км западнее, за озером Андозеро, находится город Онега. Аэродром был предназначен для приёма тяжелых стратегических бомбардировщиков. При строительстве был проложен трубопровод с железнодорожной станции…","title":"Ватега (аэродром)","revision":146225800,"qid":"Q4105272","license":"CC BY-SA 4.0"},"ru-5bf5ddff6353-o447d6716a098":{"text":"Воронежский государственный театр оперы и балета — стационарный репертуарный театр в Воронеже, основанный в 1931 году как Театр музыкальной комедии и ведущий свою современную историю с 1961 года. Существующее название носит с 1968 года.","title":"Воронежский театр оперы и балета","revision":153131635,"qid":"Q198689","license":"CC BY-SA 4.0"},"ru-5bf5ddff6353-o2eea617d0524":{"text":"Воро́нежское водохрани́лище — водохранилище на реке Воронеж на территории Воронежской области России. Целиком расположено в городском округе Воронеж и является одним из крупнейших в мире водохранилищ, целиком расположенных в городской черте. Исходные (проектные) параметры водохранилища были таковы: площадь 70 км², объём 0,204 км³, длина 35 км, средняя…","title":"Воронежское водохранилище","revision":156113922,"qid":"Q4125442","license":"CC BY-SA 4.0"},"ru-5bf5ddff6353-o9b28b9b2f80c":{"text":"ФГУП «Воронежский научно-исследовательский институт связи» (ВНИИС, бывш. НИИ-299) — советское и российское предприятие в городе Воронеж, в настоящее время — АО «Концерн „Созвездие“, являющееся головным предприятием Концерна „Созвездие“». Изначально выпускало средства связи для тактического звена управления вооружёнными силами и аппаратуру передачи данных в…","title":"Воронежский научно-исследовательский институт связи","revision":143590164,"qid":"Q4125418","license":"CC BY-SA 4.0"},"kzn-oe2add74f3563":{"text":"Национальный музей Республики Татарстан (тат. Татарстан Республикасы Милли музее) — научно-исследовательское и культурно-образовательное учреждение, ведущий музейный центр Татарстана и один из крупнейших культурно-исторических музеев в Поволжье.","title":"Национальный музей Республики Татарстан","revision":154609626,"qid":"Q4315032","license":"CC BY-SA 4.0"},"msk-o45ad9e527ebf":{"text":"«Ромэ́н» — московский музыкально-драматический театр, основанный в 1931 году Иваном и Георгием Лебедевыми. Режиссёром-постановщиком первой работы театра был Моисей Гольдблат. Театр располагается в здании отеля «Советский», имеет статус Государственного бюджетного учреждения культуры (ГБУК). В его репертуар входят постановки на известные литературные…","title":"Ромэн","revision":154839358,"qid":"Q3527555","license":"CC BY-SA 4.0"},"msk-o0eb86b17006e":{"text":"До́м-музе́й Мари́ны Цвета́евой — мемориальный музей, посвящённый жизни поэтессы Марины Цветаевой. Расположен в Москве, в доме по Борисоглебскому переулку, где Цветаева проживала вместе со своей семьёй с 1914 по 1922 год. Открытие музея состоялось в 1992-м по инициативе деятелей культуры, в том числе академика Дмитрия Лихачёва. В настоящее время в музейном…","title":"Дом-музей Марины Цветаевой","revision":151574565,"qid":"Q4165209","license":"CC BY-SA 4.0"},"msk-oe994398b9190":{"text":"Центр оперного пения Галины Вишневской — учебное заведение в Москве, включающее оперный театр (автор проекта архитектор Великанов Александр Александрович). Располагается в специально выстроенном здании на ул. Остоженка (дом 25), являющемся типичным образцом лужковского стиля. Руководитель — оперная певица Г. П. Вишневская (с 2002 по 2012 год). Под…","title":"Центр оперного пения Галины Вишневской","revision":152215772,"qid":"Q4504021","license":"CC BY-SA 4.0"},"msk-oae4d39acc5bc":{"text":"Музе́й Сере́бряного ве́ка (Дом Брю́сова) — музей, посвящённый литературным течениям начала XX века: символизму, акмеизму, авангардизму и футуризму. Учреждение было основано в 1999 году как филиал Государственного литературного музея. Располагается в особняке купца Ивана Баева, спроектированном архитектором Владимиром Чагиным в стиле северный модерн. В этом…","title":"Музей Серебряного века","revision":146881971,"qid":"Q54996298","license":"CC BY-SA 4.0"},"msk-oa2f91956025b":{"text":"«Стена Цоя» — стена дома №37 по Арбату, выходящая в Кривоарбатский переулок Москвы, которую поклонники творчества Виктора Цоя исписали надписями «Кино», «Цой жив», цитатами из песен и признаниями в любви музыканту. Представляет собой памятник, символ Арбата и достопримечательность Москвы.","title":"Стена Цоя","revision":154943905,"qid":"Q4441628","license":"CC BY-SA 4.0"},"msk-obccf28e35e6e":{"text":"Московский государственный театр «У Ники́тских воро́т» — драматический театр, расположенный в Тверском районе города Москвы. Художественный руководитель театра — Марк Розовский.","title":"У Никитских ворот","revision":156289544,"qid":"Q4468224","license":"CC BY-SA 4.0"},"msk-oe8bb1419b50c":{"text":"Сквер Мстислава Ростроповича — сквер в центре Москвы на пересечении Елисеевского и Брюсова переулков. Сквер расположен в исторической части города, в живописном и малолюдном месте, между Большой Никитской и Тверской улицами. Благодаря особенности рельефа, сквер несколько возвышается над обрамляющими его переулками.","title":"Сквер Мстислава Ростроповича","revision":156353389,"qid":"Q28881203","license":"CC BY-SA 4.0"},"Q23815663":{"text":"«Кремлёвская» (тат. Кремль) — станция Первой линии Казанского метрополитена, до 30 декабря 2010 года конечная. Расположена между станциями «Площадь Тукая» и «Козья слобода». Открыта 27 августа 2005 года в составе первого пускового участка Казанского метрополитена «Горки» — «Кремлёвская».","title":"Кремлёвская","revision":155235866,"qid":"Q23815663","license":"CC BY-SA 4.0"},"Q1999626":{"text":"Ази́мовская мече́ть (тат. Әҗе́м мәчете́), или Шестая соборная, Заводская — мечеть в Казани, памятник татарской культовой архитектуры. На территории мечети находится 2-этажное здание медресе и деревянный дом муллы.","title":"Азимовская мечеть","revision":155815438,"qid":"Q1999626","license":"CC BY-SA 4.0"},"Q1149480":{"text":"Вселенский храм, также Храм всех религий (тат. Барлык диннәр гыйбәдәтханәсе, Barlıq dinnәr ğibәdәtxәnәse), Международный культурный центр духовного единения — архитектурное сооружение в микрорайоне Старое Аракчино в Казани, посвящённое разным религиям мира, популярная достопримечательность города. Является одним из немногих в мире храмов, не относящихся к…","title":"Вселенский храм","revision":153100509,"qid":"Q1149480","license":"CC BY-SA 4.0"},"Q13207309":{"text":"Татарский государственный академический театр кукол «Экият» (тат. Татар дәүләт академия «Әкият» курчак театры) — один из крупнейших и старейших театров кукол в России. Находится в Казани на улице Петербургской в Вахитовском районе города. Название театра образовано от слова тат. әкият — «сказка». Построенное в виде сказочного замка-дворца здание театра…","title":"Экият","revision":154948438,"qid":"Q13207309","license":"CC BY-SA 4.0"},"Q183334":{"text":"Всероссийское музейное объединение «Госуда́рственная Третьяко́вская галере́я» (сокр. Третьяковская галерея, ГТГ; разг. Третьяко́вка) — российский федеральный государственный художественный музей в Москве, созданный на основе исторических коллекций купцов братьев Павла и Сергея Михайловичей Третьяковых; одно из крупнейших в мире собраний русского…","title":"Третьяковская галерея","revision":155828882,"qid":"Q183334","license":"CC BY-SA 4.0"},"Q1958711":{"text":"Центра́льный академи́ческий теа́тр Росси́йской армии (до 1993 года — Центральный академический театр Советской армии) — московский академический драматический театр, основанный 6 февраля 1930 года. Обладает самой большой в Европе сценой. С момента создания являлся ведомственным театром Вооружённых сил СССР — на его сцене «проходили службу» многие…","title":"Театр Российской армии","revision":155697613,"qid":"Q1958711","license":"CC BY-SA 4.0"},"Q1048694":{"text":"Росси́йская госуда́рственная библиоте́ка (ФГБУ РГБ) (с 1924 по 22 января 1992 года носила название Государственная библиотека СССР имени В. И. Ленина) — одна из национальных библиотек Российской Федерации, крупнейшая публичная библиотека в России и континентальной Европе и одна из крупнейших библиотек мира, расположенная в Москве; ведущее…","title":"Российская государственная библиотека","revision":156007656,"qid":"Q1048694","license":"CC BY-SA 4.0"},"Q1107243":{"text":"Госуда́рственный Да́рвиновский музе́й — московский музей, посвящённый дарвиновской теории эволюции. Инициатором создания стал биолог Александр Котс, начавший свою преподавательскую карьеру при Московских высших женских курсах в 1907 году. Этот же год считается и датой основания музея — учёный перенёс свою коллекцию редких чучел животных в здание курсов в…","title":"Государственный Дарвиновский музей","revision":154767646,"qid":"Q1107243","license":"CC BY-SA 4.0"},"Q12133686":{"text":"Нижнекамская ГЭС — гидроэлектростанция на реке Каме, расположенная в городе Набережные Челны, Татарстан. Входит в каскад гидроэлектростанций на Каме, составной части Волжско-Камского каскада, являясь его нижней и самой большой по установленной мощности ступенью. Нижнекамская ГЭС является второй по мощности электростанцией Татарстана и одной из крупнейших…","title":"Нижнекамская ГЭС","revision":155512027,"qid":"Q12133686","license":"CC BY-SA 4.0"},"Q4100079":{"text":"Бу́синово — спальный микрорайон на севере Москвы, в составе района Западное Дегунино Северного административного округа. Построен в 1980-е годы на месте одноимённого села, известного с XVI века. После административной реформы 1991 года был выделен муниципальный округ «Бусиново», с 1995 год получивший статус района и просуществовавший до 1997 года, когда…","title":"Бусиново","revision":156192466,"qid":"Q4100079","license":"CC BY-SA 4.0"},"Q949402":{"text":"Дом Пашко́ва (Пашко́в дом) — одно из самых знаменитых классицистических зданий Москвы, ныне принадлежащее Российской государственной библиотеке. Спроектировано (предположительно) Василием Баженовым. Находится по адресу Воздвиженка ул. 3/5, стр.1.","title":"Дом Пашкова","revision":153641422,"qid":"Q949402","license":"CC BY-SA 4.0"},"Q4345200":{"text":"Парк 50-летия Октября — лесопарк на западе Москвы, расположенный на территории муниципального округа Проспект Вернадского, между проспектом Вернадского, улицами Удальцова и Раменки. Площадь парка — 67 га.","title":"Парк 50-летия Октября (Москва)","revision":148603884,"qid":"Q4345200","license":"CC BY-SA 4.0"},"Q4068273":{"text":"Ботани́ческий сад биологического факультета Московского университета на проспекте Мира («Историческая территория», «Апте́карский огоро́д») — старейший ботанический сад в России, первоначально основанный Петром I в 1706 году как аптекарский сад. Имеет статус объекта культурного наследия регионального значения — памятника истории и культуры Москвы, памятника…","title":"Аптекарский огород","revision":155704808,"qid":"Q4068273","license":"CC BY-SA 4.0"},"Q2202244":{"text":"«Суко́нная слобода́» (тат. Сукно бистәсе) — станция Казанского метрополитена, расположена между станциями «Площадь Тукая» и «Аметьево». Названа по историческому району, в котором располагается. Станция открыта 27 августа 2005 года в составе первого пускового участка Казанского метрополитена «Горки» — «Кремлёвская».","title":"Суконная слобода (станция метро)","revision":155885973,"qid":"Q2202244","license":"CC BY-SA 4.0"},"Q4444553":{"text":"Театр МОСТ (Московский открытый студенческий театр) — государственное бюджетное учреждение культуры города Москвы. Создан на базе Студенческого театра МГУ в 1999 году постановлением Правительства Москвы по ходатайству Всероссийского театрального общества, фактически начал работать с июня 2000 года.","title":"МОСТ (театр)","revision":155577680,"qid":"Q4444553","license":"CC BY-SA 4.0"},"Q4304284":{"text":"Московский театр Олега Табакова («Табакерка», Подвал, Подвальный театр) — театральный комплекс, основанный в 1987 году народным артистом СССР Олегом Табаковым. Театр включает в себя две сцены: на Малой Сухаревской площади и улице Чаплыгина, художественно-производственный комбинат и театральную школу. Официально театр открылся в 1987 году.","title":"Московский театр Олега Табакова","revision":152731624,"qid":"Q4304284","license":"CC BY-SA 4.0"},"Q4430888":{"text":"Спасская башня (тат. Спас манарасы) — главная проездная башня Казанского кремля и памятник архитектуры XVI века. Находится в южной стене кремля и выходит на площадь 1 Мая. С 1 сентября 2023 года в башне открыт музей, посвящённый фортификации крепости и самой Спасской башне на разных исторических этапах.","title":"Спасская башня (Казанский кремль)","revision":155944215,"qid":"Q4430888","license":"CC BY-SA 4.0"},"Q4086274":{"text":"«Библио-Глобус» (в 1957—1992 годы — магазин № 120 «Книжный мир») — один из самых крупных книжных магазинов в России, расположенный в историческом центре Москвы. В книжном магазине также располагается одноимённый офис туроператора (для частных лиц).","title":"Библио-Глобус","revision":156015984,"qid":"Q4086274","license":"CC BY-SA 4.0"},"Q4199358":{"text":"«Иллюзио́н» — специализированный архивный кинотеатр Госфильмофонда России в Москве. Расположен в одной из знаменитых сталинских высоток по адресу Котельническая набережная, дом 1/15. Открылся 18 марта 1966 года на месте бывшего кинотеатра «Знамя» специально для демонстрации фильмов из коллекции Госфильмофонда СССР — одного из крупнейших киноархивов в мире.","title":"Иллюзион (кинотеатр, Москва)","revision":154521766,"qid":"Q4199358","license":"CC BY-SA 4.0"},"Q19910970":{"text":"Росси́йская госуда́рственная де́тская библиоте́ка (аббр. РГДБ) — одна из самых больших в мире библиотек для детей, а также научно-методический центр в сфере детской литературы, педагогики, психологии и социологии детского чтения для библиотек России.","title":"Российская государственная детская библиотека","revision":152080029,"qid":"Q19910970","license":"CC BY-SA 4.0"},"Q21641834":{"text":"Центр океаногра́фии и морско́й биоло́гии «Москва́риум» — действующий океанариум, построенный в Москве на территории ВДНХ и расположенный у павильона «Космос». Комплекс был построен в рамках программы реставрации и комплексного развития ВДНХ. Открыт 5 августа 2015 года. Общая площадь комплекса составляет 53 000 м2. Суммарный объём воды в ёмкостях экспозиции…","title":"Москвариум","revision":154990721,"qid":"Q21641834","license":"CC BY-SA 4.0"},"Q28666943":{"text":"Музей русского импрессионизма — частный музей в Москве, посвящённый русскому искусству конца XIX — первой трети XX века. Расположен в здании, построенном на территории бывшей кондитерской фабрики «Большевик».","title":"Музей русского импрессионизма","revision":154140368,"qid":"Q28666943","license":"CC BY-SA 4.0"},"Q28667331":{"text":"Галере́я Алекса́ндра Ши́лова — художественная галерея, созданная в 1997 году на базе авторских произведений народного художника СССР Александра Шилова. Основные выставочные пространства галереи располагаются в особняке XIX века по адресу улица Знаменка, 3, построенном архитектором Евграфом Тюриным. В 2003 году экспозиционные залы расширили: в соседнем…","title":"Галерея Александра Шилова","revision":152441305,"qid":"Q28667331","license":"CC BY-SA 4.0"},"Q140886315":{"text":"Balzi Rossi (Бальци Росси) — ресторан итальянской кухни в Москве, расположенный на первом этаже жилого дома на Кудринской площади. Ресторан работает с 2015 года.","title":"Balzi Rossi","revision":154775161,"qid":"Q140886315","license":"CC BY-SA 4.0"},"Q4146755":{"text":"Моско́вский госуда́рственный академи́ческий теа́тр опере́тты, сокр. назв. «Московская оперетта» или просто Мосоперетта — музыкальный театр в Москве, первый государственный театр оперетты в СССР. Расположен по адресу: ул. Большая Дмитровка, дом 6. В репертуаре театра — классическая и современная оперетта, мюзиклы.","title":"Московский театр оперетты","revision":155681426,"qid":"Q4146755","license":"CC BY-SA 4.0"},"Q181324":{"text":"Оста́нкинская телеба́шня (прежнее название — «Общесою́зная радиотелевизио́нная передаю́щая ста́нция им. 50-ле́тия Октября́») — телевизионная и радиовещательная башня, расположенная в Останкинском районе Москвы. Высота сооружения — 540,1 м. По состоянию на весну 2022 года телебашня — 15-е по высоте сооружение из когда-либо существовавших, а также высочайшее…","title":"Останкинская телебашня","revision":156016675,"qid":"Q181324","license":"CC BY-SA 4.0"},"Q4146999":{"text":"Музе́й совреме́нной исто́рии Росси́и (до сентября 1998 года Центральный Музей революции СССР, Музей революции) — один из крупнейших музеев новейшей истории в мире. Музей расположен в центре Москвы (ул. Тверская, 21), в здании — памятнике архитектуры московского классицизма конца XVIII века. С 1831 по 1917 годы в нём размещался московский Английский клуб.","title":"Музей современной истории России","revision":154215318,"qid":"Q4146999","license":"CC BY-SA 4.0"},"Q662367":{"text":"Шу́ховская ба́шня (радиоба́шня Шу́хова, Шу́ховская телеба́шня, Ша́боловская телевизио́нная ба́шня, радиоба́шня Коминте́рна) — металлическая радио- и телебашня, памятник архитектуры советского рационализма. Расположена в Москве на улице Шухова рядом с телецентром на Шаболовке. Построена в 1919—1922 годах по проекту архитектора и изобретателя Владимира Шухова.","title":"Шуховская башня","revision":155489748,"qid":"Q662367","license":"CC BY-SA 4.0"},"Q4306979":{"text":"«Мультимедиа Арт Музей» (или «Мультимедиа Арт Музей, Москва»; МАММ) — московский художественный музей, появившийся в 1996 году. По итогам 2021 года стал третьим по посещаемости художественным музеем в мире. Открылся после продолжительной реставрации в апреле 2024 года.","title":"Мультимедиа-арт-музей","revision":149821132,"qid":"Q4306979","license":"CC BY-SA 4.0"},"Q190694":{"text":"Музей Победы (с марта 2022 года Муzей Победы) — федеральное государственное учреждение культуры России, главный объект мемориального парка Победы на Поклонной горе в Москве. Также известен как Центральный музей Великой Отечественной войны. Открыт президентом России Борисом Ельциным 9 мая 1995 года.","title":"Музей Победы","revision":152807694,"qid":"Q190694","license":"CC BY-SA 4.0"},"Q1790299":{"text":"Крути́цкое подво́рье (Крути́цкое патриа́ршее подво́рье, Крути́цкий архиере́йский дом, Крути́цы) — бывшая резиденция епископов Сарских и Подонских, образованная в XIII веке в качестве монастыря. Название подворья происходит от слова «крутицы», обозначающего возвышенные левые берега Москвы ниже устья реки Яузы. В 1991 году вошло в состав Русской православной…","title":"Крутицкое подворье","revision":154038309,"qid":"Q1790299","license":"CC BY-SA 4.0"},"Q4304114":{"text":"Московский дворец молодёжи (МДМ) — развлекательный комплекс в Москве, расположен в районе Хамовники над станцией метро «Фрунзенская». Здание было построено в 1982—1988 годах по проекту архитекторов Якова Белопольского, М. Е. Беленя, Михаила Посохина, Владимира Хавина.","title":"Московский дворец молодёжи","revision":155904248,"qid":"Q4304114","license":"CC BY-SA 4.0"},"Q1370087":{"text":"Большо́й Кремлёвский дворе́ц — бывшая резиденция императоров Всероссийских в Московском Кремле. Построен в 1838—1849 годах группой архитекторов под руководством К. А. Тона по распоряжению императора Николая I. В работах принимали участие Н. И. Чичагов, Ф. Ф. Рихтер, П. А. Герасимов, В. А. Бакарев, Н. А. Шохин и другие. Архитектурный ансамбль включает…","title":"Большой Кремлёвский дворец","revision":156087241,"qid":"Q1370087","license":"CC BY-SA 4.0"},"Q3412663":{"text":"Софи́йская на́бережная — набережная на правом берегу Москвы-реки в районе Якиманка Центрального административного округа города Москвы. Проходит от улицы Серафимовича до улицы Балчуг. Нумерация домов ведётся от улицы Серафимовича. К набережной примыкает Фалеевский переулок.","title":"Софийская набережная","revision":153112975,"qid":"Q3412663","license":"CC BY-SA 4.0"},"Q930376":{"text":"Сена́тский дворе́ц Московского Кремля — памятник архитектуры екатерининского классицизма, построенный по проекту русского архитектора Матвея Казакова в 1776—1787 годах. В нынешнее время является рабочей резиденцией президента Российской Федерации.","title":"Сенатский дворец","revision":154470653,"qid":"Q930376","license":"CC BY-SA 4.0"},"Q4165336":{"text":"Дом Мельникова (Дом-мастерская архитектора Константина Степановича Мельникова) — одноквартирный жилой дом, памятник архитектуры советского авангарда. Был построен в 1927—1929 годах в Кривоарбатском переулке в Москве по проекту выдающегося советского архитектора Константина Мельникова для себя и своей семьи. Дом-мастерская является вершиной творчества…","title":"Дом Мельникова","revision":156166460,"qid":"Q4165336","license":"CC BY-SA 4.0"},"Q4304009":{"text":"Музе́и Моско́вского Кремля́ (ММК, Федеральное государственное бюджетное учреждение культуры «Государственный историко-культурный музей-заповедник «Московский Кремль») — государственное музейное учреждение, расположенное в Московском Кремле. Включает в себя следующие музеи: Оружейная палата, Архангельский, Благовещенский и Успенский соборы, Патриарший…","title":"Музеи Московского Кремля","revision":153551575,"qid":"Q4304009","license":"CC BY-SA 4.0"},"Q4304134":{"text":"Моско́вский драмати́ческий Теа́тр на Бро́нной (с 1945 по 1965 год Моско́вский драмати́ческий теа́тр, с 1965 по 2021 — Театр на Малой Бронной) — драматический театр Москвы, основанный в марте 1945 года. Первым руководителем был режиссёр Сергей Майоров. В 1965 году театр стал называться Театром на Малой Бронной, а в 2021 — Театром на Бронной. В репертуаре…","title":"Театр на Бронной","revision":154865959,"qid":"Q4304134","license":"CC BY-SA 4.0"},"Q4326700":{"text":"Но́вый Мане́ж (Малый Манеж, Гео́ргиевская электри́ческая ста́нция) — историческое здание в Тверском районе Москвы, расположенное в Георгиевском переулке, памятник архитектуры неорусского стиля XIX века. Построенное изначально в качестве электростанции, в 1995 — 1997 годах здание было реконструировано для размещения в нём Московского государственного…","title":"Новый Манеж","revision":153086964,"qid":"Q4326700","license":"CC BY-SA 4.0"},"Q55652567":{"text":"Дом Гоголя (официальное название Дом Н. В. Гоголя — мемориальный музей и научная библиотека) — государственное бюджетное учреждение культуры города Москвы, посвящён писателю Николаю Гоголю. Расположен в бывшей усадьбе графа Александра Толстого по адресу Никитский бульвар, 7а, где писатель прожил четыре года — с 1848 до своей смерти в 1852-м. На начало 2018…","title":"Дом Гоголя","revision":147817963,"qid":"Q55652567","license":"CC BY-SA 4.0"},"Q32859800":{"text":"Киноконцертный зал «Эльдар» — московский киноконцертный центр с тремя залами и музейным пространством. Центр расположен в здании бывшего кинотеатра «Казахстан» по адресу Ленинский проспект, 105 (станция метро Новаторская).","title":"Эльдар (киноконцертный зал)","revision":154522786,"qid":"Q32859800","license":"CC BY-SA 4.0"},"Q4872":{"text":"Госуда́рственный музе́й изобрази́тельных иску́сств и́мени А. С. Пу́шкина (сокр. ГМИИ имени А. С. Пушкина), Пу́шкинский музе́й — российский государственный художественный музей в Москве, одно из крупнейших в современной России собраний западного искусства. Созданный по инициативе историка и археолога, профессора Московского университета И. В. Цветаева,…","title":"Государственный музей изобразительных искусств имени А. С. Пушкина","revision":156045401,"qid":"Q4872","license":"CC BY-SA 4.0"},"Q2366807":{"text":"Савёловский райо́н — район в Москве, расположенный в Северном административном округе. Району соответствует внутригородское муниципальное образование муниципальный округ Савёловский. Вдоль южной границы района проходит участок Третьего транспортного кольца Москвы. Название район получил от Савёловского вокзала (который, однако, находится на территории…","title":"Савёловский район","revision":153189995,"qid":"Q2366807","license":"CC BY-SA 4.0"},"Q627114":{"text":"«Рабо́чий и колхо́зница» — памятник монументального искусства, «идеал и символ советской эпохи», признанный «эталон социалистического реализма». Представляет собой скульптурную группу из двух фигур, мужской и женской, которые устремлены вперёд и поднимают над своими головами серп и молот. Концепция и композиционный замысел принадлежат архитектору Борису…","title":"Рабочий и колхозница","revision":155568448,"qid":"Q627114","license":"CC BY-SA 4.0"},"Q4065115":{"text":"А́нгелов переу́лок (название утверждено 21 февраля 1995 года, ранее — Проекти́руемый прое́зд № 367) — переулок в Северо-Западном административном округе города Москвы на территории района Митино. Пролегает с востока на запад и соединяет Митинскую улицу и улицу Барышиха. Нумерация домов начинается от Митинской улицы.","title":"Ангелов переулок","revision":146246972,"qid":"Q4065115","license":"CC BY-SA 4.0"},"Q4398059":{"text":"Российский государственный архив древних актов (РГАДА) — крупнейшее российское хранилище русских манускриптов, документов и печатных книг XI — начала XIX века. Находится в городе Москва по адресу: ул. Большая Пироговская, д. 17.","title":"Российский государственный архив древних актов","revision":156179111,"qid":"Q4398059","license":"CC BY-SA 4.0"},"Q2401302":{"text":"Вознесе́нский монасты́рь — московский женский монастырь, основанный в 1386 году Евдокией Дмитриевной — женой Дмитрия Донского. Находился около Спасской башни и почти вплотную примыкал к Кремлёвской стене. В Средние века служил местом погребения представительниц московского великокняжеского рода. Был разрушен в 1929 году.","title":"Вознесенский монастырь (Москва)","revision":156343904,"qid":"Q2401302","license":"CC BY-SA 4.0"},"Q2860429":{"text":"Росси́йский госуда́рственный архи́в литерату́ры и иску́сства (РГАЛИ, ранее ЦГАЛИ и ЦГЛА) — крупнейшее хранилище России, в котором сосредоточены богатейшие материалы по истории отечественной литературы, музыки, театра, кино, изобразительного искусства, архитектуры. Изначально является также научно-исследовательским учреждением. С 1997 года включён в…","title":"Российский государственный архив литературы и искусства","revision":155987228,"qid":"Q2860429","license":"CC BY-SA 4.0"},"Q4504054":{"text":"Музей современного искусства «Гараж» — российский музей современного искусства. Основан в 2008 году Дарьей Жуковой и Романом Абрамовичем, располагается в Парке Горького в Москве. В 2018 году музей посетили 818 тысяч человек, в 2019 году музей посетили 942 тысячи человек.","title":"Гараж (музей)","revision":154926932,"qid":"Q4504054","license":"CC BY-SA 4.0"},"Q1638035":{"text":"Музей космона́втики в Москве (ранее Мемориальный музей космонавтики) — музей космической тематики в стилобате монумента «Покорителям космоса» на Аллее Космонавтов ВДНХ. Музей был открыт 10 апреля 1981 года — к 20-летию полёта в космос Юрия Гагарина. Предметный фонд музея на январь 2017-го насчитывает более 100 тыс. единиц хранения. Общая площадь музея —…","title":"Музей космонавтики (Москва)","revision":152026900,"qid":"Q1638035","license":"CC BY-SA 4.0"},"Q4453486":{"text":"«Теа́тр на Покро́вке» — драматический театр города Москвы, созданный 2 сентября 1991 года народным артистом России Сергеем Арцибашевым. Полное юридическое наименование учреждения — «Государственное бюджетное учреждение культуры города Москвы „Театр на Покровке“» (ГБУК г. Москвы «Театр на Покровке»).","title":"Театр на Покровке","revision":155719922,"qid":"Q4453486","license":"CC BY-SA 4.0"},"Q4036690":{"text":"«Кро́кус Си́ти Холл» и́мени Мусли́ма Магома́ева — многоуровневый концертный зал, располагавшийся до марта 2024 года на территории делового центра «Крокус-Сити» в Красногорске, в непосредственной близости от 67-го км МКАД и рядом со станцией метро «Мякинино». Зал был открыт 25 октября 2009 года предпринимателем Аразом Агаларовым. Стандартная вместимость…","title":"Крокус Сити Холл","revision":156122610,"qid":"Q4036690","license":"CC BY-SA 4.0"},"Q4504252":{"text":"Центра́льный дом кино́ (ЦДК) (ранее — Моско́вский дом кино́, Центра́льный дом кино́ Сою́за кинематографи́стов СССР) — творческий клуб деятелей киноискусства Москвы. Был открыт в 1934 году. Работает под руководством Союза кинематографистов России. На территории Дома кино проходят кинопоказы, творческие встречи, кинофестивали, конференции и другие мероприятия.","title":"Центральный дом кино","revision":156122990,"qid":"Q4504252","license":"CC BY-SA 4.0"},"Q4052630":{"text":"Velvet Music — российский лейбл звукозаписи и продюсерский центр, основанный продюсерами Алёной Михайловой и Лианой Меладзе 15 апреля 2004 года. Дистрибьюторами продукции лейбла в разное время становились компании «Мистерия звука», «Союз», Gala Records, CD Land и другие.","title":"Velvet Music","revision":155912153,"qid":"Q4052630","license":"CC BY-SA 4.0"},"Q13360735":{"text":"Задние, или Спасские ворота, — архитектурный памятник XVII века на территории музея-заповедника Коломенское. Ворота расположены у западной границы Государева двора и с конца XVIII века служили основным въездом на хозяйственный двор царской резиденции.","title":"Спасские ворота (Коломенское)","revision":151660496,"qid":"Q13360735","license":"CC BY-SA 4.0"},"Q18923895":{"text":"Госуда́рственный музе́й Константи́на и Ви́ктора Ме́льниковых — филиал Государственного музея архитектуры имени Алексея Щусева, открывшийся в 2014 году в доме архитектора Мельникова. Здание представляет собой памятник русского авангарда 1920-х годов, возведённый в цилиндрической форме по проекту архитектора Константина Мельникова.","title":"Музей Мельниковых","revision":155891267,"qid":"Q18923895","license":"CC BY-SA 4.0"},"Q21042388":{"text":"Музе́й археоло́гии Москвы́ — музей, посвящённый археологическим раскопкам на территории Москвы. Открытие состоялось в 1997 году, однако из-за плохого технического состояния здания в 2011-м была проведена масштабная реконструкция, продлившаяся до 2015 года. По состоянию на 2018 г. экспозиция состоит из более чем двух тысяч экспонатов и включает в себя…","title":"Музей археологии Москвы","revision":146621791,"qid":"Q21042388","license":"CC BY-SA 4.0"},"Q7089116":{"text":"Олимпийский бассейн, ранее — Плавательный бассейн Центрального стадиона им. Ленина (полное современное наименование Дворец водных видов спорта «Лужники») — центр водных видов спорта в Москве, часть спорткомплекса «Лужники». Был построен в 1956 году по проекту архитектора А. В. Власова. Реконструирован в 1980 году. Вместимость составляла 10 500 мест.…","title":"Лужники (бассейн)","revision":149445443,"qid":"Q7089116","license":"CC BY-SA 4.0"},"Q30642360":{"text":"Мюзик-холл — театральный и концертный зал, государственное учреждение культуры города Москвы.","title":"Московский мюзик-холл","revision":153151171,"qid":"Q30642360","license":"CC BY-SA 4.0"},"Q56310742":{"text":"Палаты Титовых (Палаты Г. С. Титова, палаты Титова; совр. Стрелецкие палаты) — каменное здание жилых палат XVII века в центре Москвы, в Лаврушинском переулке, напротив Третьяковской галереи, во дворе сталинского «Дома писателей». По состоянию на 2026 год, в отреставрированном здании палат располагается военно-исторический Музей Московских стрельцов…","title":"Палаты Титовых (Москва)","revision":154184896,"qid":"Q56310742","license":"CC BY-SA 4.0"},"Q47484307":{"text":"Це́нтр диза́йна Artplay (Артплэ́й) — креативный кластер в Москве. Создан в 2003 году, с 2008 года располагается на территории бывшей промзоны в районе Курского вокзала. В состав кластера входят архитектурные и дизайнерские бюро, шоурумы, офисы, университет креативных индустрий, Открытый музей, выставочные пространства, студии, заведения общепита и другие…","title":"Центр дизайна Artplay","revision":154185856,"qid":"Q47484307","license":"CC BY-SA 4.0"},"Q840812":{"text":"Моско́вский Худо́жественный теа́тр (сокр. МХТ) — исторический драматический театр в Москве, основанный Константином Станиславским и Владимиром Немировичем-Данченко, давший первое представление 14 (26) октября 1898 года. Первоначально назывался Художественно-общедоступный театр. С 1901 года — Московский Художественный театр (МХТ), с 1919 года — Московский…","title":"Московский Художественный театр","revision":154846010,"qid":"Q840812","license":"CC BY-SA 4.0"},"Q2366768":{"text":"Райо́н Алту́фьевский — район в Москве. Расположен в западной части Северо-Восточного административного округа. Району соответствует внутригородское муниципальное образование муниципальный округ Алтуфьевский.","title":"Алтуфьевский район","revision":154466753,"qid":"Q2366768","license":"CC BY-SA 4.0"},"Q1962775":{"text":"Оре́хово-Бори́сово Се́верное — район, расположенный в Южном административном округе города Москвы, а также соответствующее ему одноимённое внутригородское муниципальное образование.","title":"Орехово-Борисово Северное","revision":155840314,"qid":"Q1962775","license":"CC BY-SA 4.0"},"Q508433":{"text":"Цари́цыно — район в Южном административном округе города Москвы и соответствующий ему одноимённый муниципальный округ.","title":"Царицыно (район Москвы)","revision":154022786,"qid":"Q508433","license":"CC BY-SA 4.0"},"Q1963119":{"text":"Ю́жное Бу́тово — район города Москвы в составе Юго-Западного административного округа, а также соответствующее ему одноимённое внутригородское муниципальное образование. Расположен к югу от Московской кольцевой автодороги. Южное Бутово — спальный район. Отсутствие крупных промышленных предприятий, близость лесного массива (Бутовский лесопарк), а также…","title":"Южное Бутово","revision":156067159,"qid":"Q1963119","license":"CC BY-SA 4.0"},"Q2449813":{"text":"Трансваа́ль-парк — спортивно-развлекательный комплекс, открытый в июне 2002 года на юго-западе Москвы в районе Ясенево на Голубинской улице. Был первым аквапарком, построенным в столице. 14 февраля 2004 года произошло обрушение крыши сооружения, погибло 28 человек. В 2013 году на этом месте был открыт новый аквапарк «Мореон», ставший частью нового…","title":"Трансвааль-парк","revision":153631654,"qid":"Q2449813","license":"CC BY-SA 4.0"},"Q1346321":{"text":"СИЗО «Лефо́ртово» (ФГКУ «СИЗО ФСБ России») — следственный изолятор в Москве, находящийся в ведении ФСБ России. Расположен в районе Лефортово по адресу: Лефортовский Вал, д. 5; вход возможен со стороны Лефортовского Вала, а также со стороны Энергетической улицы (д. 3а), въезд — только со стороны Лефортовского Вала.","title":"Лефортовская тюрьма","revision":154888745,"qid":"Q1346321","license":"CC BY-SA 4.0"},"Q2628618":{"text":"Алма́зный фо́нд Росси́йской Федера́ции — постоянная выставка в Оружейной палате Московского Кремля, открытая в 1967 году; структурное подразделение Гохрана России. В коллекцию фонда входят шедевры ювелирного искусства XVIII-XX веков, а также самородки и драгоценные камни исторического и художественного значения. Коллекция Алмазного фонда была основана при…","title":"Алмазный фонд","revision":155631611,"qid":"Q2628618","license":"CC BY-SA 4.0"},"Q1018222":{"text":"Буты́рская тюрьма́ или просто «Буты́рка» (иногда также во мн. ч. «Буты́рки», исторически Буты́рский губе́рнский тюре́мный за́мок, ныне ФКУ СИЗО-2 ГУФСИН России по г. Москве) — следственный изолятор в Москве, самая крупная тюрьма российской столицы, одна из старейших сохранившихся и наиболее известных тюрем России. Располагается в Тверском районе ЦАО на…","title":"Бутырская тюрьма","revision":156227162,"qid":"Q1018222","license":"CC BY-SA 4.0"},"Q4373604":{"text":"Поселе́ние Краснопахо́рское — бывшее поселение (муниципальное образование и административная единица) в составе Троицкого административного округа города Москвы. Упразднено 8 мая 2024 года в процессе административно-территориальной реформы ТиНАО. Правопреемником поселения Краснопахорское являются органы местного самоуправления и управа Краснопахорского…","title":"Краснопахорское","revision":155760261,"qid":"Q4373604","license":"CC BY-SA 4.0"},"Q1972493":{"text":"Больша́я Ники́тская у́лица (в 1920—1993 годах — у́лица Ге́рцена) — улица в Центральном административном округе города Москвы. Проходит от Манежной площади до Кудринской площади, лежит между Тверской улицей и Воздвиженкой параллельно им. Нумерация домов ведётся от Манежной площади.","title":"Большая Никитская улица","revision":156079946,"qid":"Q1972493","license":"CC BY-SA 4.0"},"Q1327180":{"text":"Палеонтологический музей имени Ю. А. Орло́ва РАН — московский музей, один из крупнейших естественно-исторических музеев мира. Был основан в 1937 году, с 1966 года назван в честь зоолога и палеонтолога Юрия Орлова. Музей является частью Палеонтологического института имени А. А. Борисяка. Четыре экспозиционные зоны музея, включающие в себя шесть залов,…","title":"Палеонтологический музей имени Ю. А. Орлова","revision":151336686,"qid":"Q1327180","license":"CC BY-SA 4.0"},"Q1979285":{"text":"Моско́вский теа́тр «Совреме́нник» — государственный драматический театр, находится в центре Москвы, на Чистопрудном бульваре в доме 19А. Основан в 1956 году группой молодых актёров — выпускников школы-студии МХАТ. Лидером и первым художественным руководителем театра с 1956 по 1970 год был Олег Ефремов. С 1972 по 2019 год главным режиссёром и художественным…","title":"Современник (театр)","revision":154918119,"qid":"Q1979285","license":"CC BY-SA 4.0"},"Q2177054":{"text":"Росси́йский институ́т театра́льного иску́сства — ГИ́ТИС — российское высшее учебное заведение. Крупнейший театральный вуз в Европе и один из крупнейших в мире. Основан в 1878 году, расположен в Москве. Архитектурный ансамбль и главное здание вуза в Малом Кисловском переулке являются объектом культурного наследия народов России и охраняются государством.","title":"Российский институт театрального искусства — ГИТИС","revision":155924912,"qid":"Q2177054","license":"CC BY-SA 4.0"},"Q1190634":{"text":"«Лукойл Арена» (до 18 марта 2021 года: «Откры́тие Аре́на»; до 1 января 2024 года: «Откры́тие Банк Аре́на») — футбольный стадион в Москве, расположен в районе Покровское-Стрешнево, Северо-Западного административного округа. Домашняя арена клуба «Спартак» (Москва). Построен на территории бывшего Тушинского аэродрома. Принимал матчи Кубка конфедераций 2017…","title":"Лукойл Арена","revision":155514975,"qid":"Q1190634","license":"CC BY-SA 4.0"},"Q4453438":{"text":"Сце́на «Ме́льников» (с 1996 по 2024 год — Театр Романа Виктюка) — драматический театр города Москвы, созданный 16 июля 1996 года Постановлением Правительства Москвы, на основе авторского частного театра народного артиста России и Украины Романа Григорьевича Виктюка (1936—2020). До июня 2024 года имел наименование — «Театр Романа Виктюка». С октября 2024…","title":"Сцена «Мельников»","revision":153153714,"qid":"Q4453438","license":"CC BY-SA 4.0"},"Q4453559":{"text":"Госуда́рственный центра́льный Театра́льный музе́й им. А. А. Бахру́шина (сокращённо ГЦТМ им. А. А. Бахрушина, Бахрушинский музей, бывший «Литературно-Театральный музей Императорской Академии наук») — театральный музей в Москве, основанный в 1894 году известным русским купцом, меценатом и благотворителем Алексеем Александровичем Бахрушиным. Большая Советская…","title":"Театральный музей имени А. А. Бахрушина","revision":151546370,"qid":"Q4453559","license":"CC BY-SA 4.0"},"Q4141054":{"text":"«Го́голь-центр» — театральный центр, созданный режиссёром Кириллом Серебренниковым на базе расформированного Московского драматического театра имени Н. В. Гоголя.","title":"Гоголь-центр","revision":154719350,"qid":"Q4141054","license":"CC BY-SA 4.0"},"Q2704327":{"text":"Со́кол — район в Москве. Расположен в Северном административном округе. На территории района создано одноимённое муниципальное образование. Ранее на месте района находилось старинное село Всехсвятское, известное с XV века. В составе Москвы с 1917 года. Название района дано в честь посёлка Сокол, созданного в 1920-х годах. По оценке Мосгорстата район Сокол…","title":"Сокол (район Москвы)","revision":154897000,"qid":"Q2704327","license":"CC BY-SA 4.0"},"Q571291":{"text":"Госуда́рственный академи́ческий теа́тр и́мени Моссове́та — драматический театр в Москве, отмеченный орденами Ленина и Трудового Красного Знамени. Основан в 1923 году литератором и режиссёром Сергеем Ивановичем Прокофьевым как театр рабочих Московского губернского совета профессиональных союзов (МГСПС). Своё современное название получил в 1938 году.","title":"Театр имени Моссовета","revision":155578347,"qid":"Q571291","license":"CC BY-SA 4.0"},"Q200705":{"text":"Воскресе́нские воро́та (И́верские ворота, до 1680 года — Неглиненские, также Львиные, Курятные) — двойные проездные ворота Китайгородской стены, расположенные в одноимённом проезде между зданием Городской думы и Государственным историческим музеем (ГИМ). Впервые были построены в 1538 году по проекту архитектора Петрока Малого. Выстроены заново в 1680 году.…","title":"Воскресенские ворота","revision":155328404,"qid":"Q200705","license":"CC BY-SA 4.0"},"Q2549381":{"text":"«Су́харевская» (до 5 ноября 1990 года — «Колхо́зная») — станция Московского метрополитена на Калужско-Рижской линии. Расположена в Мещанском районе (ЦАО). Открыта 5 января 1972 года в составе участка «Проспект Мира» — «Китай-город». Пилонная трёхсводчатая станция глубокого заложения с одной островной платформой.","title":"Сухаревская (станция метро)","revision":151319995,"qid":"Q2549381","license":"CC BY-SA 4.0"},"Q2367665":{"text":"Би́бирево — район в Северо-Восточном административном округе Москвы, а также одноимённое внутригородское муниципальное образование. Находятся на северной окраине Москвы, примыкают к МКАД. Граничат с районами Южное Медведково, Северное Медведково, Лианозово, Алтуфьевский, Отрадное. Основная магистраль — улица Лескова. Бибирево — один из самых экологически…","title":"Бибирево (район Москвы)","revision":156183265,"qid":"Q2367665","license":"CC BY-SA 4.0"},"Q2008435":{"text":"Нижегоро́дский райо́н — район в Москве, расположенный в Юго-Восточном административном округе. Району соответствует внутригородское муниципальное образование муниципальный округ Нижегородский. Название район и муниципальное образование получили по Нижегородской улице, частично находящейся на их территории, а частично в Таганском районе. Граничит с районами…","title":"Нижегородский район (Москва)","revision":154723653,"qid":"Q2008435","license":"CC BY-SA 4.0"},"Q1963114":{"text":"Зя́бликово — район на юго-востоке Москвы, в Южном административном округе, и одноимённый муниципальный округ. Район и муниципальное образование названы по бывшей деревне Зябликово, включённой в состав Москвы в 1960 году. Управа района Зябликово, объединившая муниципальные инфраструктуры юго-восточных микрорайонов (6—12) Орехова-Борисова, расположена в…","title":"Зябликово (район Москвы)","revision":156323499,"qid":"Q1963114","license":"CC BY-SA 4.0"},"Q1962788":{"text":"Гага́ринский райо́н — район в Москве, расположенный в Юго-Западном административном округе. Району соответствует внутригородское муниципальное образование муниципальный округ Гагаринский. На месте района ранее располагалась Живодёрная слобода, частично также село Семёновское.","title":"Гагаринский район (Москва)","revision":150926316,"qid":"Q1962788","license":"CC BY-SA 4.0"},"Q2059063":{"text":"Ломоно́совский райо́н — район Юго-Западного административного округа города Москвы. В границах района образовано внутригородское муниципальное образование Ломоносовский муниципальный округ.","title":"Ломоносовский район (Москва)","revision":154598672,"qid":"Q2059063","license":"CC BY-SA 4.0"},"Q1200403":{"text":"«Театра́льная» — станция Московского метрополитена на Замоскворецкой линии. Связана пересадками со станциями «Охотный Ряд» на Сокольнической линии и «Площадь Революции» на Арбатско-Покровской линии. Расположена в Тверском районе (ЦАО); названа по Театральной площади. Открыта 11 сентября 1938 года в составе участка «Площадь Свердлова» — «Сокол» (вторая…","title":"Театральная (станция метро, Москва)","revision":154900925,"qid":"Q1200403","license":"CC BY-SA 4.0"},"Q2370140":{"text":"Покло́нная гора́ — срытый пологий холм в Западном административном округе Москвы, в районе Дорогомилово, находится между реками Сетунь и Филька. Изначально делилась по оврагу на западную и восточную части. Восточная часть Поклонной горы была срыта в 1950-е — 1960-е годы при прокладке Кутузовского проспекта и жилого квартала от Окружной железной дороги до…","title":"Поклонная гора","revision":155050326,"qid":"Q2370140","license":"CC BY-SA 4.0"},"Q2580102":{"text":"Тайни́цкий сад — сад на территории Московского Кремля. Располагается вдоль южной стены крепости, своё название получил в честь Тайницкой башни. Входит в список всемирного культурного наследия ЮНЕСКО. Часть парка, граничащая с Ивановской площадью, называется Большим Кремлёвским сквером.","title":"Тайницкий сад","revision":148021327,"qid":"Q2580102","license":"CC BY-SA 4.0"},"Q2551914":{"text":"Водоотво́дный кана́л (ранее также Обводно́й кана́л) проложен в 1783—1786 годах вдоль центральной излучины Москвы-реки вблизи Кремля. Между Водоотводным каналом и Москвой-рекой находится остров. Длина канала — 4 км, ширина — от 30 до 50 м, глубина — около 2 м. Через канал переброшено 12 мостов, в том числе 6 пешеходных. Русло канала было проложено по…","title":"Водоотводный канал","revision":154764306,"qid":"Q2551914","license":"CC BY-SA 4.0"},"Q1785861":{"text":"Лоси́ный О́стров — лесной массив на территории Москвы (районы Метрогородок, Гольяново, Богородское и, незначительно — Сокольники и Ярославский) и Московской области (городские округа Балашиха, Королёв, Мытищи и Щёлково). Крупнейший лесной массив в Москве и крупнейший среди лесов, расположенных в черте городов (Московская часть леса). С 1983 года имеет…","title":"Лосиный Остров","revision":155248201,"qid":"Q1785861","license":"CC BY-SA 4.0"},"Q2704963":{"text":"Алле́я Космона́втов (также аллея Героев космоса, аллея Героев Космонавтов) — пешеходная улица, расположенная между южным и северным входами станции метро «ВДНХ». Открыта 4 октября 1967 в честь десятилетия запуска первого искусственного спутника Земли. Проходит от Останкинского проезда до монумента «Покорителям космоса». 12 апреля 1967 года на аллее…","title":"Аллея Космонавтов","revision":153909340,"qid":"Q2704963","license":"CC BY-SA 4.0"},"Q3408535":{"text":"Дом Союзов (Дом Благородного собрания) — общественное здание на углу Охотного Ряда и Большой Дмитровки в Москве; памятник классицизма конца XVIII века. Изначально — усадьба князя Василия Долгорукова-Крымского. Было куплено Благородным собранием в 1784 году и перестроено архитектором Матвеем Казаковым. После революции в доме находился Центральный совет…","title":"Дом Союзов","revision":155843086,"qid":"Q3408535","license":"CC BY-SA 4.0"},"Q4373597":{"text":"Поселе́ние Воскресе́нское — поселение в составе района Коммунарка Новомосковского административного округ Москвы. Первоначально как самостоятельное муниципальное образование сельское поселение Воскресенское было создано в 2005 году и включило 9 населённых пунктов позже упразднённых Воскресенского и Сосенского сельских округов. 1 июля 2012 года было…","title":"Воскресенское (поселение, Москва)","revision":155525816,"qid":"Q4373597","license":"CC BY-SA 4.0"},"Q4373596":{"text":"Поселе́ние Во́роновское — бывшее внутригородское муниципальное образование и административная единица со статусом поселения в составе Троицкого административного округа, Москва. Вошло в состав Москвы 1 июля 2012 года. Упразднено 8 мая 2024 года в процессе административно-территориальной реформы ТиНАО. Правопреемником поселения Вороновское являются органы…","title":"Вороновское (поселение, Москва)","revision":156111298,"qid":"Q4373596","license":"CC BY-SA 4.0"},"Q4525087":{"text":"Театр на Тру́бной — драматический театр, созданный в 1989 году в Москве.","title":"Театр на Трубной","revision":152210034,"qid":"Q4525087","license":"CC BY-SA 4.0"},"Q4332610":{"text":"ОКО — (сокращение от «объединённые кристаллом основания») комплекс небоскрёбов, расположенных на участке 16 Московского международного делового центра «Москва-Сити». Южная башня комплекса является третьим по высоте среди полностью достроенных зданий в Европе. Правительство Москвы купило у собственника башен — фирмы Capital Group — 55 000 м² недвижимости.…","title":"Око (комплекс небоскрёбов)","revision":148084471,"qid":"Q4332610","license":"CC BY-SA 4.0"},"Q635860":{"text":"Изма́йлово — район в Восточном административном округе города Москвы, а также одноимённое внутригородское муниципальное образование. Располагается к востоку от Московского железнодорожного кольца. На территории района много исторических и архитектурных памятников. В состав района входит, помимо жилой застройки, западная часть Измайловского лесопарка.","title":"Измайлово (район Москвы)","revision":155553151,"qid":"Q635860","license":"CC BY-SA 4.0"},"Q2622887":{"text":"Ма́рьина Ро́ща — район Москвы к северу от Садового кольца в Северо-Восточном административном округе, а также одноимённое внутригородское муниципальное образование.","title":"Марьина Роща (район Москвы)","revision":155509559,"qid":"Q2622887","license":"CC BY-SA 4.0"},"Q2359096":{"text":"Ра́менки — район в Москве, расположенный в Западном административном округе, а также соответствующее ему одноимённое внутригородское муниципальное образование. Располагаются примерно на умеренном юго-западе города. Граница района с севера проходит по оси Третьего транспортного кольца, с Запада — по колее Киевского направления Московской железной дороги и…","title":"Раменки (район Москвы)","revision":152642782,"qid":"Q2359096","license":"CC BY-SA 4.0"},"Q2320761":{"text":"Пре́сненский район — район в Москве, расположенный в Центральном административном округе, и одноимённый муниципальный округ Пресненский. На территории района находятся Дом Правительства РФ, международный бизнес-центр Москва-Сити, Центр международной торговли, Московский планетарий и туристический квартал «Патриаршие пруды». В Пресненском районе имеется…","title":"Пресненский район","revision":154836790,"qid":"Q2320761","license":"CC BY-SA 4.0"},"Q462400":{"text":"Ю́го-За́падный администрати́вный о́круг (ЮЗАО) — один из 12 административных округов Москвы, находится на юго-западе города, разделён на 12 районов. Код ОКАТО — 45 293 000 000. Занимает территорию в 111,3622 км², образован за границами исторического города и простирается от площади Гагарина за МКАД. Население — 1 416 152 чел. (2025), что составляет 10.67 %…","title":"Юго-Западный административный округ","revision":154453073,"qid":"Q462400","license":"CC BY-SA 4.0"},"Q1412002":{"text":"Кита́й-го́род — исторический район Москвы внутри Китайгородской крепостной стены, пристроенной в 1538 году к угловым башням Московского Кремля: Беклемишевской и Арсенальной. После разрушений в XIX—XX веках сохранились лишь небольшие участки древней стены Китай-города. Китай-город начинается от Красной площади, граничит на севере с Охотным Рядом,…","title":"Китай-город","revision":156081911,"qid":"Q1412002","license":"CC BY-SA 4.0"},"Q2365484":{"text":"Астраха́нский ордена Трудового Красного Знамени государственный природный биосферный запове́дник — заповедник в дельте реки Волги в Астраханской области России. Включён во Всемирную сеть биосферных резерватов. Относится к водно-болотным угодьям международного значения.","title":"Астраханский заповедник","revision":154897819,"qid":"Q2365484","license":"CC BY-SA 4.0"},"Q1962799":{"text":"Черта́ново Се́верное — район в Южном административном округе Москвы и соответствующее ему одноимённое внутригородское муниципальное образование. На территории района находится уникальный для Москвы жилой комплекс — микрорайон Северное Чертаново, построенный в 1978—1980 годах.","title":"Чертаново Северное","revision":154836739,"qid":"Q1962799","license":"CC BY-SA 4.0"},"Q1112926":{"text":"Черёмушки — район в Юго-Западном административном округе Москвы, а также одноимённое внутригородское муниципальное образование. Известен своими панельными домами — «хрущёвками», построенными в 1950-е и 1960-е годы, и в настоящее время заменяемыми в ходе проекта замены жилого фонда. Имеется ряд архитектурных достопримечательностей, парк. Различают…","title":"Черёмушки (район Москвы)","revision":156297607,"qid":"Q1112926","license":"CC BY-SA 4.0"},"Q462490":{"text":"Се́веро-За́падный администрати́вный о́круг (СЗАО) — один из двенадцати административных округов города Москвы. Включает 8 районов. Образован на территории бывших Тушинского и Ворошиловского районов. Более 46 % площади Северо-Западного административного округа занимают природные ландшафты — лесопарковые массивы, водоёмы, заповедные зоны. СЗАО считается…","title":"Северо-Западный административный округ","revision":154660227,"qid":"Q462490","license":"CC BY-SA 4.0"},"Q462247":{"text":"Се́веро-Восто́чный администрати́вный о́круг (СВАО) — один из 12 административных округов города Москвы. Находится на севере города. Содержит 17 районов. Код ОКАТО — 45 280 000 000. На территории округа расположены станции Калужско-Рижской, Серпуховско-Тимирязевской и Люблинско-Дмитровской линий метро, Московской и Октябрьской железных дорог, МЦД D2, D3 и…","title":"Северо-Восточный административный округ","revision":154598611,"qid":"Q462247","license":"CC BY-SA 4.0"},"Q99296":{"text":"Природно-исторический парк «Би́тцевский лес» — особо охраняемая природная территория, второй по величине парк Москвы (2208,4 га), уступающий по размерам только парку Лосиный Остров. Протяжённость парка с севера на юг — 10 км, с запада на восток — 1,5—4 км. Назван по реке Битце, пересекающей южную окраину леса в восточном направлении. Битцевский лес имеет…","title":"Битцевский лес","revision":154336842,"qid":"Q99296","license":"CC BY-SA 4.0"},"Q1504212":{"text":"Дом на на́бережной (официальное название — Дом правительства; также известен как Первый Дом Советов, Дом ЦИК и СНК СССР) — жилой комплекс постройки 1931 года на Берсеневской набережной Москвы-реки. До 1952 года был самым высоким жилым зданием Москвы. Памятник архитектуры конструктивизма. Известен как место жительства советской элиты, пострадавшей в ходе…","title":"Дом на набережной","revision":154429582,"qid":"Q1504212","license":"CC BY-SA 4.0"},"Q961888":{"text":"Садо́вое кольцо́ — круговая магистральная система улиц в центре Москвы. Длина — 15,6 км, ширина — 60—70 м.","title":"Садовое кольцо","revision":154862317,"qid":"Q961888","license":"CC BY-SA 4.0"},"Q4381071":{"text":"Проспе́кт Акаде́мика Са́харова (до 1990 года неофициально назывался Новоки́ровский проспе́кт) — проспект в Центральном административном округе города Москвы на территории Красносельского района.","title":"Проспект Академика Сахарова (Москва)","revision":155516088,"qid":"Q4381071","license":"CC BY-SA 4.0"},"Q4373607":{"text":"Поселе́ние Первома́йское — бывшее поселение (муниципальное образование и административная единица) в составе Троицкого административного округа города Москвы. Упразднено 8 мая 2024 года в процессе административно-территориальной реформы ТиНАО. Правопреемником поселения Первомайское являются органы местного самоуправления и управа Филимонковского района.…","title":"Первомайское (поселение, Москва)","revision":151050745,"qid":"Q4373607","license":"CC BY-SA 4.0"},"Q646334":{"text":"Здание на Лубянской площади в Москве, с 1919 года служащее основным зданием органов госбезопасности РСФСР, СССР, а потом и России, было построено в конце XIX века по заказу страхового общества «Россия» как доходный дом. Работами руководили архитекторы Николай Проскурнин, Александр Иванов, Виктор Величкин. После Октябрьской революции здание перешло в…","title":"Здание органов госбезопасности на Лубянке","revision":155907816,"qid":"Q646334","license":"CC BY-SA 4.0"},"Q4373602":{"text":"Поселение Клёновское — бывшее муниципальное образование и административная единица со статусом поселение в составе Троицкого административного округа Москвы. Административный центр — село Клёново. Согласно проекту расширения территории Москвы, с 1 июля 2012 года входило в состав города. Упразднено 8 мая 2024 года в процессе административно-территориальной…","title":"Клёновское (поселение, Москва)","revision":156111301,"qid":"Q4373602","license":"CC BY-SA 4.0"},"Q4374545":{"text":"Вну́ково — посёлок при станции в Новомосковском административном округе Москвы (до 1 июля 2012 года был в составе Ленинского района Московской области). Входит в состав поселения Внуковское.","title":"Внуково (посёлок станции, Москва)","revision":153346367,"qid":"Q4374545","license":"CC BY-SA 4.0"},"Q2364279":{"text":"Некра́совка — район в Юго-Восточном административном округе Москвы, а также соответствующее ему муниципальное образование. Район расположен за МКАД. Фактически состоит из трёх частей: «старой» Некрасовки (жилой посёлок работников станции аэрации), промзоны (станция аэрации и прилегающие предприятия) и Люберецких полей (новый жилой район, соединён с…","title":"Некрасовка (район Москвы)","revision":156099643,"qid":"Q2364279","license":"CC BY-SA 4.0"},"Q425824":{"text":"Беску́дниковский райо́н — район в Северном административном округе города Москвы. Району соответствует внутригородское муниципальное образование муниципальный округ Бескудниковский.","title":"Бескудниковский район","revision":154899008,"qid":"Q425824","license":"CC BY-SA 4.0"},"Q2367455":{"text":"Лиано́зово — район в Северо-Восточном административном округе города Москвы, а также одноимённое внутригородское муниципальное образование. В северной части района располагается Лианозовский парк культуры и отдыха.","title":"Лианозово (район Москвы)","revision":156089551,"qid":"Q2367455","license":"CC BY-SA 4.0"},"Q1019199":{"text":"Вешняки́ — район в Восточном административном округе города Москвы и одноимённое внутригородское муниципальное образование. Территория района по данным Мосгорстата составляет 1067 га (на сайте управы указано 1072,4 га). Население — 121 088 чел. (2025). Включает в себя исторические местности Вешняки, Владычино и Кусково, граничит на севере с районами…","title":"Вешняки (район Москвы)","revision":156279928,"qid":"Q1019199","license":"CC BY-SA 4.0"},"Q2366010":{"text":"Академи́ческий райо́н (Академический) — район в Москве. Расположен в Юго-Западном административном округе. Району соответствует внутригородское муниципальное образование — муниципальный округ Академический в городе Москве. Территория района составляет 557 га.","title":"Академический район (Москва)","revision":154899321,"qid":"Q2366010","license":"CC BY-SA 4.0"},"Q598088":{"text":"Щу́кино — район в Москве, расположенный в Северо-Западном административном округе, а также одноимённое внутригородское муниципальное образование Москвы на берегу Москвы-реки. Территория района ограничена с запада руслом реки Москвы и каналом имени Москвы, с севера Рижским направлением МЖД, с востока Малым кольцом МЖД, с юга и юго-запада улицей Берзарина.…","title":"Щукино (район Москвы)","revision":151839695,"qid":"Q598088","license":"CC BY-SA 4.0"},"Q2458029":{"text":"Чи́стые пруды́, официально также Чистый пруд (в настоящее время пруд только один) — пруд в Москве. Исторически у стен Белого города; с XVIII века — на Чистопрудном бульваре. Это название также носит и парковая зона на бульваре.","title":"Чистые пруды","revision":152522192,"qid":"Q2458029","license":"CC BY-SA 4.0"},"Q4146725":{"text":"Госуда́рственный музе́й исто́рии росси́йской литерату́ры и́мени В. И. Да́ля (сокр. ГМИРЛИ), также исторически известный как Государственный литерату́рный музе́й (ГЛМ) — крупнейший в России музей истории российской литературы, созданный по инициативе Владимира Бонч-Бруевича. По состоянию на 2021 год в состав музея входят 12 отделов, фонды состоят из более…","title":"Государственный литературный музей","revision":155682785,"qid":"Q4146725","license":"CC BY-SA 4.0"},"Q3031250":{"text":"«Вы́ставочный центр» — закрытая станция Московского монорельса. Располагается между станциями «Улица Академика Королёва» и «Улица Сергея Эйзенштейна». Находится на территории Останкинского района Северо-Восточного административного округа города Москвы. Имела переход на станцию метро ВДНХ Калужско-Рижской линии. Названа в честь Всероссийского выставочного…","title":"Выставочный центр (станция монорельса)","revision":156103596,"qid":"Q3031250","license":"CC BY-SA 4.0"},"Q4109489":{"text":"Веско́вский переу́лок (ранее Лесной проезд) — переулок в Тверском районе ЦАО города Москвы. Проходит от 1-й Миусской улицы до Долгоруковской улицы. Нумерация домов ведётся от Миусской улицы.","title":"Весковский переулок","revision":145748797,"qid":"Q4109489","license":"CC BY-SA 4.0"},"Q2308006":{"text":"Спа́со-ха́ус (англ. Spaso House, от сокращения названия Спасопесковской площади), или особня́к Вто́рова, — исторический особняк в центре Москвы, с конца 1933 года арендуется правительством США как резиденция посла США в СССР или России. Памятник неоклассической архитектуры предреволюционного времени, расположен по адресу: Спасопесковский переулок, 10.","title":"Спасо-хаус","revision":153641610,"qid":"Q2308006","license":"CC BY-SA 4.0"},"Q4473896":{"text":"Улица Сальвадо́ра Алье́нде — улица в районе Сокол Северного административного округа города Москвы, названная в честь чилийского государственного и политического деятеля Сальвадора Альенде.","title":"Улица Сальвадора Альенде","revision":154454256,"qid":"Q4473896","license":"CC BY-SA 4.0"},"Q4366595":{"text":"Пого́динская изба́ — историческое здание на Девичьем поле в Москве, построенное по проекту архитектора Николая Никитина в дар историку и коллекционеру Михаилу Погодину на средства предпринимателя Василия Кокорева. Представляет собой высокий деревянный сруб, оформленный в традициях народного деревянного зодчества. Постройка этой избы дала толчок развитию…","title":"Погодинская изба","revision":154935357,"qid":"Q4366595","license":"CC BY-SA 4.0"},"Q4365571":{"text":"Площадь Ильи́нские Воро́та (Ильи́нский проезд) — площадь в Москве, расположенная в Тверском районе между улицей Ильинкой, Лубянским проездом, Старой и Новой площадями.","title":"Ильинские Ворота (площадь)","revision":151681813,"qid":"Q4365571","license":"CC BY-SA 4.0"},"Q4087179":{"text":"Бирюлёвский дендрарий (Бирюлёвский дендропарк, в 1950-х годах также был известен как дендропарк Управления озеленения Москвы) — парк-питомник, созданный в 1938 году под руководством дендролога Всеволода Константиновича Порозова. Заложен в форме маточного сада с парковым типом планировки и перспективой превращения в коллекционный сад, то есть в декоративный…","title":"Бирюлёвский дендрарий","revision":156358407,"qid":"Q4087179","license":"CC BY-SA 4.0"},"Q4249235":{"text":"Куско́во — бывшее подмосковное село, с 1925 года ставшее городом, который уже в 1938 году вошёл в состав города Перово. Вблизи села располагалась усадьба Шереметевых «Кусково».","title":"Кусково (Москва)","revision":151084542,"qid":"Q4249235","license":"CC BY-SA 4.0"},"Q4297959":{"text":"«Миха́лково» — усадьба, принадлежавшая княжеским родам Дашковых и Паниных. Неоднократно перестраивалась, основной архитектурный ансамбль был сформирован в 1780—1784 годах по проекту Василия Баженова. До конца XVIII века являлась одной из самых красивых усадеб Подмосковья. С начала XIX века стала местом расположения ситцевой фабрики и рабочего посёлка. В…","title":"Михалково (усадьба)","revision":155902111,"qid":"Q4297959","license":"CC BY-SA 4.0"},"Q2091312":{"text":"Це́рковь Благове́щения на Жи́тном дворе́ (Церковь Благовещения Пресвято́й Богоро́дицы, что на Житном дворе) — утраченный православный храм в Москве, находившийся в Московском Кремле у Благовещенской башни. Была построена в 1731 году. Разрушена в 1932 году.","title":"Церковь Благовещения на Житном дворе","revision":154298367,"qid":"Q2091312","license":"CC BY-SA 4.0"},"Q97662741":{"text":"Парк Света — парк на северо-востоке Москвы, расположенный в районе Бибирево. Общая площадь составляет 7,5 га. Парк был разбит на территории старого сквера вдоль Костромской улицы, со временем пришедшего в запустение. Открытие состоялось 23 августа 2019 года после завершения работ по комплексному благоустройству территории в рамках программы «Мой район».…","title":"Парк Света","revision":154526198,"qid":"Q97662741","license":"CC BY-SA 4.0"},"Q108185938":{"text":"Сквер Промышленников Прохоровых — сквер в Пресненском районе Центрального административного округа Москвы, расположенный между Большим Предтеченским переулком и Нововаганьковским переулком вблизи пересечения их с Малым Предтеченским переулком. Название безымянному скверу присвоено постановлением Правительства Москвы от 4 сентября 2018 года. Сквер посвящён…","title":"Сквер Промышленников Прохоровых","revision":146913270,"qid":"Q108185938","license":"CC BY-SA 4.0"},"Q626920":{"text":"Арба́т — исторический и административный район в Москве, а также внутригородское муниципальное образование. Район находится на территории Центрального административного округа к западу от Кремля. Площадь территории района — 211 га. Численность населения — 26,9 тыс. человек (на 1 января 2010 года). На территории находятся важные министерства: Минобороны…","title":"Арбат (район Москвы)","revision":154598529,"qid":"Q626920","license":"CC BY-SA 4.0"},"Q862100":{"text":"Хамо́вники — район города Москвы, расположенный в Центральном административном округе, а также одноимённое внутригородское муниципальное образование. Расположен в излучине Москвы-реки.","title":"Хамовники","revision":154598556,"qid":"Q862100","license":"CC BY-SA 4.0"},"Q4074570":{"text":"Ба́бушкин (до 1939 года — Лосиноостро́вская) — бывший подмосковный город в Мытищинском районе, в августе 1960 года вошедший в состав Москвы. Получил название в честь полярного лётчика, Героя Советского Союза Михаила Бабушкина, родившегося и выросшего в тех местах.","title":"Бабушкин (Москва)","revision":155828931,"qid":"Q4074570","license":"CC BY-SA 4.0"},"Q942798":{"text":"Тага́нский район — район Центрального административного округа Москвы. Расположен к востоку и юго-востоку от исторического центра города — Зарядья и Китай-города, по левому (северному) берегу реки Москвы. Району соответствует внутригородское муниципальное образование муниципальный округ Таганский. Территория района, заселявшаяся с запада на восток, начиная…","title":"Таганский район","revision":154597259,"qid":"Q942798","license":"CC BY-SA 4.0"},"Q2360436":{"text":"Отра́дное — район в Москве, расположенный в Северо-Восточном административном округе, а также соответствующее ему одноимённое внутригородское муниципальное образование.","title":"Отрадное (район Москвы)","revision":154518835,"qid":"Q2360436","license":"CC BY-SA 4.0"},"Q1627784":{"text":"«ВДНХ» — станция Московского метрополитена на Калужско-Рижской линии. Расположена на границе Останкинского и Алексеевского районов (СВАО). Открыта 1 мая 1958 года в составе участка «Ботанический сад» — «ВСХВ» (ныне «ВДНХ»). Пилонная трёхсводчатая станция глубокого заложения с одной островной платформой; на момент открытия — самая глубокая станция…","title":"ВДНХ (станция метро)","revision":156021293,"qid":"Q1627784","license":"CC BY-SA 4.0"},"Q2366899":{"text":"Новогире́ево — район в Восточном административном округе города Москвы и одноимённое внутригородское муниципальное образование. Район Новогиреево занимает территорию в 445,29 га. Население — 99 906 чел. (2025). Площадь жилого фонда на 1 января 2010 года составила 1704 тыс. м². Адрес управы: Зелёный проспект, дом 20. Глава управы — Чернов Дмитрий…","title":"Новогиреево (район Москвы)","revision":154899033,"qid":"Q2366899","license":"CC BY-SA 4.0"},"Q1963403":{"text":"Капо́тня — район, расположенный в Юго-Восточном административном округе и соответствующее ему одноимённое внутригородское муниципальное образование в городе Москве. В течение долгого времени считался самым экологически неблагоприятным районом Москвы из-за нахождения тут Московского нефтеперерабатывающего завода, который в 2011 году начал проведение…","title":"Капотня (район Москвы)","revision":153666834,"qid":"Q1963403","license":"CC BY-SA 4.0"},"Q1963039":{"text":"Нага́тино-Садо́вники — район в Южном административном округе Москвы и соответствующее ему одноимённое внутригородское муниципальное образование.","title":"Нагатино-Садовники","revision":154598687,"qid":"Q1963039","license":"CC BY-SA 4.0"},"Q4477577":{"text":"Де́тский парк «Уса́дьба Трубецки́х в Хамо́вниках» (известный также как парк Мандельшта́ма, ранее также Немчи́новский сад) — небольшой парк в Москве, бывшая подмосковная усадьба князей Трубецких. Расположен рядом с Комсомольским проспектом между улицами Усачёвой, Трубецкой, Ефремова и переулком Хользунова. Открыт для посещения только в дневное время.","title":"Усадьба Трубецких в Хамовниках","revision":146204911,"qid":"Q4477577","license":"CC BY-SA 4.0"},"Q4504300":{"text":"Центральный дом работников искусств (ЦДРИ) в Москве — культурно-просветительное учреждение; творческий клуб деятелей искусства (театра, изобразительного искусства, музыки, эстрады и др.). Этот дом работников искусств, созданный по инициативе наркома просвещения Анатолия Луначарского, был открыт 25 февраля 1930 года. ЦДРИ — единственный творческий дом в…","title":"Центральный дом работников искусств","revision":155681398,"qid":"Q4504300","license":"CC BY-SA 4.0"},"Q913949":{"text":"Су́харева башня — памятник русской гражданской архитектуры, построенный в 1695 году в Москве по проекту Михаила Чоглокова на пересечении Садового кольца, Сретенки и 1-й Мещанской улицы (ныне проспект Мира). Была разрушена в 1934 году в рамках Генеральной реконструкции Москвы. Образец сооружения в стиле «московского барокко». Имеются планы восстановления…","title":"Сухарева башня","revision":156249526,"qid":"Q913949","license":"CC BY-SA 4.0"},"Q4514073":{"text":"Черноморский бульвар — бульвар в Южном и Юго-Западном административных округах города Москвы. Проходит от Варшавского шоссе до Азовской улицы. Пересекает Симферопольский бульвар. Справа примыкают Артековская и Ялтинская улицы. Нумерация домов ведётся от Варшавского шоссе.","title":"Черноморский бульвар","revision":153121512,"qid":"Q4514073","license":"CC BY-SA 4.0"},"Q3954120":{"text":"Здание Министерства иностранных дел — одна из семи построенных «сталинских высоток». Возведено в 1948—1953 годах по проекту архитекторов В. Г. Гельфрейха, М. А. Минкуса и конструкторов Г. М. Лимановского и С. Д. Гомберга для Министерства иностранных дел СССР.","title":"Здание Министерства иностранных дел России","revision":156132251,"qid":"Q3954120","license":"CC BY-SA 4.0"},"Q19908995":{"text":"Общественное пространство Москвы, городской культурно-просветительский центр «Зарядье» — объект в одноимённом историческом районе Москвы, созданный на месте снесённой в 2006 году гостиницы «Россия». Расположен на территории площадью в 13 га между Китайгородским проездом, улицей Варваркой и Москворецкой набережной. Построен в 2014—2017 годы по проекту…","title":"Зарядье (парк)","revision":155609031,"qid":"Q19908995","license":"CC BY-SA 4.0"},"Q60829545":{"text":"Памятник Исламу Каримову — монумент британского скульптора Пола Дэя, созданный в 2018 году. Посвящён первому президенту Узбекистана Исламу Каримову и находится в сквере его имени в Москве, столице России.","title":"Памятник Исламу Каримову","revision":154527621,"qid":"Q60829545","license":"CC BY-SA 4.0"},"Q115291033":{"text":"Памятник Фиделю Кастро установлен в 2022 году в Москве, в районе Сокол на площади Фиделя Кастро (на пересечении Новопесчаной и 2-й Песчаной улиц). Авторы памятника — скульптор Алексей Чебаненко и архитектор Андрей Белый.","title":"Памятник Фиделю Кастро (Москва)","revision":151659743,"qid":"Q115291033","license":"CC BY-SA 4.0"},"Q2366712":{"text":"Хорошёвский райо́н — район в Москве, расположенный на юго-западе Северного административного округа. Району соответствует внутригородское муниципальное образование муниципальный округ Хорошёвский.","title":"Хорошёвский район","revision":154123077,"qid":"Q2366712","license":"CC BY-SA 4.0"},"Q2367469":{"text":"Се́верное Ту́шино — район и муниципальный округ Северо-Западного административного округа Москвы. Граница проходит по оси МКАД, Химкинского водохранилища, далее по осям северного проезда Химкинского бульвара, бульвара Яна Райниса и улицы Саломеи Нерис до МКАД. Муниципалитет граничит с районами Южное Тушино, Митино, Куркино и Левобережный , а также с…","title":"Северное Тушино","revision":154896576,"qid":"Q2367469","license":"CC BY-SA 4.0"},"Q4165827":{"text":"Домик Каширина — музей, расположенный в Нижнем Новгороде, Почтовый съезд, д. 21, в доме деда М. Горького (А. М. Пешкова) по материнской линии. Объект культурного наследия народов РФ федерального значения. Описан в повести «Детство». Одноэтажный, на полуподвале деревянный дом, в пяти комнатах которого проживала семья из шестнадцати человек. Интерьеры…","title":"Домик Каширина","revision":154861775,"qid":"Q4165827","license":"CC BY-SA 4.0"},"Q2921906":{"text":"Покро́вский бульвар — бульвар в Басманном районе Центральном административном округе города Москвы. Назван по улице Покровка и Покровским воротам Белого города. Проходит от Хохловской площади (Хохловского переулка) на севере до улицы Воронцово Поле (Яузского бульвара) на юге. Нумерация домов ведётся от площади Покровские Ворота, захватывая дома по внешним…","title":"Покровский бульвар","revision":154116750,"qid":"Q2921906","license":"CC BY-SA 4.0"},"Q4304207":{"text":"Моско́вский моне́тный двор — филиал акционерного общества «Гознак», один из двух действующих монетных дворов в России (наряду с Санкт-Петербургским). Предприятие специализируется на изготовлении государственных заказов по выпуску разменных и памятных монет, государственных наград, медалей и орденов. Помимо этого, двор выполняет заказы на чеканку монет для…","title":"Московский монетный двор","revision":152050119,"qid":"Q4304207","license":"CC BY-SA 4.0"},"Q1988060":{"text":"Сандуно́вские бани (в просторечии Сандуны́) — действующие с 1808 года публичные бани, памятник архитектуры в стиле бозар. Расположены в центре Москвы на углу Неглинной улицы и Сандуновского переулка. Архитектор — Борис Фрейденберг. В конце XIX века бани пользовались большой популярностью и считались передовыми благодаря своим тогдашним владельцам Алексею…","title":"Сандуновские бани","revision":151687545,"qid":"Q1988060","license":"CC BY-SA 4.0"},"Q4060405":{"text":"Алабя́но-Балти́йский тонне́ль (Балти́йский тонне́ль) — автомобильный тоннель в Москве, соединяющий территории районов Сокол, Аэропорт и Коптево; составная часть развязки на Соколе. Тоннель — транзитом через Балтийскую улицу — соединил улицу Алабяна и Большую Академическую улицу, входит в состав Северо-Западной хорды. Алабяно-Балтийский тоннель…","title":"Алабяно-Балтийский тоннель","revision":154588839,"qid":"Q4060405","license":"CC BY-SA 4.0"},"Q4304332":{"text":"Московский электромеханический завод имени Владимира Ильича — предприятие в Москве.","title":"Московский электромеханический завод имени Владимира Ильича","revision":151109440,"qid":"Q4304332","license":"CC BY-SA 4.0"},"Q4439075":{"text":"«Совкомбанк Арена» (до июля 2025: «Нижний Новгород») — футбольный стадион международного класса. Расположен в Нижнем Новгороде на Стрелке — месте впадения реки Оки в Волгу. Является домашней ареной футбольного клуба «Нижний Новгород» и используется в качестве многофункционального спортивного комплекса. В рамках чемпионата мира по футболу 2018 года здесь…","title":"Совкомбанк Арена","revision":155691504,"qid":"Q4439075","license":"CC BY-SA 4.0"},"Q4516884":{"text":"Чка́ловская ле́стница — монументальная лестница в историческом центре Нижнего Новгорода, соединяющая Верхне-Волжскую и Нижне-Волжскую набережные, считается визитной карточкой Нижнего Новгорода. Построена по проекту архитекторов Александра Яковлева, Льва Руднева и Владимира Мунца. Проект лестницы был создан и утверждён в 1943 году, а торжественное открытие…","title":"Чкаловская лестница (Нижний Новгород)","revision":155264232,"qid":"Q4516884","license":"CC BY-SA 4.0"},"Q15622071":{"text":"Архитектурно-этнографический музей-заповедник «Щёлоковский хутор» (до 2014 года — Музей архитектуры и быта народов Нижегородского Поволжья в составе Нижегородского государственного историко-архитектурного музея-заповедника) — музей деревянного зодчества под открытым небом в Нижнем Новгороде, расположенный в Советском районе, на 35,9 гектаров территории…","title":"Щёлоковский хутор","revision":155732598,"qid":"Q15622071","license":"CC BY-SA 4.0"},"Q16270969":{"text":"Памятник М. В. Ломоносову на Воробьёвых горах Москвы установлен в центре комплекса зданий Московского университета.","title":"Памятник Ломоносову (Москва, Воробьёвы горы)","revision":155843371,"qid":"Q16270969","license":"CC BY-SA 4.0"},"Q13688221":{"text":"Верхо́вье — деревня в Троицком административном округе Москвы (до 1 июля 2012 года была в составе Наро-Фоминского района Московской области). Входит в состав поселения Первомайское.","title":"Верховье (деревня, Москва)","revision":156272373,"qid":"Q13688221","license":"CC BY-SA 4.0"},"Q16021234":{"text":"Калинино — деревня в Клинском районе Московской области, в составе Воронинского сельского поселения. Население — 3 чел. (2010). До 2006 года Калинино входило в состав Воронинского сельского округа","title":"Калинино (Московская область)","revision":154267102,"qid":"Q16021234","license":"CC BY-SA 4.0"},"Q18406802":{"text":"Дмитриевская (Дмитровская) башня — проездная башня Нижегородского кремля, выходящая на площадь Минина и Пожарского. Считается главными воротами крепости; является неофициальным символом Нижнего Новгорода. Современный облик в русском стиле получила в 1895 году.","title":"Дмитриевская башня","revision":155944387,"qid":"Q18406802","license":"CC BY-SA 4.0"},"Q19692529":{"text":"Ивановская башня — крупнейшая четырёхъярусная воротная башня Нижегородского кремля. Расположена в подгорной части между Часовой и Белой башнями. Через неё проходит нижний отрезок Ивановского съезда, который раньше назывался Большой Мостовой улицей. Названа по расположенной на подступах к ней церкви Иоанна Предтечи. Современный вид башня приобрела в 1950-е…","title":"Ивановская башня","revision":155944517,"qid":"Q19692529","license":"CC BY-SA 4.0"},"Q97198026":{"text":"На́бережная Федоро́вского — набережная в историческом районе Започаинье Нижнего Новгорода. Ранее называлась Верхней набережной Оки, современное название получила в честь выдающегося учёного, доктора геолого-минералогических наук Николая Михайловича Федоровского. В 2021 году набережная стала частью Парка 800-летия Нижнего Новгорода.","title":"Набережная Федоровского","revision":155546652,"qid":"Q97198026","license":"CC BY-SA 4.0"},"Q141737413":{"text":"Kaif Provenance — ресторан в Москве, расположенный на Большой Дмитровке. Был открыт в октябре 2020 года музыкантом Моргенштерном и предпринимателем Эдуардом Поповым, известным как Янис Грек. Первоначально Моргенштерн и Попов владели равными долями управляющего рестораном ООО «Кайф»; в ноябре 2022 года единственным владельцем компании остался Попов.","title":"Kaif Provenance","revision":156168365,"qid":"Q141737413","license":"CC BY-SA 4.0"},"Q191566":{"text":"Западно-Сибирская равнина — равнина, расположенная на севере Азии. Занимает всю западную часть Сибири от Уральских гор на западе до Среднесибирского плоскогорья на востоке. На севере ограничена побережьем Карского моря, на юге простирается до Казахского мелкосопочника, на юго-востоке Западно-Сибирская равнина, постепенно повышаясь, сменяется предгорьями…","title":"Западно-Сибирская равнина","revision":155463989,"qid":"Q191566","license":"CC BY-SA 4.0"},"Q2219087":{"text":"Те́йковский райо́н — административно-территориальная единица (район) и муниципальное образование (муниципальный район) на юго-западе Ивановской области России. Административный центр района — город Тейково (в состав района не входит).","title":"Тейковский район","revision":153524779,"qid":"Q2219087","license":"CC BY-SA 4.0"},"Q558690":{"text":"Нижнева́ртовский райо́н — административно-территориальная единица и муниципальное образование (муниципальный район) в Ханты-Мансийском автономном округе — Югре в составе Тюменской области России. Расположен в восточной части округа и является его самым крупным районом. Административный центр — город Нижневартовск (в район не входит).","title":"Нижневартовский район","revision":153498119,"qid":"Q558690","license":"CC BY-SA 4.0"},"Q2216704":{"text":"Черня́нский райо́н — административно-территориальная единица (район) и муниципальное образование (муниципальный район) в Белгородской области России. Административный центр — пгт Чернянка.","title":"Чернянский район","revision":154279117,"qid":"Q2216704","license":"CC BY-SA 4.0"},"Q2625311":{"text":"«Ле́нинская» — 3-я станция Нижегородского метрополитена. Расположена на Автозаводско-Нагорной линии, между станциями «Чкаловская» и «Заречная». Станция расположена на границе Канавинского и Ленинского районов в микрорайоне Молитовский. Недалеко от станции находится памятный знак, посвященный началу строительства метро в декабре 1977 года.","title":"Ленинская (станция метро, Нижний Новгород)","revision":155319629,"qid":"Q2625311","license":"CC BY-SA 4.0"},"Q4323576":{"text":"Новодви́нская кре́пость — комплекс фортификационных сооружений в дельте реки Северная Двина. Находится в 20 км к северу от центра Архангельска, на северо-западной оконечности острова Линский Прилук, на северной окраине посёлка Конвейер. Административно относится к Маймаксанскому округу Архангельска. Крепость была заложена в 1701 году по личному указанию…","title":"Новодвинская крепость","revision":152152288,"qid":"Q4323576","license":"CC BY-SA 4.0"},"Q4255378":{"text":"Ла́хта — недействующий военный аэродром Военно-морского флота России в 22 км к юго-востоку от города Архангельск. Находится в 4 км юго-западнее города Новодвинск, в 2 км восточнее посёлка Катунино, или Архангельск-27 (в этом посёлке располагался воинский гарнизон). Подразделения, базировавшиеся на аэродроме Лахта, входили в состав авиации Северного флота и…","title":"Лахта (аэродром)","revision":153088111,"qid":"Q4255378","license":"CC BY-SA 4.0"},"Q4123700":{"text":"Волого́дский госуда́рственный о́рдена «Знак почёта» драмати́ческий теа́тр — крупнейший театр Вологодской области и один из старейших в России.","title":"Вологодский драматический театр","revision":156356632,"qid":"Q4123700","license":"CC BY-SA 4.0"},"Q4123684":{"text":"Вологодская областная картинная галерея (ВОКГ) создана в 1952 году на базе художественного отдела Областного краеведческого музея, открыта 12 февраля 1954 года. Единственная в области картинная галерея.","title":"Вологодская областная картинная галерея","revision":153532436,"qid":"Q4123684","license":"CC BY-SA 4.0"},"Q853183":{"text":"Белгородский государственный театр кукол — кукольный театр в Белгороде, ведущий свою историю с 1961 года. Официальный статус театр получил в 1965 году. Создан во многом, благодаря усилиям энтузиаста театрального дела — Антонины Емельяновны Шиковой.","title":"Белгородский театр кукол","revision":150507451,"qid":"Q853183","license":"CC BY-SA 4.0"},"Q4404456":{"text":"Сагра́ — посёлок в Свердловской области России, административно подчинённый городу Верхней Пышме. Входит в городской округ Верхняя Пышма. Ранее Сагра входила в состав Исетского поссовета города Верхней Пышмы.","title":"Сагра (посёлок)","revision":154849554,"qid":"Q4404456","license":"CC BY-SA 4.0"},"Q16023568":{"text":"Смолино — деревня в Наро-Фоминском районе Московской области, входит в состав сельского поселения Волчёнковское. Численность постоянного населения по Всероссийской переписи 2010 года — 14 человек, в деревне числятся 2 улицы и 3 садовых товарищества. До 2006 года Смолино входило в состав Назарьевского сельского округа. Деревня расположена в юго-западной…","title":"Смолино (Московская область)","revision":147628157,"qid":"Q16023568","license":"CC BY-SA 4.0"},"Q16321365":{"text":"Подчерково — село в Дмитровском городском округе Московской области России. Бывший центр Подчёрковской волости. До 1939 года — центр Подчерковского сельсовета. В 1994—2006 годах Подчерково входило в состав Внуковского сельского округа, с 2006 по 2018 год — в состав городского поселения Дмитров Дмитровского района.","title":"Подчерково","revision":152557455,"qid":"Q16321365","license":"CC BY-SA 4.0"},"Q16681048":{"text":"Никулино — деревня в Дмитровском районе Московской области, в составе Сельского поселения Костинское. Население — 29 чел. (2021). До 2006 года Никулино входило в состав Гришинского сельского округа.","title":"Никулино (Дмитровский муниципальный округ)","revision":152557583,"qid":"Q16681048","license":"CC BY-SA 4.0"},"Q24934742":{"text":"Музей истории города Йошкар-Олы — муниципальное бюджетное учреждение культуры в городе Йошкар-Ола. Основан в 1996 году.","title":"Музей истории города Йошкар-Олы","revision":147661356,"qid":"Q24934742","license":"CC BY-SA 4.0"},"Q12102665":{"text":"Дуброва — деревня в Самойловском сельском поселении Бокситогорского района Ленинградской области.","title":"Дуброва (Ленинградская область)","revision":149650111,"qid":"Q12102665","license":"CC BY-SA 4.0"},"Q100696637":{"text":"Театра́льная пло́щадь — площадь в историческом центре Нижнего Новгорода. Находится на пересечении улиц Большой Покровской и Пискунова.","title":"Театральная площадь (Нижний Новгород)","revision":146843672,"qid":"Q100696637","license":"CC BY-SA 4.0"},"Q101435113":{"text":"Музей «Мир забытых вещей» — филиал Вологодского государственного музея-заповедника. Экспозиции музея рассказывают посетителям о быте горожан в дореволюционную эпоху, а также об истории Вологодского портрета.","title":"Мир забытых вещей (музей)","revision":151024294,"qid":"Q101435113","license":"CC BY-SA 4.0"},"Q4453469":{"text":"Теа́тр звере́й и́мени Влади́мира Ду́рова (до 1982 — «Уголок дедушки Дурова») — московский детский театр зверей, основанный 8 января 1912 года дрессировщиком, артистом цирка Владимиром Дуровым. На сцене театра выступают животные.","title":"Театр зверей имени Дурова","revision":152731951,"qid":"Q4453469","license":"CC BY-SA 4.0"},"Q3527555":{"text":"«Ромэ́н» — московский музыкально-драматический театр, основанный в 1931 году Иваном и Георгием Лебедевыми. Режиссёром-постановщиком первой работы театра был Моисей Гольдблат. Театр располагается в здании отеля «Советский», имеет статус Государственного бюджетного учреждения культуры (ГБУК). В его репертуар входят постановки на известные литературные…","title":"Ромэн","revision":154839358,"qid":"Q3527555","license":"CC BY-SA 4.0"},"Q4230096":{"text":"Компрессорный — жилой район (микрорайон) Екатеринбурга, расположенный на юго-востоке города, на удалении 13 км от его центра. Входит в Октябрьский район и представляет собой обособленный микрорайон, соединенный с центром города Сибирским трактом и его дублёром, а также Кольцовским трактом.","title":"Компрессорный (Екатеринбург)","revision":148065900,"qid":"Q4230096","license":"CC BY-SA 4.0"},"Q4189579":{"text":"Зверевский центр современного искусства — московский некоммерческий арт-центр имени Анатолия Зверева.","title":"Зверевский центр современного искусства","revision":147523472,"qid":"Q4189579","license":"CC BY-SA 4.0"},"Q4146878":{"text":"Государственный музей изобразительных искусств Республики Татарстан (сокр. ГМИИ РТ; тат. Татарстан Республикасы дәүләт сынлы сәнгать музее) — один из крупнейших региональных художественных музеев в России.","title":"Государственный музей изобразительных искусств Республики Татарстан","revision":153802888,"qid":"Q4146878","license":"CC BY-SA 4.0"},"Q4235072":{"text":"Ки́ноконце́ртный театр «Ко́смос» — трёхзальный кинотеатр в Екатеринбурге и главный концертный зал города. Архитекторы — Г. И. Белянкин, Н. Н. Надёжин, инженеры — В. В. Бурдакин, Н. В. Максимов. Кинотеатр и само здание находится в муниципальной собственности. Кроме кинотеатра, в здании располагается ресторанный комплекс «Космос», принадлежащий бизнес-клубу…","title":"Космос (киноконцертный театр)","revision":154938003,"qid":"Q4235072","license":"CC BY-SA 4.0"},"Q4441169":{"text":"Старый Английский двор — архитектурно-историческая достопримечательность Москвы (ул. Варварка, 4А). Памятник гражданской архитектуры XV—XVII веков, резиденция английской торговой Московской компании, а во время посольских миссий — Английский посольский дом. Считается первым официальным представительством иностранной державы, сохранившимся в Москве. Здание,…","title":"Старый Английский двор","revision":154285100,"qid":"Q4441169","license":"CC BY-SA 4.0"},"Q4449600":{"text":"Государственный парк культуры и отдыха «Таганский» (в советское время — Ждановский парк) — парк, расположенный на территории Центрального административного округа города Москвы, в районе Таганский.","title":"Таганский парк (Москва)","revision":155796273,"qid":"Q4449600","license":"CC BY-SA 4.0"},"Q4501032":{"text":"Храм Спа́са Преображе́ния на Болва́новке — православный храм в районе Замоскворечье Центрального административного округа Москвы. Принадлежит к Москворецкому благочинию Московской епархии Русской православной церкви.","title":"Храм Спаса Преображения на Болвановке","revision":142669891,"qid":"Q4501032","license":"CC BY-SA 4.0"},"Q4165209":{"text":"До́м-музе́й Мари́ны Цвета́евой — мемориальный музей, посвящённый жизни поэтессы Марины Цветаевой. Расположен в Москве, в доме по Борисоглебскому переулку, где Цветаева проживала вместе со своей семьёй с 1914 по 1922 год. Открытие музея состоялось в 1992-м по инициативе деятелей культуры, в том числе академика Дмитрия Лихачёва. В настоящее время в музейном…","title":"Дом-музей Марины Цветаевой","revision":151574565,"qid":"Q4165209","license":"CC BY-SA 4.0"},"Q4172358":{"text":"Дюссельдорфский парк (прежнее название — Парк 10-го микрорайона Марьинского Парка) — парк в Юго-Восточном округе Москвы, в районе Марьино. Расположен на пересечении Перервинского бульвара, улиц Белореченской и Новомарьинской.","title":"Дюссельдорфский парк","revision":155103239,"qid":"Q4172358","license":"CC BY-SA 4.0"},"Q16692627":{"text":"Российская госуда́рственная библиоте́ка для молодёжи (РГБМ) — федеральное государственное бюджетное учреждение культуры, специализированная библиотека, обслуживающая молодёжь в возрасте 14—30 лет, а также физические и юридические лица, профессионально занимающиеся проблемами молодёжи. Научный, информационно-консалтинговый центр для публичных библиотек…","title":"Российская государственная библиотека для молодёжи","revision":149133369,"qid":"Q16692627","license":"CC BY-SA 4.0"},"Q16702698":{"text":"Театр «Студия театрального искусства» («СТИ») — федеральный драматический театр в Москве под руководством Сергея Женовача. Основан в 2005 году.","title":"Студия театрального искусства","revision":153400530,"qid":"Q16702698","license":"CC BY-SA 4.0"},"Q23687347":{"text":"Дом с атлантами — обиходное название бывшего доходного дома с чайным магазином Торгового дома «Д. и А. Расторгуевы» на улице Солянка в Москве. Дом построен в 1882 г. по проекту архитектора В. Н. Карнеева. Расположен на исторической территории Белого города (урочище Кулишки). Выявленный объект культурного наследия; входит в состав пяти кварталов…","title":"Дом с атлантами на Солянке","revision":155950178,"qid":"Q23687347","license":"CC BY-SA 4.0"},"Q27921892":{"text":"Доходный дом купца Чувильдина (косой дом) — бывший доходный дом в Екатеринбурге, принадлежавший купцу Василию Ивановичу Чувильдину. Является памятником истории и архитектуры регионального (областного) значения с 2015 года. Входит в туристический маршрут «Красная линия» Екатеринбурга.","title":"Доходный дом купца Чувильдина","revision":154981312,"qid":"Q27921892","license":"CC BY-SA 4.0"},"Q54996579":{"text":"Дом-музе́й А. П. Че́хова — отдел Государственного литературного музея (Государственного музея истории российской литературы имени В. И. Даля), посвящённый жизни и литературной деятельности писателя Антона Павловича Чехова, располагается в Москве в доме на Садовой-Кудринской улице, где драматург проживал со своей семьёй с 1886 по 1890 год. Открытие…","title":"Дом-музей А. П. Чехова (Москва)","revision":146770718,"qid":"Q54996579","license":"CC BY-SA 4.0"},"Q60851703":{"text":"Преображе́нский ры́нок — продуктовый рынок в Москве, в районе Преображенское на улице Преображенский Вал, 17.","title":"Преображенский рынок","revision":151570173,"qid":"Q60851703","license":"CC BY-SA 4.0"},"Q60851981":{"text":"Ленингра́дский ры́нок — продуктовый рынок в Москве на Часовой улице, расположенный неподалёку от станций метро «Сокол» и «Аэропорт». Существует с 1963 года. В XIX веке на месте современного района Аэропорт находилось село Всехсвятское. На его территории, на пересечении современных улиц Черняховского и Усиевича, существовал рынок, называемый Инвалидным — по…","title":"Ленинградский рынок","revision":147346123,"qid":"Q60851981","license":"CC BY-SA 4.0"},"Q56062360":{"text":"Усадьба Сабитовых — комплекс исторических зданий в Казани, в Старо-Татарской слободе, на улице Шигабутдина Марджани, дом 8. Построен во второй половине XIX века. Объект культурного наследия местного значения.","title":"Усадьба Сабитовых","revision":155017811,"qid":"Q56062360","license":"CC BY-SA 4.0"},"Q1577987":{"text":"Политехни́ческий музе́й (Полите́х) — один из старейших научно-технических музеев мира, расположен в Москве на Новой площади. Образован в 1872 году по инициативе Общества любителей естествознания, антропологии и этнографии при активном участии профессоров Московского университета Григория Щуровского, Анатолия Богданова и Августа Давидова. В основу фондов…","title":"Политехнический музей","revision":154327005,"qid":"Q1577987","license":"CC BY-SA 4.0"},"Q1186561":{"text":"Госуда́рственный академи́ческий теа́тр и́мени Евгения Вахта́нгова — драматический театр в Москве. Был образован в 1913 году как Студенческая драматическая студия, руководил которой Евгений Вахтангов. Официальной датой открытия 3-й студии Московского Художественного театра (МХАТ) считается 13 ноября 1921 года, в этот день был показан спектакль «Чудо святого…","title":"Театр имени Е. Б. Вахтангова","revision":155950196,"qid":"Q1186561","license":"CC BY-SA 4.0"},"Q4146855":{"text":"Государственный музей Владимира Высоцкого («Дом Высоцкого на Таганке») — культурный и научный центр, занимающийся сбором, хранением и изучением материалов, отражающих жизнь и творчество Владимира Семёновича Высоцкого, а также эпоху, в которой он жил. Здание музея расположено по адресу: Москва, улица Высоцкого, дом 3, строение 1.","title":"Музей Владимира Высоцкого","revision":153101417,"qid":"Q4146855","license":"CC BY-SA 4.0"},"Q4453482":{"text":"Теа́тр Ми́мики и Же́ста — первый в мире стационарный профессиональный театр глухих актёров. Создан как студия в 1917 году в Петрограде, вскоре после этого переехал в Москву, с 1963 — стационарный. Спектакли театра основаны на выразительности жестового языка глухих, на пластике, элементах пантомимы, музыки, танца. Происходящее на сцене синхронно озвучивают…","title":"Театр мимики и жеста (Москва)","revision":154937136,"qid":"Q4453482","license":"CC BY-SA 4.0"},"Q4500889":{"text":"Храм Преподобного Сергия Радонежского в Крапивниках — православный храм в Тверском районе Москвы. Входит в состав Иверского благочиния Московской епархии Русской православной церкви, является подворьем патриарха Московского и всея Руси. Архитектор (предположительно) Дмитрий Ухтомский.","title":"Храм Сергия Радонежского в Крапивниках","revision":147847820,"qid":"Q4500889","license":"CC BY-SA 4.0"},"Q4338224":{"text":"Особня́к Рябуши́нского — городская усадьба, построенная архитектором Фёдором Шехтелем для предпринимателя Степана Рябушинского в 1900—1903 годах. Является одним из наиболее репрезентативных примеров раннего модерна в русской архитектуре. С 1965 года в здании располагается музей-квартира Горького.","title":"Особняк С. П. Рябушинского","revision":153641848,"qid":"Q4338224","license":"CC BY-SA 4.0"},"Q13668656":{"text":"Дом Ярошенко — жилое здание в центре Москвы, в Подколокольном переулке. Объект культурного наследия регионального значения, внесён в реестр под названием: «Торговые ряды П. В. Степанова — ночлежный дом Е. П. Ярошенко. 1860-е — 1880-е гг., палаты стольника Е. И. Бутурлина. 1660-е гг.» Дом Ярошенко находится на исторической территории Белого города урочища…","title":"Дом Ярошенко","revision":152217066,"qid":"Q13668656","license":"CC BY-SA 4.0"},"Q21641924":{"text":"Музей землеведения МГУ — учебный музей по наукам о Земле и землеведению, для студентов МГУ и организованных групп посетителей. Является подразделением МГУ. Экспонаты музея охватывают науки географического и геологического цикла. Экспозиция также раскрывает историю развития естественнонаучных знаний и представлений о Земле. В музее постоянно проводятся…","title":"Музей землеведения МГУ","revision":152603147,"qid":"Q21641924","license":"CC BY-SA 4.0"},"Q20279500":{"text":"Парк Северного речного вокзала, Парк Северного Речного вокзала — парк в Левобережном районе Северного административного округа Москвы. Расположен вдоль Ленинградского шоссе у Химкинского водохранилища. В парке находится здание Северного речного вокзала. В основе планировки — три аллеи, идущие параллельно шоссе и одна перпендикулярно. Площадь парка вместе…","title":"Парк Северного речного вокзала","revision":146626124,"qid":"Q20279500","license":"CC BY-SA 4.0"},"Q21196839":{"text":"Московский Губернский театр (открыт в 2013 году) — театр в Москве, с 2024 года имеющий федеральный статус.","title":"Московский губернский театр","revision":154784336,"qid":"Q21196839","license":"CC BY-SA 4.0"},"Q4304127":{"text":"Московский драматический театр «Бенефис» п/р Анны Неровной — московский театр, основан в 1987 году как экспериментальный театр-студия вскоре после того, как его организатор Анна Неровная была удостоена приза за лучшую режиссуру современной драматургии на Международном театральном фестивале «Лефортовские игры — 87». Инициатива создания репертуарного театра…","title":"Бенефис (театр)","revision":148049718,"qid":"Q4304127","license":"CC BY-SA 4.0"},"Q4085185":{"text":"Берсе́невская на́бережная — набережная на правом берегу Москвы-реки в районе Якиманка Центрального административного округа города Москвы. Проходит от стрелки острова до Большого Каменного моста. Выходит на улицу Серафимовича.","title":"Берсеневская набережная","revision":150157948,"qid":"Q4085185","license":"CC BY-SA 4.0"},"Q4016509":{"text":"Дом-музей Ви́ктора Миха́йловича Васнецо́ва — музей, посвящённый творчеству художника Виктора Васнецова. Расположен в Москве по адресу переулок Васнецова, 13 и входит в состав музейного комплекса Третьяковской галереи. Васнецов самостоятельно спроектировал особняк в неорусском стиле и прожил в нём с 1894 по 1926 год. Музей открылся в 1953 году после…","title":"Дом-музей В. М. Васнецова","revision":147200385,"qid":"Q4016509","license":"CC BY-SA 4.0"},"Q4304209":{"text":"Московский музей анимации — первый в России международный анимационный музей, открытый в 2006 году сотрудниками киностудии «Союзмультфильм». Коллекция экспонатов связана с историей развития анимации и мультипликации в России и за рубежом. В настоящее время основная экспозиция расположена на территории Измайловского Кремля, также музею принадлежит павильон…","title":"Московский музей анимации","revision":151363154,"qid":"Q4304209","license":"CC BY-SA 4.0"},"Q2033910":{"text":"Госуда́рственный Кремлёвский дворе́ц (до 1992 года — Кремлёвский дворец съездов) — общественное здание, расположенное на территории Московского Кремля. Было построено по инициативе Никиты Хрущёва по проекту авторского коллектива под руководством архитектора Михаила Посохина. Предназначался для проведения съездов КПСС, также выполнял функции площадки для…","title":"Государственный Кремлёвский дворец","revision":155948001,"qid":"Q2033910","license":"CC BY-SA 4.0"},"Q3345170":{"text":"Центра́льный дом худо́жника (сокр. ЦДХ) на Крымском Валу — выставочный центр в Москве, учреждение Международной конфедерации союзов художников, один из самых известных комплексов подобного рода в России, существовавший с 1979 года по 2019 год. В годы существования ЦДХ делил одно здание с Третьяковской галереей (Новой Третьяковкой), занимая западную часть…","title":"Центральный дом художника","revision":154190515,"qid":"Q3345170","license":"CC BY-SA 4.0"},"Q4290219":{"text":"Мемориа́льный дом-музе́й акаде́мика Серге́я Королёва — московский мемориальный музей, посвящённый жизни и деятельности Главного конструктора космической техники Сергея Королёва. Официальное открытие состоялось в 1975 году по инициативе жены Нины Ивановны Королёвой, передавшей во владение музея около 19 000 предметов, ставших экспонатами. Учреждение…","title":"Мемориальный дом-музей академика С. П. Королёва","revision":147200368,"qid":"Q4290219","license":"CC BY-SA 4.0"},"Q4453394":{"text":"Теа́тр.dóc — российский театр документальной пьесы. Независимый, негосударственный, некоммерческий, коллективный проект драматургов. Основан Еленой Греминой и Михаилом Угаровым в 2002 году по адресу Трёхпрудный переулок, 11/13, стр. 1; с 2015 года не имеет постоянной площадки. Спектакли театра многократно становились лауреатами профессиональных премий,…","title":"Театр.doc","revision":154220868,"qid":"Q4453394","license":"CC BY-SA 4.0"},"Q4468224":{"text":"Московский государственный театр «У Ники́тских воро́т» — драматический театр, расположенный в Тверском районе города Москвы. Художественный руководитель театра — Марк Розовский.","title":"У Никитских ворот","revision":156289544,"qid":"Q4468224","license":"CC BY-SA 4.0"},"Q4504021":{"text":"Центр оперного пения Галины Вишневской — учебное заведение в Москве, включающее оперный театр (автор проекта архитектор Великанов Александр Александрович). Располагается в специально выстроенном здании на ул. Остоженка (дом 25), являющемся типичным образцом лужковского стиля. Руководитель — оперная певица Г. П. Вишневская (с 2002 по 2012 год). Под…","title":"Центр оперного пения Галины Вишневской","revision":152215772,"qid":"Q4504021","license":"CC BY-SA 4.0"},"Q4441628":{"text":"«Стена Цоя» — стена дома №37 по Арбату, выходящая в Кривоарбатский переулок Москвы, которую поклонники творчества Виктора Цоя исписали надписями «Кино», «Цой жив», цитатами из песен и признаниями в любви музыканту. Представляет собой памятник, символ Арбата и достопримечательность Москвы.","title":"Стена Цоя","revision":154943905,"qid":"Q4441628","license":"CC BY-SA 4.0"},"Q4227959":{"text":"Колледж музыкально-театрального искусства имени Г. П. Вишневской — Государственное бюджетное профессиональное образовательное учреждение города Москвы.","title":"Колледж музыкально-театрального искусства № 61","revision":145719997,"qid":"Q4227959","license":"CC BY-SA 4.0"},"Q2582782":{"text":"Ледовый дворец «Крылатское» (спортивный комплекс «Крылатское») — современный спортивный комплекс для организации соревнований по конькобежному спорту и хоккея с мячом, а также организации тренировок спортсменов, расположенный в городе Москве, в районе Крылатское.","title":"Крылатское (ледовый дворец)","revision":151793158,"qid":"Q2582782","license":"CC BY-SA 4.0"},"Q4395752":{"text":"«Ро́дина» — кинотеатр в Восточном административном округе города Москвы, район Соколиная Гора. Является объектом культурного наследия регионального значения. Здание кинотеатра представляет собой один из наиболее сохранившихся образцов постконструктивизма в Москве и является характерным примером советской кинотеатральной архитектуры 1930-х годов.","title":"Родина (кинотеатр, Москва)","revision":152047453,"qid":"Q4395752","license":"CC BY-SA 4.0"},"Q4379620":{"text":"Провиантские склады — комплекс зданий в стиле ампир в Москве по адресу Зубовский бульвар, дом 2. Одно из немногих крупных московских общественных сооружений 1-й половины XIX века, сохранившихся почти целиком. В настоящее время архитектурный комплекс является зданием музейного объединения «Музей Москвы» (вход со стороны ул. Остоженка, 48).","title":"Провиантские склады (Москва)","revision":154447329,"qid":"Q4379620","license":"CC BY-SA 4.0"},"Q13359071":{"text":"Водовзводная башня — архитектурный памятник на территории музея-заповедника Коломенское. Построена в 70-е годы XVII века для размещения водоподъёмного механизма, снабжавшего водой Государев двор.","title":"Водовзводная башня в Коломенском","revision":151657641,"qid":"Q13359071","license":"CC BY-SA 4.0"},"Q21641853":{"text":"Московский дом композиторов (МДК) — концертная площадка Союза композиторов, а также место проведения музыкальных фестивалей, конференций и конкурсов. В МДК выступали симфонические оркестры под руководством Евгения Светланова, Кирилла Кондрашина, Геннадия Рождественского; струнные квартеты имени Бородина и Бетховена; солисты Святослав Рихтер, Мстислав…","title":"Московский дом композиторов","revision":147342285,"qid":"Q21641853","license":"CC BY-SA 4.0"},"Q55438181":{"text":"Ботанический сад ВИЛАР — ботанический сад в Москве при Всероссийском НИИ лекарственных и ароматических растений. Расположен на юге города в районе Северное Бутово. Основан в 1951 году. Площадь сада составляет около 30 га (или 45 га, считая территорию института). Ботанический сад ВИЛАР имеет статус особо охраняемой природной территории федерального значения.","title":"Ботанический сад ВИЛАР","revision":155969895,"qid":"Q55438181","license":"CC BY-SA 4.0"},"Q54996298":{"text":"Музе́й Сере́бряного ве́ка (Дом Брю́сова) — музей, посвящённый литературным течениям начала XX века: символизму, акмеизму, авангардизму и футуризму. Учреждение было основано в 1999 году как филиал Государственного литературного музея. Располагается в особняке купца Ивана Баева, спроектированном архитектором Владимиром Чагиным в стиле северный модерн. В этом…","title":"Музей Серебряного века","revision":146881971,"qid":"Q54996298","license":"CC BY-SA 4.0"},"Q60851445":{"text":"Парк Каза́чьей сла́вы — парк, расположенный в районе Лефортово Юго-Восточного административного округа Москвы.","title":"Парк Казачьей славы","revision":154145210,"qid":"Q60851445","license":"CC BY-SA 4.0"},"Q29587":{"text":"Уса́дьба Куско́во — бывшее имение графов Шереметевых, где сохранился архитектурно-художественный ансамбль XVIII века. Расположен на востоке Москвы на территории района Вешняки. Ансамбль включает дворец, построенный во второй половине XVIII века в стиле классицизма; регулярный, украшенный скульптурой парк с павильонами: «Грот», «Оранжерея» (проекты…","title":"Кусково","revision":154745424,"qid":"Q29587","license":"CC BY-SA 4.0"},"Q1341402":{"text":"«Парк культу́ры» (также «Парк культу́ры»-радиальная) — станция Московского метрополитена на Сокольнической линии. Связана пересадкой с одноимённой станцией на Кольцевой линии. Расположена в районе Хамовники Центрального административного района Москвы; названа по Центральному парку культуры и отдыха имени Горького. Открыта 15 мая 1935 года в составе…","title":"Парк культуры (станция метро, Сокольническая линия)","revision":151975026,"qid":"Q1341402","license":"CC BY-SA 4.0"},"Q3889320":{"text":"Сад «Эрмита́ж» («Новый Эрмитаж», «Щукинский») — центр летней гастрольной и эстрадной жизни Москвы, памятник садово-паркового искусства, один из первых московских увеселительных садов, популярное место культурного отдыха. Расположен в центре Москвы в Тверском районе на улице Каретный Ряд, 3. Сад «Эрмитаж» занимает бо́льшую часть улицы Каретный Ряд (по…","title":"Сад «Эрмитаж»","revision":152209942,"qid":"Q3889320","license":"CC BY-SA 4.0"},"Q4145444":{"text":"Не путать с усадьбой Разумовского на Воздвиженке Городская усадьба Разумовского — усадьба и парк в Басманном районе Москвы. При усадьбе на берегу Яузы разбит парк площадью ок. 40 га (охраняемая территория — 29 га). Усадебным храмом служила близлежащая Вознесенская церковь. В советское время на территории парка были устроены спортивные площадки. Ближайшие…","title":"Усадьба Разумовского на Яузе","revision":152214308,"qid":"Q4145444","license":"CC BY-SA 4.0"},"Q4376411":{"text":"«Пра́ктика» — московский театр, созданный как экспериментальный центр новой драмы в 2005 году режиссёром Эдуардом Бояковым. Учредитель — Правительство Москвы.","title":"Практика (театр)","revision":151527658,"qid":"Q4376411","license":"CC BY-SA 4.0"},"Q4175105":{"text":"Ело́ховский прое́зд — небольшая улица в центре Москвы в Басманном районе между Елоховской площадью и Нижней Красносельской улицей. Здесь расположен Елоховский собор, кафедральный собор Московского Патриархата.","title":"Елоховский проезд","revision":154520664,"qid":"Q4175105","license":"CC BY-SA 4.0"},"Q4304187":{"text":"Моско́вский междунаро́дный Дом му́зыки (ММДМ) — государственное бюджетное учреждение культуры города Москвы, один из крупнейших в России и мире филармонических комплексов, многофункциональный культурный центр, направленный на развитие современного исполнительского искусства. В четырёх залах Дома музыки — Светлановском, Камерном, Театральном и Новом…","title":"Дом музыки (Москва)","revision":154520849,"qid":"Q4304187","license":"CC BY-SA 4.0"},"Q4350005":{"text":"Переведе́новский переу́лок — улица на востоке Москвы в Басманном районе между Спартаковской площадью и Бакунинской улицей.","title":"Переведеновский переулок","revision":154820597,"qid":"Q4350005","license":"CC BY-SA 4.0"},"Q4504251":{"text":"Центральный дом журналиста (ЦДЖ, Домжур, ранее — Дом печати) — общественный центр Союза журналистов России, одна из старейших культурных и информационных площадок Москвы. В холле, залах и кинотеатре Дома проводятся творческие встречи, образовательные и культурно-просветительские мероприятия. Здание построено не позднее 1736 года для князей Гагариных,…","title":"Центральный дом журналиста","revision":154190466,"qid":"Q4504251","license":"CC BY-SA 4.0"},"Q4249036":{"text":"Курчатовский центр культуры — центр культуры, расположенный по адресу Москва, ул. Рогова, 1/8. Построен в 1949 году по инициативе Игоря Васильевича Курчатова, как структурное подразделение Института Курчатова. В 1998-м году на базе ДК была создана Автономная некоммерческая организация «Курчатовский центр культуры». В 2016 году здание было признано…","title":"Курчатовский центр культуры","revision":146437925,"qid":"Q4249036","license":"CC BY-SA 4.0"},"Q3330571":{"text":"Музей Московской железной дороги — московский музей-павильон, расположенный около Павелецкого вокзала. До 1992 года — филиал Центрального музея В. И. Ленина «Траурный поезд В. И. Ленина», получивший своё название из-за расположенного в нём траурного поезда (паровоз У127 и багажный вагон № 1691), который в 1924 году доставил тело Ленина в Москву. С 2001…","title":"Музей Московской железной дороги","revision":147337977,"qid":"Q3330571","license":"CC BY-SA 4.0"},"Q4483274":{"text":"Детский парк «Фестивальный», встречается также Детский парк «Марьина роща» — парк в Центральном административном округе Москвы, в Мещанском районе, общей площадью 12,6 га.","title":"Фестивальный парк","revision":153931905,"qid":"Q4483274","license":"CC BY-SA 4.0"},"Q18405696":{"text":"Центральная научная сельскохозяйственная библиотека (ЦНСХБ) — одна из крупнейших библиотек подобного профиля в мире. Она является научно-методическим центром сельскохозяйственных библиотек России и депозитарием FAO.","title":"Центральная научная сельскохозяйственная библиотека","revision":151622421,"qid":"Q18405696","license":"CC BY-SA 4.0"},"Q19933526":{"text":"Особня́к Гу́бина — здание в стиле классицизм, расположенное в Москве на улице Петровке. Было построено в 1793—1799 годах по проекту архитектора Матвея Казакова для купца Михаила Губина. С середины XIX века помещения сдавались в аренду разным организациям и частным школам, после 1917 года усадьба перешла в ведомство Института фтизиатрии и ортопедии…","title":"Особняк Губина","revision":152579213,"qid":"Q19933526","license":"CC BY-SA 4.0"},"Q110318614":{"text":"Парк «Пальмира» – зона отдыха, расположенная в Северо-Западном округе Москвы, на территории района Куркино. Примыкает к жилой застройке и зданию школы №1387 на Соколово-Мещерской улице. Площадь – 2 га. Парк был обустроен в 2019 году по программе Мэра Москвы «Мой район».","title":"Пальмира (парк)","revision":149169446,"qid":"Q110318614","license":"CC BY-SA 4.0"},"Q1190902":{"text":"«Охо́тный Ряд» — станция Сокольнической линии Московского метрополитена. Расположена между станциями «Лубянка» и «Библиотека имени Ленина». Находится на территории Тверского района Центрального административного округа Москвы. «Охотный Ряд» — ближайшая к Красной площади станция метро. Ранее носила названия «И́мени Кагано́вича» и «Проспе́кт Ма́ркса».","title":"Охотный Ряд (станция метро)","revision":154900511,"qid":"Q1190902","license":"CC BY-SA 4.0"},"Q4504006":{"text":"Це́нтр междунаро́дной торго́вли (ЦМТ, ранее — Совинцентр, «Хаммеровский центр») — деловой комплекс Москвы, расположен на Краснопресненской набережной столицы. Построен при участии Арманда Хаммера в конце 1970-х годов. ЦМТ находится в формирующемся деловом центре города, рядом с выставочным комплексом «Экспоцентр» и бизнес-комплексом Москва-Сити; ближайшие…","title":"Центр международной торговли (Москва)","revision":154481486,"qid":"Q4504006","license":"CC BY-SA 4.0"},"Q4290882":{"text":"Мерзляко́вский переулок (ранее Мамстрюков переулок, Мастрюков переулок) — переулок в Центральном административном округе города Москвы. Проходит от улицы Новый Арбат до Большой Никитской, лежит параллельно Никитскому бульвару, слева от него. Нумерация домов ведётся от Нового Арбата.","title":"Мерзляковский переулок","revision":146219738,"qid":"Q4290882","license":"CC BY-SA 4.0"},"Q4073621":{"text":"Ащеу́лов переу́лок — переулок в Центральном административном округе города Москвы на территории Красносельского района. Соединяет улицу Сретенка и Костянский переулок. Лежит между Рыбниковым переулком и Луковым переулком. Нумерация домов ведётся от Сретенки.","title":"Ащеулов переулок","revision":154917091,"qid":"Q4073621","license":"CC BY-SA 4.0"},"Q2011787":{"text":"Богородице-Рождественский монастырь, известен как Рождественский монастырь — один из древнейших женских монастырей Москвы. Расположен на пересечении улицы Рождественка и Рождественского бульвара, которым он дал имя.","title":"Рождественский монастырь (Москва)","revision":152214548,"qid":"Q2011787","license":"CC BY-SA 4.0"},"Q2922035":{"text":"Страстно́й бульва́р — бульвар в Тверском районе Центрального административного округа города Москвы, один из бульваров Бульварного кольца, объект культурного наследия регионального значения. Проходит от Пушкинской площади до площади Петровские Ворота. Слева к бульвару примыкает улица Малая Дмитровка. Нумерация домов ведётся от Пушкинской площади. Бульвар…","title":"Страстной бульвар","revision":156010810,"qid":"Q2922035","license":"CC BY-SA 4.0"},"Q4143544":{"text":"Горбатый мост — мост в Пресненском районе Москвы через ныне несуществующий проток Старого русла реки Пресни. Находится рядом со зданием Правительства России. Мост построен в середине XVIII века на плотине Среднего Пресненского пруда (мост носил название «Нижний Пресненский» в противоположность Верхнему Пресненскому, через который ныне проходит улица…","title":"Горбатый мост (Москва)","revision":146280193,"qid":"Q4143544","license":"CC BY-SA 4.0"},"Q4342474":{"text":"«Палаты Мазепы» — жилые помещения, расположенные в Москве в Колпачном переулке, дом № 10, построенные в XVI—XVII веках. Один из древнейших памятников московского гражданского зодчества. Своё название получили от того, что долгое время ошибочно считались домом, где проживал гетман Иван Мазепа при посещении Москвы.","title":"Палаты Мазепы (Москва)","revision":152215086,"qid":"Q4342474","license":"CC BY-SA 4.0"},"Q1635756":{"text":"Софи́йский собо́р (Собор Софии Премудрости Божией) — православный храм в Вологде, на территории Вологодского кремля. Возведён в 1568—1570 годах по распоряжению Ивана Грозного. Древнейшее сохранившееся каменное сооружение города. С 1587 по 1923 год — кафедральный собор Вологодской епархии (с 1776 по 1938 годы — вместе с тёплым Воскресенским собором) и…","title":"Софийский собор (Вологда)","revision":156002641,"qid":"Q1635756","license":"CC BY-SA 4.0"},"Q4318666":{"text":"Нижегородский острог — бывшая тюрьма в историческом центре Нижнего Новгорода. Острог представляет собой комплекс из тюрьмы и административного здания. Построен в виде прямоугольника с четырьмя башнями по углам. Вся территория обнесена кирпичной стеной. В настоящее время используется как музей. Расположен по адресу: Нижний Новгород, пл. Свободы, 2а.","title":"Нижегородский острог","revision":155315377,"qid":"Q4318666","license":"CC BY-SA 4.0"},"Q4377551":{"text":"Пречи́стенский переу́лок (в 1937—1993 годах — переулок Н. А. Островского) — улица в центре Москвы в Хамовниках между Пречистенкой и Большим Власьевским переулком. В переулке располагаются посольства Австрии, Дании и Марокко.","title":"Пречистенский переулок","revision":154122158,"qid":"Q4377551","license":"CC BY-SA 4.0"},"Q401590":{"text":"Храм святителя Николая в Сабурове — православный храм Даниловского благочиния Московской городской епархии. Храм расположен в районе Москворечье-Сабурово, Южного административного округа города Москвы (Каширское шоссе, дом 59, корпус 4).","title":"Храм Святителя Николая в Сабурове","revision":135131395,"qid":"Q401590","license":"CC BY-SA 4.0"},"Q2082457":{"text":"Марийский национальный театр драмы имени М. Шкетана (луговомар. М. Шкетан лӱмеш Марий кугыжаныш драме театр) — старейший театр марийского народа. Здание театра расположено в центре Йошкар-Олы, на площади Ленина.","title":"Марийский национальный театр драмы имени М. Шкетана","revision":155878379,"qid":"Q2082457","license":"CC BY-SA 4.0"},"Q21393993":{"text":"Птичья башня — глухая башня (полубашня) Китайгородской стены, расположенная на северной стороне крепости, на берегу реки Неглинной. Построена была в 1535—1538 годах Петроком Малым Фрязином, как и вся стена. Из всех башен Китай-города является единственной сохранившейся до настоящего времени. Как башня называлась в Средневековье, неизвестно, равно как и…","title":"Птичья башня","revision":149485094,"qid":"Q21393993","license":"CC BY-SA 4.0"},"Q21660987":{"text":"White Rabbit — ресторан в Москве, открытый ресторатором Борисом Зарьковым и ставший флагманским проектом основанного им альянса White Rabbit Family. Концепция ресторана — современная русская кухня. C 2015 года White Rabbit входит в топ-50 лучших ресторанов мира (The World’s 50 Best Restaurants), который ежегодно составляет британский журнал Restaurant и…","title":"White Rabbit (ресторан)","revision":154968132,"qid":"Q21660987","license":"CC BY-SA 4.0"},"Q28881203":{"text":"Сквер Мстислава Ростроповича — сквер в центре Москвы на пересечении Елисеевского и Брюсова переулков. Сквер расположен в исторической части города, в живописном и малолюдном месте, между Большой Никитской и Тверской улицами. Благодаря особенности рельефа, сквер несколько возвышается над обрамляющими его переулками.","title":"Сквер Мстислава Ростроповича","revision":156353389,"qid":"Q28881203","license":"CC BY-SA 4.0"},"Q48949058":{"text":"Павильон «Шелководство» — 311-й павильон ВДНХ, построенный в 1939 году, и сначала носивший название «Молдавская ССР». Название «Шелководство» получил в 1954 году.","title":"Павильон № 311 «Шелководство» на ВДНХ","revision":146714028,"qid":"Q48949058","license":"CC BY-SA 4.0"},"Q1652738":{"text":"Костромско́й райо́н — административно-территориальная единица (район) и муниципальное образование (муниципальный район) на западе Костромской области России. Административный центр — город Кострома (в состав района не входит).","title":"Костромской район","revision":156226832,"qid":"Q1652738","license":"CC BY-SA 4.0"},"Q604615":{"text":"Акмо́линская область (Омская область в 1918—1919 годах, с июля 1919 — до 3 января 1920 года) — административно-территориальная единица в составе Российской империи, Государства Российского, существовавшая в 1868—1920 годах. Административный центр — город Омск.","title":"Акмолинская область (1868—1920)","revision":155670563,"qid":"Q604615","license":"CC BY-SA 4.0"},"Q4325168":{"text":"Новороссийский муниципальный драматический театр им. Амербекяна — театр в городе Новороссийске. До 2014 года театр имел любительский статус и носил название Новороссийский народный драматический театр.","title":"Новороссийский народный драматический театр имени Амербекяна","revision":147807287,"qid":"Q4325168","license":"CC BY-SA 4.0"},"Q4146739":{"text":"Государственный академический Северный русский народный хор — профессиональный художественный коллектив, основанный Антониной Яковлевной Колотиловой в 1926 году, исполняющий русскую народную музыку. Один из старейших хоров России. Хранитель северной фольклорной традиции. В его состав входят три группы: хоровая, танцевальная и оркестр русских народных…","title":"Северный русский народный хор","revision":155524278,"qid":"Q4146739","license":"CC BY-SA 4.0"},"Q4302220":{"text":"Мончего́рский музе́й цветно́го ка́мня и́мени В. Н. Да́ва — минералогический музей, муниципальное некоммерческое учреждение в городе Мончегорск Мурманской области, Россия. Основан 31 марта 1971 года по инициативе советского геолога Владимира Николаевича Дава, в честь которого назван.","title":"Мончегорский музей цветного камня имени В. Н. Дава","revision":156346360,"qid":"Q4302220","license":"CC BY-SA 4.0"},"Q4134225":{"text":"Здание бывшей гауптвахты в Костроме — памятник архитектуры эпохи позднего классицизма (ампира), одна из достопримечательностей города, входящая в архитектурный ансамбль Сусанинской площади. Архитектор — П. И. Фурсов.","title":"Гауптвахта (Кострома)","revision":152216023,"qid":"Q4134225","license":"CC BY-SA 4.0"},"Q2784775":{"text":"Гле́бовское (Глебовка) — село в Приморском районе муниципального образования город Новороссийск Краснодарского края России.","title":"Глебовское (Краснодарский край)","revision":147568889,"qid":"Q2784775","license":"CC BY-SA 4.0"},"Q3083691":{"text":"Камча́тка — хутор в муниципальном образовании город Новороссийск Краснодарского края. Входит в состав сельского округа Абрау-Дюрсо.","title":"Камчатка (Краснодарский край)","revision":147568533,"qid":"Q3083691","license":"CC BY-SA 4.0"},"Q16627074":{"text":"Ближнево — деревня в Дмитровском районе Московской области, в составе городского поселения Дмитров. Население — 86 чел. (2021). До 2006 года Ближнево входило в состав Внуковского сельского округа. По ревизской сказке 1811 года Ближнево входило в экономическую Подчёрковскую волость. В селении числилось 68 мужчин. По ревизской сказке 1834 года в Ближнево…","title":"Ближнево (Московская область)","revision":152557895,"qid":"Q16627074","license":"CC BY-SA 4.0"},"Q16696638":{"text":"Селявино — деревня в Дмитровском районе Московской области, в составе городского поселения Яхрома. Население — 8 чел. (2021). До 2006 года Селявино входило в состав Подъячевского сельского округа.","title":"Селявино","revision":152557865,"qid":"Q16696638","license":"CC BY-SA 4.0"},"Q138781245":{"text":"Центральный парк культуры и отдыха — парк в городе Кострома. В северной части примыкает к Советской площади, ограничен улицами Чайковского, 1 мая, застройкой по улице Табачные ряды. Вход в парк обустроен со стороны Табачных (Овощных) торговых рядов и с улицы Чайковского. Через парк можно выйти на смотровую площадку, с которой открывается акватория реки…","title":"Центральный парк культуры и отдыха (Кострома)","revision":154191039,"qid":"Q138781245","license":"CC BY-SA 4.0"},"Q375029":{"text":"Ры́бинское водохрани́лище (разг. Ры́бинское мо́ре) — большое водохранилище на реке Волге и её притоках Шексне и Мологе. Расположено на севере Центральной России — в основном в Ярославской области (3246 км²), частично также в Тверской и Вологодской областях. Объём воды: полная ёмкость — 25,4 км³; полезная ёмкость — 16,7 км³. Площадь поверхности — 4580 км².…","title":"Рыбинское водохранилище","revision":155509596,"qid":"Q375029","license":"CC BY-SA 4.0"},"Q52242":{"text":"Ставропо́льский райо́н — административно-территориальная единица Самарской области России. В границах района образован одноимённый муниципальный район. Административный центр — город Тольятти (в состав самого района не входит), который до 1964 года назывался Ставрополь (неофициально Ставрополь-на-Волге для отличия от Ставрополя-на-Кавказе).","title":"Ставропольский район","revision":155707014,"qid":"Q52242","license":"CC BY-SA 4.0"},"Q4182333":{"text":"Забайка́льский краево́й драмати́ческий теа́тр им. Н. А. Березина — театр в Чите. С 2019—2022 гг проводилась реконструкция здания, изменён внешний вид входа здания, внутри всё заменено на новое оборудование, сделана крутящая сцена.","title":"Забайкальский краевой драматический театр","revision":154114968,"qid":"Q4182333","license":"CC BY-SA 4.0"},"Q367382":{"text":"Прохла́дненский райо́н (кабард.-черк. Прохладнэ куей, карач.-балк. Прохладна район) — административно-территориальная единица и муниципальное образование (муниципальный район) в составе Кабардино-Балкарской Республики Российской Федерации. Административный центр — город Прохладный (в состав района не входит).","title":"Прохладненский район","revision":153004032,"qid":"Q367382","license":"CC BY-SA 4.0"},"Q4146975":{"text":"Государственный театр кукол Республики Мордовия (возник в 1938 г.) — участник многих смотров и фестивалей, их призер и дипломант, постоянно гастролирует по Мордовии, а также в Московской, Калужской, Нижегородской, Пензенской и других областях. В своем репертуаре он опирается на классическую сказку и мордовский фольклор. Главным режиссером театра до 2020…","title":"Театр кукол Республики Мордовия","revision":156166571,"qid":"Q4146975","license":"CC BY-SA 4.0"},"Q4401560":{"text":"Рыбинский государственный историко-архитектурный и художественный музей-заповедник ― государственное учреждение культуры в городе Рыбинске Ярославской области. Один из старейших и крупнейших музеев Верхней Волги (более 100 тысяч единиц хранения). Основное здание музея ― бывшая Хлебная биржа, построенная в 1912 году по проекту московского архитектора А. В.…","title":"Рыбинский музей-заповедник","revision":155273669,"qid":"Q4401560","license":"CC BY-SA 4.0"},"Q2263092":{"text":"Нары́н-кала́ — персидская цитадель, часть Дербентской крепости, соединённая с Каспийским морем двойными стенами, призванными перекрывать так называемые Каспийские ворота в Персидскую державу. Входит в список всемирного наследия ЮНЕСКО. Один из вариантов переводов названия исторического памятника — «солнечная крепость». Со Средних веков Дербентская…","title":"Нарын-кала","revision":155663424,"qid":"Q2263092","license":"CC BY-SA 4.0"},"Q4302544":{"text":"Мордо́вский госуда́рственный национа́льный драмати́ческий театр — театр в Саранске (Мордовия), основанный в 1989 году. В 2007 году переехал в новое здание на Советской улице. Театр был открыт 1 августа 1989 года. Здание, для него выделенное, имело зрительный зал всего на 35 мест, находившийся в полуподвальном помещении. Первыми артистами театра стали…","title":"Мордовский государственный национальный драматический театр","revision":151774759,"qid":"Q4302544","license":"CC BY-SA 4.0"},"Q4146924":{"text":"Госуда́рственный ру́сский драмати́ческий теа́тр Респу́блики Мордо́вия — театр в Саранске, столице Республики Мордовия. В его репертуаре постановки по пьесам классиков русской и зарубежной драматургии, а также современных авторов. Был основан в 1932 году, сначала как труппа, прикреплённая к Мордовскому национальному драматическому театру. Здание театра…","title":"Русский драматический театр Республики Мордовия","revision":149258649,"qid":"Q4146924","license":"CC BY-SA 4.0"},"Q4211332":{"text":"Каменская — деревня в муниципальном округе Егорьевск Московской области России. Входит в культурно-историческую местность Леоновщина.","title":"Каменская (Московская область)","revision":147561659,"qid":"Q4211332","license":"CC BY-SA 4.0"},"Q4397920":{"text":"Российская Восточная окраина — государственное образование, существовавшее с 16 января по 28 октября 1920 года на территории Забайкалья. Указом Верховного правителя А. В. Колчака от 4 января 1920 года Г. М. Семёнову была передана (до получения указаний от назначенного Верховным правителем России А. И. Деникина) «вся полнота военной и гражданской власти на…","title":"Российская восточная окраина (государственное образование)","revision":152079750,"qid":"Q4397920","license":"CC BY-SA 4.0"},"Q4164026":{"text":"Довмонтов город — каменная постройка XIII века, пристроенная для дополнительного укрепления Крома, расширения площади крепости и защиты городского посада Пскова. Название произошло от имени Довмонта (в крещении Тимофея), псковского князя 1266—1299 годов.","title":"Довмонтов город","revision":146501758,"qid":"Q4164026","license":"CC BY-SA 4.0"},"Q16020426":{"text":"Гу́бино — деревня в Клинском районе Московской области, в составе Зубовского сельского поселения. Население — 4 чел. (2010).","title":"Губино (городской округ Клин)","revision":146582995,"qid":"Q16020426","license":"CC BY-SA 4.0"},"Q19649945":{"text":"Зати́шье (до 1998 года — посёлок Совхо́за-1) — посёлок в Богородском городском округе Московской области России, до 2018 года входивший в состав ныне упразднённого сельского поселения Буньковское.","title":"Затишье (Московская область)","revision":154523639,"qid":"Q19649945","license":"CC BY-SA 4.0"},"Q28108849":{"text":"Атаманский дворец — памятник гражданской архитектуры XIX века в Новочеркасске. Атаманский дворец построен в 1863 году в Александровском саду как официальная резиденция наказного атамана Войска Донского. Дворец также служил местом пребывания царя и наследников престола (августейших атаманов) во время их приезда в Новочеркасск. Здесь останавливались в дни…","title":"Атаманский дворец (Новочеркасск)","revision":152218578,"qid":"Q28108849","license":"CC BY-SA 4.0"},"Q48945145":{"text":"Тольяттинская филармония — государственное учреждение культуры Самарской области, основанное 16 апреля 1992 года и расположенное в городе Тольятти. Филармония ведёт концертную, музыкально-лекционную деятельность. Ежегодно концерты филармонии посещает около 100 тысяч человек.","title":"Тольяттинская филармония","revision":150894398,"qid":"Q48945145","license":"CC BY-SA 4.0"},"Q48948881":{"text":"Орловский театр кукол — театр для детей в городе Орле, основанный в годы немецкой оккупации. В репертуаре театра около 50 спектаклей для самых разных детских возрастов.","title":"Орловский театр кукол","revision":150507485,"qid":"Q48948881","license":"CC BY-SA 4.0"},"Q84170610":{"text":"Тольяттинский краеведческий музей — музей исторического профиля в Тольятти, посвящённый истории города и местного края.","title":"Тольяттинский краеведческий музей","revision":147866055,"qid":"Q84170610","license":"CC BY-SA 4.0"},"Q25616990":{"text":"Моско́вский областно́й теа́тр дра́мы и коме́дии (прежде — Ноги́нский драмтеа́тр) — государственный драматический театр, учреждённый в Ногинске в 1930 году на базе ранее созданной в Богородском уезде передвижной труппы. Своё нынешнее название и статус получил в 2012 году. Остаётся единственным драмтеатром областного подчинения, работающим непосредственно в…","title":"Московский областной театр драмы и комедии","revision":156292960,"qid":"Q25616990","license":"CC BY-SA 4.0"},"Q1965852":{"text":"Каши́ра — административно-территориальная единица (город областного подчинения с административной территорией), в границах которой создано муниципальное образование городской округ Кашира — городской округ на юге Московской области России. До 2015 года его территорию занимал Каши́рский район.","title":"Кашира (городской округ)","revision":152206506,"qid":"Q1965852","license":"CC BY-SA 4.0"},"Q1654216":{"text":"Би́йский райо́н — административно-территориальное образование (сельский район) и муниципальное образование (муниципальный район) в Алтайском крае России. Административный центр — город Бийск, в состав района не входящий.","title":"Бийский район","revision":156170879,"qid":"Q1654216","license":"CC BY-SA 4.0"},"Q559807":{"text":"Бронетанковый музей в городе Кубинка — один из крупнейших в мире музеев, экспонирующих броневое и танковое вооружение и технику (БТВТ), различных видов и исторических периодов. Музей расположен в городе Кубинка Московской области. На открытых площадках и в павильонах экспонировано более 350 единиц броневого и танкового вооружения и техники из 14 государств…","title":"Бронетанковый музей в Кубинке","revision":156153729,"qid":"Q559807","license":"CC BY-SA 4.0"},"Q960064":{"text":"Костромская ГРЭС — третья по установленной мощности тепловая электростанция России, расположена в городе Волгореченске Костромской области, на правом берегу Волги. Входит в состав Группы Интер РАО (ранее — ОАО «ОГК-3»).","title":"Костромская ГРЭС","revision":155886397,"qid":"Q960064","license":"CC BY-SA 4.0"},"Q3893581":{"text":"Спасо-Преображенский собор — православный храм в городе Торжке Тверской области. Памятник русского культового зодчества эпохи ампира. Возведён на берегу реки Тверцы в 1815—1822 годах. Храм входит в ансамбль собора Спаса Преображения и церкви Входа Господня в Иерусалим. Является подворьем Новоторжского Борисоглебского монастыря Тверской епархии Русской…","title":"Спасо-Преображенский собор (Торжок)","revision":154929661,"qid":"Q3893581","license":"CC BY-SA 4.0"},"Q731549":{"text":"Ковы́лкинский райо́н (мокш. Лашмань аймак) — административно-территориальная единица (район) и муниципальное образование (муниципальный район) в составе Республики Мордовия Российской Федерации. Административный центр — город Ковылкино, который имеет статус города республиканского значения и не входит в административный район, но является составной частью…","title":"Ковылкинский район","revision":149689855,"qid":"Q731549","license":"CC BY-SA 4.0"},"Q4409416":{"text":"Сахалинский областной художественный музей — один из самых молодых художественных музеев России, единственный художественный музей Сахалинской области.","title":"Сахалинский областной государственный художественный музей","revision":147197780,"qid":"Q4409416","license":"CC BY-SA 4.0"},"Q4298326":{"text":"Мичу́ринский — посёлок в Брянском районе Брянской области, административный центр Мичуринского сельского поселения.","title":"Мичуринский (Брянская область)","revision":147542841,"qid":"Q4298326","license":"CC BY-SA 4.0"},"Q4203089":{"text":"Ирби́тский госуда́рственный музе́й мотоци́клов — единственный в России музей мотоциклов, имеющий статус государственного. Находится в городе Ирбит по адресу ул. Советская, 100а.","title":"Ирбитский государственный музей мотоциклов","revision":147198237,"qid":"Q4203089","license":"CC BY-SA 4.0"},"Q24585612":{"text":"Музей первого Совета расположен в здании бывшей мещанской управы в городе Иваново; является подразделением Ивановского государственного историко-краеведческого музея имени Д. Г. Бурылина.","title":"Музей первого Совета","revision":149557526,"qid":"Q24585612","license":"CC BY-SA 4.0"},"Q28666355":{"text":"Сахалинский театр кукол — государственное автономное учреждение культуры, театр кукол в городе Южно‐Сахалинск, расположенный по адресу: Коммунистический проспект, 28а.","title":"Сахалинский театр кукол","revision":150507492,"qid":"Q28666355","license":"CC BY-SA 4.0"},"Q15569926":{"text":"Ряби́новый — посёлок в Ирбитском муниципальном образовании Свердловской области России, пригород Ирбита.","title":"Рябиновый (Свердловская область)","revision":147674726,"qid":"Q15569926","license":"CC BY-SA 4.0"},"Q92018369":{"text":"Майский Дворец (также известный под названиями ДК БМЗ, Дворец культуры БМЗ, Майский дворец в Бежице) — заложенный в 1927 году бывший дворец культуры машиностроительного завода в Брянске, памятник архитектуры и культуры регионального значения. Располагается на не административной Майской площади, территория дворца с Майским парком простирается вдоль улицы…","title":"Майский Дворец (ДК БМЗ)","revision":155562000,"qid":"Q92018369","license":"CC BY-SA 4.0"},"Q1739474":{"text":"Смоле́нская АЭС — атомная электростанция, расположенная на юге Смоленской области в 3 км от города Десногорск. Находится на правом берегу Десногорского водохранилища. Расстояние до города Смоленска — 150 км. В промышленной эксплуатации на станции находится три энергоблока с уран-графитовыми канальными реакторами типа РБМК-1000. Электрическая мощность…","title":"Смоленская АЭС","revision":154895634,"qid":"Q1739474","license":"CC BY-SA 4.0"},"Q1069990":{"text":"Унечский район — административно-территориальная единица (район) и муниципальное образование (муниципальный район) в Брянской области России. Административный центр — город Унеча.","title":"Унечский район","revision":155311899,"qid":"Q1069990","license":"CC BY-SA 4.0"},"Q14324673":{"text":"Центрально-Чернозёмная область (ЦЧО) — административно-территориальная единица РСФСР 1928—1934 годов. Область первоначально была разделена на 11 округов и 178 районов. Областным центром являлся город Воронеж. Площадь — 191 941 км², население — 11 824,8 тыс. человек (на 1 апреля 1930 года). Первым секретарём обкома партии ЦЧО (1928—1934 гг.) был И. М.…","title":"Центрально-Чернозёмная область","revision":155145043,"qid":"Q14324673","license":"CC BY-SA 4.0"},"Q1651507":{"text":"Бузулу́кский район — административно-территориальная единица (район) и муниципальное образование (муниципальный район) в Оренбургской области России.","title":"Бузулукский район","revision":156177167,"qid":"Q1651507","license":"CC BY-SA 4.0"},"Q3329597":{"text":"Ярославский художественный музей — центральный художественный музей Ярославской области. Находится в зоне ЮНЕСКО и объединяет несколько зданий и парковых зон в историческом центре города. Главный комплекс расположен на Волжской набережной в исторических зданиях — бывшем губернаторском доме, Митрополичьих палатах и в доме Сорокиной — купеческом особняке XIX…","title":"Ярославский художественный музей","revision":152926928,"qid":"Q3329597","license":"CC BY-SA 4.0"},"Q1646651":{"text":"Серо́вский райо́н — административно-территориальная единица (район) в Свердловской области России. Административный центр — город Серов (не входит в состав района). В рамках муниципального устройства, на территории района с 1 октября 2017 года существует только Сосьвинский городской округ. До 1 октября 2017 года частично к району также относился Серовский…","title":"Серовский район","revision":152900878,"qid":"Q1646651","license":"CC BY-SA 4.0"},"Q1546590":{"text":"Мейендорф или Подушкино — стилизованная под шато усадьба баронессы Мейендорф (Meyendorff) в посёлке Барвиха Одинцовского городского округа Московской области, на Подушкинском шоссе.","title":"Усадьба Мейендорф","revision":146290902,"qid":"Q1546590","license":"CC BY-SA 4.0"},"Q4306477":{"text":"Музей техники Вадима Задорожного — крупнейший в России частный музей техники (ретроавтомобилей, мотоциклов, военной техники). Основан в 2001 году, расположен в посёлке Архангельское Красногорского городского округа Московской области.","title":"Музей техники Вадима Задорожного","revision":154929011,"qid":"Q4306477","license":"CC BY-SA 4.0"},"Q4309603":{"text":"Мыти́щинский исто́рико-худо́жественный музе́й — центральный музей городского округа Мытищи. Открыт в 1962 году.","title":"Мытищинский историко-художественный музей","revision":151626129,"qid":"Q4309603","license":"CC BY-SA 4.0"},"Q2217289":{"text":"Нижнеу́динский райо́н — административно-территориальное образование (район) и муниципальное образование (муниципальный район) в Иркутской области России. Административный центр — город Нижнеудинск.","title":"Нижнеудинский район","revision":154064454,"qid":"Q2217289","license":"CC BY-SA 4.0"},"Q4538871":{"text":"Ярославский государственный театр юного зрителя имени В. С. Розова — театр юного зрителя в Ярославле, государственное учреждение культуры Ярославской области.","title":"Ярославский театр юного зрителя","revision":152094285,"qid":"Q4538871","license":"CC BY-SA 4.0"},"Q4319902":{"text":"Никитское — деревня в Талдомском городском округе Московской области России, до 2018 года входила в состав сельского поселения Квашёнковское Талдомского района. Находится рядом со Спас-Углом — старинным русским селом, где родился Салтыков-Щедрин. Ранее принадлежала Тверской губернии.","title":"Никитское (Талдомский городской округ)","revision":147539805,"qid":"Q4319902","license":"CC BY-SA 4.0"},"Q4306319":{"text":"Музей истории города Ярославля — музей в городе Ярославле, посвящённый его истории.","title":"Музей истории города Ярославля","revision":154943656,"qid":"Q4306319","license":"CC BY-SA 4.0"},"Q4306222":{"text":"Ярославский Музей Боевой Славы — музей в городе Ярославле, посвящённый военным и трудовым подвигам жителей города во время Великой Отечественной войны . Изначально был музеем 234-й стрелковой дивизии (234-й Ломоносовско-Пражской орденов Суворова и Богдана Хмельницкого стрелковой дивизии, также известной как Ярославская дивизия народного ополчения и…","title":"Музей боевой славы (Ярославль)","revision":154104841,"qid":"Q4306222","license":"CC BY-SA 4.0"},"Q2895767":{"text":"Федеральный военный мемориал «Пантеон защитников Отечества» (полное наименование — федеральное государственное бюджетное учреждение «Федеральный военный мемориал „Пантеон защитников Отечества“» Министерства обороны Российской Федерации, «ФГБУ ФВМ ПЗО МО РФ») — российский мемориал, расположенный в городском округе Мытищи Московской области на 4-м километре…","title":"Федеральный военный мемориал «Пантеон защитников Отечества»","revision":154222823,"qid":"Q2895767","license":"CC BY-SA 4.0"},"Q4343081":{"text":"Па́мятник Бе́лому Би́му Чёрное у́хо — контактная скульптура, посвящённая собаке Белому Биму Чёрное ухо — герою одноимённой повести советского писателя Гавриила Троепольского; установлена в Воронеже на площади перед Воронежским театром кукол «Шут» (Проспект Революции, 50).","title":"Памятник Белому Биму","revision":153131360,"qid":"Q4343081","license":"CC BY-SA 4.0"},"Q1747451":{"text":"Валдгейм (идиш װאלדהײם‎ от װאלד‎ — лес и הײם‎ — дом, домашний очаг, обитель) — село в Биробиджанском районе Еврейской автономной области. Административный центр Валдгеймского сельского поселения.","title":"Валдгейм","revision":147603745,"qid":"Q1747451","license":"CC BY-SA 4.0"},"Q18771316":{"text":"Вороново — деревня в Талдомском районе Московской области России. Входит в сельское поселение Ермолинское.","title":"Вороново (Талдомский городской округ)","revision":147647535,"qid":"Q18771316","license":"CC BY-SA 4.0"},"Q135112093":{"text":"Воронежский музей Юго-Восточной железной дороги — технический музей, посвященный истории железнодорожной техники Юго-Восточной железной дороги. Располагается на территории грузового двора железнодорожного вокзала «Воронеж-I» и в Дворце культуры Железнодорожников.","title":"Воронежский музей железнодорожной техники","revision":156310167,"qid":"Q135112093","license":"CC BY-SA 4.0"},"Q1120899":{"text":"Красноя́рская ГЭС (имени 50-летия СССР) — гидроэлектростанция на реке Енисее вблизи города Дивногорска Красноярского края. Входит в Енисейский каскад ГЭС, составляя его третью ступень. Является второй по мощности (после Саяно-Шушенской ГЭС) электростанцией России. В комплекс Красноярского гидроузла входит единственный в России судоподъёмник. Строительство…","title":"Красноярская ГЭС","revision":155510225,"qid":"Q1120899","license":"CC BY-SA 4.0"},"Q2109878":{"text":"Ка́нский райо́н — административно-территориальная единица (район) и муниципальное образование (муниципальный район) в восточной части Красноярского края России. Административный центр — город Канск.","title":"Канский район","revision":154898453,"qid":"Q2109878","license":"CC BY-SA 4.0"},"Q894049":{"text":"Бородино́ — деревня в Можайском муниципальном округе Московской области. Бывший административный центр сельского поселения Бородинское. Деревня расположена 12 км западнее Можайска на автомобильной трассе Можайск — Уваровка. Расстояние до ближайшей железнодорожной станции в посёлке Бородино — 4 км. Впервые упоминается в 1601 году в Можайских Писцовых…","title":"Бородино (деревня, Можайский муниципальный округ)","revision":156247999,"qid":"Q894049","license":"CC BY-SA 4.0"},"Q2719580":{"text":"Усть-Или́мская ГЭС — гидроэлектростанция на реке Ангаре в городе Усть-Илимске Иркутской области. Является третьей ступенью Ангарского каскада ГЭС и четвёртой по мощности гидроэлектростанцией России, уступая только Саяно-Шушенской, Красноярской и Братской ГЭС. Сооружения станции образуют Усть-Илимское водохранилище, одно из крупнейших по объёму в России.…","title":"Усть-Илимская ГЭС","revision":155512102,"qid":"Q2719580","license":"CC BY-SA 4.0"},"Q4425938":{"text":"Собо́р Свято́го Архистрати́га Арха́нгела Михаи́ла — православный храм в Центральном районе Сочи, старейший храм города. Относится к Сочинской епархии Русской православной церкви.","title":"Собор Михаила Архангела (Сочи)","revision":155760020,"qid":"Q4425938","license":"CC BY-SA 4.0"},"Q4262671":{"text":"А́длерский райо́н — один из четырёх внутригородских районов города Сочи, расположенного в Краснодарском крае России. Самый южный, второй по территории и населению район города Сочи. В 2014 году в Адлерском районе прошли все соревнования Зимних Олимпийских игр 2014. Административным центром района является курортный поселок Адлер.","title":"Адлерский район","revision":155628931,"qid":"Q4262671","license":"CC BY-SA 4.0"},"Q4483270":{"text":"Конце́ртный зал «Фестива́льный» — культурно-развлекательное учреждение (концертный зал) в Центральном районе города Сочи, Краснодарский край, Россия. Построен по проекту архитекторов В. Шульрихтера и И. Рябышева в 1979 г. Концертный зал «Фестивальный» находится в самом центре города Сочи на берегу Черного моря. Фестивальный входит в число…","title":"Фестивальный (концертный зал, Сочи)","revision":152214118,"qid":"Q4483270","license":"CC BY-SA 4.0"},"Q1370434":{"text":"Эстосадо́к или Э́сто-Садо́к — село в Адлерском районе муниципального образования город-курорт Сочи в Краснодарском крае. Входит в состав Краснополянского поселкового округа.","title":"Эстосадок","revision":154270239,"qid":"Q1370434","license":"CC BY-SA 4.0"},"Q2632849":{"text":"Вятскополя́нский райо́н — административно-территориальная единица (район) и муниципальное образование (муниципальный район) на крайнем юге Кировской области России. Административный центр — город Вятские Поляны (в состав района не входит).","title":"Вятскополянский район","revision":153099396,"qid":"Q2632849","license":"CC BY-SA 4.0"},"Q1335490":{"text":"«Ро́за Ху́тор» — круглогодичный горнолыжный курорт, расположенный на берегах реки Мзымта и горных склонах к югу от неё в Адлерском районе Сочи. На курорте работают 32 канатных дороги, общая протяжённость горнолыжных трасс составляет 105 км, имеется 14 отелей, а также собственный пляж на черноморском побережье. В зимний сезон 2017/2018 года курорт принял…","title":"Роза Хутор","revision":153243929,"qid":"Q1335490","license":"CC BY-SA 4.0"},"Q951551":{"text":"Сочинский национальный парк был создан по постановлению Совета Министров РСФСР № 214 от 5 мая 1983 года в целях сохранения уникальных природных комплексов Черноморского побережья Кавказа, использования их в природоохранных, рекреационных, просветительных и научных целях.","title":"Сочинский национальный парк","revision":153121142,"qid":"Q951551","license":"CC BY-SA 4.0"},"Q4537065":{"text":"Я́корная Щель — станция Северо-Кавказской железной дороги РЖД, расположена в посёлке Якорная Щель Лазаревского района города Сочи, Краснодарский край, Россия.","title":"Якорная Щель (станция)","revision":154631946,"qid":"Q4537065","license":"CC BY-SA 4.0"},"Q4460566":{"text":"Тонне́ль и́мени Ста́лина (официально Владивостокский тоннель) — однопутный железнодорожный тоннель во Владивостоке, проложенный под горой Шошина. Связывает долину Первой Речки с районом Минного городка и Луговой улицей. Расположен между платформами «Третья Рабочая» и «Луговая». Имеет статус стратегического объекта, а также памятника истории и архитектуры…","title":"Тоннель имени Сталина","revision":153611345,"qid":"Q4460566","license":"CC BY-SA 4.0"},"Q4055021":{"text":"Уса́дьба Абра́мцево (Государственный историко-художественный и литературный музей-заповедник «Абрамцево») — музей-заповедник, расположенный на берегу реки Вори в одноимённом селе Сергиево-Посадском городском округе Московской области, в 60 км к северо-востоку от Москвы,","title":"Абрамцево (музей-заповедник)","revision":154935411,"qid":"Q4055021","license":"CC BY-SA 4.0"},"Q4332485":{"text":"«Океан» — кинотеатр во Владивостоке, первый широкоформатный и самый большой кинотеатр Дальнего Востока. Построен в 1969 году. Входит в сеть кинотеатров «Иллюзион».","title":"Океан (кинотеатр, Владивосток)","revision":150137869,"qid":"Q4332485","license":"CC BY-SA 4.0"},"Q16270974":{"text":"Скульптурная композиция «Пуп земли» в Кунгуре установлена на набережной реки Сылвы на улице Карла Маркса у памятника первопроходцам.","title":"Пуп земли (Кунгур)","revision":147618496,"qid":"Q16270974","license":"CC BY-SA 4.0"},"Q16688358":{"text":"Приморская сцена Мариинского театра (до 1 января 2016 года — Государственный Приморский театр оперы и балета) — театр оперы и балета во Владивостоке. Открыт 18 октября 2013 года.","title":"Приморская сцена Мариинского театра","revision":154250385,"qid":"Q16688358","license":"CC BY-SA 4.0"},"Q4063545":{"text":"Экстрим-парк «Роза Хутор» — спортивный комплекс, расположенный на территории горнолыжного комплекса «Роза Хутор» к западу от плато Роза хутор, на котором находится горная олимпийская деревня. Экстрим-парк был построен для проведения соревнований зимних Олимпийских игр 2014 года по сноуборду и фристайлу. Первоначально предполагалось фристайл-центр…","title":"Роза Хутор (экстрим-парк)","revision":146568988,"qid":"Q4063545","license":"CC BY-SA 4.0"},"Q61605107":{"text":"«Уссури» — кинотеатр во Владивостоке, памятник градостроительства и архитектуры. Построен в 1921—1927 годах. Автор проекта — инженер А. Л. Фёдоров. Историческое здание по адресу Светланская улица, 31 является объектом культурного наследия Российской Федерации.","title":"Уссури (кинотеатр)","revision":146780482,"qid":"Q61605107","license":"CC BY-SA 4.0"},"Q12197211":{"text":"Нижнее Учдере́ — село в Лазаревском районе муниципального образования город-курорт Сочи Краснодарского края России. Входит в состав Верхнелооского сельского округа.","title":"Нижнее Учдере","revision":147718449,"qid":"Q12197211","license":"CC BY-SA 4.0"},"Q2706278":{"text":"Новосиби́рский госуда́рственный академи́ческий теа́тр о́перы и бале́та (НГАТОиБ, НОВАТ) — российский театр оперы и балета. Открылся в 1945 году. Является одним из ведущих театров России. Крупнейшее в России и СССР здание театра было сооружено в 1931—1941 годах, представляет собой сложный и уникальный архитектурный комплекс, и имеет статус объекта…","title":"Новосибирский театр оперы и балета","revision":156224078,"qid":"Q2706278","license":"CC BY-SA 4.0"},"Q4274880":{"text":"Майко́пская гидроэлектроста́нция — ГЭС на реке Белой в Адыгее, в Майкопе. Входит в Белореченский каскад ГЭС. Собственник станции — ПАО «ЭЛ5-Энерго».","title":"Майкопская ГЭС","revision":153489409,"qid":"Q4274880","license":"CC BY-SA 4.0"},"Q2177261":{"text":"«Тысячелетие России» — монумент, воздвигнутый в Новгороде в 1862 году в честь тысячелетнего юбилея летописного призвания варягов, с которым традиционно связывается начало русской государственности. Авторами проекта памятника являются график и живописец Михаил Микешин, скульптор Иван Шредер и архитектор Виктор Гартман. Памятник находится в новгородском…","title":"Тысячелетие России","revision":153841744,"qid":"Q2177261","license":"CC BY-SA 4.0"},"Q2620967":{"text":"Баргузи́нский госуда́рственный приро́дный биосфе́рный запове́дник — заповедник в Бурятии, на территории Северо-Байкальского района. Исторический центр — Давша; с 2012 года управление заповедником располагается в посёлке Усть-Баргузин.","title":"Баргузинский заповедник","revision":154903904,"qid":"Q2620967","license":"CC BY-SA 4.0"},"Q1658382":{"text":"Же́рдевский райо́н — административно-территориальная единица (район) и муниципальное образование (муниципальный район) на юге Тамбовской области России. Административный центр — город Жердевка.","title":"Жердевский район","revision":141100283,"qid":"Q1658382","license":"CC BY-SA 4.0"},"Q827202":{"text":"Карача́й — засыпанное озеро в Челябинской области России. С октября 1951 года используется для хранения радиоактивных отходов ПО «Маяк». С 1986 года велись работы по засыпке водоёма. 26 ноября 2015 года работы по консервации озера объявлены завершёнными.","title":"Карачай (озеро)","revision":152818038,"qid":"Q827202","license":"CC BY-SA 4.0"},"Q2478158":{"text":"Адыге́йская автоно́мная о́бласть — административно-территориальная единица РСФСР, существовавшая с 27 июля 1922 года по 3 июля 1991 года. Столица — Майкоп (до 1936 года — Краснодар).","title":"Адыгейская автономная область","revision":155541411,"qid":"Q2478158","license":"CC BY-SA 4.0"},"Q4325478":{"text":"Новосибирский областной театр кукол — театральное учреждение, расположенное в Железнодорожном районе Новосибирска, на пересечении улиц Ленина и Революции","title":"Новосибирский областной театр кукол","revision":156209751,"qid":"Q4325478","license":"CC BY-SA 4.0"},"Q4219239":{"text":"Ке́меровская ГРЭС — электростанция в Центральном районе Кемерова, действующая с 1934 года. Входит в АО «Кемеровская генерация», структурного подразделения ООО «Сибирская генерирующая компания».","title":"Кемеровская ГРЭС","revision":144668207,"qid":"Q4219239","license":"CC BY-SA 4.0"},"Q4349454":{"text":"Первомайский сквер — сквер в Центральном районе Новосибирска напротив здания мэрии. Сквер расположен у станции метро «Площадь Ленина».","title":"Первомайский сквер (Новосибирск)","revision":154665057,"qid":"Q4349454","license":"CC BY-SA 4.0"},"Q4505275":{"text":"Церковь Феодора Стратила́та «на Ручью́» (на Фёдоровой улице) — недействующий православный храм в Великом Новгороде 1360—1361 годов постройки. Классический памятник новгородского зодчества и один из выдающихся памятников архитектуры средневекового Новгорода. Расположен на перекрёстке Андреевской улицы и улицы Фёдоровский ручей. Памятник архитектуры…","title":"Церковь Феодора Стратилата на Ручью","revision":154093718,"qid":"Q4505275","license":"CC BY-SA 4.0"},"Q4333960":{"text":"Бугри́нский мост — мост через Обь в Новосибирске, соединяющий Кировский, Первомайский и Октябрьский районы. Работы по выбору места размещения створа мостового перехода, проектная и рабочая документация были выполнены Институтом «Стройпроект». Строительство началось 17 февраля 2010 года и завершилось в октябре 2014 года. Автомобильный мост через Обь с самым…","title":"Бугринский мост","revision":156173348,"qid":"Q4333960","license":"CC BY-SA 4.0"},"Q1218832":{"text":"Исторические памятники Новгорода и окрестностей (англ. Historic Monuments of Novgorod and Surroundings) — собирательное название, под которым ЮНЕСКО в 1992 году внесло в список объектов Всемирного наследия средневековое архитектурное наследие города Новгорода (с 1999 года — Великий Новгород): 1 апреля 2009 года Центральный банк России выпустил памятные…","title":"Исторические памятники Новгорода и окрестностей","revision":150941352,"qid":"Q1218832","license":"CC BY-SA 4.0"},"Q4203315":{"text":"Иркутский областной краеведческий музей имени Н. Н. Муравьёва-Амурского — государственное автономное учреждение культуры Иркутской области. Музей включает в себя 7 экспозиционных отделов: отдел истории, отдел природы, выставочный отдел «Окно в Азию», выставочный отдел «Музейная студия», ледокол «Ангара», музей В. Г. Распутина, Культурно-просветительский…","title":"Иркутский областной краеведческий музей","revision":155658830,"qid":"Q4203315","license":"CC BY-SA 4.0"},"Q16666454":{"text":"Котласский краеведческий музей – муниципальное учреждение культуры «Котласский краеведческий музей». Музей расположен по адресу: Архангельская область, г. Котлас, ул. Виноградова, 22.","title":"Котласский краеведческий музей","revision":151229751,"qid":"Q16666454","license":"CC BY-SA 4.0"},"Q15110694":{"text":"Пиллау (нем. Festung Pillau) — крепость в Пиллау в Восточной Пруссии (ныне Балтийск, Калининградская область, Россия).","title":"Пиллау (крепость)","revision":156322306,"qid":"Q15110694","license":"CC BY-SA 4.0"},"Q8047264":{"text":"Якутская телебашня (Башня Якутска) — телевизионная и радиовещательная башня, расположенная в Якутске, в Республике Саха (Якутия), высотой 225,875 м, введена в эксплуатацию в октябре 1982 г. Телевизионная башня находится в хозяйственном ведении Российская телевизионная и радиовещательная сеть (обособленное подразделение в регионе - филиал РТРС…","title":"Якутская телебашня","revision":155951121,"qid":"Q8047264","license":"CC BY-SA 4.0"},"Q20743809":{"text":"Каменушка — посёлок в Новосибирском районе Новосибирской области России. Входит в состав Барышевского сельсовета.","title":"Каменушка (Новосибирская область)","revision":152914084,"qid":"Q20743809","license":"CC BY-SA 4.0"},"Q106775741":{"text":"Зда́ние Дворя́нского собра́ния — трёхэтажное кирпичное здание в стиле классицизма с оградой, располагающееся в историческом центре города Великого Новгорода по адресу: площадь Победы — Софийская, 2. Здание является памятником архитектуры XIX века и объектом культурного наследия с региональной категорией охраны в соответствии с решением облисполкома № 104…","title":"Здание дворянского собрания (Великий Новгород)","revision":154030911,"qid":"Q106775741","license":"CC BY-SA 4.0"},"Q113554351":{"text":"Рязанская ВДНХ (до 1959 — Рязанская областная сельскохозяйственная, промышленная и строительная выставка, до 2024 — Торго́вый городо́к) — выставочный комплекс на улице Свободы в Советском районе города Рязани, построенный в 1955 году для демонстрации успехов народного хозяйства. Проектирование, строительство и озеленение комплекса было произведено всего за…","title":"Рязанская ВДНХ","revision":155220954,"qid":"Q113554351","license":"CC BY-SA 4.0"},"Q843017":{"text":"Горячево́дский — посёлок городского типа в муниципальном образовании город-курорт Пятигорск Ставропольского края России. В 2010 году был самым крупным в России посёлком городского типа.","title":"Горячеводский","revision":147486022,"qid":"Q843017","license":"CC BY-SA 4.0"},"Q4229832":{"text":"Коммуна́льный мост — автодорожный железобетонный арочный мост через реку Енисей в Красноярске. Соединяет Центральный и Свердловский районы города.","title":"Коммунальный мост (Красноярск)","revision":156100597,"qid":"Q4229832","license":"CC BY-SA 4.0"},"Q1018007":{"text":"Бу́товский полиго́н — историческое наименование урочища, известного как одно из мест массовых казней и захоронений жертв сталинских репрессий и расположенного рядом с посёлками городского типа Боброво и Дрожжино Ленинского городского округа Московской области, где, согласно результатам исследований архивно-следственных документов, в 1930—1950-х годах были…","title":"Бутовский полигон","revision":154462640,"qid":"Q1018007","license":"CC BY-SA 4.0"},"Q650999":{"text":"Красноя́рский краево́й краеве́дческий музе́й — один из старейших музеев Сибири и Дальнего Востока, один из крупнейших музеев России. Научно-методический центр для музеев Красноярского края и Восточной Сибири, информационный и образовательный центр. Является членом Союза музеев России с 2002 года, представлен в ИКОМ России. В 2002 году был признан лучшим…","title":"Красноярский краеведческий музей","revision":155658846,"qid":"Q650999","license":"CC BY-SA 4.0"},"Q2429170":{"text":"Башкирский государственный природный заповедник — заповедник в Республике Башкортостан, на отрогах Южного Урала.","title":"Башкирский заповедник","revision":149210064,"qid":"Q2429170","license":"CC BY-SA 4.0"},"Q4239248":{"text":"Красноя́рский госуда́рственный теа́тр о́перы и бале́та имени Д. А. Хворосто́вского — стационарный репертуарный театр в городе Красноярске. Основан в 1976 году. Первая постановка была представлена в 1978 году.","title":"Красноярский театр оперы и балета имени Д. А. Хворостовского","revision":155554554,"qid":"Q4239248","license":"CC BY-SA 4.0"},"Q2294354":{"text":"Балтийский пролив (нем. Pillauer-Tief — Пиллауский пролив, устар. Пиллавский пролив) — самый западный пролив России. Расположен в 30 километрах к западу от Калининграда, соединяет Калининградский залив и Гданьский залив и отделяет Пиллауский полуостров от Балтийской косы. Пролив находится на территории города Балтийска (бывшего Пилла́у).","title":"Балтийский пролив","revision":155903260,"qid":"Q2294354","license":"CC BY-SA 4.0"},"Q4239259":{"text":"Красноя́рский музыка́льный теа́тр — стационарный репертуарный театр. Разнообразие спектаклей включает в себя большое количество жанров — от классической оперетты до рок-опер и мюзиклов.","title":"Красноярский музыкальный театр","revision":154943375,"qid":"Q4239259","license":"CC BY-SA 4.0"},"Q4230231":{"text":"Комсомо́льский па́рк расположен в северо-восточной части города Пятигорска в административном районе «Белая Ромашка», ограничен улицами Орджоникидзе и Панагюриште. Кадастровый номер участка 26:33:13 03 02:0002, разрешённое использование (назначение) — для туристско-рекреационной деятельности. Парк отнесён ко второму поясу зоны санитарной охраны.","title":"Комсомольский парк (Пятигорск)","revision":154342882,"qid":"Q4230231","license":"CC BY-SA 4.0"},"Q16666965":{"text":"Музейный центр «Площадь Мира» (разговорные наименования — «музей на Стрелке», музей современного искусства — организация в Красноярске, крупнейшая в Сибири выставочная площадка современного искусства (общая площадь здания — 10 404 м², экспозиционная площадь — 5 тыс. м², площадь временных выставок — 1 037 м², единиц хранения — 15 725, из них 14 226…","title":"Площадь Мира (музейный центр)","revision":155358282,"qid":"Q16666965","license":"CC BY-SA 4.0"},"Q16666958":{"text":"Красноярский театр юного зрителя — один из ведущих молодёжных театров Сибири. Первый предназначенный для юных зрителей в Красноярском крае театр; был основан 7 декабря 1964 года в Красноярске.","title":"Красноярский театр юного зрителя","revision":156252576,"qid":"Q16666958","license":"CC BY-SA 4.0"},"Q18755271":{"text":"Музей «Дом Машарова» — учреждение культуры исторического профиля, находится в памятнике архитектуры федерального значения (Указ Президента Российской Федерации № 176 от 20.02.1995) по адресу Тюмень, ул. Ленина, 24. Музей входит в ГУК ТО «Музейный комплекс им. И. Я. Словцова». Заведующая музеем — Гульнара Геннадьевна Демчук. Экспозиционно-выставочная…","title":"Дом Машарова","revision":153764210,"qid":"Q18755271","license":"CC BY-SA 4.0"},"Q123184706":{"text":"Академическая галерея, ранее — Елизаветинская галерея, — достопримечательность в Пятигорске, Ставропольский край, Россия, по адресу проспект Кирова, д. 1а. Находится на месте расположения кислосерного Елизаветинского источника. Современное здание галереи в стиле итальянского Возрождения построено в 1848—1850 годах архитектором Самуилом Уптоном и является…","title":"Академическая галерея","revision":136436339,"qid":"Q123184706","license":"CC BY-SA 4.0"},"Q123221670":{"text":"Лермонтовская галерея — галерея из железа и стекла в Пятигорске, Ставропольский край, Россия, построенная в 1901 году и названная в честь русского поэта М. Ю. Лермонтова. Расположена в парке «Цветник» по адресу проспект Кирова, д. 21. Вмещает концертный и выставочный залы, принадлежит Северо-Кавказской филармонии. Является объектом культурного наследия…","title":"Лермонтовская галерея","revision":138207477,"qid":"Q123221670","license":"CC BY-SA 4.0"},"Q29254925":{"text":"Карау́льная гора (Покро́вская гора, Часо́венная гора, Кум-Тиге́й) — сопка расположенная в городе Красноярске, названная в честь располагавшейся здесь караульной вышки.","title":"Караульная гора (Красноярск)","revision":150674567,"qid":"Q29254925","license":"CC BY-SA 4.0"},"Q46999182":{"text":"Усадьба Колокольниковых — культурное учреждение исторического профиля в городе Тюмень. Расположена по адресу улица Республики, д. 18-20. Устраиваются выставки, мастер-классы, экскурсии.","title":"Усадьба Колокольниковых","revision":153850156,"qid":"Q46999182","license":"CC BY-SA 4.0"},"Q2885362":{"text":"Камская ГЭС — гидроэлектростанция, расположенная на реке Кама в Пермском крае, в городе Пермь. Входит в Волжско-Камский каскад ГЭС, является верхней ступенью каскада на Каме. На момент пуска в 1956 году последних гидроагрегатов Камская ГЭС была второй по мощности гидроэлектростанцией в СССР, уступая лишь Днепрогэсу (483 МВт против 650 МВт). Камская ГЭС…","title":"Камская ГЭС","revision":155982435,"qid":"Q2885362","license":"CC BY-SA 4.0"},"Q115035":{"text":"Пермский театр оперы и балета (полное название — Пермский государственный ордена Трудового Красного Знамени академический театр оперы и балета им. П. И. Чайковского) — один из старейших музыкальных театров России, инициатор Дягилевского фестиваля и Конкурса артистов балета «Арабеск» имени Екатерины Максимовой. Один из основных творческих принципов театра —…","title":"Пермский театр оперы и балета имени П. И. Чайковского","revision":151927499,"qid":"Q115035","license":"CC BY-SA 4.0"},"Q4351536":{"text":"Пермский академический Театр-Театр (до 2007 года — Пермский академический театр драмы) — театр в Перми, основанный в 1927 году как Театр рабочей молодёжи. Расположен в центре города, на Эспланаде. Здание театра (1981, архитекторы В. П. Давыденко и В. И. Лютикова) является памятником архитектуры регионального значения. Коллектив театра составляет 300…","title":"Театр-Театр","revision":155681006,"qid":"Q4351536","license":"CC BY-SA 4.0"},"Q750350":{"text":"Астраханский кремль — крепость в Астрахани, выстроенная на месте первых фортификационных сооружений, появившихся в связи с переносом города в 1557—1558 годах воеводой Иваном Черемисиновым. Располагается на острове, омываемом водами Волги, Кутума и Царёва ерика, на самом высоком его холме — Заячьем бугре. Строительство велось в 1580—1620 годах; строители —…","title":"Астраханский кремль","revision":154129675,"qid":"Q750350","license":"CC BY-SA 4.0"},"Q4518915":{"text":"Чёрный рынок — крупный торговый центр, действовавший в городе Перми в XIX — начале XX века, также имевший название Хлебного рынка. В настоящее время часть территории бывшего рынка — это сквер Уральских добровольцев.","title":"Чёрный рынок (Пермь)","revision":155643275,"qid":"Q4518915","license":"CC BY-SA 4.0"},"Q4533061":{"text":"Этнографи́ческий музе́й наро́дов Забайка́лья (бур. Υбэр Байгалай хизаарай арадуудай угсаатанай зγйн музей) — музейный комплекс под открытым небом в городе Улан-Удэ (Республика Бурятия), в микрорайоне Верхняя Берёзовка.","title":"Этнографический музей народов Забайкалья","revision":155598638,"qid":"Q4533061","license":"CC BY-SA 4.0"},"Q4306291":{"text":"Музе́й исто́рии Буря́тии и́мени М. Н. Ханга́лова (бур. М. Н. Хангаловай нэрэмжэтэ Тγγхын музей) — исторический музей в городе Улан-Удэ, Республика Бурятия.","title":"Музей истории Бурятии","revision":147205336,"qid":"Q4306291","license":"CC BY-SA 4.0"},"Q1320520":{"text":"Ледо́вая аре́на «Тра́ктор» имени Валерия Константиновича Белоусова — ледовый дворец в Челябинске, предназначенный для проведения спортивных и культурно-массовых мероприятий. Арена была местом проведения чемпионата Европы по дзюдо 2012 года, чемпионата мира по дзюдо 2014 года и чемпионата мира по тхэквондо 2015 года. Арена расположена в Калининском районе…","title":"Трактор (ледовая арена)","revision":154303064,"qid":"Q1320520","license":"CC BY-SA 4.0"},"Q4351500":{"text":"Пе́рмская госуда́рственная худо́жественная галере́я — региональный художественный музей России. Коллекции составляют около 50 000 произведений изобразительного искусства с древнейших времен до современности, представляющих различные виды искусства.","title":"Пермская художественная галерея","revision":156219196,"qid":"Q4351500","license":"CC BY-SA 4.0"},"Q2239589":{"text":"Чеченская автономная область (Чеченская АО) — административно-территориальная единица РСФСР, существовавшая с 30 ноября 1922 года по 15 января 1934 года. Административный центр — город Грозный.","title":"Чеченская автономная область","revision":154282375,"qid":"Q2239589","license":"CC BY-SA 4.0"},"Q4298332":{"text":"Мичу́ринский драматический театр — театр в городе Мичуринске, единственное здание в Тамбовской области, которое было изначально построено как театр. В современном здании театр функционирует с 1913 года.","title":"Мичуринский драматический театр","revision":152066639,"qid":"Q4298332","license":"CC BY-SA 4.0"},"Q4071716":{"text":"Астраханский государственный театр кукол (Астраханский театр кукол) — специализированное учреждение культуры в городе Астрахань.","title":"Астраханский государственный театр кукол","revision":156146359,"qid":"Q4071716","license":"CC BY-SA 4.0"},"Q2537852":{"text":"Ледовый дворец «Уральская молния» — современный спортивный комплекс для организации соревнований по конькобежному спорту и организации тренировок спортсменов, расположенный в городе Челябинске. Архитекторы В. П. Ковалёв, А. А. Латышев, Ж. Ю. Чернева, инженер В. И. Брюкин. Ледовый Дворец «Уральская молния» имени шестикратной олимпийской чемпионки Лидии…","title":"Уральская молния","revision":155410171,"qid":"Q2537852","license":"CC BY-SA 4.0"},"Q28665966":{"text":"Челябинский государственный академический театр оперы и балета имени М. И. Глинки — стационарный театр оперы и балета в Челябинске. Вместимость зала — 894 места.","title":"Челябинский театр оперы и балета имени М. И. Глинки","revision":154890009,"qid":"Q28665966","license":"CC BY-SA 4.0"},"Q4351549":{"text":"Пермский музей авиации — бывший частный музей авиационной техники в городе Пермь. Основан в 2000 году Павловым Михаилом Анатольевичем. Закрыт летом 2023. Экспозиция состояла из техники, которую удалось сохранить после расформирования Пермского военного авиатехнического училища, аэропорта местных авиалиний Бахаревка. Музей находился под открытым небом, в…","title":"Пермский музей авиации","revision":147573816,"qid":"Q4351549","license":"CC BY-SA 4.0"},"Q4351545":{"text":"Пе́рмский краеве́дческий музе́й (полное название Государственное краевое бюджетное учреждение культуры «Пермский краеведческий музей») — старейший и крупнейший музей Пермского края. Насчитывает 600 000 единиц хранения и включает более 50 коллекций регионального, российского и мирового значения; в числе объектов музея 22 памятника истории и культуры, из них…","title":"Пермский краеведческий музей","revision":156183178,"qid":"Q4351545","license":"CC BY-SA 4.0"},"Q4071712":{"text":"Астраханский государственный театр оперы и балета — государственный музыкальный театр в городе Астрахани.","title":"Астраханский театр оперы и балета","revision":154965245,"qid":"Q4071712","license":"CC BY-SA 4.0"},"Q4276141":{"text":"Макси́миха — село в Баргузинском районе Бурятии. Входит в городское поселение «Посёлок Усть-Баргузин».","title":"Максимиха (Бурятия)","revision":147596276,"qid":"Q4276141","license":"CC BY-SA 4.0"},"Q21645302":{"text":"Челябинская областная универсальная научная библиотека расположена в Челябинске на проспекте Ленина. Является одной из крупнейших библиотек на Урале.","title":"Челябинская областная универсальная научная библиотека","revision":155681085,"qid":"Q21645302","license":"CC BY-SA 4.0"},"Q77254766":{"text":"Памятник водопроводчику — достопримечательность Перми, жанровая городская скульптура, расположенная в сквере перед домом № 63 по улице Ленина. Имеет народное название «Петрович».","title":"Памятник водопроводчику","revision":155213313,"qid":"Q77254766","license":"CC BY-SA 4.0"},"Q4439206":{"text":"Музей-заповедник «Сталинградская битва» — музейный комплекс в Волгограде.","title":"Сталинградская битва (музей-заповедник)","revision":156260225,"qid":"Q4439206","license":"CC BY-SA 4.0"},"Q4460569":{"text":"Тоннель под Амуром (во время строительства — стройка № 4; засекреченное — Объект № 4 Народного комиссариата путей сообщения) — однопутный железнодорожный тоннель протяжённостью 7198 метров на Транссибирской магистрали, в Хабаровске. Построен в 1937—1941 годах для дублирования моста через Амур. Является единственным подводным сооружением на железных дорогах…","title":"Тоннель под Амуром","revision":155886877,"qid":"Q4460569","license":"CC BY-SA 4.0"},"Q4122949":{"text":"Волгоградская ТЭЦ-3 — энергетическое предприятие в Волгограде, Южный федеральный округ. ТЭЦ является генерирующей мощностью «Лукойл-Волгоградэнерго».","title":"Волгоградская ТЭЦ-3","revision":156348730,"qid":"Q4122949","license":"CC BY-SA 4.0"},"Q4289955":{"text":"Ме́льница Ге́ргардта, или ме́льница Груди́нина — здание паровой мельницы начала XX века, разрушенное в дни Сталинградской битвы и не восстановленное как память о войне. Входит в состав Музея-заповедника «Сталинградская битва».","title":"Мельница Гергардта","revision":154263537,"qid":"Q4289955","license":"CC BY-SA 4.0"},"Q4122968":{"text":"Волгоградский государственный Новый экспериментальный театр (НЭТ) — волгоградский драматический театр, расположенный в Центральном районе.","title":"Новый экспериментальный театр","revision":155527214,"qid":"Q4122968","license":"CC BY-SA 4.0"},"Q4421337":{"text":"Сказ об Урале — скульптурная композиция на Привокзальной площади в городе Челябинске, символ Урала.","title":"Сказ об Урале","revision":152922582,"qid":"Q4421337","license":"CC BY-SA 4.0"},"Q4494351":{"text":"Хаба́ровский краево́й теа́тр дра́мы — драматический театр в Хабаровске.","title":"Хабаровский краевой театр драмы и комедии","revision":154125212,"qid":"Q4494351","license":"CC BY-SA 4.0"},"Q4155963":{"text":"Дворец спорта волгоградских профсоюзов — универсальный спортивно-зрелищный комплекс, расположенный на проспекте Ленина 65 в Краснооктябрьском районе Волгограда, несколько севернее Центрального стадиона. Рядом расположен памятник-ансамбль «Героям Сталинградской битвы», а также ряд торговых и бизнес-центров. Вместимость главной арены составляет 2500…","title":"Дворец спорта волгоградских профсоюзов","revision":146492662,"qid":"Q4155963","license":"CC BY-SA 4.0"},"Q24931738":{"text":"Театр ЧТЗ (Театр Челябинского тракторного завода) расположен в Челябинске на проспекте Ленина в Тракторозаводском районе города.","title":"Театр ЧТЗ","revision":149124626,"qid":"Q24931738","license":"CC BY-SA 4.0"},"Q28667731":{"text":"«Пищеви́к», также известен как «Спарта́к» — стадион в Ворошиловском районе Волгограда.","title":"Пищевик (стадион)","revision":148540224,"qid":"Q28667731","license":"CC BY-SA 4.0"},"Q53803959":{"text":"«Мая́к» — один из старейших ресторанов Волгограда, расположенный на Набережной 62-й Армии в Центральном районе города.","title":"Маяк (ресторан)","revision":151854626,"qid":"Q53803959","license":"CC BY-SA 4.0"},"Q86677479":{"text":"Дальневосто́чная госуда́рственная нау́чная библиоте́ка — крупнейшая и старейшая библиотека Хабаровского края и Дальневосточного федерального округа, ведущее научно-исследовательское учреждение в области библиотековедения, библиографии и книговедения, методический и консультативный центр зональных (ДФО) библиотек. Основана 6  декабря 1894 года как…","title":"Дальневосточная государственная научная библиотека","revision":146836749,"qid":"Q86677479","license":"CC BY-SA 4.0"},"Q18609425":{"text":"Дальневосточный художественный музей (ДВХМ) — художественный музей в Хабаровске.","title":"Дальневосточный художественный музей","revision":147822757,"qid":"Q18609425","license":"CC BY-SA 4.0"},"Q1739361":{"text":"Били́бинская АЭС (АТЭЦ) — остановленная атомная электростанция (точнее, атомная теплоэлектроцентраль), расположенная рядом с городом Билибино Чукотского автономного округа (4,5 км). От Анадыря, административного центра региона, до АЭС 610 км. Является филиалом госконцерна «Росэнергоатом». В декабре 2025 года были поэтапно остановлены три из четырёх…","title":"Билибинская АЭС","revision":156023640,"qid":"Q1739361","license":"CC BY-SA 4.0"},"Q1965517":{"text":"Бра́тская ГЭС (им. 50-летия Великого Октября) — гидроэлектростанция на реке Ангаре в городе Братске Иркутской области. Является третьей по мощности и первой по среднегодовой выработке гидроэлектростанцией России. Входит в Ангарский каскад ГЭС, являясь его второй ступенью. Сооружения станции образуют Братское водохранилище, крупнейшее в России по полезному…","title":"Братская ГЭС","revision":156132055,"qid":"Q1965517","license":"CC BY-SA 4.0"},"Q2217076":{"text":"Колпа́шевский райо́н — административно-территориальная единица (район) и муниципальное образование (муниципальный район) в центральной части Томской области России. Административный центр района — город Колпашево.","title":"Колпашевский район","revision":146208134,"qid":"Q2217076","license":"CC BY-SA 4.0"},"Q4306467":{"text":"Музей современного изобразительного искусства на Дмитровской / МСИИД — художественный музей в Ростове-на-Дону.","title":"Музей современного изобразительного искусства на Дмитровской","revision":152330719,"qid":"Q4306467","license":"CC BY-SA 4.0"},"Q4408477":{"text":"Саратовский театр кукол «Теремок» — театр Саратова, основанный в 1936 году, один из первых театров кукол России.","title":"Теремок (театр кукол, Саратов)","revision":150507501,"qid":"Q4408477","license":"CC BY-SA 4.0"},"Q1347765":{"text":"Нахичева́нь-на-Дону́ (Нахичеван, Нахиджеван, з.-арм. Նոր Նախիջեւան [noɾ nɑχit͡ʃʰevɑ́n] — Новый Нахичеван) — в прошлом город на правом берегу реки Дон, с 1929 года — часть Пролетарского района города Ростова-на-Дону. Был основан в 1779 году армянами, переселёнными из Крыма по указу Екатерины II от 14 ноября 1779 года.","title":"Нахичевань-на-Дону","revision":156170866,"qid":"Q1347765","license":"CC BY-SA 4.0"},"Q490188":{"text":"Вое́нно-возду́шная акаде́мия и́мени Ю. А. Гага́рина — российское высшее военное учебное заведение, предназначенное для подготовки командных кадров Военно-Воздушных Сил, располагалось в посёлке Монино Московской области. Военно-воздушная академия являлась одним из ведущих военных учреждений профессионального образования в области подготовки военных кадров…","title":"Военно-воздушная академия имени Ю. А. Гагарина","revision":153404705,"qid":"Q490188","license":"CC BY-SA 4.0"},"Q4475195":{"text":"Ульяновский драматический театр имени И. А. Гончарова — государственный драматический театр Ульяновской области Российской Федерации. Спасской улице, 12.","title":"Ульяновский областной драматический театр","revision":156037311,"qid":"Q4475195","license":"CC BY-SA 4.0"},"Q4398487":{"text":"Ростовский академический театр драмы имени М. Горького — один из крупнейших театров Ростова-на-Дону. Его здание, определяющее облик Театральной площади, известно в архитектурном мире как поздний памятник конструктивизма и единственное здание в этом стиле включённое в Национальный индекс культурного наследия.","title":"Ростовский театр драмы имени М. Горького","revision":154810056,"qid":"Q4398487","license":"CC BY-SA 4.0"},"Q4343405":{"text":"Па́мятник Н. Г. Черныше́вскому — установлен на одноимённой площади возле Парка Липки на пересечении улиц Радищева и Волжской в Саратове.","title":"Памятник Чернышевскому (Саратов, площадь Чернышевского)","revision":151659785,"qid":"Q4343405","license":"CC BY-SA 4.0"},"Q4398492":{"text":"Ростовский государственный музыкальный театр — музыкальный театр в Южном Федеральном округе России. Находится в городе Ростове-на-Дону.","title":"Ростовский музыкальный театр","revision":156266096,"qid":"Q4398492","license":"CC BY-SA 4.0"},"Q4475183":{"text":"ОГБУК «Дворец книги — Ульяновская областная научная библиотека им. В. И. Ленина» — центральная государственная научная библиотека Ульяновской области, преемница Симбирской Карамзинской общественной библиотеки, открытой в 1848 году в честь знаменитого симбирянина, писателя и историографа государства Российского Николая Михайловича Карамзина.","title":"Ульяновская областная научная библиотека имени В. И. Ленина","revision":153904019,"qid":"Q4475183","license":"CC BY-SA 4.0"},"Q4419529":{"text":"Симбирская классическая гимназия — первая гимназия в Симбирске. В историческом здании проходит обучение учеников начальных классов Гимназии № 1 им. В. И. Ленина, а в здании-пристройке располагается музей «Симбирская классическая гимназия» (входящий в состав Музея-заповедника «Родина В. И. Ленина»).","title":"Симбирская классическая гимназия","revision":155527038,"qid":"Q4419529","license":"CC BY-SA 4.0"},"Q4036369":{"text":"Coffee Bean (произносится «Кофе бин») — первая появившаяся в Москве сеть кофеен. В настоящее время[когда?] сеть включает 21 кофейню в девяти городах России.","title":"Coffee Bean","revision":153851183,"qid":"Q4036369","license":"CC BY-SA 4.0"},"Q18406345":{"text":"Новошахтинский драматический театр имени Михаила Бушнова — театр в городе Новошахтинске (Россия), созданный в 1996 году на базе народного театра; самый молодой профессиональный театр Ростовской области, расположенный на улице Садовая, 31. Художественный руководитель театра Светлана Сопова.","title":"Новошахтинский драматический театр","revision":155029549,"qid":"Q18406345","license":"CC BY-SA 4.0"},"Q25396711":{"text":"«Побе́да» — бывший саратовский кинотеатр, располагавшийся на площади Кирова в Фрунзенском районе города.","title":"Победа (кинотеатр, Саратов)","revision":153980325,"qid":"Q25396711","license":"CC BY-SA 4.0"},"Q28667001":{"text":"Дом Павла Кузнецова — дом, в котором в 1878 году родился живописец Павел Варфоломеевич Кузнецов. Находится на пересечении улиц Октябрьская и Валовая города Саратова. После смерти художника в 1968 году было предложено открыть его дом-музей. Однако официальное разрешение на открытие удалось получить только спустя 20 лет. Реконструкция здания началась в 1988…","title":"Дом-музей Павла Кузнецова","revision":155517389,"qid":"Q28667001","license":"CC BY-SA 4.0"},"Q28603753":{"text":"Музей русско-армянской дружбы — отдел ГБУК РО «Ростовский областной музей краеведения» в городе Ростов-на-Дону. С 2011 года располагается в старинном особняке нахичеванского купца Марка Яковлевича Искидарова на площади Свободы, 14/2. Адрес музея: 344019, Ростовская область, г. Ростов-на-Дону, площадь Свободы, 14/2.","title":"Музей русско-армянской дружбы","revision":148000895,"qid":"Q28603753","license":"CC BY-SA 4.0"},"Q134444188":{"text":"Владимирский сад — одна из достопримечательностей Ульяновска, памятник природы, занесён в соответствующий кадастр как ООПТ Ульяновской области.","title":"Владимирский сад","revision":156321481,"qid":"Q134444188","license":"CC BY-SA 4.0"},"Q25053793":{"text":"Ледовый дворец спорта «Кристалл» (сокр. ЛДС «Кристалл») — крытая многофункциональная спортивная арена в Саратове. Открыт в 1969 году, вмещает 6100 зрителей. Используется для проведения хоккейных матчей, баскетбольных игр, концертов и других мероприятий. Домашняя арена хоккейного клуба «Кристалл» (Всероссийская хоккейная лига) и баскетбольного клуба…","title":"Кристалл (ледовый дворец спорта)","revision":148671369,"qid":"Q25053793","license":"CC BY-SA 4.0"},"Q775528":{"text":"Сара́товский мост — автомобильный мост через Волгу, соединяющий правый берег, на котором стоит город Саратов, и левый — на котором расположен город Энгельс.","title":"Саратовский мост","revision":155878512,"qid":"Q775528","license":"CC BY-SA 4.0"},"Q1263125":{"text":"Дубна́ — посёлок городского типа в Тульской области России, административный центр Дубенского района. Образует городское поселение рабочий посёлок Дубна. Население — 5811 человек (2025).","title":"Дубна (Тульская область)","revision":154918121,"qid":"Q1263125","license":"CC BY-SA 4.0"},"Q4384198":{"text":"Тверской императорский путевой дворец — дворец в Твери, памятник архитектуры XVIII века. Расположен в историческом центре города на Соборной площади, между Советской (б. Миллионной) улицей, Староволжским мостом и Городским садом.","title":"Путевой дворец (Тверь)","revision":152214710,"qid":"Q4384198","license":"CC BY-SA 4.0"},"Q4464750":{"text":"Трёхсвя́тская у́лица (в советский период — улица Урицкого), известна как тверской Арбат — пешеходная улица, расположенная в историческом центре Твери. Трёхсвятская улица — популярное место для отдыха жителей города и народных гуляний. Многие здания, расположенные на улице, являются памятниками истории и архитектуры.","title":"Трёхсвятская улица","revision":146298834,"qid":"Q4464750","license":"CC BY-SA 4.0"},"Q4408470":{"text":"Саратовский областной театр оперетты — музыкальный театр, расположенный на улице Театральной в городе Энгельсе Саратовской области.","title":"Саратовский областной театр оперетты","revision":150602318,"qid":"Q4408470","license":"CC BY-SA 4.0"},"Q4453263":{"text":"Тверской государственный театр кукол — кукольный театр в Твери, государственное областное учреждение культуры. Расположен на пересечении проспекта Победы с Волоколамским проспектом, рядом с Парком Победы. Зрительный зал — по одним данным 360, по другим — 366 мест.","title":"Тверской театр кукол","revision":147807632,"qid":"Q4453263","license":"CC BY-SA 4.0"},"Q544112":{"text":"Га́йский райо́н — административно-территориальная единица (район) в Оренбургской области России. В 2016 году в рамках организации местного самоуправления, в его границах вместе с городом Гай и посёлком Калиновка был преобразован в единое муниципальное образование Гайский городской округ, образованное вместо упразднённых одноимённых муниципального района и…","title":"Гайский район","revision":148138031,"qid":"Q544112","license":"CC BY-SA 4.0"},"Q4189366":{"text":"«Звезда» — один из крупнейших кинотеатров в Тверской области. Расположен в центре Твери на набережной Степана Разина, которая проходит по правому берегу Волги. Построен на месте домика Петра I, в котором император останавливался, проезжая через Тверь. Открыт в 1937 году, здание кинотеатра (архитектор В. П. Калмыков) — памятник архитектуры позднего…","title":"Звезда (кинотеатр в Твери)","revision":152215349,"qid":"Q4189366","license":"CC BY-SA 4.0"},"Q4453261":{"text":"Тверской городской музейно-выставочный центр создан в мае 2007 года и уже в июне в одном из залов центра открылась первая выставка. В марте 2009 года центр получил статус муниципального учреждения культуры и его работа продолжилась уже в трёх выставочных залах, где ежемесячно проводятся различные выставки от городского до международного масштаба.","title":"Тверской городской музейно-выставочный центр","revision":147219363,"qid":"Q4453261","license":"CC BY-SA 4.0"},"Q4315028":{"text":"Национальный музей Республики Карелия — крупнейший музей города Петрозаводска, основан в 1871 году губернатором Олонецкой губернии Г. Г. Григорьевым. Расположен в здании бывшего губернаторского дома постройки конца XVIII века.","title":"Национальный музей Республики Карелия","revision":153954900,"qid":"Q4315028","license":"CC BY-SA 4.0"},"Q2605238":{"text":"Музей изобразительных искусств Республики Карелия — музей в городе Петрозаводске, основан в 1960 году.","title":"Музей изобразительных искусств Республики Карелия","revision":153552366,"qid":"Q2605238","license":"CC BY-SA 4.0"},"Q4524815":{"text":"Шишково — деревня в Волоколамском муниципальном округе Московской области России. Входит в состав сельского поселения Кашинское. Население — 275 чел. (2021).","title":"Шишково (Московская область)","revision":152558582,"qid":"Q4524815","license":"CC BY-SA 4.0"},"Q4214453":{"text":"Карачарово — село в Волоколамском районе Московской области России. Входит в состав сельского поселения Осташёвское. Население — 87 чел. (2021).","title":"Карачарово (Волоколамский муниципальный округ)","revision":152555927,"qid":"Q4214453","license":"CC BY-SA 4.0"},"Q4314820":{"text":"Национа́льная библиоте́ка Респу́блики Каре́лия — бюджетное учреждение, главное книгохранилище Республики Карелия для национальных, республиканских, российских и зарубежных изданий. Библиотека содержит более 1,6 миллиона документов по всем отраслям знаний на различных носителях информации. Расположена в городе Петрозаводск.","title":"Национальная библиотека Республики Карелия","revision":155658441,"qid":"Q4314820","license":"CC BY-SA 4.0"},"Q16680610":{"text":"Нижнетагильский театр кукол — один из четырёх театров Нижнего Тагила. Расположен в Ленинском районе Нижнего Тагила на проспекте Ленина, в Центре города. Театр находится между двумя большими скверами (Комсомольским и Пионерским) в историческом центре города.","title":"Нижнетагильский театр кукол","revision":150507482,"qid":"Q16680610","license":"CC BY-SA 4.0"},"Q19911282":{"text":"Нижнетагильская филармония — филармония в городе Нижний Тагил Свердловской области. Одна из первых муниципальных филармоний в России.","title":"Нижнетагильская филармония","revision":152577591,"qid":"Q19911282","license":"CC BY-SA 4.0"},"Q109413618":{"text":"Магада́нский музыка́льный и драмати́ческий теа́тр имени А. М. Горького — театр в Магадане, основан 6 ноября 1938 года.","title":"Магаданский музыкальный и драматический театр имени А. М. Горького","revision":147831321,"qid":"Q109413618","license":"CC BY-SA 4.0"},"Q4449573":{"text":"Таганро́гский морско́й торго́вый порт (ТМТП) — порт на Азовском море в городе Таганроге (Ростовская область России). Полное наименование — Акционерное общество «Таганрогский морской торговый порт».","title":"Таганрогский морской торговый порт","revision":146194075,"qid":"Q4449573","license":"CC BY-SA 4.0"},"Q1652683":{"text":"Ле́нинск-Кузне́цкий райо́н — административно-территориальная единица (район) в Кемеровской области России. В рамках организации местного самоуправления в границах района существует муниципальное образование Ленинск-Кузнецкий муниципальный округ (с 2004 до 2019 гг. — муниципальный район). Административный центр — город Ленинск-Кузнецкий (входит в состав…","title":"Ленинск-Кузнецкий район","revision":152790076,"qid":"Q1652683","license":"CC BY-SA 4.0"},"Q1976280":{"text":"Таганрогский художественный музей — художественный музей в Таганроге, основанный в 1898 году, в год 200-летия Таганрога. Коллекция насчитывает более 7 тыс. единиц.","title":"Таганрогский художественный музей","revision":153455880,"qid":"Q1976280","license":"CC BY-SA 4.0"},"Q4062928":{"text":"Алтайский государственный краеведческий музей — старейший музей Барнаула. Здание музея является памятником архитектуры, истории и культуры середины XIX века и расположено в здании бывшей горной лаборатории, в историческом центре Барнаула в Центральном районе. Адрес: улица Ползунова, 46.","title":"Алтайский государственный краеведческий музей","revision":148052419,"qid":"Q4062928","license":"CC BY-SA 4.0"},"Q4062937":{"text":"Алтайский государственный музыкальный театр — театр в Барнауле и Алтайском крае.","title":"Алтайский театр музыкальной комедии","revision":151543414,"qid":"Q4062937","license":"CC BY-SA 4.0"},"Q4214953":{"text":"Теа́тр ку́кол Респу́блики Каре́лия — государственный театр кукол в столице Республики Карелия Петрозаводске. Является одним из старейших театров кукол в России.","title":"Театр кукол Республики Карелия","revision":153521422,"qid":"Q4214953","license":"CC BY-SA 4.0"},"Q4395750":{"text":"«Ро́дина» — исторический кинотеатр в Барнауле (закрыт в этом качестве 12 января 2017 года). Место временного базирования алтайского театра кукол «Сказка». Расположен в Центральном районе города на проспекте Ленина.","title":"Родина (кинотеатр, Барнаул)","revision":149617820,"qid":"Q4395750","license":"CC BY-SA 4.0"},"Q1998125":{"text":"Кива́ч — охраняемая природная территория, государственный лесной заповедник в России, расположенный в Кондопожском районе Республики Карелия. Центральным объектом заповедника является одноимённый водопад, а создан он для сохранения образцового участка европейских среднетаёжных лесов с отдельными вкраплениями лиственных и широколиственных пород.","title":"Кивач (заповедник)","revision":156262614,"qid":"Q1998125","license":"CC BY-SA 4.0"},"Q3943275":{"text":"Ржавки (ранее посёлок ВНИИПП) — посёлок городского типа в Московской области России. Входит в городской округ Солнечногорск, относится к территориальному управлению Ржавки-Менделеево в рамках администрации городского округа. Население — 4564 чел. (2025 год).","title":"Ржавки","revision":156336374,"qid":"Q3943275","license":"CC BY-SA 4.0"},"Q4518872":{"text":"«Чёрный дельфи́н» (ранее рус. дореф. Илецкій острогъ; ФКУ ИК-6 УФСИН России по Оренбургской области; до 2007 года — ЮК-25/6) — исправительная колония особого режима для пожизненно осуждённых в городе Соль-Илецке рядом с озером Развал (Оренбургская область). Самая большая колония подобного типа в России (на 1600 человек). По некоторым данным, на 2009 год в…","title":"Чёрный дельфин","revision":156293151,"qid":"Q4518872","license":"CC BY-SA 4.0"},"Q4327353":{"text":"Нори́льский Заполя́рный теа́тр дра́мы и́мени Вл. Маяко́вского — драматический театр в Норильске, Россия. Самый северный театр в мире. Старше города более чем на десяток лет, традиционно ведёт свою историю с ноября 1941 года. Находится в центре города, на Театральной площади. В декабре 2009 года Законом Красноярского края (№ 9-4246 от 24.12.2009) Норильский…","title":"Норильский Заполярный театр драмы имени Вл. Маяковского","revision":154588290,"qid":"Q4327353","license":"CC BY-SA 4.0"},"Q4144507":{"text":"Горная аптека — памятник архитектуры федерального значения в Барнауле. Расположен в Центральном районе города на улице Ползунова (бывшей Петропавловской линии). Одноэтажное кирпичное здание, построено в XVIII веке.","title":"Горная аптека","revision":149212447,"qid":"Q4144507","license":"CC BY-SA 4.0"},"Q97270413":{"text":"Музыка́льный теа́тр Респу́блики Каре́лия — государственный театр в Петрозаводске. В репертуаре театра представлены музыкально-сценические жанры: опера, балет, оперетта, музыкальная комедия, мюзикл.","title":"Музыкальный театр Республики Карелия","revision":150643143,"qid":"Q97270413","license":"CC BY-SA 4.0"},"Q4297820":{"text":"Миха́йловское — село, расположенное на южной границе городского округа Домодедово Московской области. Входит в состав Вельяминовского административного округа.","title":"Михайловское (городской округ Домодедово)","revision":153882785,"qid":"Q4297820","license":"CC BY-SA 4.0"},"Q15918779":{"text":"Красный Холм — деревня в Клинском районе Московской области, в составе Нудольского сельского поселения. Население — 8 чел. (2010). До 2006 года Красный Холм входил в состав Малеевского сельского округа. Деревня расположена в южной части района, у границы с Солнечногорским районом, примерно в 16 км к югу от райцентра Клин, на правом берегу реки Катыш…","title":"Красный Холм (Московская область)","revision":146568884,"qid":"Q15918779","license":"CC BY-SA 4.0"},"Q18407193":{"text":"Чурилково — деревня в Московской области. Входит в городской округ Домодедово.","title":"Чурилково (Московская область)","revision":155438420,"qid":"Q18407193","license":"CC BY-SA 4.0"},"Q65173153":{"text":"Губернаторский сад (карел. Gubernuatoran sadu) — парк в городе Петрозаводске, памятник ландшафтной архитектуры, один из старейших парков города. Находится в историческом центре города, ограниченным улицами Герцена, Гоголя, Заводской линией и Закаменским переулком.","title":"Губернаторский сад (Петрозаводск)","revision":147159543,"qid":"Q65173153","license":"CC BY-SA 4.0"},"Q62059633":{"text":"Театр «Грань» — профессиональный драматический театр в Новокуйбышевске.","title":"Грань (театр-студия)","revision":156364391,"qid":"Q62059633","license":"CC BY-SA 4.0"},"Q18781000":{"text":"Колычёво — село в Московской области. Входит в городской округ Домодедово. Расположено на правом берегу реки Пахра, к востоку от города Домодедово, у восточных окраин деревни Чурилково.","title":"Колычёво (городской округ Домодедово)","revision":147699920,"qid":"Q18781000","license":"CC BY-SA 4.0"},"Q60021845":{"text":"Памятник Отто Вильгельмовичу Куусинену — памятник российскому и советскому государственному, политическому и партийному деятелю, установлен на Советской площади города Петрозаводска Республики Карелия. Монумент имеет статус выявленного объекта культурного наследия.","title":"Памятник О. В. Куусинену","revision":151659384,"qid":"Q60021845","license":"CC BY-SA 4.0"},"Q4306253":{"text":"Музей Градостроительства и быта — единственный в России музей градостроительства и быта. Расположен в особняке «Дома Шаронова», отнесённом Указом Президента Российской Федерации № 176 от 20 февраля 1995 года к памятникам архитектуры РФ. Входит в состав Таганрогского государственного литературного и историко-архитектурного музея-заповедника. Музей…","title":"Музей градостроительства и быта","revision":153641835,"qid":"Q4306253","license":"CC BY-SA 4.0"},"Q126646":{"text":"Чувашский государственный театр оперы и балета (чуваш. Чӑваш патшалӑх оперӑпа балет театрӗ) — театр в Чебоксарах, созданный на основе Чувашского государственного музыкального театра в 1993 году. Полное официальное наименование учреждения — Автономное учреждение Чувашской Республики «Чувашский государственный театр оперы и балета» Министерства культуры, по…","title":"Чувашский театр оперы и балета","revision":154630927,"qid":"Q126646","license":"CC BY-SA 4.0"},"Q1994714":{"text":"Иже́вский пруд (Ижевское водохранилище) — искусственный водоём, созданный в 1760 году. Расположен на территории города Ижевска, столицы Удмуртии. Кроме реки Иж, на которой устроен пруд, в него впадают реки Малиновка, Пазелинка, Подборенка, Шабердейка и ручей Пионерский.","title":"Ижевский пруд","revision":154497288,"qid":"Q1994714","license":"CC BY-SA 4.0"},"Q1193131":{"text":"Во́ткинский райо́н (удм. Вотка ёрос) — административно-территориальная единица и упразднённое муниципальное образование (муниципальный район) в Удмуртской республике Российской Федерации. Располагается в восточной части республики. Район образован 4 ноября 1926 года, в результате муниципальной реформы с 1 января 2006 года наделён статусом муниципального…","title":"Воткинский район","revision":151688915,"qid":"Q1193131","license":"CC BY-SA 4.0"},"Q3433576":{"text":"Рязанская ГРЭС (иногда называемая «Новомичуринская ГРЭС») — тепловая электрическая станция в городе Новомичуринск Пронского района Рязанской области (в 80 км к югу от Рязани), на берегу реки Проня. Входит в состав ПАО «ОГК-2». Рязанская ГРЭС занимает шестую позицию в списке мощнейших теплоэлектростанций России, в европейской части России она уступает…","title":"Рязанская ГРЭС","revision":153650018,"qid":"Q3433576","license":"CC BY-SA 4.0"},"Q4517493":{"text":"Чува́шский национа́льный музе́й (чуваш. Чӑваш наци музейӗ) — культурно-образовательное и научно-исследовательское учреждение Чувашской Республики. Крупнейшее хранилище памятников природы, истории, материальной и духовной культуры чувашского и других этносов, центр всей музейной работы на территории Чувашской Республики и в местах компактного проживания…","title":"Чувашский национальный музей","revision":147200369,"qid":"Q4517493","license":"CC BY-SA 4.0"},"Q4146912":{"text":"Государственный ордена «Знак почёта» Русский драматический театр (чуваш. Патшалăх «Хисеп палли» орденлĕ вырăс драма театрĕ) — драматический театр, расположенный в г. Чебоксары. Основан 14 декабря 1922 года.","title":"Русский драматический театр (Чебоксары)","revision":155681405,"qid":"Q4146912","license":"CC BY-SA 4.0"},"Q4198185":{"text":"Ижевский зоопарк (Зоопарк Удмуртии, Бюджетное учреждение культуры Удмуртской Республики «Зоопарк Удмуртии») — государственный зоологический парк, выставочный комплекс, расположенный в парке культуры и отдыха им. Кирова в черте города Ижевска.","title":"Ижевский зоопарк","revision":156323278,"qid":"Q4198185","license":"CC BY-SA 4.0"},"Q4535848":{"text":"Я́блоницы (фин. Jablonitz) — упразднённая деревня на территории Курского сельского поселения Волосовского района Ленинградской области, историческая часть деревни Курск.","title":"Яблоницы","revision":154367062,"qid":"Q4535848","license":"CC BY-SA 4.0"},"Q4209545":{"text":"Калинингра́дский областно́й музе́й изобрази́тельных иску́сств (до ноября 2017 года — Калининградский областной музей «Художественная галерея») — художественный музей в Калининграде, открывшийся 24 ноября 1988 года. Фонды музея насчитывают более 16 тысяч произведений живописи, графики, скульптуры, предметов декоративно-прикладного искусства. Основу собрания…","title":"Калининградский областной музей изобразительных искусств","revision":146332537,"qid":"Q4209545","license":"CC BY-SA 4.0"},"Q4508059":{"text":"Чебокса́ры (чуваш. Шупашкар) — железнодорожная станция Горьковской железной дороги ОАО «РЖД», расположена в центральной части города Чебоксары, столицы Чувашии.","title":"Чебоксары (станция)","revision":156106005,"qid":"Q4508059","license":"CC BY-SA 4.0"},"Q17140201":{"text":"Оренбу́ргский Карава́н-сара́й (тат. Кәрвансарай, баш. Каруанһарай) — историко-архитектурный комплекс в г. Оренбурге (Российская Федерация). Был построен в 1837—1846 годах на добровольные пожертвования для размещения канцелярии командующего Башкиро-мещерякским войском, гостиницы для башкир и мишар, приезжавших в Оренбург «по своей надобности и по делам…","title":"Караван-сарай (Оренбург)","revision":154955119,"qid":"Q17140201","license":"CC BY-SA 4.0"},"Q16639074":{"text":"Государственный театр кукол Удмуртской Республики (удм. Удмурт Республикаысь мунё кун театр) находится в городе Ижевске в Индустриальном районе города.","title":"Государственный театр кукол Удмуртской Республики","revision":155529697,"qid":"Q16639074","license":"CC BY-SA 4.0"},"Q16639081":{"text":"Государственный театр оперы и балета Удмуртской Республики им. Петра Ильича Чайковского находится в Ижевске на Пушкинской улице, примыкая к Центральной площади в Октябрьском районе города.","title":"Государственный театр оперы и балета Удмуртской Республики","revision":142663561,"qid":"Q16639081","license":"CC BY-SA 4.0"},"Q21671128":{"text":"Медовники — деревня в Боровском районе Калужской области России. Входит в состав сельского поселения «Деревня Асеньевское».","title":"Медовники","revision":155854643,"qid":"Q21671128","license":"CC BY-SA 4.0"},"Q1829":{"text":"Калинингра́д (МФА: ) — город в России, административный центр Калининградской области, являющийся самым западным областным центром Российской Федерации. До 4 июля 1946 года город носил название Кёнигсбе́рг (нем. Königsberg), ранее фигурировало название Короле́вец (пол. Królewiec, лит. Karaliaučius, бел. Каралявец, чеш. Královec); до 1255 года — Тва́нгсте…","title":"Калининград","revision":156104067,"qid":"Q1829","license":"CC BY-SA 4.0"},"Q225459":{"text":"До́мский собо́р Богома́тери и Свято́го Адальбе́рта — недействующий кафедральный собор, расположенный в историческом районе города Калининграда — Кнайпхофе (ныне официально именуемом как «Остров Иммануила Канта»), одной из островных частей бывшего восточно-прусского города Кёнигсберга. До начала церковной реформации XVI века собор являлся главным…","title":"Кёнигсбергский собор","revision":154831262,"qid":"Q225459","license":"CC BY-SA 4.0"},"Q571409":{"text":"Кёнигсбергский замок (нем. Königsberger Schloss) — замок Тевтонского ордена в Кёнигсберге (нынешний Калининград). Замок был заложен в 1255 году чешским королём Оттокаром II Пржемыслом и просуществовал до 27 мая 1970 года.До 1945 года в его стенах размещались различные управленческие и общественные учреждения города и Восточной Пруссии, находились музейные…","title":"Кёнигсбергский замок","revision":156071289,"qid":"Q571409","license":"CC BY-SA 4.0"},"Q1913193":{"text":"Чка́ловск (до 29 июля 1948 года — Танненвальде, Зидлунг, нем. Tannenwalde, Siedlung) — микрорайон (ранее поселок), входящий в состав города Калининграда Калининградской области Российской Федерации. Административно относится к Центральному району города. В состав нынешнего Чкаловска входит поселение (бывшее восточно-прусское название — Зидлунг), выросшее…","title":"Чкаловск (Калининград)","revision":153073375,"qid":"Q1913193","license":"CC BY-SA 4.0"},"Q3642634":{"text":"Борисогле́бский городско́й о́круг — административно-территориальная единица и муниципальное образование в статусе городского округа в составе Воронежской области России. Административный центр — город Борисоглебск.","title":"Борисоглебский городской округ","revision":156099349,"qid":"Q3642634","license":"CC BY-SA 4.0"},"Q555977":{"text":"Бранденбу́ргские воро́та (нем. Brandenburger Tor) — одни из восьми сохранившихся городских ворот Калининграда. Расположены у окончания улицы Багратиона, переходящей далее в улицу Суворова (бывшая Берлинская), на границе исторического городского района Хаберберг. Бранденбургские ворота — единственные городские ворота Калининграда, до сих пор использующиеся…","title":"Бранденбургские ворота (Калининград)","revision":153400375,"qid":"Q555977","license":"CC BY-SA 4.0"},"Q2210832":{"text":"Закхаймские ворота (нем. Sackheimer Tor) — памятник истории и культуры федерального значения, одни из восьми сохранившихся городских ворот Калининграда, современное пространство арт-платформы «Ворота» на пересечении Московского проспекта и Литовского вала.","title":"Закхаймские ворота","revision":153400363,"qid":"Q2210832","license":"CC BY-SA 4.0"},"Q3162406":{"text":"Сибирский ботанический сад — первый и в течение долгого времени крупнейший ботанический сад за Уралом. Подразделение Томского государственного университета (ТГУ). Площадь сада 126,5 га, из них: 10 га — заповедный парк, в том числе оранжерейно-тепличный комплекс (в Университетской роще). 116,5 га — экосистемная дендрологическая территория (между…","title":"Сибирский ботанический сад","revision":155970025,"qid":"Q3162406","license":"CC BY-SA 4.0"},"Q322967":{"text":"Кирха памяти королевы Луизы — историческое здание в Калининграде, одна из достопримечательностей города. В прошлом — лютеранская церковь, ныне в здании кирхи расположен Калининградский областной театр кукол. Адрес — проспект Победы, 1 (на территории Центрального парка).","title":"Кирха памяти королевы Луизы","revision":153400141,"qid":"Q322967","license":"CC BY-SA 4.0"},"Q289928":{"text":"Микрорайон имени Алекса́ндра Космодемья́нского — микрорайон, входящий в состав Калининграда (до 1946 года — Метгетен, нем. Metgethen, в 1946—1956 годах — Лесное). Административно относится к Центральному району города. Население составляет примерно тридцать тысяч жителей. Посёлок в 2017 году был переименован в микрорайон Алекса́ндра Космодемья́нского","title":"Микрорайон Александра Космодемьянского","revision":155702059,"qid":"Q289928","license":"CC BY-SA 4.0"},"Q1255657":{"text":"«Калинингра́дский областно́й драмати́ческий теа́тр» — государственный драматический театр Калининградской области Российской Федерации, основанный в 1947 году в Калининграде. Полное официальное наименование театра — «Государственное автономное учреждение Калининградской области „Калининградский областной драматический театр“», сокращённое наименование —…","title":"Калининградский областной драматический театр","revision":152135773,"qid":"Q1255657","license":"CC BY-SA 4.0"},"Q4220894":{"text":"Кинома́кс-Томск — кинотеатр в Томске, до реконструкции назывался «Родина». Расположен по адресу: улица Розы Люксембург, 73. Входит в федеральную сеть кинотеатров «Киномакс».","title":"Киномакс (кинотеатр, Томск)","revision":154930901,"qid":"Q4220894","license":"CC BY-SA 4.0"},"Q1194741":{"text":"Центральный парк Калининграда (ранее — Парк культуры и отдыха имени Калинина, до войны — Луизенваль нем. Luisenwahl) — один из парков Калининграда. Расположен между проспектом Мира, улицей Пушкина, Дмитрия Донского и улицей Сержанта Колоскова. Главный вход — с проспекта Мира. Через парк протекает Парковый ручей (бывший Хуфенфрайграбен нем.…","title":"Центральный парк (Калининград)","revision":154190988,"qid":"Q1194741","license":"CC BY-SA 4.0"},"Q1195681":{"text":"Фридрихсбургские ворота — единственные сохранившиеся до наших дней ворота крепости (позднее — форта) Фридрихсбург в Кёнигсберге (ныне Калининград). Являются объектом культурного наследия народов РФ федерального значения и филиалом Музея Мирового океана.","title":"Фридрихсбургские ворота","revision":155666933,"qid":"Q1195681","license":"CC BY-SA 4.0"},"Q4450877":{"text":"Тамбовский областной краеведческий музей — музей в Тамбове, основанный 24 декабря 1879 года. Музей располагается на Державинской улице в бывшем здании Дома политического просвещения, которое является памятником архитектуры. Фонды музея насчитывают 112 693 единицы хранения, среди них коллекция русской печатной гравюры XVIII—XIX вв., коллекция китайских и…","title":"Тамбовский областной краеведческий музей","revision":155658829,"qid":"Q4450877","license":"CC BY-SA 4.0"},"Q435497":{"text":"Здание кёнигсбергской биржи — одна из достопримечательностей Калининграда, памятник архитектуры. Здание расположено на берегу реки Преголи рядом с Эстакадным мостом (современный адрес Ленинский проспект, дом 83). В настоящее время в здании размещён Калининградский областной музей изобразительных искусств.","title":"Здание биржи (Калининград)","revision":154967101,"qid":"Q435497","license":"CC BY-SA 4.0"},"Q4392418":{"text":"«Дворе́ц Пу́тина» (также «дворец в Геленджике́» или «резиде́нция на мы́се Идокопа́с») — дворцово-парковый ансамбль на берегу Чёрного моря возле села Прасковеевка в 20 км от города Геленджика. По утверждениям и документам предпринимателей, связанных со строительством резиденции, а также согласно расследованиям ряда журналистов, активистов и оппозиционных…","title":"Дворец Путина","revision":154953280,"qid":"Q4392418","license":"CC BY-SA 4.0"},"Q24931497":{"text":"Усадьба Асеевых — музейный комплекс, расположенный в городе Тамбове, на набережной реки Цны. Усадьба включает основное здание, фонтан и парк.","title":"Усадьба Асеевых","revision":151287491,"qid":"Q24931497","license":"CC BY-SA 4.0"},"Q1294226":{"text":"Башня Врангель (нем. Wrangelturm) — это фортификационное сооружение в городе Калининград (до 1946 года — Кёнигсберг).","title":"Башня Врангеля","revision":153400353,"qid":"Q1294226","license":"CC BY-SA 4.0"},"Q102121800":{"text":"Игу́менский парк — небольшой парк вокруг озера в центре Томска. Находится по адресу ул. Карташова 21, рядом с Буфф-садом, лютеранской церковью Святой Марии и Дворцом творчества детей и молодежи г. Томска.","title":"Игуменский парк","revision":155894702,"qid":"Q102121800","license":"CC BY-SA 4.0"},"Q2218646":{"text":"Пересла́вский райо́н — бывшая административно-территориальная единица (район) на юге Ярославской области России. Ныне входит в состав Переславль-Залесского округа. Административный центр — город Переславль-Залесский (в район не входит). В рамках организации местного самоуправления в границах района и райцентра функционирует городской округ город…","title":"Переславский район","revision":154029944,"qid":"Q2218646","license":"CC BY-SA 4.0"},"Q23742":{"text":"Горги́ппия (Синдская гавань, др.-греч. Γοργιππία) — античный город на побережье Чёрного моря, существовавший в IV веке до н. э. — III веке н. э. в составе Боспорского царства.","title":"Горгиппия","revision":154896871,"qid":"Q23742","license":"CC BY-SA 4.0"},"Q4464143":{"text":"Тру́беж — река в Переславском районе Ярославской области России, впадает в Плещеево озеро. Является основным притоком озера.","title":"Трубеж (река, впадает в Плещеево озеро)","revision":146185784,"qid":"Q4464143","license":"CC BY-SA 4.0"},"Q2380900":{"text":"Дагеста́нская о́бласть — административно-территориальная единица в Российской империи и РСФСР, располагавшаяся в северо-восточной части Кавказского перешейка, к северу от Главного Кавказского хребта. Административный центр — Темир-Хан-Шура. На севере Дагестанская область отделялась от Терской области главным образом Сулако-Терским водоразделом, или…","title":"Дагестанская область","revision":153578931,"qid":"Q2380900","license":"CC BY-SA 4.0"},"Q1975841":{"text":"Джиги́нка (также Михаэльсфельд, нем. Michaelsfeld; Джигинское) — село (до 1893 года — хутор) в Краснодарском крае России, входит в состав муниципального образования город-курорт Анапа. Административный центр Джигинского сельского округа.","title":"Джигинка","revision":153042272,"qid":"Q1975841","license":"CC BY-SA 4.0"},"Q4144213":{"text":"Горицкий Успенский монастырь — упразднённый в 1744 году мужской православный монастырь в городе Переславле-Залесском; памятник архитектуры XVII и XVIII веков. До 1788 года использовался как резиденция переславских архиереев (архиерейский двор). На территории монастыря с 1919 года расположен Переславль-Залесский государственный историко-архитектурный и…","title":"Горицкий Успенский монастырь","revision":152223858,"qid":"Q4144213","license":"CC BY-SA 4.0"},"Q4348492":{"text":"Пензенский областной драматический театр имени А. В. Луначарского — один из старейших театров России, расположенный в Пензе.","title":"Пензенский областной драматический театр имени А. В. Луначарского","revision":152736113,"qid":"Q4348492","license":"CC BY-SA 4.0"},"Q152188":{"text":"Кавказская губерния — административная единица Российской империи. Образована в 1785 году в составе Кавказского наместничества. В 1790 году переименована в Кавказскую область и подчинена Астраханской губернии, в 1796 году Кавказская область упразднена. Вновь Кавказская губерния образована в 1802 году с центром в Георгиевске. В 1822 году переименована в…","title":"Кавказская губерния","revision":155145582,"qid":"Q152188","license":"CC BY-SA 4.0"},"Q4306405":{"text":"Музей одной картины имени Г. В. Мясникова — государственный музей в г. Пензе, филиал Пензенской областной картинной галереи им. К. А. Савицкого. Открыт 12 февраля 1983 года.","title":"Музей одной картины имени Г. В. Мясникова","revision":154951068,"qid":"Q4306405","license":"CC BY-SA 4.0"},"Q4279535":{"text":"Мальцевский рынок — рынок в Санкт-Петербурге. Расположен в Центральном районе на улице Некрасова, д. 52. На первом этаже рынка развёрнута торговля преимущественно сельскохозяйственной продукцией. На втором — различными промышленными товарами.","title":"Мальцевский рынок","revision":153789287,"qid":"Q4279535","license":"CC BY-SA 4.0"},"Q4504055":{"text":"ГБУК Центр театрального искусства «Дом Мейерхо́льда» — государственный музей-театр в Пензе, в доме, в котором в 1881—1895 гг. жил Карл Мейерхольд. В экспозиции музея представлены жизнь и творчество В. Э. Мейерхольда. Приоритетным направлением деятельности центра является создание экспериментальных спектаклей, в основе которых лежат научные разработки…","title":"Дом Мейерхольда","revision":155601981,"qid":"Q4504055","license":"CC BY-SA 4.0"},"Q4417807":{"text":"Серпухо́вский музыка́льно-драмати́ческий теа́тр (СМДТ; Серпуховский гортеатр) — единственный в Подмосковье музыкально-драматический театр, расположен в историческом центре Серпухова на пересечении улиц Чехова и Театральной. Основан в 1915 году тенором Большого театра А. А. Говоровым и серпуховским купцом А. В. Малаховцевым.","title":"Серпуховский музыкально-драматический театр","revision":155523913,"qid":"Q4417807","license":"CC BY-SA 4.0"},"Q4504710":{"text":"Це́рковь Проро́ка Ильи́ (церковь Илии́ Пророка «на Торгу́») — православный храм в историческом центре города Серпухова Московской области. Относится к Серпуховскому благочинию Подольской епархии Русской православной церкви.","title":"Церковь Илии Пророка (Серпухов)","revision":146341355,"qid":"Q4504710","license":"CC BY-SA 4.0"},"Q16273189":{"text":"Академгородок — микрорайон города Апатиты, построенный для размещения учреждений Кольского научного центра РАН и проживания его сотрудников. Площадь около 42 га.","title":"Академгородок (Апатиты)","revision":155558349,"qid":"Q16273189","license":"CC BY-SA 4.0"},"Q55658113":{"text":"Камерный театр Малыщицкого — драматический театр Санкт-Петербурга, основанный в 1989 году Владимиром Малыщицким.","title":"Камерный театр Малыщицкого","revision":154686641,"qid":"Q55658113","license":"CC BY-SA 4.0"},"Q116896022":{"text":"Владимирский областной театр кукол — учреждение культуры в городе Владимире. Расположен на улице Гагарина, д. 7. Создан в целях формирования и удовлетворения потребностей населения города Владимира и Владимирской области в сценическом искусстве, развития театра как вида искусства и социального института, пропаганды достижений театра культуры в российских…","title":"Владимирский областной театр кукол","revision":155427778,"qid":"Q116896022","license":"CC BY-SA 4.0"},"Q132783":{"text":"Эрмита́ж (от фр. ermitage — место уединения, келья, приют отшельника, затворничество), Госуда́рственный Эрмита́ж (до 1917 года — Императорский Эрмитаж) — российский государственный художественный и культурно-исторический музей в Санкт-Петербурге, одно из крупнейших в мире учреждений подобного рода. Главный музейный комплекс Эрмитажа расположен в…","title":"Эрмитаж","revision":156052164,"qid":"Q132783","license":"CC BY-SA 4.0"},"Q4407659":{"text":"Санкт-Петербургская государственная Театральная библиотека — библиотечное и научное учреждение культуры Санкт-Петербурга со специализированным фондом рукописных и печатных документов по драматургии, истории и теории театра.","title":"Санкт-Петербургская государственная Театральная библиотека","revision":151452597,"qid":"Q4407659","license":"CC BY-SA 4.0"},"Q16270744":{"text":"«Чижик-Пыжик» — миниатюрная анималистическая скульптура в Санкт-Петербурге. Была установлена 19 ноября 1994 года на реке Фонтанке, у Михайловского (Инженерного) замка рядом с 1-м Инженерным мостом, напротив дома № 12/1. Высота фигурки — 11 см, масса — около 5 кг.","title":"Чижик-Пыжик (памятник)","revision":153455657,"qid":"Q16270744","license":"CC BY-SA 4.0"},"Q1149264":{"text":"Ленинградский зоологический парк — один из старейших зоопарков России и один из самых северных зоопарков мира. Ведёт свою историю от дореволюционного Петербургского зоосада.","title":"Ленинградский зоопарк","revision":156101429,"qid":"Q1149264","license":"CC BY-SA 4.0"},"Q4407688":{"text":"Санкт-Петербургский академический театр Комедии имени Н. П. Акимова — академический театр, получивший славу и достигший наибольшего расцвета при руководстве Николая Павловича Акимова. Официальная дата основания — 1 октября 1929 года. Современное название носит с 1989 года.","title":"Санкт-Петербургский театр комедии имени Н. П. Акимова","revision":156278218,"qid":"Q4407688","license":"CC BY-SA 4.0"},"Q1058832":{"text":"Росси́йский этнографи́ческий музе́й — один из крупнейших этнографических музеев Европы. Основан как этнографический отдел Русского музея, с 1934 года — самостоятельное учреждение. Является членом-учредителем Ассоциации этнографических музеев России. Расположен в Санкт-Петербурге, на Инженерной улице, дом 4/1, рядом со зданием Русского музея. Здание музея…","title":"Российский этнографический музей","revision":155479156,"qid":"Q1058832","license":"CC BY-SA 4.0"},"Q3364400":{"text":"Примо́рский парк Побе́ды — парк, открытый в честь морских побед, одержанных СССР в Великой Отечественной войне. Расположен в Санкт-Петербурге в западной части Крестовского острова. С 1988 года является объектом культурного наследия регионального значения. Начиная с 2010-х годов западная часть парка была лишена охранного статуса и активно застраивается, при…","title":"Приморский парк Победы","revision":154122586,"qid":"Q3364400","license":"CC BY-SA 4.0"},"Q4407739":{"text":"Са́нкт-Петербу́ргский госуда́рственный теа́тр музыка́льной коме́дии — российский театр, основу репертуара которого составляют оперетты и мюзиклы.","title":"Санкт-Петербургский театр музыкальной комедии","revision":156143834,"qid":"Q4407739","license":"CC BY-SA 4.0"},"Q4266865":{"text":"Лопухинский сад — сад в Санкт-Петербурге, памятник архитектуры и истории регионального значения. Расположен по нечётной стороне Каменноостровского проспекта между улицей Академика Павлова и Малой Невкой. Площадь сада составляет 5,7 га.","title":"Лопухинский сад","revision":153450768,"qid":"Q4266865","license":"CC BY-SA 4.0"},"Q3527505":{"text":"Санкт-Петербургский академический театр имени Ленсовета — драматический театр; создан в Ленинграде в 1933 году под названием «Новый театр», в 1953 переименован в Ленинградский театр имени Ленсовета. Занимает бывший особняк князя Голицына на Владимирском проспекте, 12 (архитектор Андрей Михайлов).","title":"Санкт-Петербургский академический театр имени Ленсовета","revision":156324714,"qid":"Q3527505","license":"CC BY-SA 4.0"},"Q4231897":{"text":"Концертный зал Мариинского театра — комплекс концертного зала в Санкт-Петербурге, расположенный в двух зданиях: перестроенном в 2000-х годах здании декорационных мастерских Мариинского театра по адресу: улица Писарева, дом 20 (вход с улицы Декабристов, 37) и соединённом с ним Южном корпусе по адресу: улица Декабристов, дом 39. Открытие Концертного зала…","title":"Концертный зал Мариинского театра","revision":150387016,"qid":"Q4231897","license":"CC BY-SA 4.0"},"Q2349693":{"text":"Эрмитажный театр — театральное здание в Санкт-Петербурге, построенное в 1783—1789 годах по проекту итальянского архитектора Джакомо Кваренги. Здание расположено на месте бывшего Зимнего дворца Петра I, на углу Дворцовой набережной (дом № 32) и Зимней канавки. Оно завершает комплекс построек, протянувшихся вдоль реки Невы и связанных арками и переходами в…","title":"Эрмитажный театр","revision":152816918,"qid":"Q2349693","license":"CC BY-SA 4.0"},"Q1620227":{"text":"Дворец великого князя Алексея Александровича («Дом музыки», «Алексеевский дворец») — один из великокняжеских дворцов Санкт-Петербурга, расположенный на набережной Мойки. Построен М. Е. Месмахером для великого князя Алексея Александровича в 1882—1885 гг. С февраля 2006 года в здании располагается Санкт-Петербургский Дом музыки — учреждение, основная цель…","title":"Дворец великого князя Алексея Александровича","revision":153734722,"qid":"Q1620227","license":"CC BY-SA 4.0"},"Q17489369":{"text":"Музей Фаберже — частный музей в Санкт-Петербурге, расположен во дворце Нарышкиных-Шуваловых. Обладает не имеющим аналогов собранием русского ювелирного и декоративно-прикладного искусств XIX—XX вв. Наиболее ценные и известные предметы в коллекции музея — 9 императорских пасхальных яиц, созданных фирмой Карла Густавовича Фаберже. В коллекции музея, в том…","title":"Музей Фаберже в Санкт-Петербурге","revision":155897264,"qid":"Q17489369","license":"CC BY-SA 4.0"},"Q24591486":{"text":"«Ленинград» — кинотеатр, функционировавший с 1959 до 2004 года по адресу Потемкинская улица, дом 4.","title":"Ленинград (кинотеатр, Санкт-Петербург)","revision":155757937,"qid":"Q24591486","license":"CC BY-SA 4.0"},"Q55344728":{"text":"Дом Теппера де Фергюсона — историческое здание в Пушкине. Построено в 1790-е гг. Объект культурного наследия федерального значения. Расположено на Средней улице, дом 4, на углу с Церковной улицей.","title":"Дом Теппера де Фергюсона","revision":156125419,"qid":"Q55344728","license":"CC BY-SA 4.0"},"Q104245347":{"text":"«СКА Аре́на» — многофункциональный спортивно-концертный комплекс в Санкт-Петербурге. Основная арена комплекса вмещает до 21,5 тысяч зрителей на спортивных мероприятиях и до 23 тысяч — на концертах. Домашняя арена хоккейного клуба СКА и китайского клуба «Шанхайские драконы».","title":"СКА Арена","revision":155336024,"qid":"Q104245347","license":"CC BY-SA 4.0"},"Q120674706":{"text":"Кузнечный рынок — памятник архитектуры. Расположен в Санкт-Петербурге, современный адрес дома — Кузнечный переулок, 3. В XIX веке участок принадлежал Владимирской церкви и был застроен дровяными складами и сараями. Первый рынок на этом месте появился около 1916—1917 года и назывался Владимирским базаром. С 1922 года началось проектирование и постройка…","title":"Кузнечный рынок","revision":151715366,"qid":"Q120674706","license":"CC BY-SA 4.0"},"Q118121947":{"text":"Павловский дворец — памятник архитектуры XVIII — первой трети XIX веков. Расположен в Павловске, в центральном районе Павловского парка (Садовая улица, 20), вместе с которым образует дворцово-парковый музей-заповедник (ГМЗ) «Павловск». До 1786 года строительством дворца занимался Чарлз Камерон, с 1796 по 1800 год архитектором построек дворца был Винченцо…","title":"Павловский дворец","revision":154666367,"qid":"Q118121947","license":"CC BY-SA 4.0"},"Q138504545":{"text":"Нева — кинотеатр, расположенный в Санкт-Петербурге, на Невском проспекте, 108Ш, во дворовом флигеле доходного дома Иванова. Кинотеатр начал работу во дворе дома на рубеже XIX—XX веков. Отдельное здание кинотеатра было возведено в 1913–1914 годах по проекту архитектора Владимира Карповича. Постройка представляла собой двухъярусный корпус. В 1923–1928 годах…","title":"Нева (кинотеатр, Санкт-Петербург)","revision":155108159,"qid":"Q138504545","license":"CC BY-SA 4.0"},"Q211043":{"text":"Госуда́рственный Ру́сский музе́й (сокр. ГРМ; при учреждении и по 1917 год — «Ру́сский Музе́й Импера́тора Алекса́ндра III») — российский государственный художественный музей в Санкт-Петербурге, крупнейшее в мире собрание русского изобразительного искусства. Выставочный комплекс современного Русского музея — один из крупнейших в мире по площади (в общей…","title":"Русский музей","revision":155681372,"qid":"Q211043","license":"CC BY-SA 4.0"},"Q1258473":{"text":"Петерго́ф (от нем. Péterhof — «двор Петра») — дворцово-парковый ансамбль на южном берегу Финского залива. Находится на территории муниципального образования город Петергоф (с 1944 года по 1997 год — «Петродворец») в Петродворцовом районе Санкт-Петербурга. От него произошло название «Петергофской дороги». Часть его находится в ведении государственного…","title":"Петергоф (дворцово-парковый ансамбль)","revision":155918258,"qid":"Q1258473","license":"CC BY-SA 4.0"},"Q775909":{"text":"Импера́торский Царскосе́льский лице́й (с 1843 по 1917 год — Алекса́ндровский лицей) — привилегированное высшее учебное заведение для детей дворян в Российской империи, действовавшее в Царском Селе с 1811 по 1843 год. В русской истории известно в первую очередь как школа, воспитавшая А. С. Пушкина и воспетая им.","title":"Императорский Царскосельский лицей","revision":155229985,"qid":"Q775909","license":"CC BY-SA 4.0"},"Q2753218":{"text":"Шува́ловский парк (в XIX веке: Парголовский сад) — исторический парк в посёлке Парголово, бывшем имении графов Шуваловых, на севере территории современного Санкт-Петербурга. Парк занимает 142 га к северу от реки Старожиловки, из них 136 га находится в границах охраняемого объекта культурного наследия (новое строительство там запрещено). В парке много…","title":"Шуваловский парк","revision":154436580,"qid":"Q2753218","license":"CC BY-SA 4.0"},"Q1461235":{"text":"Стро́гановский дворе́ц — дворец Строгановых, построенный по проекту архитектора Бартоломео Франческо Растрелли в 1753—1754 годах, один из образцов уникального растреллиевского «барочно-рокайльного стиля». Ныне — филиал Государственного Русского музея, которому здание принадлежит с 1988 года.","title":"Строгановский дворец","revision":152544621,"qid":"Q1461235","license":"CC BY-SA 4.0"},"Q2622043":{"text":"Зда́ние Гла́вного шта́ба (Гла́вный штаб и Министе́рства) — историческое здание на Дворцовой площади в Санкт-Петербурге. Построено в 1819—1829 годах. Архитектор: Карл Росси. Скульпторы: Степан Пименов, Василий Демут-Малиновский. До 1917 года в здании располагались Главный штаб Русской императорской армии, Министерство иностранных дел, Министерство финансов,…","title":"Здание Главного штаба","revision":156356047,"qid":"Q2622043","license":"CC BY-SA 4.0"},"Q722970":{"text":"«Газпром Аре́на» (на всех международных матчах — стадион «Санкт-Петербург») — футбольный стадион в Санкт-Петербурге. Расположен на Крестовском острове, на месте снесённого стадиона имени С. М. Кирова. Автор проекта «Газпром Арены» — японский архитектор Кисё Курокава. Строительство стадиона началось в 2007 году. Официально объект введён в эксплуатацию 29…","title":"Газпром Арена","revision":156129767,"qid":"Q722970","license":"CC BY-SA 4.0"},"Q1805979":{"text":"По́ртик Но́вого Эрмита́жа — крыльцо в виде крытой галереи перед главным входом в здание Нового Эрмитажа в Санкт-Петербурге, расположенной на главном (южном) фасаде здания, выходящем на Миллионную улицу. До середины 1920-х годов здесь был вход в музей. Портик украшают десять огромных фигур атлантов работы скульптора А. И. Теребенёва с помощниками, из серого…","title":"Портик Нового Эрмитажа","revision":156048752,"qid":"Q1805979","license":"CC BY-SA 4.0"},"Q4315611":{"text":"Нева́фи́льм (ранее Нева́-1) — российская кинокомпания, расположенная в Санкт-Петербурге. Занимается дублированием иностранных кинофильмов на русский язык, переозвучиванием отечественных фильмов, кинопрокатом, проектированием кинотеатров, поставками оборудования для кинотеатров и сервисом по кинооборудованию, включая IMAX-кинотеатры.","title":"Невафильм","revision":154943675,"qid":"Q4315611","license":"CC BY-SA 4.0"},"Q576071":{"text":"Государственный музей городской скульптуры (сокр. ГМГС) — музей в Санкт-Петербурге, основанный в 1939 году, в сферу деятельности которого, помимо основных музейных мероприятий, также входит изучение, реставрация и охрана памятников монументального искусства, расположенных под открытым небом. Состоит из нескольких филиалов, ряда экспозиционных залов и…","title":"Государственный музей городской скульптуры","revision":151018818,"qid":"Q576071","license":"CC BY-SA 4.0"},"Q2081756":{"text":"Памятник Николаю I установлен на Исаакиевской площади в Санкт-Петербурге. Расположен между Мариинским дворцом и Исаакиевским собором. Памятник начал строиться в 1856 году после смерти императора по проекту архитектора Огюста Монферрана и был открыт 25 июня (7 июля) 1859 года.","title":"Памятник Николаю I","revision":154828179,"qid":"Q2081756","license":"CC BY-SA 4.0"},"Q19842255":{"text":"Монумент героическим защитникам Ленинграда на площади Победы (Мемориал на Средней Рогатке) — памятник подвигу ленинградцев в трагические дни блокады 1941—1944 годов. С апреля 2024 года — объект культурного наследия России регионального значения. В бронзе на Монументе отлиты слова «О камни! Будьте стойкими, как люди!» из стихотворения «Камни» Юрия Воронова…","title":"Монумент героическим защитникам Ленинграда","revision":155350291,"qid":"Q19842255","license":"CC BY-SA 4.0"},"Q12880254":{"text":"Литерату́рное кафе́ — исторически значимый ресторан на Невском проспекте в Санкт-Петербурге, который в XIX веке посещали знаменитые писатели, музыканты, а также их друзья.","title":"Литературное кафе (Санкт-Петербург)","revision":150968407,"qid":"Q12880254","license":"CC BY-SA 4.0"},"Q56310150":{"text":"Санкт-Петербургский государственный театр «Суббота» — театр в Санкт-Петербурге. Театр основан российским ученым, театроведом и режиссёром Юрием Смирновым-Несвицким в 1969 г. в Ленинграде.","title":"Суббота (театр)","revision":154686427,"qid":"Q56310150","license":"CC BY-SA 4.0"},"Q83528889":{"text":"Санкт-Петербу́ргская сту́дия документа́льных фи́льмов (ныне — Откры́тая киносту́дия «Лендо́к») — одна из крупнейших документальных киностудий России, основана в 1932 году как Ленинградская студия кинохроники. В годы Отечественной войны силами остававшихся в блокадном городе сотрудников создан полнометражный фильм — «Ленинград в борьбе» (1942). В 1980-х…","title":"Лендок","revision":155456216,"qid":"Q83528889","license":"CC BY-SA 4.0"},"Q6755164":{"text":"Мра́морный (Палла́диев, Сиби́рский) мост, также Сиби́рская мра́морная галере́я — пешеходный мост в Екатерининском парке Царского Села. Построен в 1772—1774 годах по проекту В. И. Неелова, который повторял, с некоторыми отличиями, палладианский проект, к тому моменту уже несколько раз воспроизведённый в английских усадебных парках и восходящий к мосту в…","title":"Мраморный мост","revision":153406060,"qid":"Q6755164","license":"CC BY-SA 4.0"},"Q124100016":{"text":"Белая башня — памятник архитектуры. Расположен в Александровском парке, в пейзажной части, к северо-западу от дворца.","title":"Белая башня (Царское Село)","revision":153181170,"qid":"Q124100016","license":"CC BY-SA 4.0"},"Q138547289":{"text":"Исаакиевский сквер — маленький городской парк в Санкт-Петербурге, на Исаакиевской площади перед южным фасадом Исаакиевского собора. Имеет форму трапеции, ограничен Большой и Малой Морскими улицами, Вознесенским проспектом, проездом перед домом посольства Германии от Исаакиевского собора на Синий мост. Площадь сквера 0,75 га. Памятник градостроительства и…","title":"Исаакиевский сквер","revision":156348761,"qid":"Q138547289","license":"CC BY-SA 4.0"},"Q2361481":{"text":"Санкт-Петербу́ргский моне́тный двор Гозна́ка (в 1914—1924 — Петроградский монетный двор, в 1924—1996 — Ленинградский монетный двор) — один из крупнейших монетных дворов мира по чеканке монет, в том числе памятных и юбилейных из драгоценных металлов, а также по изготовлению орденов, медалей, знаков отличия и других изделий из цветных металлов и их сплавов.…","title":"Санкт-Петербургский монетный двор","revision":152030030,"qid":"Q2361481","license":"CC BY-SA 4.0"},"Q168713":{"text":"«Авро́ра» — крейсер 1-го ранга Балтийского флота типа «Диана». Назван в честь парусного фрегата «Аврора», прославившегося при обороне Петропавловска-Камчатского в годы Крымской войны. Во время русско-японской войны участвовал в походе Второй Тихоокеанской эскадры, закончившимся Цусимским сражением. Крейсер принимал участие также в Первой мировой войне.…","title":"Аврора (крейсер)","revision":155500214,"qid":"Q168713","license":"CC BY-SA 4.0"},"Q260832":{"text":"Комаро́во (до 1948 года — Ке́лломяки, от фин. Kellomäki — колокольная горка) — посёлок в России, внутригородское муниципальное образование в составе Курортного района города федерального значения Санкт-Петербурга.","title":"Комарово (Санкт-Петербург)","revision":155826504,"qid":"Q260832","license":"CC BY-SA 4.0"},"Q46850":{"text":"Зеленого́рск (до 1948 года — Те́рийо́ки, Терио́ки, от фин. Terijoki — Смоляная река) — город в России, внутригородское муниципальное образование в составе Курортного района города федерального значения Санкт-Петербурга, климатический курорт на северном берегу Финского залива Балтийского моря. Железнодорожная станция Зеленогорск расположена на 50-м…","title":"Зеленогорск (Санкт-Петербург)","revision":155747660,"qid":"Q46850","license":"CC BY-SA 4.0"},"Q207028":{"text":"Госуда́рственный академи́ческий Марии́нский теа́тр (в 1935—1992 годах — Ленинградский ордена Ленина и ордена Октябрьской Революции академический театр оперы и балета имени С. М. Кирова, также часто сокращённо — Кировский театр, в просторечии — Мариинка) — театр оперы и балета в Санкт-Петербурге, один из ведущих музыкальных театров России и мира. Труппа,…","title":"Мариинский театр","revision":155935492,"qid":"Q207028","license":"CC BY-SA 4.0"},"Q588680":{"text":"Константиновский дворец (Большой Стрельнинский дворец) — памятник архитектуры XVIII века, формирующий дворцово-парковый ансамбль в Стрельне, с 2003 года — Государственный комплекс «Дворец конгрессов». Комплекс находится на южном берегу Финского залива на реках Стрелка и Кикенка вдоль Петергофской дороги в 19 км от центра Санкт-Петербурга. Находится в…","title":"Константиновский дворец","revision":155586431,"qid":"Q588680","license":"CC BY-SA 4.0"},"Q1277585":{"text":"Музе́й антрополо́гии и этногра́фии и́мени Петра́ Вели́кого Российской академии наук (акрон. МАЭ РАН, МАЭ), также известный под историческим названием Кунстка́мера (устар. куншткамора, от нем. Kunstkammer — кабинет искусств или кабинет редкостей) — российский государственный естественно-научный музей в Санкт-Петербурге, учреждённый Петром Великим в 1714…","title":"Кунсткамера","revision":156179001,"qid":"Q1277585","license":"CC BY-SA 4.0"},"Q2000542":{"text":"Миха́йловский или Инжене́рный за́мок — бывший императорский дворец в центре Санкт-Петербурга по адресу Садовая ул., № 2. Возведён по заказу императора Павла I на рубеже XVIII—XIX веков в стиле романтического классицизма по типу «замка на воде» (расположен на стыке реки Мойки и реки Фонтанки; с западной и южной сторон были несохранившийся Церковный канал и…","title":"Михайловский замок","revision":154512734,"qid":"Q2000542","license":"CC BY-SA 4.0"},"Q4068202":{"text":"Апра́ксин двор — архитектурный комплекс в центральной части Санкт-Петербурга между Садовой улицей, Апраксиным переулком, набережной реки Фонтанки и улицей Ломоносова, один из крупнейших исторических торговых центров города. Занимает площадь в 14 гектаров, включает в себя 57 корпусов. Общая площадь внутренних помещений составляет 170 тыс. м². Комплекс…","title":"Апраксин двор","revision":155703740,"qid":"Q4068202","license":"CC BY-SA 4.0"},"Q4304236":{"text":"Моско́вский парк Побе́ды, (в 1939—1945 гг. Московский парк культуры и отдыха) — парк в Московском районе Санкт-Петербурга. Впервые заложен в 1939—1941 годах в соответствии с Генеральным планом развития Ленинграда как Парк культуры и отдыха. Повторно заложен в 1945 году в честь Победы в Великой Отечественной войне как парк Победы. Ограничен с севера…","title":"Московский парк Победы","revision":154095967,"qid":"Q4304236","license":"CC BY-SA 4.0"},"Q1229016":{"text":"Марии́нский дворе́ц — дворец в Санкт-Петербурге на Исаакиевской площади, назван в честь дочери императора Николая I Марии, которой предназначался как свадебный подарок по случаю бракосочетания с герцогом Максимилианом Лейхтенбергским. Построен в 1839—1844 годах по проекту Андрея Штакеншнейдера и считается[кем?] лучшим произведением зодчего. В 1880-х годах…","title":"Мариинский дворец (Санкт-Петербург)","revision":156318616,"qid":"Q1229016","license":"CC BY-SA 4.0"},"Q3363766":{"text":"Алекса́ндровский парк — парк в составе Государственного музея-заповедника «Царское Село». Находится на территории города Пушкин в Санкт-Петербурге, памятник архитектуры XVIII—XIX веков. Площадь — около 200 га. Примыкает к Екатерининскому дворцу со стороны парадного входа, откуда можно попасть в парк по Большому китайскому мосту. С другой стороны пройти в…","title":"Александровский парк (Царское Село)","revision":152352680,"qid":"Q3363766","license":"CC BY-SA 4.0"},"Q4475857":{"text":"Университе́тская набережная — набережная Большой Невы в Санкт-Петербурге, на Васильевском острове, пролегающая от Биржевой площади до площади Трезини и 6-й линии.","title":"Университетская набережная","revision":149519166,"qid":"Q4475857","license":"CC BY-SA 4.0"},"Q1990715":{"text":"Николаевский дворец — бывшая трёхэтажная резиденция великого князя Николая Николаевича в глубине обнесённого решёткой сквера на площади Труда Санкт-Петербурга. Строился в 1853—1861 годах известным мастером эклектики А. И. Штакеншнейдером и его помощниками Августом Ланге и Карлом Циглером. При дворце имелись манеж и церковь, освящённая во имя иконы «Всех…","title":"Николаевский дворец","revision":156178103,"qid":"Q1990715","license":"CC BY-SA 4.0"},"Q4167652":{"text":"Санкт-Петербургский государственный драматический театр «Комедианты» — камерный театр, работающий с 25 декабря 1989 года. На 17 декабря 2014 года в театре служило 113 человек из них труппа — 38 актёров.","title":"Комедианты (театр)","revision":146332615,"qid":"Q4167652","license":"CC BY-SA 4.0"},"Q4159466":{"text":"Санкт-Петербургский государственный детский драматический театр «На Неве́» (Детский театр «На Неве») — авторский театр Заслуженного деятеля искусств России Татьяны Аркадьевны Са́венковой.","title":"На Неве (театр)","revision":155930333,"qid":"Q4159466","license":"CC BY-SA 4.0"},"Q3287172":{"text":"Конногвардейский манеж — (Центральный выставочный зал «Манеж», 1977—2015) монументальное здание в стиле классицизма, которое было выстроено в Санкт-Петербурге в 1804—1807 годах по проекту Джакомо Кваренги для зимней и летней выучки, а также парадных конных выездок Лейб-гвардии Конного полка. Здание манежа занимает часть Конногвардейского бульвара, фасадом…","title":"Конногвардейский манеж","revision":150774620,"qid":"Q3287172","license":"CC BY-SA 4.0"},"Q2402356":{"text":"Памятник Екатерине II — памятник на площади Островского в Санкт-Петербурге, установленный в честь императрицы Екатерины II в 1873 году.","title":"Памятник Екатерине II (Санкт-Петербург)","revision":155484422,"qid":"Q2402356","license":"CC BY-SA 4.0"},"Q19788418":{"text":"Драматический театр Балтийского флота — театр Балтфлота. В декабре 1930 года окончились манёвры Краснознаменного БалтФлота. По этому случаю был дан концерт, на котором присутствовал Маршал Советского Союза К. Е. Ворошилов. Под впечатлением от мастерства актёров, маршал предложил создать военно-морской театр из числа энтузиастов в городе-крепости Кронштадт.","title":"Драматический театр Балтийского флота","revision":155892503,"qid":"Q19788418","license":"CC BY-SA 4.0"},"Q691377":{"text":"Екатеринго́ф (нем. Ekaterinhof, Katharinenhof, то есть «двор Екатерины») — исторический пейзажный парк на юго-западе Адмиралтейского района Санкт-Петербурга, ведущий свою историю с петровского времени, когда в устье речки Екатерингофки был выстроен Подзорный дворец. В 1933 году переименован в парк имени 1-го Мая, затем в 1948 году в парк имени 30-летия…","title":"Екатерингоф","revision":156307501,"qid":"Q691377","license":"CC BY-SA 4.0"},"Q672444":{"text":"«Ме́дный вса́дник» — монументальный конный памятник первому российскому императору Петру Великому, созданный в 1768—1778 годах французским скульптором Этьеном Морисом Фальконе, открытый на Сенатской площади в Санкт-Петербурге 7 (18) августа 1782 года. Один из символов Санкт-Петербурга и одно из самых известных произведений русского классицизма. Название…","title":"Медный всадник","revision":156049232,"qid":"Q672444","license":"CC BY-SA 4.0"},"Q2367636":{"text":"Стрелка Васильевского острова — мыс на восточной оконечности Васильевского острова в Санкт-Петербурге, омываемый Большой Невой и Малой Невой; один из самых известных архитектурных ансамблей города; пример гармонии архитектуры города с пейзажем берегов Невы. Стрелка Васильевского острова относится к исторической части Санкт-Петербурга и вместе с находящимся…","title":"Стрелка Васильевского острова","revision":153965797,"qid":"Q2367636","license":"CC BY-SA 4.0"},"Q219746":{"text":"Адмиралте́йский райо́н — административно-территориальная единица Санкт-Петербурга. Расположен в центральной части города на левом берегу реки Невы.","title":"Адмиралтейский район","revision":155415076,"qid":"Q219746","license":"CC BY-SA 4.0"},"Q1267630":{"text":"Металлостро́й — посёлок в России, внутригородское муниципальное образование в составе Колпинского района города Санкт-Петербурга. В посёлке располагаются железнодорожные платформы Металлострой, имеющая выход к одноимённому депо, и Ижоры.","title":"Металлострой","revision":155711493,"qid":"Q1267630","license":"CC BY-SA 4.0"},"Q4373150":{"text":"Пороховы́е — муниципальный округ, муниципальное образование в составе Красногвардейского района Санкт-Петербурга. Включает в себя южную и западную части жилого района Ржевка-Пороховые, в которую также входят исторические районы Жерновка и Малиновка. Границы округа проходят по Соединительной железнодорожной линии, железнодорожным линиям Ладожский вокзал —…","title":"Пороховые (муниципальный округ)","revision":156175629,"qid":"Q4373150","license":"CC BY-SA 4.0"},"Q270112":{"text":"Моско́вский райо́н — административно-территориальная единица Санкт-Петербурга. Занимает площадь 7305,48 гектаров в центральном секторе южной части города между Кировским и Красносельским районами на западе и Фрунзенским районом на востоке. Южную и юго-западную оконечность Московского района формирует граница с Пушкинским районом, сформированным в 1938—1959…","title":"Московский район (Санкт-Петербург)","revision":154618067,"qid":"Q270112","license":"CC BY-SA 4.0"},"Q4504316":{"text":"Центральный музей связи имени А. С. Попова — один из старейших научно-технических музеев мира, основанный в 1872 году как Телеграфный музей. Тематически посвящён истории развития различных видов связи, включая почту, телеграф, телефон, радиосвязь, радиовещание, телевидение, космическую связь, современные технологии связи. В музее хранится Государственная…","title":"Центральный музей связи имени А. С. Попова","revision":154915165,"qid":"Q4504316","license":"CC BY-SA 4.0"},"Q2317742":{"text":"Дворцо́вая набережная — набережная реки Невы в центре Санкт-Петербурга. Проходит от набережной реки Фонтанки до Дворцового моста, за которым продолжается Адмиралтейской набережной. За Фонтанкой продолжается набережной Кутузова. Длина — 1,3 км. На набережной расположены здания Государственного Эрмитажа, Русского музея и пр. Вышеупомянутые здания занимают…","title":"Дворцовая набережная","revision":154369812,"qid":"Q2317742","license":"CC BY-SA 4.0"},"Q4114427":{"text":"Военно-медицинский музей — музей медицины России и военно-медицинской службы — хранитель первых медицинских музеев Российской империи и Советского Союза: Мастеровой избы, Хирургического музея Императорской Медико-хирургической академии, Музея Н. И. Пирогова, Военно-санитарного музея, Музея военно-медицинской службы Красной армии, Музея Красного Креста и…","title":"Военно-медицинский музей","revision":150544768,"qid":"Q4114427","license":"CC BY-SA 4.0"},"Q4504094":{"text":"Центральная ТЭЦ — предприятие энергетики Санкт-Петербурга, входящее в ПАО «ТГК-1». Объединяет в себе три старейшие электростанции России, здания которых построены в 1897-1898 годах. Установленная электрическая мощность станции ЭС-1 — 100 МВт, ЭС-2 — 23 МВт. Установленная тепловая мощность станции ЭС-1 — 624 Гкал/ч, ЭС-2 — 756 Гкал/ч. Основное топливо…","title":"Центральная ТЭЦ (Санкт-Петербург)","revision":154187546,"qid":"Q4504094","license":"CC BY-SA 4.0"},"Q2025062":{"text":"Зоологи́ческий музе́й Зоологи́ческого институ́та Росси́йской акаде́мии нау́к — старейший зоологический музей на территории России и один из трёх крупнейших в мире. Расположен в Санкт-Петербурге. Выставочная коллекция насчитывает около 30 000 экспонатов. История музея восходит к Кунсткамере, первому отечественному музею, основанному Петром I в 1714 году.","title":"Зоологический музей Зоологического института РАН","revision":154927094,"qid":"Q2025062","license":"CC BY-SA 4.0"},"Q4493373":{"text":"Фундаментальная библиотека Санкт-Петербургского государственного политехнического университета (ФБ СПбГПУ) — открылась одновременно с Санкт-Петербургским политехническим институтом в 1902 году и в настоящее время является одной из крупнейших в городе. В создании библиотеки и формировании её фондов принимали участие ведущие ученые Санкт-Петербургского…","title":"Фундаментальная библиотека Санкт-Петербургского государственного политехнического университета","revision":133269414,"qid":"Q4493373","license":"CC BY-SA 4.0"},"Q2077375":{"text":"Коло́нна Сла́вы (Па́мятник Сла́вы) — памятник. Воздвигнут в Санкт-Петербурге перед Троицким собором в честь подвигов русских войск, принимавших участие и победивших в Русско-турецкой войне 1877—1878 годов. Был построен в 1886 году, снесен в 1930 году и восстановлен в 2005 году.","title":"Колонна Славы","revision":155289765,"qid":"Q2077375","license":"CC BY-SA 4.0"},"Q4211214":{"text":"Каменноостровский театр — один из сохранившихся в Санкт-Петербурге памятников деревянного зодчества эпохи классицизма. Здание было построено в 1827 г. по проекту архитектора С. Л. Шустова. С 2005 года Каменноостровский театр — часть сценического комплекса Большого драматического театра.","title":"Каменноостровский театр","revision":152215879,"qid":"Q4211214","license":"CC BY-SA 4.0"},"Q16678420":{"text":"Музей гигиены (Музей гигиены Городского центра медицинской профилактики) — естественно-научный музей в Санкт-Петербурге. Основан в 1919 году.","title":"Музей гигиены (Санкт-Петербург)","revision":153639407,"qid":"Q16678420","license":"CC BY-SA 4.0"},"Q17333545":{"text":"Тучко́в буя́н (от устаревшего буян — речная пристань; место для выгрузки товаров с судов), в XIX веке ошибочно именовался «дворец Бирона» — бывшее здание пеньковых складов, выстроенное в 1763—1772 годах на одноимённом островке в русле Малой Невы, памятник раннеклассической петербургской архитектуры. В начале XX века протоки между буяном, соседними…","title":"Тучков буян","revision":155412123,"qid":"Q17333545","license":"CC BY-SA 4.0"},"Q55541554":{"text":"Дом Ф. Каноббио (Канобио) — историческое здание в Пушкине по адресу Леонтьевская улица, дом 18. Построено в 1815 году, имеет статус объекта культурного наследия федерального значения.","title":"Дом Каноббио","revision":154524443,"qid":"Q55541554","license":"CC BY-SA 4.0"},"Q151860":{"text":"Блокада Ленинграда — военная блокада города Ленинграда (ныне — Санкт-Петербург) немецкими и финскими войсками и их союзниками во время Великой Отечественной войны. Длилась с 8 сентября 1941 по 27 января 1944 года (блокадное кольцо было прорвано 18 января 1943 года) — блокада продолжалась 872 дня, в ряде источников 871 день. В литературе и на памятниках…","title":"Блокада Ленинграда","revision":156044665,"qid":"Q151860","license":"CC BY-SA 4.0"},"Q178310":{"text":"Петерго́ф (от нем. Peterhof — «двор Петра», «Петров двор», с 1944 по 1997 год — Петродворе́ц) — город, внутригородское муниципальное образование в составе Петродворцового района города федерального значения Санкт-Петербурга. Расположен на южном берегу Финского залива к западу от Санкт-Петербурга, в 29 км по железной дороге. Крупный туристический (ГМЗ…","title":"Петергоф","revision":155747756,"qid":"Q178310","license":"CC BY-SA 4.0"},"Q270402":{"text":"Куро́ртный райо́н — административно-территориальная единица Санкт-Петербурга. До 1994 года назывался Сестрорецким по имени города Сестрорецка.","title":"Курортный район","revision":156276961,"qid":"Q270402","license":"CC BY-SA 4.0"},"Q4334119":{"text":"О́льгино — исторический район Санкт-Петербурга, примыкающий к историческому району Лахта с запада. Включён в черту города 17 января 1963 года. Входит в Приморский район Петербурга в составе внутригородского муниципального образования Лахта-Ольгино.","title":"Ольгино (исторический район)","revision":153518913,"qid":"Q4334119","license":"CC BY-SA 4.0"},"Q2367357":{"text":"Но́вая Голла́ндия — остров в Адмиралтейском районе Санкт-Петербурга, ограниченный рекой Мойкой, Крюковым и Адмиралтейским каналами. Кроме того, Новая Голландия — один из старейших утилитарных ансамблей города. Площадь острова — 7,8 га.","title":"Новая Голландия","revision":155237824,"qid":"Q2367357","license":"CC BY-SA 4.0"},"Q3350078":{"text":"Суздальское (до 23.10.2025 — Муниципа́льный о́круг № 15) — муниципальный округ в составе Выборгского района Санкт-Петербурга. Администрация округа находится по адресу: улица Руднева, 4.","title":"Суздальское (муниципальный округ)","revision":153410814,"qid":"Q3350078","license":"CC BY-SA 4.0"},"Q4313104":{"text":"На́рвский о́круг — муниципальный округ, муниципальное образование в составе Кировского района Санкт-Петербурга. Нарвский округ расположен на юго-западе Санкт-Петербурга. В своих нынешних границах он существует с 1997 года. В XVIII веке граница города проходила по реке Фонтанке, и вся местность за рекой именовалась Московской стороной, а начало дороги на…","title":"Нарвский округ","revision":151084848,"qid":"Q4313104","license":"CC BY-SA 4.0"},"Q4238184":{"text":"Кра́сненькая ре́чка — муниципальный округ № 30 в составе Кировского района Санкт-Петербурга.","title":"Красненькая речка","revision":151084841,"qid":"Q4238184","license":"CC BY-SA 4.0"},"Q1024181":{"text":"Институ́т ру́сской литерату́ры (Пу́шкинский Дом) Росси́йской акаде́мии нау́к (сокращенное наименование: ИРЛИ РАН) — научное учреждение, подведомственное Министерству науки и высшего образования Российской Федерации и Российской академии наук. В структуру Института входят научно-исследовательские отделы, центры, группы и лаборатории, а также Литературный…","title":"Пушкинский Дом","revision":155658215,"qid":"Q1024181","license":"CC BY-SA 4.0"},"Q3563832":{"text":"Комаро́вский мост — автодорожный железобетонный рамный мост через реку Охту в Красногвардейском районе Санкт-Петербурга. По мнению ряда авторов, относится к числу лучших ленинградских мостов 1960-х годов.","title":"Комаровский мост","revision":151360708,"qid":"Q3563832","license":"CC BY-SA 4.0"},"Q968295":{"text":"Дом торгового товарищества «Братья Елисеевы» (Елисеевский магазин) — здание на углу Невского проспекта (дом 56) и Малой Садовой улицы (дом 8) в Санкт-Петербурге, памятник архитектуры раннего модерна, или «модерн-классицизма».","title":"Дом торгового товарищества «Братья Елисеевы»","revision":153950154,"qid":"Q968295","license":"CC BY-SA 4.0"},"Q2388030":{"text":"Вое́нно-истори́ческий музе́й артилле́рии, инжене́рных войск и войск свя́зи (Артиллерийский музей) — советский и российский музей в Санкт-Петербурге.","title":"Военно-исторический музей артиллерии, инженерных войск и войск связи","revision":156334784,"qid":"Q2388030","license":"CC BY-SA 4.0"},"Q24930021":{"text":"Гром-ка́мень — валун, ставший основой пьедестала Медного всадника. Исторические координаты камня:","title":"Гром-камень","revision":156049058,"qid":"Q24930021","license":"CC BY-SA 4.0"},"Q4095118":{"text":"Ботани́ческий сад Санкт-Петербургского государственного университета находится во дворе здания Двенадцати коллегий. Насчитывает более 4600 видов растений.","title":"Ботанический сад СПбГУ","revision":156117353,"qid":"Q4095118","license":"CC BY-SA 4.0"},"Q4165576":{"text":"Дом с башнями в Санкт-Петербурге, также известный как дом Розенштейна — Белогруда — здание на площади Льва Толстого, обращённое центральной частью к Каменноостровскому проспекту и выходящее боковыми фасадами на Большой проспект и улицу Льва Толстого. Благодаря двум мощным шестигранным башням-эркерам здание стало архитектурной доминантой площади Льва…","title":"Дом с башнями","revision":156007613,"qid":"Q4165576","license":"CC BY-SA 4.0"},"Q1621200":{"text":"Ца́рское Село́ — музей-заповедник в Пушкине, включающий в себя дворцово-парковый ансамбль XVIII—XIX веков, бывшую загородную царскую резиденцию, превращённую в музей после национализации в марте 1918 года. Современное название музей-заповедник получил в 1992 году. В состав музея-заповедника входят Екатерининский парк с дворцом и павильонами,…","title":"Царское Село (музей-заповедник)","revision":154772750,"qid":"Q1621200","license":"CC BY-SA 4.0"},"Q2506336":{"text":"Павловский парк — пейзажный парк в составе Государственного музея-заповедника «Павловск». Расположен в долине реки Славянки в городе Павловске под Санкт-Петербургом, памятник русского классицизма конца XVIII — начала XIX веков с коллекциями русского, западноевропейского и античного искусства. Площадь парка составляет около 600 га. Парк включает семь…","title":"Павловский парк","revision":154572825,"qid":"Q2506336","license":"CC BY-SA 4.0"},"Q616578":{"text":"Исторический центр Санкт-Петербурга и связанные с ним группы памятников (англ. Historic Centre of Saint Petersburg and Related Groups of Monuments) — первый в СССР и России объект Всемирного наследия ЮНЕСКО. Он был включён в список памятников Всемирного наследия на 14-й сессии комитета Всемирного наследия — одновременно с четырьмя другими советскими…","title":"Исторический центр Санкт-Петербурга и связанные с ним группы памятников","revision":154182288,"qid":"Q616578","license":"CC BY-SA 4.0"},"Q4407679":{"text":"Санкт-Петербургский Дом музыки (Федеральное государственное бюджетное учреждение культуры «Дом музыки») — учреждение в системе Министерства культуры РФ, созданное в 2006 г. Располагается в стенах бывшего дворца великого князя Алексея Александровича (набережная реки Мойки, д. 122).","title":"Санкт-Петербургский Дом музыки","revision":146509943,"qid":"Q4407679","license":"CC BY-SA 4.0"},"Q2817285":{"text":"Па́мятник Низами́ Гянджеви́ — памятник выдающемуся поэту, классику персидской поэзии, уроженцу Гянджи Низами Гянджеви, установленный в Санкт-Петербурге, в сквере, расположенном между домами 25 и 27а по Каменноостровскому проспекту.","title":"Памятник Низами Гянджеви (Санкт-Петербург)","revision":151659342,"qid":"Q2817285","license":"CC BY-SA 4.0"},"Q182147":{"text":"Зи́мний дворе́ц (в 1918—1943 годах — Дворец Искусств) — главный императорский дворец России, расположенный на Дворцовой площади в Санкт-Петербурге. Здание дворца (пятое по счёту) было построено в 1754—1762 годах российским архитектором итальянского происхождения Франческо Бартоломео Растрелли в стиле пышного елизаветинского барокко с элементами…","title":"Зимний дворец","revision":155922907,"qid":"Q182147","license":"CC BY-SA 4.0"},"Q1229234":{"text":"Ле́тний сад — парковый ансамбль, памятник садово-паркового искусства первой трети XVIII века в Центральном районе Санкт-Петербурга. Сад был заложен по повелению Петра I в 1704 году и первоначально был регулярным. Занимает отдельный одноимённый остров, омываемый реками Невой, Фонтанкой, Мойкой и Лебяжьей канавкой.","title":"Летний сад","revision":154171880,"qid":"Q1229234","license":"CC BY-SA 4.0"},"Q215423":{"text":"Исаа́киевский собо́р (собор преподо́бного Исаа́кия Далма́тского) — крупнейший православный храм в Санкт-Петербурге. Расположен на Исаакиевской площади. Кафедральный собор Санкт-Петербургской епархии с 1858 по 1929 год. С 1928 года имеет статус музея (Государственный музей «Исаакиевский собор»). Современное здание собора является четвёртым петербургским…","title":"Исаакиевский собор","revision":156323080,"qid":"Q215423","license":"CC BY-SA 4.0"},"Q907366":{"text":"Алекса́ндровская коло́нна (также иногда называется Александрийский столп, по стихотворению А. С. Пушкина «Памятник») — памятник в стиле ампир, находящийся в центре Дворцовой площади Санкт-Петербурга. Воздвигнута в 1834 году архитектором Огюстом Монферраном по указу императора Николая I в память о победе его старшего брата Александра I над Наполеоном.…","title":"Александровская колонна","revision":156049002,"qid":"Q907366","license":"CC BY-SA 4.0"},"Q1963797":{"text":"Воронцо́вский дворе́ц — дворец в центральной части Санкт-Петербурга, расположенный на Садовой улице напротив Гостиного двора. Возведён по проекту архитектора Франческо Растрелли в 1749—1758 годах для канцлера Михаила Воронцова. Дворец отличался богатым, нарядным декором фасадов и пышной отделкой интерьеров, имеет более 50 парадных залов и помещений. Из-за…","title":"Воронцовский дворец (Санкт-Петербург)","revision":152214022,"qid":"Q1963797","license":"CC BY-SA 4.0"},"Q4315896":{"text":"ТЧ-5 «Не́вское» — тяговое (эксплуатационное) электродепо Петербургского метрополитена, расположено на Невско-Василеостровской линии, за станцией «Рыбацкое». Обслуживает Невско-Василеостровскую линию.","title":"Невское (электродепо)","revision":152862183,"qid":"Q4315896","license":"CC BY-SA 4.0"},"Q3661730":{"text":"Дом Петра I — первая постройка в Санкт-Петербурге, жилище царя Петра I в период с 1703 по 1708 год. Этот небольшой деревянный дом площадью 60 м2 был построен солдатами-плотниками недалеко от Троицкой площади всего за три дня — с 13 мая (24 мая) 1703 по 15 мая (26 мая) 1703. Здесь же 16 мая (27 мая) прошло празднование по случаю присоединения земель и…","title":"Домик Петра I (Санкт-Петербург)","revision":156184639,"qid":"Q3661730","license":"CC BY-SA 4.0"},"Q4212326":{"text":"Кандикю́ля (фин. Peräkylä) — деревня в составе Лебяженского городского поселения Ломоносовского района Ленинградской области России.","title":"Кандикюля","revision":152262634,"qid":"Q4212326","license":"CC BY-SA 4.0"},"Q4334115":{"text":"О́льгино — платформа Сестрорецкого направления Октябрьской железной дороги в Санкт-Петербурге, в юго-западной оконечности посёлка Ольгино. Расположена рядом с Песочной улицей и Коннолахтинским проспектом, на участке перегона Лахта — Лисий Нос и имеет одну платформу, расположенную с северной стороны пути.На платформе можно найти расписание движения…","title":"Ольгино (платформа, Санкт-Петербург)","revision":149719905,"qid":"Q4334115","license":"CC BY-SA 4.0"},"Q3301865":{"text":"Великокняжеская усыпальница — усыпальница некоронованных членов российского императорского дома, расположена в Санкт-Петербурге в Петропавловской крепости рядом с Петропавловским собором. Традиционное название «Великокняжеская усыпальница» не совсем точно: помимо особ, имевших титул великих князей и княгинь, усыпальница была предназначена также для князей…","title":"Великокняжеская усыпальница","revision":155351710,"qid":"Q3301865","license":"CC BY-SA 4.0"},"Q4165338":{"text":"Дом Ме́ртенса — историческое здание, памятник архитектуры на Невском проспекте в Санкт-Петербурге: торговый дом, стиль которого иллюстрирует оригинальное течение модерн-классицизма в архитектуре русского модерна.","title":"Дом Мертенса","revision":155341742,"qid":"Q4165338","license":"CC BY-SA 4.0"},"Q4343404":{"text":"Памятник Чапаеву — памятник Василию Ивановичу Чапаеву перед Военной академией связи им. С. М. Будённого в Санкт-Петербурге. Монумент отлит скульптором Матвеем Манизером в 1933—1934 годах и является точной копией его же памятника 1932 года, установленного в Самаре. Монумент охраняется государством как памятник монументального искусства регионального значения.","title":"Памятник Чапаеву (Санкт-Петербург)","revision":155578443,"qid":"Q4343404","license":"CC BY-SA 4.0"},"Q3361196":{"text":"Ново-Михайловский дворец — памятник архитектуры федерального значения, великокняжеский дворец, расположенный в центре Санкт-Петербурга по адресу Дворцовая набережная, 18 и Миллионная улица, 19 (Шталмейстерский корпус). Архитектор — Андре́й Ива́нович Штакеншне́йдер, дворец считается третьей крупной великокняжеской резиденцией, возведённой по проекту…","title":"Ново-Михайловский дворец","revision":155294375,"qid":"Q3361196","license":"CC BY-SA 4.0"},"Q4365826":{"text":"Площадь Шевче́нко — площадь в Петроградском районе Санкт-Петербурга, образованная пересечением Малого проспекта Петроградской стороны, Левашовского проспекта и Ординарной улицы. Названа так в 2001 году в честь великого украинского поэта, прозаика и художника Тараса Григорьевича Шевченко, чья жизнь была тесно связана с Санкт-Петербургом.","title":"Площадь Шевченко (Санкт-Петербург)","revision":146465177,"qid":"Q4365826","license":"CC BY-SA 4.0"},"Q4198652":{"text":"Измайловский сад (сад Буфф) — парк в Санкт-Петербурге, расположенный на набережной реки Фонтанки.","title":"Измайловский сад (Санкт-Петербург)","revision":150188550,"qid":"Q4198652","license":"CC BY-SA 4.0"},"Q4474191":{"text":"Улица Те́льмана — улица в Невском районе Санкт-Петербурга. Широтная улица в жилом районе Севернее улицы Новосёлов, а также в историческом районе Весёлый Посёлок. Проходит от Октябрьской набережной до проспекта Большевиков. Параллельна улице Новосёлов и улице Крыленко. Участок от Октябрьской набережной до Дальневосточного проспекта фактически представляет…","title":"Улица Тельмана (Санкт-Петербург)","revision":148371633,"qid":"Q4474191","license":"CC BY-SA 4.0"},"Q101244339":{"text":"Памятник А. С. Грибоедову — скульптурный монумент русскому писателю и дипломату А. С. Грибоедову. Установлен в 1959 году в Санкт-Петербурге на Пионерской площади перед Театром юных зрителей имени А. А. Брянцева. Авторы проекта памятника — скульптор В. В. Лишев и архитектор В. И. Яковлев. Памятник является объектом культурного наследия федерального значения.","title":"Памятник А. С. Грибоедову (Санкт-Петербург)","revision":151658216,"qid":"Q101244339","license":"CC BY-SA 4.0"},"Q120450716":{"text":"Кофейный домик (Павильон Росси) — памятник архитектуры. Расположен в Санкт-Петербурге, в Летнем саду, на набережной Фонтанки.","title":"Кофейный домик","revision":150968328,"qid":"Q120450716","license":"CC BY-SA 4.0"},"Q124034413":{"text":"Пирамида (египетская пирамида, пирамида из дикого камня, пирамида с урнами, пирамидальный мавзолей, пирамидальная беседка, китайская пирамида) — памятник архитектуры. Расположен в Екатерининском парке Царского Села (город Пушкин) к югу от Мраморного моста.","title":"Пирамида (Царское Село)","revision":155980673,"qid":"Q124034413","license":"CC BY-SA 4.0"},"Q21643738":{"text":"Памятник Николаю Михайловичу Пржевальскому в Санкт-Петербурге находится в Александровском саду в Адмиралтейском районе города. Памятник является объектом культурного наследия федерального значения.","title":"Памятник Пржевальскому (Санкт-Петербург)","revision":148597545,"qid":"Q21643738","license":"CC BY-SA 4.0"},"ru-63fcf18a365e-o8a102dedbdd9":{"text":"Гридчинхолл (англ. Gridchinhall) — арт-центр, частная галерея современного искусства, одна из первых российских художественных резиденций. Основанный предпринимателем и коллекционером Сергеем Гридчиным, Гридчинхолл ориентируется на развитие оригинальных проектов, созданных в резиденции или в сотрудничестве с арт-центром. Гридчинхолл был открыт 19 сентября…","title":"Гридчинхолл","revision":154590250,"qid":"Q4149514","license":"CC BY-SA 4.0"},"ru-63fcf18a365e-o6b6169d6c545":{"text":"Гридчинхолл (англ. Gridchinhall) — арт-центр, частная галерея современного искусства, одна из первых российских художественных резиденций. Основанный предпринимателем и коллекционером Сергеем Гридчиным, Гридчинхолл ориентируется на развитие оригинальных проектов, созданных в резиденции или в сотрудничестве с арт-центром. Гридчинхолл был открыт 19 сентября…","title":"Гридчинхолл","revision":154590250,"qid":"Q4149514","license":"CC BY-SA 4.0"},"ru-63fcf18a365e-o6b9f8a86d8aa":{"text":"Красного́рский филиа́л Музе́я Побе́ды — музей в Красногорске, основанный в 1985 году. Филиал Центрального музея Великой Отечественной войны (Музей Победы).","title":"Мемориальный музей немецких антифашистов","revision":152761055,"qid":"Q4290259","license":"CC BY-SA 4.0"},"ru-6b1bab7dee45-oe35d0450306b":{"text":"Яросла́вский зоопа́рк — крупнейший по занимаемой площади зоопарк России. Ярославский зоопарк — первый в России и странах СНГ зоопарк ландшафтного типа, расположенный в Заволжском районе Ярославля, вблизи Смоленского бора. Официально открыт 20 августа 2008 года в рамках подготовки к 1000-летию Ярославля. Общая площадь зоопарка составила более 67 гектаров,…","title":"Ярославский зоопарк","revision":153680599,"qid":"Q16723452","license":"CC BY-SA 4.0"},"ru-6edd2a33d03a-o70f76d55c761":{"text":"Канашский вагоноремонтный завод — российское предприятие по производству и ремонту вагонов для нужд железнодорожного транспорта, одно из старейших предприятий Чувашской республики. Расположен в городе Канаш. Входит в Концерн «Тракторные заводы». Оператором завода является ООО «Канашский вагоноремонтный завод» (ИНН 2123023410), ранее — АО «Вагон» (прежнее…","title":"Канашский вагоноремонтный завод","revision":154342039,"qid":"Q4212220","license":"CC BY-SA 4.0"},"ru-7339e8342cb4-oc622736bfde0":{"text":"Ино́рс (ИНОРС) — жилой район в Калининском районе на северо-востоке города Уфы. Расположен на месте исторического села Моторного (Богородского), основанном в 1604 году. В Инорсе расположен историко-архитектурный ансамбль XIX века, включающий Казанско-Богородскую церковь и Богородскую надкладезную часовню, а также постройка сталинской архитектуры — Дом…","title":"Инорс","revision":149186006,"qid":"Q4201286","license":"CC BY-SA 4.0"},"ru-7339e8342cb4-o5956c1b4d4db":{"text":"Памятник Загиру Исмагилову установлен в Уфе в Кировском районе города.","title":"Памятник Загиру Исмагилову","revision":154591994,"qid":"Q4343177","license":"CC BY-SA 4.0"},"ru-784b1911182d-o5a402c55287f":{"text":"Парк истории реки Чусовой — этнографический музей под открытым небом в Пермском крае, собравший в себе экспонаты крестьянского быта Среднего Урала XIX — начала XX вв. Основатель музея — Постников, Леонард Дмитриевич, заслуженный работник культуры России.","title":"Парк истории реки Чусовой","revision":147198452,"qid":"Q4533059","license":"CC BY-SA 4.0"},"ru-79da737a603b-oe01d23fd0e33":{"text":"Адлерская ТЭС — российская электростанция, расположенная в районе Имеретинской низменности Адлерского района города Сочи Краснодарского края и занимает площадь в 9,89 га.","title":"Адлерская ТЭС","revision":146459547,"qid":"Q4057618","license":"CC BY-SA 4.0"},"ru-7b6de6a586d0-o600ef5c7bcfe":{"text":"Открытое акционерное общество «Издательско-полиграфический комплекс „Дальпресс“» — издательско-полиграфический комплекс, расположенный во Владивостоке. Образован на базе издательства «Красное знамя», основанного в 1987 году и является лидером на рынке печатной продукции Дальнего Востока. Руководителем общества является Мая Щекина.","title":"Дальпресс","revision":147343604,"qid":"Q27346410","license":"CC BY-SA 4.0"},"ru-7b6de6a586d0-o749105d1a530":{"text":"Ханка́йский райо́н — административно-территориальная единица (район) в Приморском крае России. В рамках организации местного самоуправления ему соответствует муниципальное образование Ханкайский муниципальный округ (с 2004 до 2020 гг. — муниципальный район). Административный центр — село Камень-Рыболов.","title":"Ханкайский район","revision":151259085,"qid":"Q904381","license":"CC BY-SA 4.0"},"ru-7b6de6a586d0-of7f93e26ec47":{"text":"Бухта Теляковского — внутренняя акватория залива Петра Великого Японского моря, располагается у восточного побережья полуострова Гамова в Хасанском районе, Приморского края, между мысом Гамова и мысом Теляковского.","title":"Бухта Теляковского","revision":154597512,"qid":"Q4100561","license":"CC BY-SA 4.0"},"ru-7dfa745eaa19-o55ededc0951a":{"text":"Краснодарский краевой выставочный зал изобразительных искусств — крупнейший художественный экспозиционный центр на юге России.","title":"Краснодарский краевой выставочный зал изобразительных искусств","revision":147510562,"qid":"Q4238531","license":"CC BY-SA 4.0"},"ru-7eeb876e7b67-oae83ae529135":{"text":"Лопа́сня-Зача́тьевское — памятник архитектуры и садово-паркового искусства XVIII – XIX веков, усадебный ансамбль, и находящийся в главном доме музей в городе Чехове Московской области (бывшее село Лопасня), по адресу: ул. Пушкина, 7, 10. На протяжении нескольких столетий имение на реке Лопасня принадлежало Васильчиковым; с XVI века до 1917 года оно…","title":"Лопасня-Зачатьевское","revision":151708152,"qid":"Q16157365","license":"CC BY-SA 4.0"},"Q1092754":{"text":"Уфи́мский райо́н (баш. Өфө районы) — административно-территориальная единица (район) и муниципальное образование (муниципальный район), в её границах под наименованием муниципальный район Уфимский район (баш. Өфө районы муниципаль районы) в составе Республики Башкортостан Российской Федерации. Административный центр — город Уфа (не входит в состав района).","title":"Уфимский район","revision":156327528,"qid":"Q1092754","license":"CC BY-SA 4.0"},"Q781569":{"text":"Аургази́нский райо́н (баш. Ауырғазы районы) — административно-территориальная единица (район) и муниципальное образование (муниципальный район) в её границах под наименованием муниципальный район Аургазинский район (баш. Ауырғазы районы муниципаль районы) в составе Республики Башкортостан Российской Федерации. Административный центр — село Толбазы,…","title":"Аургазинский район","revision":155799157,"qid":"Q781569","license":"CC BY-SA 4.0"},"Q1636570":{"text":"Тобо́льский кремль — единственный каменный кремль в Сибири, уникальный образец сибирского зодчества. Создавался в XVII—XVIII веках.","title":"Тобольский кремль","revision":156283101,"qid":"Q1636570","license":"CC BY-SA 4.0"},"Q2575351":{"text":"Мелеке́сский райо́н — административно-территориальная единица (административный район) и муниципальное образование (муниципальный район) в Ульяновской области России Крупнейший по площади (3472,3 км²) район области, образован в 1928 году.","title":"Мелекесский район","revision":154905107,"qid":"Q2575351","license":"CC BY-SA 4.0"},"Q4080170":{"text":"Башкирский государственный художественный музей имени М. В. Нестерова (баш. М. В. Нестеров исемендәге Башҡорт дәүләт художество музейы) — художественный музей Уфы. Основан 5 января 1919 года, открыт 5 января 1920 года.","title":"Башкирский государственный художественный музей имени М. В. Нестерова","revision":153829355,"qid":"Q4080170","license":"CC BY-SA 4.0"},"Q1653880":{"text":"Охинский район — административно-территориальная единица (район), в границах которой вместо упразднённого одноимённого муниципального района образован Охинский муниципальный округ в Сахалинской области России. Административный центр — город Оха.","title":"Охинский район","revision":156106562,"qid":"Q1653880","license":"CC BY-SA 4.0"},"Q4123105":{"text":"Во́лжская ба́шня (Во́лжские воро́та, Арсена́льная ба́шня) — бывшая крепостная башня в Ярославле, одна из трёх сохранившихся башен Земляного города.","title":"Волжская башня","revision":156349863,"qid":"Q4123105","license":"CC BY-SA 4.0"},"Q4113610":{"text":"Вла́сьевская (Зна́менская) башня — бывшая крепостная башня в Ярославле, одна из трёх сохранившихся башен Земляного города. Первое название башни происходит от находившейся рядом древней Власьевской церкви, второе — от Знаменской церкви, пристроенной к башне с восточной стороны в середине XIX века. Башню также называли Углицкими воротами, так как от неё…","title":"Власьевская башня (Ярославль)","revision":156001956,"qid":"Q4113610","license":"CC BY-SA 4.0"},"Q2269003":{"text":"Семендер (до 1996 года — совхоз им. Ленина) — посёлок городского типа в Дагестане. Входит в городской округ город Махачкала. Подчинён Кировской районной администрации города Махачкала.","title":"Семендер (посёлок городского типа)","revision":152834888,"qid":"Q2269003","license":"CC BY-SA 4.0"},"Q2083279":{"text":"Башкирский государственный академический театр драмы имени Мажита Гафури (баш. Мәжит Ғафури исемендәге Башҡорт дәүләт академия драма театры) — драматический театр в городе Уфе, носящий имя народного поэта Башкортостана Мажита Гафури.","title":"Башкирский театр драмы имени Мажита Гафури","revision":155946115,"qid":"Q2083279","license":"CC BY-SA 4.0"},"Q4080168":{"text":"Башкирский государственный театр кукол (баш. Башҡорт дәүләт ҡурсаҡ театры) — один из старейших театров Республики Башкортостан.","title":"Башкирский государственный театр кукол","revision":155945948,"qid":"Q4080168","license":"CC BY-SA 4.0"},"Q4153932":{"text":"Дагестанский государственный театр кукол — кукольный театр в городе Махачкала.","title":"Дагестанский театр кукол","revision":144111405,"qid":"Q4153932","license":"CC BY-SA 4.0"},"Q4302175":{"text":"«Дру́жба» (баш. Дуҫлыҡ; разг. монумент Дружбы) — монумент в честь 400-летия присоединения (вхождения) исторического Башкортостана в состав Русского государства, на Первомайской площади в городе Уфе. Установлен в историческом центре города — Старой Уфе — на Троицком холме, где ранее находились Уфимский кремль и уничтоженная Троицкая церковь. Объект…","title":"Монумент Дружбы (Уфа)","revision":150569213,"qid":"Q4302175","license":"CC BY-SA 4.0"},"Q4395753":{"text":"«Ро́дина» — типовой кинотеатр в Новой Уфе, на улице Ленина в Кировском районе города Уфы. Здание является памятником архитектуры второй половины XX века, относится к объектам культурного наследия России. Единственно действующий из старейших кинотеатров Уфы. Имел филиалы — Дом просвещения (ныне — Молодежный театр) и Дом актёра. В кинотеатре проводятся…","title":"Родина (кинотеатр, Уфа)","revision":146471365,"qid":"Q4395753","license":"CC BY-SA 4.0"},"Q4290215":{"text":"Мемориальный Дом-музей С. Т. Аксакова (баш. С. Т. Аксаковтың мемориаль йорт-музейы) — музей в городе Уфе, расположенный в доме, в котором жил писатель С. Т. Аксаков. Музей является филиалом Национального музея Республики Башкортостан. Основан в 1978 году.","title":"Мемориальный дом-музей С. Т. Аксакова","revision":150213030,"qid":"Q4290215","license":"CC BY-SA 4.0"},"Q21656893":{"text":"Орский краеведческий музей — расположен в Орске по адресу проспект Ленина, 46.","title":"Орский краеведческий музей","revision":152398711,"qid":"Q21656893","license":"CC BY-SA 4.0"},"Q60850503":{"text":"Национальный музей Республики Дагестан им. А. Тахо-Годи — учреждение культуры Республики Дагестан. Находится в Махачкале, в здании дома Барятинского-Ванецова по адресу улица Даниялова, 31. Здание музея является памятником градостроительства и архитектуры в статусе объекта культурного наследия России регионального значения.","title":"Национальный музей Республики Дагестан имени А. Тахо-Годи","revision":152794187,"qid":"Q60850503","license":"CC BY-SA 4.0"},"Q111987813":{"text":"«Волна» — единственный парк в Затоне Ленинского района города Уфы, в квартале улиц Ирендык, Союзной, Шмидта и Ахметова.","title":"Волна (парк, Уфа)","revision":155036700,"qid":"Q111987813","license":"CC BY-SA 4.0"},"Q114210067":{"text":"«Башкортоста́н» (ранее — Дворец культуры «Нефтяник») — государственный концертный зал на улице Ленина в Новой Уфе Кировского района города Уфы, одно из самых крупных сооружений Башкортостана — площадь всех его помещений составляет более 15000 м2. Напротив расположено здание КГБ Башкирской АССР, с которым концертный зал создают единый ансамбль.","title":"Башкортостан (концертный зал)","revision":146946200,"qid":"Q114210067","license":"CC BY-SA 4.0"},"Q1072349":{"text":"Стерлитама́кский райо́н (баш. Стәрлетамаҡ районы) — административно-территориальная единица (район) и муниципальное образование (муниципальный район) в её границах под наименованием муниципальный район Стерлитамакский район (баш. Стәрлетамаҡ районы муниципаль районы) в составе Республики Башкортостан Российской Федерации. Административный центр — город…","title":"Стерлитамакский район","revision":155145073,"qid":"Q1072349","license":"CC BY-SA 4.0"},"Q2218003":{"text":"Зубцо́вский муниципа́льный о́круг — административно-территориальная единица и одноимённое муниципальное образование (муниципальный округ) на юге Тверской области России. Административный центр — город Зубцов.","title":"Зубцовский муниципальный округ","revision":156100733,"qid":"Q2218003","license":"CC BY-SA 4.0"},"Q4174801":{"text":"Елизаве́тинская — станица в Прикубанском внутригородском округе города Краснодара. Административный центр Елизаветинского сельского округа. Станица расположена на левом берегу реки Кубани, в 7 км. к западу от центра Краснодара, напротив адыгейского аула Хаштук. Елизаветинская примыкает восточной и северной окраинами к городской черте Краснодара. В границы…","title":"Елизаветинская (Краснодарский край)","revision":156106058,"qid":"Q4174801","license":"CC BY-SA 4.0"},"Q2711863":{"text":"Ко́льский райо́н — административно-территориальная единица в Мурманской области. В границах района образован одноимённый муниципальный район. Административный центр — город Кола.","title":"Кольский район","revision":154914489,"qid":"Q2711863","license":"CC BY-SA 4.0"},"Q4238521":{"text":"Краснодарская филармония имени Григория Пономаренко — государственное концертное бюджетное учреждение культуры Краснодарского края. Образована 10 мая 1939 года. С 1997 года носит имя композитора Г. Ф. Пономаренко. С 2011 года Государственное концертное бюджетное учреждение культуры Краснодарского края «Краснодарская филармония имени Г. Ф. Пономаренко».…","title":"Краснодарская филармония имени Григория Пономаренко","revision":147837089,"qid":"Q4238521","license":"CC BY-SA 4.0"},"Q4511853":{"text":"Чепелёво — деревня в Чеховском муниципальном районе в Московской области в составе сельского поселения Стремиловское. Расположена на старом Симферопольском шоссе в 4 км от г. Чехова и в 45-47 км от МКАД. С юго-западной стороны к деревне примыкает железнодорожная линия Московско-Курского направления с расположенной на ней пл. Чепелёво. Эту деревню часто…","title":"Чепелёво (Московская область)","revision":152555878,"qid":"Q4511853","license":"CC BY-SA 4.0"},"Q4238532":{"text":"Краснодарский краевой художественный музей имени Ф. А. Коваленко — один из старейших художественных музеев на Северном Кавказе. Фонд музея насчитывает около 13 000 произведений живописи, графики, скульптуры и декоративно-прикладного искусства. Коллекция русского искусства представлена от основных школ иконописи: новгородской, московской, северной до…","title":"Краснодарский краевой художественный музей имени Ф. А. Коваленко","revision":153802934,"qid":"Q4238532","license":"CC BY-SA 4.0"},"Q4056058":{"text":"Кинотеа́тр «Авро́ра» — широкоформатный кинотеатр в Краснодаре, объект культурного наследия регионального значения.","title":"Аврора (кинотеатр, Краснодар)","revision":146291033,"qid":"Q4056058","license":"CC BY-SA 4.0"},"Q4304643":{"text":"Мостови́к — посёлок в Сергиево-Посадском городском округе Московской области.","title":"Мостовик (посёлок)","revision":154945201,"qid":"Q4304643","license":"CC BY-SA 4.0"},"Q4238526":{"text":"Краснодарский академический театр драмы им. Горького — драматический театр в Краснодаре.","title":"Краснодарский академический театр драмы","revision":152733808,"qid":"Q4238526","license":"CC BY-SA 4.0"},"Q2218125":{"text":"Шимановский райо́н — административно-территориальная единица (район) и муниципальное образование (муниципальный район) в Амурской области России. Административный центр — город Шимановск (в состав района не входит).","title":"Шимановский район","revision":154064315,"qid":"Q2218125","license":"CC BY-SA 4.0"},"Q16666890":{"text":"Краснодарский краевой театр кукол — театр в Краснодаре, расположенный по адресу ул. Красная, 31.","title":"Краснодарский краевой театр кукол","revision":156344595,"qid":"Q16666890","license":"CC BY-SA 4.0"},"Q18396427":{"text":"Алекса́ндровская триумфа́льная а́рка (также Ца́рские воро́та) — памятник в русском стиле в центре Краснодара, расположенный на пересечении двух улиц — Красной и Бабушкина. Возведена к визиту Императора Александра III вместе с августейшей семьёй в Екатеринодар в 1888 году. Разрушена в 1928 году, восстановлена в 2008 году на новом месте.","title":"Царские ворота (Краснодар)","revision":156249489,"qid":"Q18396427","license":"CC BY-SA 4.0"},"Q122680640":{"text":"Литературный музей Кубани — музей в Краснодаре, представляющий литературную жизнь Кубани с первой половины XVIII века до наших дней. Является отделом Краснодарского государственного историко-археологического музея-заповедника им. Е. Д. Фелицына. Расположен в здании — единственном сохранившемся в Краснодаре образце деревянного зодчества начала XIX века.","title":"Литературный музей Кубани","revision":147791708,"qid":"Q122680640","license":"CC BY-SA 4.0"},"Q124323179":{"text":"Каскадная лестница — достопримечательность в Кисловодске, Ставропольский край, Россия. Расположена у входа в Кисловодский национальный парк, продолжая проспект Дзержинского и связывая центр города с верхней частью парка. Является одной из визитных карточек кисловодского курорта.","title":"Каскадная лестница (Кисловодск)","revision":144599584,"qid":"Q124323179","license":"CC BY-SA 4.0"},"Q124360974":{"text":"Курортный зал Общества Вла­ди­кав­каз­ской железной дороги, сокращённо — Курзал, — комплекс зданий в Кисловодске, Ставропольский край, Россия. Расположен к западу от железнодорожного вокзала, по адресу пр-т Карла Маркса, д. 3а. Является объектом культурного наследия федерального значения. В настоящее время помещения Курзала используются Северо-Кавказской…","title":"Курзал (Кисловодск)","revision":138118435,"qid":"Q124360974","license":"CC BY-SA 4.0"},"Q203479":{"text":"Дом Па́влова (Дом Солдатской Славы, Дом Афанасьева — Павлова) — 4-этажный жилой дом, расположенный на площади Ленина в Волгограде, в котором во время Сталинградской битвы в течение 58 дней героически держала оборону группа советских бойцов. Часть историков считают, что обороной руководил старший сержант Яков Павлов, принявший командование отделением от…","title":"Дом Павлова","revision":155376139,"qid":"Q203479","license":"CC BY-SA 4.0"},"Q1601986":{"text":"«Ро́дина-мать зовёт!» — скульптура, композиционный центр памятника-ансамбля «Героям Сталинградской битвы» на Мамаевом кургане в Волгограде. Символ города, одна из самых высоких статуй мира, высочайшая статуя России (без постамента — самая высокая статуя в мире на момент постройки и в течение последующих 22 лет).","title":"Родина-мать (Волгоград)","revision":154120939,"qid":"Q1601986","license":"CC BY-SA 4.0"},"Q2456133":{"text":"Спа́со-Преображе́нский собо́р — православный храм в городе Новокузнецке Кемеровской области, кафедральный собор Новокузнецкой епархии Русской православной церкви. Построен в XVIII веке. Вид на храм, располагавшийся на высокой береговой террасе реки Томи, открывался при подъезде к городу. Долгое время Спасо-Преображенский собор с его сорокаметровой…","title":"Спасо-Преображенский собор (Новокузнецк)","revision":153127151,"qid":"Q2456133","license":"CC BY-SA 4.0"},"Q2218449":{"text":"Вышневоло́цкий райо́н — район, существовавший в Тверской области России с 1929 до 2019 года, а также соответствующий ему одноимённый муниципальный район (2006—2019). Административный центр — город Вышний Волочёк (в состав района не входит). В апреле 2019 года муниципальный район был упразднён, а все входившие в его состав поселения были объединены с…","title":"Вышневолоцкий район","revision":150571774,"qid":"Q2218449","license":"CC BY-SA 4.0"},"Q1651606":{"text":"Гусь-Хруста́льный райо́н (ранее Гусевско́й район) — административно-территориальная единица (район), которому с 2025 года соответствует муниципальное образование Гусь-Хрустальный муниципальный округ, на юге Владимирской области России. Административный центр — город Гусь-Хрустальный (не входит в состав района).","title":"Гусь-Хрустальный район","revision":154904954,"qid":"Q1651606","license":"CC BY-SA 4.0"},"Q770040":{"text":"Тульский кремль — каменная крепость в центре Тулы, памятник архитектуры XVI века, старейшее сооружение города и области.","title":"Тульский кремль","revision":152104815,"qid":"Q770040","license":"CC BY-SA 4.0"},"Q2382926":{"text":"Невья́нская ба́шня — наклонная башня, расположенная в центре Невьянска, была построена в 1721—1725 годах по приказу Акинфия Никитича Демидова. Входит в состав Невьянского государственного историко-архитектурного музея. Высота башни — 57,5 метров, основание в плане представляет собой квадрат со стороной около 9 метров. Отклонение башни от вертикали — около…","title":"Невьянская башня","revision":155925821,"qid":"Q2382926","license":"CC BY-SA 4.0"},"Q4306088":{"text":"Музей «Тульские самовары» — музей в г. Тула, Россия, филиал музейного объединения «Тульский областной историко-архитектурный и литературный музей». Основа экспозиции, коллекция образцов самоваров XVIII—XX веков.","title":"Тульские самовары (музей)","revision":154792377,"qid":"Q4306088","license":"CC BY-SA 4.0"},"Q285506":{"text":"Ке́жемский райо́н — административно-территориальная единица (район) и муниципальное образование (муниципальный район) в восточной части Красноярского края России. Приравнен к районам Крайнего Севера, находится в Нижнем Приангарье. Административный центр — город Кодинск (до 1988 года административным центром было село Кежма).","title":"Кежемский район","revision":155932416,"qid":"Q285506","license":"CC BY-SA 4.0"},"Q3982347":{"text":"Новокузнецкий драматический театр — государственное автономное учреждение культуры в городе Новокузнецке Кемеровской области, один из старейших театров Кузбасса, важный центр культурной жизни города. Расположен в специально построенном здании на проспекте Металлургов, дом 28.","title":"Новокузнецкий драматический театр","revision":155837427,"qid":"Q3982347","license":"CC BY-SA 4.0"},"Q4496816":{"text":"Национальный парк «Хвалынский» — расположен в Хвалынском районе, в северо-восточной части Саратовского Правобережья и в юго-восточной части Приволжской возвышенности.","title":"Хвалынский национальный парк","revision":154134134,"qid":"Q4496816","license":"CC BY-SA 4.0"},"Q4360419":{"text":"Петраковское — село в Хасавюртовском районе Дагестана. Вместе с селом Могилевское составляют Могилевский сельсовет.","title":"Петраковское (Дагестан)","revision":148440645,"qid":"Q4360419","license":"CC BY-SA 4.0"},"Q1319514":{"text":"Культурно-спортивный комплекс «Ледовый дворец „Витязь“» — спортивное сооружение в городе Подольск, Московская область, Россия. Вмещает 5500 зрителей. С 2013 по 2022 год здесь выступал клуб Континентальной хоккейной лиги «Витязь» (переехавший из Чехова обратно в Подольск ввиду недостаточной вместимости арены в Чехове). Также здесь выступала команда…","title":"Витязь (ледовый дворец)","revision":154199305,"qid":"Q1319514","license":"CC BY-SA 4.0"},"Q4057337":{"text":"Ада́мова ме́льница (Ада́мовская ме́льница) — мукомольная мельница купцов Адамовых. Одна из достопримечательностей Ливенского района Орловской области и региональный памятник промышленной архитектуры конца XIX века.","title":"Адамова мельница","revision":153856972,"qid":"Q4057337","license":"CC BY-SA 4.0"},"Q4465219":{"text":"Ту́льская областна́я филармо́ния — государственное учреждение культуры, расположенное в историческом центре города Тулы. Носит имя народного артиста РСФСР И. А. Михайловского.","title":"Тульская областная филармония","revision":147338798,"qid":"Q4465219","license":"CC BY-SA 4.0"},"Q18246464":{"text":"Историко-мемориальный музей Демидовых — учреждение культуры в городе Тула, филиал Государственного учреждения культуры Тульской области \"Объединение «Историко-краеведческий и художественный музей». Посвящён династии Демидовых — русских предпринимателей-горнозаводчиков, крупных промышленников. Составной частью музея является родовая усыпальница Демидовых в…","title":"Историко-мемориальный музей Демидовых","revision":152217558,"qid":"Q18246464","license":"CC BY-SA 4.0"},"Q19649505":{"text":"Де́нежниково — посёлок в Раменском муниципальном районе Московской области. Входит в состав сельского поселения Константиновское. Население — 977 чел. (2010).","title":"Денежниково (посёлок, Раменский муниципальный округ)","revision":152557803,"qid":"Q19649505","license":"CC BY-SA 4.0"},"Q47223376":{"text":"Новокузнецкий художественный музей расположен в городе Новокузнецк, является первым художественным музеем в Кузбассе, был основан в 1961 году. По состоянию на сентябрь 2021 года, насчитывает более 9300 произведений живописи, графики, скульптуры, декоративно-прикладного искусства, а также небольшие отделы редкой книги, фотографии и детского рисунка, однако…","title":"Новокузнецкий художественный музей","revision":155002719,"qid":"Q47223376","license":"CC BY-SA 4.0"},"Q100786302":{"text":"Музей станка (также Музей машин, ранее — Музей станкостроения) — первый в России мультимедийный музей машин, который посвящён становлению промышленности в России, в том числе на примере Тульской области с медиатекой — бесплатной электронной энциклопедией. Площадь музея составляет 700 м2. По версии издания Russia Beyond, вошёл в пятёрку популярных…","title":"Музей станка","revision":150241057,"qid":"Q100786302","license":"CC BY-SA 4.0"},"Q110319499":{"text":"Сад Металлургов — сад Центрального района города Новокузнецка, граничит с парком культуры и отдыха имени Ю. А. Гагарина и Дворцом культуры и техники КМК. Первоначально — сквер Кузнецкого металлургического комбината.","title":"Сад Металлургов (Новокузнецк)","revision":146905808,"qid":"Q110319499","license":"CC BY-SA 4.0"},"Q904732":{"text":"Новокузне́цкий райо́н — административно-территориальная единица (район) и муниципальное образование (муниципальный район) в Кемеровской области России. Самый крупный по площади и один из самых населённых районов области. Административный центр — город Новокузнецк, который в состав района не входит.","title":"Новокузнецкий район","revision":155713844,"qid":"Q904732","license":"CC BY-SA 4.0"},"Q394767":{"text":"Краснохо́лмский муниципа́льный о́круг — административно-территориальная единица и одноимённое муниципальное образование (муниципальный округ) на востоке Тверской области России. Административный центр — город Красный Холм.","title":"Краснохолмский муниципальный округ","revision":156100226,"qid":"Q394767","license":"CC BY-SA 4.0"},"Q1551216":{"text":"Коло́менский кремль — одна из самых больших и мощных крепостей своего времени, которая строилась в 1525—1531 годах в Коломне, во времена правления Василия III. Московское княжество к тому времени уже присоединило Новгородскую республику и Псков и стремилось укрепить южные границы в борьбе с татарами — Казанским и Крымским ханствами. Помимо этого, разгром…","title":"Коломенский кремль","revision":146221228,"qid":"Q1551216","license":"CC BY-SA 4.0"},"Q4385963":{"text":"Пятницкие ворота (Пятницкая башня) — главные, парадные ворота Коломенского кремля. Башня расположена на восточной стороне кремля, между Застеночной (не сохранилась) и Погорелой башнями, выходя на дорогу Владимир — Кашира (ныне — улица Зайцева). Это одни из шести ворот Коломенского кремля (включая пробивные) и единственная сохранившаяся до наших дней…","title":"Пятницкие ворота (Коломна)","revision":155945637,"qid":"Q4385963","license":"CC BY-SA 4.0"},"Q4308109":{"text":"Мурманский областной краеведческий музей — старейший музей области, основан 17 октября 1926 года, расположен в здании, являющемся памятником истории города. Занимается комплектованием, хранением, популяризацией памятников истории и культуры Мурманской области. С южной торцевой стороны здания музея находится памятник ледоколу «Ермак».","title":"Мурманский областной краеведческий музей","revision":155658834,"qid":"Q4308109","license":"CC BY-SA 4.0"},"Q4308111":{"text":"Мурманский областной художественный музей — музей в городе Мурманске (Россия).","title":"Мурманский областной художественный музей","revision":147199767,"qid":"Q4308111","license":"CC BY-SA 4.0"},"Q153502":{"text":"Сама́рский академи́ческий театр дра́мы имени М. Горького — один из старейших драматических театров России. Расположен в городе Самаре, основан в 1851 году. Историческое здание театра, построенное в 1888 году, является объектом культурного наследия народов России федерального значения и охраняется государством.","title":"Самарский театр драмы имени М. Горького","revision":155885904,"qid":"Q153502","license":"CC BY-SA 4.0"},"Q167201":{"text":"Самарский академический театр оперы и балета имени Д. Д. Шостаковича — музыкальный театр в Самаре. Основан в 1931 году, первый сезон открыл оперой Модеста Мусоргского «Борис Годунов», первой балетной премьерой 3 июля 1931 стал «Красный мак» на музыку Рейнгольда Глиэра. 18 февраля 1982 года театру присвоено почётное звание «академический». В 2022 году…","title":"Самарский театр оперы и балета имени Д. Д. Шостаковича","revision":156085454,"qid":"Q167201","license":"CC BY-SA 4.0"},"Q4306071":{"text":"Музей «Коло́менская пастила́» (также известен как Музей исчезнувшего вкуса) — расположенный в городе Коломна Московской области музей. Музей расположен во флигеле старинной купеческой усадьбы Сурановых. На музейном производстве создают три вида русской пастилы: рыхлую белковую, рыхлую безбелковую и плотную пастилу. Авторами проекта являются Наталья…","title":"Коломенская пастила (музей)","revision":154482780,"qid":"Q4306071","license":"CC BY-SA 4.0"},"Q19910143":{"text":"Монумент Славы в честь работников авиапромышленности в Самаре находится на площади Славы в Ленинском районе города. Является одним из символов Самары.","title":"Монумент Славы (Самара)","revision":153998076,"qid":"Q19910143","license":"CC BY-SA 4.0"},"Q27825316":{"text":"Дом мастеро́в — музей народного искусства в городе Калуге. Расположен в украшенном резьбой по дереву доме середины XIX века, который является памятником истории и архитектуры. Объект культурного наследия народов России федерального значения.","title":"Дом мастеров","revision":154996659,"qid":"Q27825316","license":"CC BY-SA 4.0"},"Q32362763":{"text":"Калу́жский областной краеведческий музей — объединённый музей-заповедник в городе Калуге и области. Дирекция и главный офис Калужского областного краеведческого музея-заповедника расположены в городе Калуге на ул. Пушкина д. 4. Собрание музея состоит из огромного количества экспонатов и коллекций, среди которых: «Археология», «Дерево», «Документы и редкие…","title":"Калужский областной краеведческий музей","revision":156129288,"qid":"Q32362763","license":"CC BY-SA 4.0"},"Q53727755":{"text":"Храм в честь Покрова Пресвятой Богородицы «что на рву» — приходской храм Калужской епархии Русской православной церкви. Одна из старейших сохранившихся церквей в Калуге. Построена в стиле русское узорочье в 1687 году на месте деревянной церкви. В советские годы была закрыта и использовалась как инкубатор.","title":"Церковь Покрова Пресвятой Богородицы «на рву»","revision":155006498,"qid":"Q53727755","license":"CC BY-SA 4.0"},"Q136500433":{"text":"Калужская областная филармония — российское учреждение культуры. Расположено в городе Калуга, улица Ленина, д. 60. Областная филармония имеет зал на 881 место.","title":"Калужская областная филармония","revision":149384097,"qid":"Q136500433","license":"CC BY-SA 4.0"},"Q137989689":{"text":"Усадьба Клодта — архитектурная композиция в Самаре, включающая особняк Клодта — здание, расположенное по адресу улица Куйбышева, дом 139. Объект культурного наследия федерального значения. Ныне здесь расположена Самарская детская картинная галерея. Неофициальные прозвища — «пряничный домик» и «теремок».","title":"Усадьба Клодта","revision":155553775,"qid":"Q137989689","license":"CC BY-SA 4.0"},"Q51222377":{"text":"Мортуарий, павильон траурных собраний или пантеон — недействующее церемониальное сооружение, построенное для проведения траурных обрядов. Находится на территории городского кладбища № 1 в городе Волжском. Внесен внесен в реестр объектов культурного наследия РФ.","title":"Мортуарий (Волжский)","revision":156145260,"qid":"Q51222377","license":"CC BY-SA 4.0"},"ru-88bf324d7303-o51dcc8049ce8":{"text":"Моршанский историко-художественный музей им. П. П. Иванова — музей в Моршанске Тамбовской области. Филиал Тамбовского областного краеведческого музея.","title":"Моршанский историко-художественный музей","revision":154927047,"qid":"Q4303498","license":"CC BY-SA 4.0"},"ru-8cfbe842e803-o7e3c6c414018":{"text":"Национальный музей Республики Адыгея (НМРА) — российский музей в городе Майкоп, Адыгея. Имеет филиал — Литературный музей имени Т. Керашева.","title":"Национальный музей Республики Адыгея","revision":148466156,"qid":"Q16679937","license":"CC BY-SA 4.0"},"ru-8d0a05bf3b8a-o03360e0dc90b":{"text":"Десяти́нный монастырь — недействующий, в прошлом женский второклассный монастырь Русской православной церкви в Великом Новгороде. Расположен в Людином конце, к югу от Прусской улицы. Примыкает к линии вала Окольного города. До сих пор нет единого мнения, почему монастырь называется именно так. Хотя известно, что первый каменный храм, построенный в Киеве…","title":"Десятинный монастырь","revision":152465920,"qid":"Q4159248","license":"CC BY-SA 4.0"},"ru-8dea00e39aab-o263326ce7d38":{"text":"Новосиби́рская ГЭС — гидроэлектростанция на реке Оби в Советском районе города Новосибирска. Единственная гидроэлектростанция на Оби, играет важную роль в работе энергосистемы Новосибирска, обеспечении надёжного водоснабжения, работе речного транспорта. Построена в 1950—1959 годах. Собственником Новосибирской ГЭС (за исключением судоходного шлюза) является…","title":"Новосибирская ГЭС","revision":154900218,"qid":"Q4325430","license":"CC BY-SA 4.0"},"ru-8dea00e39aab-o24f4e1a29e9a":{"text":"Технопарк новосибирского Академгородка (Академпарк) — технопарк, построенный в Новосибирском Академгородке. Основная официально заявленная цель проекта — обеспечение ускоренного развития высокотехнологичных отраслей экономики и превращение их в одну из основных движущих сил экономического роста региона. Локальная цель — создание не менее 20 успешных…","title":"Технопарк новосибирского Академгородка","revision":156325872,"qid":"Q4456911","license":"CC BY-SA 4.0"},"ru-8dea00e39aab-o88854730204e":{"text":"Новосибирский музыкальный театр — музыкальный театр, расположенный в Новосибирске. Основан 2 февраля 1959 года. До 2017 года назывался «Новосибирский театр музыкальной комедии». В репертуаре театра — классика жанра оперетты, музыкальной комедии, современные экспериментальные работы в жанре мюзикла, спектакли для детей и юношества. Здание театра расположено…","title":"Новосибирский музыкальный театр","revision":152822284,"qid":"Q4325483","license":"CC BY-SA 4.0"},"ru-8dea00e39aab-o0013d6547b47":{"text":"«Новосиби́рский госуда́рственный театра́льный институ́т» (НГТИ) — российское государственное автономное образовательное учреждение высшего образования Новосибирской области, расположенное в городе Новосибирске. Основан в 1960 году как «Новосибирское государственное театральное училище». 1 сентября 2003 года образовательное учреждение реорганизовано в…","title":"Новосибирский государственный театральный институт","revision":156092489,"qid":"Q54577864","license":"CC BY-SA 4.0"},"ru-969d3bb64d8e-o765e7be00f2c":{"text":"Кыштымское машиностроительное объединение — крупнейший российский производитель горно-шахтного, горно-бурового оборудования и бурового инструмента. Основан Никитой Демидовым в 1757 году как железоделательный завод. Завод находится в городе Кыштым Челябинской области. Один из старейших заводов Урала.","title":"Кыштымское машиностроительное объединение","revision":149077623,"qid":"Q4251022","license":"CC BY-SA 4.0"},"ru-988157bfd6d5-o19651666851e":{"text":"Памятник «Металлург» — однофигурная скульптурная композиция в полный рост, высотой 4,75 метра, выполнена из кованой меди, возвышается на постаменте из кирпича и облицованном белым мрамором. Общая высота — 10,5 м. К памятнику ведут широкие лестничные марши. Автор постамента — архитектор В. Н. Богун. Памятник является образцом монументального искусства…","title":"Металлург (памятник, Магнитогорск)","revision":155674086,"qid":"Q4291570","license":"CC BY-SA 4.0"},"ru-98e62df9591a-oae5a2554feb2":{"text":"Зара́йский кремль — крепость в историческом центре Зарайска, главный общественно-политический и историко-художественный комплекс города. Объект культурного наследия федерального значения. На территории кремля действует Государственный музей-заповедник «Зарайский кремль». В отличие от распространённого убеждения, Зарайский кремль не самый маленький из…","title":"Зарайский кремль","revision":152725684,"qid":"Q663206","license":"CC BY-SA 4.0"},"ru-9a72b5109413-o45a35db227d6":{"text":"Об усадьбе в Дмитровском районе см. Горки Рогачёвские Усадьба «Большие Горки» — архитектурно-художественный ансамбль начала XIX века, расположенный на берегу реки Пахра в посёлке Горки Ленинские Ленинского района Московской области, примерно в 10 км от МКАД. Территорию усадьбы занимает Государственный исторический музей-заповедник «Горки Ленинские».","title":"Горки (усадьба)","revision":146531733,"qid":"Q3286190","license":"CC BY-SA 4.0"},"ru-9b0efbd022bb-o918a259b0e39":{"text":"Грот Лермонтова — достопримечательность на востоке города Пятигорска. В 1829 году во время устройства Емануелевского парка братьями Бернардацци были сделаны два романтических грота: большой и малый. Большой грот имеет естественное происхождение — небольшую пещеру лишь углубили. Первоначально назывался грот Калипсо. В 1860-х годах его начали называть…","title":"Грот Лермонтова","revision":156094263,"qid":"Q4150349","license":"CC BY-SA 4.0"},"ru-9b968c73f4d4-o964545161434":{"text":"«Красноярский машиностроительный завод» (также используется аббревиатура Красмаш) — крупнейшее предприятие оборонно-промышленного комплекса России. Входит в госкорпорацию «Роскосмос», является дочерним предприятием АО «ГРЦ Макеева».","title":"Красноярский машиностроительный завод","revision":153286688,"qid":"Q4239257","license":"CC BY-SA 4.0"},"ru-9b968c73f4d4-o5ff8f3c3de06":{"text":"Па́рк фло́ры и фа́уны «Ро́ев руче́й» — зоопарк в Красноярске, один из крупнейших зоопарков России. Официальное наименование управляющей зоопарком организации — Муниципальное автономное учреждение «Красноярский парк флоры и фауны „Роев ручей“». За годы деятельности в парке создана зоологическая коллекция, уступающая в Российской Федерации только Московскому…","title":"Роев ручей","revision":154547143,"qid":"Q3337557","license":"CC BY-SA 4.0"},"ru-9fdcc25fa3d0-o29719273ca40":{"text":"Этнографи́ческий музе́й наро́дов Забайка́лья (бур. Υбэр Байгалай хизаарай арадуудай угсаатанай зγйн музей) — музейный комплекс под открытым небом в городе Улан-Удэ (Республика Бурятия), в микрорайоне Верхняя Берёзовка.","title":"Этнографический музей народов Забайкалья","revision":155598638,"qid":"Q4533061","license":"CC BY-SA 4.0"},"ru-a2072dc545be-odc45331052a4":{"text":"(Национальный) Музей Чеченской Республики — чеченский краеведческо-исторический музей, расположенный в Грозном. Музей также имеет пять филиалов в сёлах республики.","title":"Национальный музей Чеченской Республики","revision":154980543,"qid":"Q16679941","license":"CC BY-SA 4.0"},"ru-a309e4ce2f36-of3600a1c1872":{"text":"Пермский театр кукол находится в Перми на Сибирской улице в Свердловском районе города.","title":"Пермский театр кукол","revision":155917065,"qid":"Q16685870","license":"CC BY-SA 4.0"},"ru-a309e4ce2f36-ofb33e5b08560":{"text":"Дом Мешкова — особняк в историческом центре Перми, памятник архитектуры. Название получил по имени одного из владельцев здания предпринимателя и мецената Николая Васильевича Мешкова. Расположен по адресу: улица Монастырская, 11.","title":"Дом Мешкова","revision":152214738,"qid":"Q4165340","license":"CC BY-SA 4.0"},"ru-a52b73890cfe-oa39b907a6a4e":{"text":"ОАО «Волгоградский судостроительный завод» — судостроительное предприятие России, располагавшееся в Волгограде.","title":"Волгоградский судостроительный завод","revision":156349052,"qid":"Q4122988","license":"CC BY-SA 4.0"},"ru-b22cf685e391-o31e76f41e8f9":{"text":"Армазово — деревня в Новомосковском административном округе Москвы (до 1 июля 2012 года в составе Подольского района Московской области). Входит в состав поселения Рязановское.","title":"Армазово","revision":155717249,"qid":"Q4069548","license":"CC BY-SA 4.0"},"ru-b2601b186da2-o42670968fdb5":{"text":"Тульский государственный ордена Трудового Красного Знамени академический театр драмы имени М. Горького — академический драматический театр в Туле.","title":"Тульский академический театр драмы","revision":156103847,"qid":"Q4465236","license":"CC BY-SA 4.0"},"ru-b28b6f6f1435-o9e11a55fc3f8":{"text":"Кузне́цкая крепость — крепость на Вознесенской горе в Кузнецком районе города Новокузнецка Кемеровской области, памятник истории и архитектуры федерального значения. Была опорным пунктом Сибирской линии в верховьях Томи. Построена в 1800—1820 годах по проекту, утверждённому императором Павлом I, для защиты Южной Сибири от возможного нападения со стороны…","title":"Кузнецкая крепость","revision":156294284,"qid":"Q4244866","license":"CC BY-SA 4.0"},"ru-b28b6f6f1435-o19875250482b":{"text":"Новокузнецкий краеведческий музей — первый музей Кемеровской области, один из крупнейших (более 56 тыс. экспонатов) в Кузбассе. Создан на основе частного музейного собрания кузнецких краеведов Дмитрия Тимофеевича Ярославцева и Георгия Степановича Блынского (первого директора музея до 1932 года) в 1927 году.","title":"Новокузнецкий краеведческий музей","revision":156296118,"qid":"Q21643527","license":"CC BY-SA 4.0"},"ru-b28b6f6f1435-o7ea01c5ea15d":{"text":"Кузне́цкие ферроспла́вы — предприятие металлургического комплекса, расположено в городе Новокузнецк Кемеровской области. Полное название — Акционерное общество «Кузнецкие ферросплавы», Сокращённое наименование — АО «КФ».","title":"Кузнецкие ферросплавы","revision":146271049,"qid":"Q4244873","license":"CC BY-SA 4.0"},"ru-b7127184ead6-o24b5e314ff86":{"text":"ФГУП «Атомфлот», также известное как Росатомфлот — предприятие, в обязанности которого входит эксплуатация и обслуживание атомного гражданского ледокольного флота России для хозяйственного освоения Северного морского пути, начатого Советским Союзом. База судов расположена в городе Мурманске. Из-за вторжения России на Украину предприятие находится под…","title":"Атомфлот","revision":155796534,"qid":"Q558639","license":"CC BY-SA 4.0"},"ru-b7127184ead6-o382e4ae66fc6":{"text":"Мурманский колледж искусств (официальное наименование — Государственное областное бюджетное профессиональное образовательное учреждение «Мурманский колледж искусств», ГОБПОУ МКИ) — государственное учреждение среднего профессионального образования в Мурманске, осуществляющее подготовку специалистов в области музыкального и изобразительного искусства.…","title":"Мурманский колледж искусств","revision":154212476,"qid":"Q85610538","license":"CC BY-SA 4.0"},"ru-bb035cc31dc2-o763f266be9f7":{"text":"ГУК Самарской области «Самарский театр кукол» — театр кукол в Самаре, расположенный по адресу ул. Самарская, 95.","title":"Самарский театр кукол","revision":155553821,"qid":"Q7211823","license":"CC BY-SA 4.0"},"ru-bb035cc31dc2-oca824afd5064":{"text":"Поволжский музей железнодорожной техники — специализированный музей Самары, расположенный по адресу улица Литвинова, 332 литер А. Музей расположен на территории учебных корпусов Самарского государственного университета путей сообщения (СамГУПС). Также может упоминаться как Музей железнодорожной техники СамГУПС, Самарский музей железнодорожной техники и…","title":"Поволжский музей железнодорожной техники","revision":153593646,"qid":"Q4406407","license":"CC BY-SA 4.0"},"ru-bb035cc31dc2-o0c5f5536b7c4":{"text":"Музей-центр самарского футбола — первый в России общественный музей футбола. находится в Самаре.","title":"Музей самарского футбола","revision":151648332,"qid":"Q4306457","license":"CC BY-SA 4.0"},"ru-bebfd75da0da-oe26e0209de6f":{"text":"Ульяновский колледж культуры и искусства — среднее профессиональное учебное заведение города Ульяновска. Полное наименование — областное государственное бюджетное профессиональное образовательное учреждение «Ульяновский колледж культуры и искусства» (сокр. ОГБПОУ «Ульяновский колледж культуры и искусства» или ОГБПОУ \"УККиИ\"). В прошлом, до 2015 г. —…","title":"Ульяновское училище культуры","revision":152043528,"qid":"Q4475229","license":"CC BY-SA 4.0"},"ru-bf465fda7834-oc10b2882d40a":{"text":"Октя́брьский райо́н — один из шести районов Саратова, четвёртый по населению (после Ленинского, Заводского и Кировского) район города. Важный промышленный, транспортный, научный и социальный район города.","title":"Октябрьский район (Саратов)","revision":152805891,"qid":"Q4333158","license":"CC BY-SA 4.0"},"ru-c1cfe4b9f7c2-o309dff01496a":{"text":"Ростовский областной музей краеведения — музей в городе Ростове-на-Дону (Большая Садовая ул., 79). Один из крупнейших на юге России. Основан в 1937 году в связи с образованием Ростовской области. Музей представляет природу, культуру и историю Ростовской области. Наиболее интересная экспозиция представлена в зале «Сокровища Донских курганов» — 2000…","title":"Ростовский областной музей краеведения","revision":148998416,"qid":"Q4398507","license":"CC BY-SA 4.0"},"ru-c1cfe4b9f7c2-o3238b1f77e83":{"text":"«Донская казачья гвардия» — подразделение Донского государственного технического университета (ДГТУ) Донской государственный технический университет, крупнейшего ВУЗа на Юге России. В основе экспозиции — частная коллекция ростовчанина Николая Новикова, которую он собирал с 1990 года. Помещение для ее экспонирования предоставлено ректором ДГТУ Б. Ч. Месхи в…","title":"Донская казачья гвардия","revision":154251480,"qid":"Q86670165","license":"CC BY-SA 4.0"},"ru-c52ea942555e-of191374a39b1":{"text":"Тверской театр юного зрителя (ТТЮЗ) — театр юного зрителя в Твери, государственное областное учреждение культуры, ориентированный на детей, один из многих построенных в годы советской власти.","title":"Тверской театр юного зрителя","revision":155658396,"qid":"Q4453278","license":"CC BY-SA 4.0"},"ru-c52ea942555e-o5f33e55c6f12":{"text":"Памятник Михаилу Евграфовичу Салтыкову-Щедрину — один из памятников Твери; бронзовая скульптура, посвящённая писателю и вице-губернатору Твери Салтыкову-Щедрину. Памятник был открыт 26 января 1976 года, к 150-летию рождения Салтыкова-Щедрина. Это первый в России памятник Салтыкову-Щедрину. Авторы памятника: скульптор О. К. Комов, архитектор Н. А.…","title":"Памятник Салтыкову-Щедрину","revision":152455314,"qid":"Q108934596","license":"CC BY-SA 4.0"},"ru-c6a7e59004b4-o07c54f95768b":{"text":"Шахта «Распа́дская» — крупнейшая угольная шахта в России. Расположена в 11 км севернее Междуреченска (Кемеровская область). Первый уголь шахтой был добыт в 1973 году. В конце 80-х — начале 90-х годов XX века шахта являлась одним из центров шахтёрского забастовочного движения. Шахта входит в состав «Распадской угольной компании» (на долю шахты приходится…","title":"Распадская (шахта)","revision":151375433,"qid":"Q4390222","license":"CC BY-SA 4.0"},"ru-ca091eae2c39-o4ce2a36ed1cb":{"text":"Бастионная, земляная Великолукская крепость — крепость в городе Великие Луки (Псковской области, России). Горожанами обычно называется «Валом» или «Крепостью».","title":"Великолукская крепость","revision":151737087,"qid":"Q4106740","license":"CC BY-SA 4.0"},"ru-ca8fb626709c-o7abd48dc8e42":{"text":"Никольский собор — недействующий православный храм в городе Волоколамске Московской области, входящий в ансамбль Волоколамского кремля. Построен в 1853—1862 годах и посвящён памяти погибших в Крымской войне. Параметры собора были выбраны с оглядкой на стоящий рядом Воскресенский собор XV века. У храма одна глава на широком барабане, полукружия закомар, два…","title":"Никольский собор (Волоколамск)","revision":153788895,"qid":"Q39085083","license":"CC BY-SA 4.0"},"ru-cb8ae35a93df-o05ee8b0362af":{"text":"Магаданский областной краеведческий музей — культурно-образовательное и научно-просветительское государственное бюджетное учреждение в городе Магадане Российской Федерации. Один из крупнейших научно-просветительских музеев на Северо-Востоке. В собрании музея находятся археологическая и картографическая коллекции, документальный фонд исторических документов…","title":"Магаданский областной краеведческий музей","revision":155911236,"qid":"Q85862542","license":"CC BY-SA 4.0"},"ru-ccc344878fd4-o90df6ff1a4a2":{"text":"Проспе́кт Ка́рла Ма́ркса (карел. Karl Marksan prospektu, фин. Karl Marxin valtakatu) — проспект в центральной части города Петрозаводска, столицы Республики Карелия. Проходит от Большой Петропавловской улицы до площади Ленина. Нумерация домов ведётся от Онежского озера. Является одной из самых старых улиц города. Застройка проспекта включена в список…","title":"Проспект Карла Маркса (Петрозаводск)","revision":154939733,"qid":"Q4381154","license":"CC BY-SA 4.0"},"ru-d13945a87017-o40e1de3b534a":{"text":"Алтайский моторный завод — российское машиностроительное предприятие в Барнауле. Производит дизельные двигатели, дизель-генераторы и судовые дизель-редукторные агрегаты. С 2006 года ОАО «АМЗ» входил в концерн «Тракторные заводы». В 2019 году после банкротства на основе акционерного общества было создано ООО «Алтайский моторостроительный завод».","title":"Алтайский моторный завод","revision":155645235,"qid":"Q4062938","license":"CC BY-SA 4.0"},"ru-d13945a87017-o7e844e0aa272":{"text":"Барнаульский станкостроительный завод — предприятие оборонной промышленности в Барнауле.","title":"Барнаульский станкостроительный завод","revision":149833429,"qid":"Q4078419","license":"CC BY-SA 4.0"},"ru-d13945a87017-o2ed73f189079":{"text":"Алтайский шинный комбинат (Барнаульский шинный завод) — предприятие химической промышленности в Барнауле. Расположен в Ленинском районе города.","title":"Алтайский шинный комбинат","revision":153584925,"qid":"Q4062947","license":"CC BY-SA 4.0"},"ru-d13945a87017-oc86efd18588a":{"text":"Барнаульский Знаменский монастырь — женский монастырь Барнаульской епархии Русской православной церкви в Барнауле. Открыт в 1994 году при Знаменской церкви.","title":"Знаменский монастырь (Барнаул)","revision":151660888,"qid":"Q4192835","license":"CC BY-SA 4.0"},"ru-d13945a87017-o40e02740fb57":{"text":"Государственная филармония Алтайского края — учреждение культуры Барнаула, расположенное в историческом здании, памятнике архитектуры начала XX века. Филармония находится в Центральном районе города на улице Ползунова.","title":"Государственная филармония Алтайского края","revision":147528355,"qid":"Q4146658","license":"CC BY-SA 4.0"},"ru-d414a2e89e1e-o3b457e8bdb3f":{"text":"Смоленская крепостная стена — городская стена Смоленска протяжённостью 6,5 км, построенная в 1595—1602 годах под руководством зодчего Фёдора Коня. Одна из крупнейших из сохранившихся кирпичных крепостей мира. Имела огромное оборонное значение в Русском государстве. Значительная часть крепости была уничтожена в ночь с 4 на 5 ноября (по новому стилю — 17…","title":"Смоленская крепостная стена","revision":155187497,"qid":"Q1565762","license":"CC BY-SA 4.0"},"ru-d4dadcfd355d-o57c81c7ab8ac":{"text":"Середнико́во (историческое название Алешино (в честь Всеволодского), сельцо) — бывшее имение Всеволожских и Столыпиных, парково-усадебный ансамбль конца XVIII — начала XIX века, одно из наиболее известных лермонтовских мест России. Усадьба расположена в городском округе Химки Московской области, к югу от посёлка и платформы Фирсановка. Рядом с усадьбой…","title":"Середниково","revision":155572813,"qid":"Q2970685","license":"CC BY-SA 4.0"},"ru-d5bd18b922c1-o3055f33ac932":{"text":"Собор Казанской иконы Божией Матери — православный храм в городе Элиста в Калмыкии, кафедральный собор Элистинской епархии Русской Православной Церкви.","title":"Казанский собор (Элиста)","revision":147553386,"qid":"Q4207829","license":"CC BY-SA 4.0"},"ru-dce97bffdeb2-o1ff7aa8d4a49":{"text":"Музей истории Оренбурга — муниципальный историко-краеведческий музей в Оренбурге. Расположен в историческом здании середины XIX века, являющемся памятником федерального значения. Музей открылся в 1983 году как отдел досоветского периода истории России Оренбургского областного краеведческого музея, в 1989 году преобразован в самостоятельный Музей истории…","title":"Музей истории Оренбурга","revision":152405172,"qid":"Q4306053","license":"CC BY-SA 4.0"},"ru-dce97bffdeb2-o60490c213edd":{"text":"Оренбургский музей изобразительных искусств — музей изобразительных искусств в городе Оренбурге.","title":"Оренбургский областной музей изобразительных искусств","revision":155839441,"qid":"Q18643430","license":"CC BY-SA 4.0"},"ru-deb1d05a71ce-ob3b558baeae0":{"text":"Национальный музей Удмуртской Республики имени Кузебая Герда расположен в Ижевске в здании бывшего Арсенала оружейного завода по улице Коммунаров в Октябрьском районе города.","title":"Национальный музей Удмуртской Республики имени Кузебая Герда","revision":152997954,"qid":"Q16679939","license":"CC BY-SA 4.0"},"ru-df284e77a45c-o5e647c3224d9":{"text":"Кинешемский драматический театр имени А. Н. Островского расположен в городе Кинешма, Ивановской области. Основан в 1897 году. Является одним из старейших театров России. Это единственный театр, который носит имя Александра Николаевича Островского с первого дня своего существования. Театр создан при участии членов семьи драматурга — его вдовы и брата.","title":"Кинешемский драматический театр имени А. Н. Островского","revision":155526462,"qid":"Q4220825","license":"CC BY-SA 4.0"},"ru-df679694d505-oebc634025bc1":{"text":"Калинингра́дская областна́я филармо́ния и́мени Е. Ф. Светла́нова — областная филармония, расположенная в здании бывшей кирхи Святого Семейства в городе Калининграде (до 1946 года — Кёнигсберг). Открыта 22 августа 1980 года. В настоящее[когда?] время — место проведения различных международных музыкальных фестивалей. Директор филармонии — народный артист…","title":"Калининградская областная филармония","revision":156052708,"qid":"Q4209539","license":"CC BY-SA 4.0"},"ru-df679694d505-o3b3d59eb9c19":{"text":"Калининградский областной музыкальный театр — государственный музыкальный театр Калининградской области Российской Федерации, созданный в 2001 году в Калининграде. Полное официальное наименование — «Государственное автономное учреждение Калининградской области „Калининградский областной музыкальный театр“», сокращённое наименование — «ГАУ КО КОМТ».","title":"Калининградский областной музыкальный театр","revision":140963246,"qid":"Q51078696","license":"CC BY-SA 4.0"},"ru-e3b0eae8a4ce-o5642b309eac7":{"text":"Музей истории Томска — музей, создан решением томской городской администрации от 16 июля 1997 года.","title":"Музей истории Томска","revision":147579036,"qid":"Q4306303","license":"CC BY-SA 4.0"},"ru-e3b0eae8a4ce-o0aeb5568ad87":{"text":"Октя́брьский райо́н — один из четырёх внутригородских районов в Томске. Занимает обширную площадь в северо-восточной части города, включая в себя почти половину территории города (126 из 294 квадратных километров). Население района составляет 174 тысячи жителей. Назван в честь Великой Октябрьской социалистической революции.","title":"Октябрьский район (Томск)","revision":152466290,"qid":"Q37900995","license":"CC BY-SA 4.0"},"ru-e3b0eae8a4ce-o888a61454b1f":{"text":"Томская ТЭЦ-3 — тепловая электростанция в Томске. Структурное подразделение АО «Томская генерация». Томская ТЭЦ-3 расположена в северо-восточной части Томска, рядом с ТНХК. Численность персонала — 360 человек. 1 турбина и 2 котлоагрегата. Электрическая мощность 140 МВт, тепловая — 780 Гкал/ч. Директор Томской ТЭЦ-3 — Ковалёв Олег Викторович (с 2006 года).","title":"Томская ТЭЦ-3","revision":155424680,"qid":"Q4460363","license":"CC BY-SA 4.0"},"ru-e3b0eae8a4ce-o73fef582af72":{"text":"Томский областной художественный музей — учреждение культуры, действующее в Томске с 1979 года.","title":"Томский областной художественный музей","revision":153607371,"qid":"Q16706833","license":"CC BY-SA 4.0"},"ru-e3b0eae8a4ce-oa4d9f3ecc9ea":{"text":"Лагерный сад — парк в Кировском районе Томска, на высоком правом берегу Томи, в оползневой зоне. Площадь около 40 гектар, размер примерно 1300×300 метров.","title":"Лагерный сад","revision":146203975,"qid":"Q4252365","license":"CC BY-SA 4.0"},"ru-e3b0eae8a4ce-o9a23964c3f9d":{"text":"Лагерный сад — парк в Кировском районе Томска, на высоком правом берегу Томи, в оползневой зоне. Площадь около 40 гектар, размер примерно 1300×300 метров.","title":"Лагерный сад","revision":146203975,"qid":"Q4252365","license":"CC BY-SA 4.0"},"ru-e3b0eae8a4ce-o6d47deb0c75c":{"text":"Памятник счастью или Памятник «Щас спою…» — памятник в Томске, изображающий волка — персонаж мультфильма «Жил-был пёс».","title":"Памятник счастью","revision":152770698,"qid":"Q4343364","license":"CC BY-SA 4.0"},"ru-e3b0eae8a4ce-obc7f4f852702":{"text":"Миха́йловская ро́ща — лесопарк в южной части Октябрьского района Томска. Территория рощи ограничена с юга и юго-востока правым берегом реки Ушайки, с запада — Комсомольским проспектом, с северо-востока — посёлком Ближним, с севера — бывшей промзоной подшипникового завода. Площадь рощи составляет 53,7 гектара. В роще находятся несколько родников. В местной…","title":"Михайловская роща","revision":154973170,"qid":"Q16677003","license":"CC BY-SA 4.0"},"ru-eacb5f151a2e-o38cc3f40129b":{"text":"Быха́нов сад (ранее — Комсомольский парк имени В. Н. Скороходова) — парк в Правобережном округе города Липецка. Официальное название — парк «Быха́нов сад». Расположен между улицами Гагарина, Балмочных, Тельмана и Евдокиевским кладбищем. Площадь — 13,5418 га. В составе древесных пород преобладают ель, берёза, каштан. Также здесь растут декоративные…","title":"Быханов сад","revision":156204328,"qid":"Q4101254","license":"CC BY-SA 4.0"},"ru-ecc165849814-o9409ac7d2739":{"text":"Дворец культуры УАЗа — архитектурный памятник, расположенный в городе Каменске-Уральском Свердловской области. Здание Дворца культуры Уральского алюминиевого завода построено в 1947 году по проекту свердловского архитектора В. В. Емельянова. Постановлением Правительства Свердловской области № 859-ПП от 28 декабря 2001 года присвоен статус памятника…","title":"Дворец культуры УАЗа","revision":153280213,"qid":"Q52554529","license":"CC BY-SA 4.0"},"ru-efc02a6a273b-o5c6734cd68b8":{"text":"Серпухо́вский историко-художественный музей в Серпухове — крупнейшая и богатейшая картинная галерея Подмосковья. Основан в 1918 году. Основа собрания — коллекция серпуховской фабрикантши Анны Васильевны Мараевой. В 1920 — начале 1930-х годов фонды музея пополнились произведениями искусства и бытовыми предметами из окрестных усадеб — Райсеменовское…","title":"Серпуховский историко-художественный музей","revision":148064914,"qid":"Q3329632","license":"CC BY-SA 4.0"},"ru-efc02a6a273b-o3c469a0c27d2":{"text":"Храм преподо́бного Серафи́ма Саро́вского (Церковь Пресвято́й Богоро́дицы в Ста́рой Мы́зе, Богоро́дицкая церковь, Серафи́мовская церковь, Серафимосаро́вская церковь) — православный храм в городе Серпухове Московской области. Расположен в северной части города, на улице Пушкина, на территории Серпуховского автомобильного завода.","title":"Храм Серафима Саровского (Серпухов)","revision":149564126,"qid":"Q4501007","license":"CC BY-SA 4.0"},"ru-efc02a6a273b-o571f2a39b0d6":{"text":"Храм преподо́бного Серафи́ма Саро́вского (Церковь Пресвято́й Богоро́дицы в Ста́рой Мы́зе, Богоро́дицкая церковь, Серафи́мовская церковь, Серафимосаро́вская церковь) — православный храм в городе Серпухове Московской области. Расположен в северной части города, на улице Пушкина, на территории Серпуховского автомобильного завода.","title":"Храм Серафима Саровского (Серпухов)","revision":149564126,"qid":"Q4501007","license":"CC BY-SA 4.0"},"ru-fc14353f5a1d-obd9ab3cc59ab":{"text":"Салаватский государственный башкирский драматический театр (баш. Салауат башҡорт дәүләт драма театры) — башкирский драматический театр в Салавате.","title":"Салаватский государственный башкирский драматический театр","revision":155908503,"qid":"Q4405613","license":"CC BY-SA 4.0"},"ru-ff3292b1a1d2-ofb496a28cc31":{"text":"Акционерное общество «Пензадизельмаш» (Пензенский дизельный завод) — промышленное предприятие, ведущий в России производитель дизельных двигателей для тепловозов. Выпускает дизели и дизель-генераторы широкого назначения для магистральных, маневровых и промышленных тепловозов, электростанций, морских и речных судов, тяговых агрегатов горнодобывающей…","title":"Пензадизельмаш","revision":153819101,"qid":"Q4348453","license":"CC BY-SA 4.0"},"ru-ff3292b1a1d2-o48967e934fc8":{"text":"Пензенский музей народного творчества — государственный музей в Пензе, занимающийся сохранением, изучением и пропагандой традиционных пензенских художественных промыслов, ремёсел и работ народных умельцев.","title":"Пензенский музей народного творчества","revision":146280699,"qid":"Q4348489","license":"CC BY-SA 4.0"},"ru-ff894fb7acb4-o06e17a13fa4f":{"text":"Невинномысская ГРЭС — электростанция федерального значения в Невинномысске Ставропольского края, филиал ПАО «ЭЛ5-Энерго» (ранее — Энел Россия).","title":"Невинномысская ГРЭС","revision":154928579,"qid":"Q4315786","license":"CC BY-SA 4.0"},"spb-o76932bb9600f":{"text":"Музей железных дорог России — музей в Санкт-Петербурге, открытый 25 июля 1978 года как музей Октябрьской железной дороги; современная площадка музея начала действовать 30 октября 2017 года, в день 180-летия Российских железных дорог. Входит в Союз музеев России, в Европейскую ассоциацию туристических и музейных железных дорог FEDECRAIL, во Всероссийское…","title":"Музей железных дорог России","revision":153441520,"qid":"Q1761925","license":"CC BY-SA 4.0"},"spb-oda2e0a89dc82":{"text":"Дворе́ц Белосе́льских-Белозе́рских; Се́ргиевский дворец — дворец в Санкт-Петербурге, на Невском проспекте в месте его пересечения с рекой Фонтанкой. Автор проекта — архитектор А. И. Штакеншнейдер, осуществивший строительство в стиле так называемого «русского необарокко».","title":"Дворец Белосельских-Белозерских","revision":152214578,"qid":"Q2477653","license":"CC BY-SA 4.0"},"spb-o0586d59633b4":{"text":"Киносту́дия «Ленфи́льм» — старейшая кинокомпания России, её история восходит к 1918 году — времени создания Петроградского кинокомитета Наркомпроса РСФСР. За всё время студией выпущено около 1500 игровых кинофильмов. С 2025 года 100 % акций Акционерного общества «Киностудия „Ленфильм“» принадлежат Санкт-Петербургу. Основная территория киностудии находится…","title":"Ленфильм","revision":155951231,"qid":"Q158478","license":"CC BY-SA 4.0"},"spb-oc1de2e724d82":{"text":"Квартирники у Гороховского — один из самых необычных культурных центров в Санкт-Петербурге, ориентированный на некоммерческое современное искусство. Концерты и выставки проводятся в обычной квартире Дмитрия Гороховского.","title":"Квартирники у Гороховского","revision":152216785,"qid":"Q4218558","license":"CC BY-SA 4.0"},"spb-o374dc9944a8e":{"text":"Мальтийская капелла — католическая церковь ордена мальтийских рыцарей, построенная Джакомо Кваренги в конце XVIII века. Капелла входит в архитектурный комплекс Воронцовского дворца в Санкт-Петербурге (пристроена к главному корпусу дворца со стороны сада).","title":"Мальтийская капелла","revision":154555707,"qid":"Q2957294","license":"CC BY-SA 4.0"},"spb-o239c0ea17bc7":{"text":"Центральный музей железнодорожного транспорта Российской Федерации — технический музей в Санкт-Петербурге, посвящённый железным дорогам, подвижному составу и всему, что с этим связано. Основан в 1813 году.","title":"Центральный музей железнодорожного транспорта Российской Федерации","revision":154190729,"qid":"Q4504319","license":"CC BY-SA 4.0"},"spb-o283a45b9dd89":{"text":"«Леннаучфи́льм» (сокр. от Ленинградская студия научно-популярных и учебных фильмов) — советская и российская киностудия в Санкт-Петербурге. Студия полного цикла, работавшая от сценарной заявки до кинотеатрального, видео- и телевизионного проката. Это три съёмочных павильона, цеха съёмочной, свето- и звукотехники, мультипликации, обработки цветной и…","title":"Леннаучфильм","revision":151865179,"qid":"Q4258535","license":"CC BY-SA 4.0"},"spb-oc4529eed2e73":{"text":"Особня́к Румя́нцева в Санкт-Петербурге расположен по адресу Английская набережная, дом 44. Ныне отдел (филиал) Государственного музея истории Санкт-Петербурга.","title":"Особняк Румянцева","revision":152352532,"qid":"Q3360919","license":"CC BY-SA 4.0"},"spb-of5a4093ef44f":{"text":"«Госуда́рственный драмати́ческий теа́тр на Васи́льевском» — государственный драматический театр Ленинградской области Российской Федерации, расположенный на Васильевском острове в городе Санкт-Петербурге. Основан 1 сентября 1989 года Владимиром Словохотовым, который в настоящее время является художественным руководителем и директором театра. Полное…","title":"Театр на Васильевском","revision":153039915,"qid":"Q4453442","license":"CC BY-SA 4.0"},"spb-oa0b67237e162":{"text":"Дом Кочневой (дом Ильиных) — памятник архитектуры. Расположен в Санкт-Петербурге, современный адрес дома — набережная реки Фонтанки, 41. Построен Л. Руска в 1805—1808 годах для купца Ф. Ильина. До блокады Ленинграда автор здания был неизвестен. Для строительства был отведён небольшой участок, поэтому здание асимметрично, Г-образное в плане. На красную…","title":"Дом Кочневой","revision":146983371,"qid":"Q120442600","license":"CC BY-SA 4.0"},"spb-o92adc2dc4be0":{"text":"Росси́йский аукцио́нный до́м, или РАД — аукционный дом, площадка для продажи государственного, корпоративного, банковского, проблемного и частного имущества по всей территории России, проведения закупок для обеспечения государственных и муниципальных нужд. Полное наименование — Акционерное общество «Российский аукционный дом». Основан в 2009 году.…","title":"Российский аукционный дом","revision":154522517,"qid":"Q16692645","license":"CC BY-SA 4.0"},"spb-o72f0a64860b2":{"text":"Мемориальный музей семьи актёров Самойловых — музей-квартира в Санкт-Петербурге, филиал Санкт-Петербургского музея театрального и музыкального искусства. Музей, посвящённый жизни и творчеству актёрской династии Самойловых, занимает второй этаж дома № 8 по Стремянной улице, где в 1869—1887 годах жил актёр Александринского театра Василий Васильевич Самойлов.","title":"Мемориальный музей семьи актёров Самойловых","revision":148320216,"qid":"Q110259697","license":"CC BY-SA 4.0"},"spb-o046b72e53ec5":{"text":"Люба́шинский сад — сад, расположенный в Калининском районе Санкт-Петербурга между проспектом Металлистов, Замшиной улицей и Полюстровским проспектом. Часть исторического района Полюстрово. Сад получил имя по прежнему названию части проспекта Металлистов Любашинскому проспекту. В зелёной зоне установлен поклонный крест в память о Покровской церкви на…","title":"Любашинский сад","revision":151526629,"qid":"Q4271396","license":"CC BY-SA 4.0"},"spb-oc9c83478bcc4":{"text":"Особня́к Кшеси́нской (улица Куйбышева, д. № 2—4 / Кронверкский проспект, д. № 1) — памятник архитектуры в стиле модерн в Санкт-Петербурге.","title":"Особняк Кшесинской","revision":155318980,"qid":"Q3146313","license":"CC BY-SA 4.0"},"spb-o14f2affd41a3":{"text":"Никольский сад — сад в Санкт-Петербурге, разбитый в XVIII веке между набережной Крюкова канала, набережной канала Грибоедова, проспектом Римского-Корсакова и Никольским переулком, на Никольской площади. Сейчас это прямоугольный сад площадью 0,725 га.","title":"Никольский сад","revision":156071901,"qid":"Q13668621","license":"CC BY-SA 4.0"},"spb-oee1761ad4cd9":{"text":"«Балти́йский дом» — советский и российский государственный театр в городе Санкт-Петербурге, получивший статус «театра-фестиваля», на базе которого ежегодно проводятся международные форумы, мастер-классы, сценические фестивали. «Балтийский дом» — международный проект, планомерно работающий над укреплением культурных связей между Россией и странами…","title":"Балтийский дом","revision":155903223,"qid":"Q4076929","license":"CC BY-SA 4.0"},"spb-o423e36b689f7":{"text":"Санкт-Петербургский государственный академический театр балета имени Леонида Якобсона (Балет Якобсона) — первый в СССР балетный театр, учреждённый отдельно от оперной труппы. Основан в 1966 году танцовщиком и балетмейстером Петром Гусевым как «Камерный балет», позже «Хореографические миниатюры». С 1969 по октябрь 1975 года коллектив возглавлял Леонид…","title":"Театр балета имени Леонида Якобсона","revision":146198947,"qid":"Q27962300","license":"CC BY-SA 4.0"},"spb-o7d93f0401a6d":{"text":"Музей Петербургского метрополитена (позже — Интерактивный центр истории метрополитена (ИЦИМ)) — ведомственный музей в Санкт-Петербурге, посвящённый истории Петербургского метрополитена. Был открыт 14 ноября 2005 года к 50-летию открытия метрополитена в Петербурге. Раньше музей существовал на площадке депо «Автово», но юбилей подтолкнул к тому, чтобы…","title":"Музей Петербургского метрополитена","revision":152976967,"qid":"Q4306171","license":"CC BY-SA 4.0"},"spb-o83b83b07a622":{"text":"«Театра́льная» — «станция-призрак» на Лахтинско-Правобережной линии Петербургского метрополитена, расположенная между действующими станциями «Спасская» и «Горный институт». В связи с отсутствием у станции выхода на поверхность, появление одного из которых планируется не ранее 2030 года, поезда проезжают её без остановки, аналогично станции «Обводный…","title":"Театральная (станция метро, Санкт-Петербург)","revision":156239328,"qid":"Q4453513","license":"CC BY-SA 4.0"},"spb-ob15ba8cf2fe0":{"text":"Алекса́ндровский дворе́ц (устар. Новый Царскосельский дворец) — один из императорских дворцов Царского Села (ныне Пушкин, Санкт-Петербург). Построен в стиле палладианского классицизма в 1792—1796 годах, по распоряжению императрицы Екатерины II в подарок к бракосочетанию её внука, великого князя Александра Павловича. Проект дворца составил Джакомо Кваренги,…","title":"Александровский дворец","revision":154182966,"qid":"Q1519034","license":"CC BY-SA 4.0"},"spb-o3c71bd7d4f74":{"text":"Navicula Artis — галерея современного искусства, созданная в Санкт-Петербурге в 1992 году. Действует в составе Арт-центра «Пушкинская, 10».","title":"Navicula Artis","revision":150868734,"qid":"Q4132351","license":"CC BY-SA 4.0"},"spb-ob3ef0471f2b2":{"text":"Санкт-Петербургский Интерьерный театр — драматический театр в Санкт-Петербурге. Интерьерный театр, создателем и бессменным руководителем которого является режиссёр Николай Беляк, всегда представлял интересы петербургской культуры, раскрывал её самобытность и уникальность. За прошедшие двадцать семь лет с момента своего создания он реализовал себя как…","title":"Интерьерный театр","revision":147213424,"qid":"Q4407763","license":"CC BY-SA 4.0"},"spb-o04b33c8f041c":{"text":"Площадь Ста́рого Теа́тра — площадь на Каменном острове в Петроградском районе Санкт-Петербурга. Находится на пересечении набережной реки Крестовки, Полевой аллеи, Театральной аллеи и набережной реки Средней Невки.","title":"Площадь Старого Театра","revision":146498473,"qid":"Q4365789","license":"CC BY-SA 4.0"},"spb-o39e90898fe80":{"text":"Музей Людвига в Русском музее (Санкт-Петербург) — государственный музей современного искусства в Санкт-Петербурге. Располагается в Мраморном дворце — филиале Русского музея.","title":"Музей Людвига в Русском музее","revision":153684464,"qid":"Q2467421","license":"CC BY-SA 4.0"},"spb-o7bd234b9ce06":{"text":"Кра́сное Село́ (до 1765 — Красное) — город в России, внутригородское муниципальное образование в составе Красносельского района города федерального значения Санкт-Петербурга. Поселение до 1811 года официально именовалось «дворцовое село Красное» и было Удельным имением. Населённый пункт расположен в южной части района на холмах Ижорской возвышенности, у…","title":"Красное Село","revision":153319209,"qid":"Q155587","license":"CC BY-SA 4.0"},"spb-o6274939ddc91":{"text":"«Литера́торские мостки́» — участок на Волковском кладбище Санкт-Петербурга, музей-некрополь, где захоронены многие русские и советские писатели, музыканты, актёры, архитекторы, учёные и общественные деятели.","title":"Литераторские мостки","revision":154272019,"qid":"Q4263743","license":"CC BY-SA 4.0"},"spb-o72e16812ae13":{"text":"Памятник поребрику и бордюру — оригинальная достопримечательность в Санкт-Петербурге. Расположен в Парке Победы, Московский район. Адрес: Бассейная ул., у д. 12. Высота памятника около 1 м, он образован гранитными столбиками двух контрастных цветов: серого, как обычный дождливый день Петербурга, и красного, по названию главной площади Москвы. На каждом из…","title":"Памятник поребрику и бордюру","revision":156162490,"qid":"Q141250098","license":"CC BY-SA 4.0"},"spb-o7bc195697e17":{"text":"Дом Салтыкова (Дом Гротена) — просторный особняк в Санкт-Петербурге в створе Дворцовой набережной (№ 4) и Миллионной улицы (№ 3). После окончания строительства в 1788 г. подарен Екатериной II царедворцу Николаю Ивановичу Салтыкову. Впоследствии неоднократно перестраивался, так что в нынешний облик здания свою лепту внесли архитекторы Кваренги, Карл Росси,…","title":"Дом Салтыкова","revision":155451385,"qid":"Q3360856","license":"CC BY-SA 4.0"},"spb-o50de7c431ced":{"text":"Овся́нниковский сад (сад Черныше́вского) — сад в Санкт-Петербурге. Расположен между проспектом Бакунина, 3-й Советской, Мытнинской и Старорусской улицами. Является объектом культурного наследия России регионального значения.","title":"Овсянниковский сад","revision":153452304,"qid":"Q16682387","license":"CC BY-SA 4.0"},"spb-o7774d4ecec20":{"text":"Музе́й «Росси́я в Вели́кой войне́» — военно-исторический музей в Пушкине под Петербургом, посвящённый участию Российской империи в Первой мировой войне. Входит в состав Государственного музея-заповедника «Царское село». Музейная экспозиция, подготовленная в 1917 году, не сохранилась. Музей «Россия в Великой войне» открыт в 2014 году, к 100-летию Первой…","title":"Музей Первой мировой войны","revision":147198917,"qid":"Q18405202","license":"CC BY-SA 4.0"},"spb-o6e99e8f83fc2":{"text":"Дом Никола́евых («Дом с русалками», Малый Гостиный двор) — памятник архитектуры. Расположен в Центральном районе Санкт-Петербурга, современный адрес дома — Садовая улица, 25 (23/6). Здание было построено в конце XVIII века неизвестным архитектором, перестраивалось Ливеном в 1842 году и П. Н. Волковым в 1879—1880 годах. Изначально на месте широких оконных…","title":"Дом Николаевых","revision":148773952,"qid":"Q129651559","license":"CC BY-SA 4.0"},"spb-oc79be1f8316a":{"text":"Некрасовский сад — сад в Санкт-Петербурге на углу Греческого проспекта и улицы Некрасова. Также известен под названиями Греческий сад и Прудки.","title":"Некрасовский сад","revision":151246319,"qid":"Q4382449","license":"CC BY-SA 4.0"},"spb-ob78e38902d7d":{"text":"Дворец Нарышкиных-Шуваловых — памятник архитектуры XIX века в Санкт-Петербурге. Находится на углу Набережной реки Фонтанки, дом 21 и Итальянской улицы, дом 39. Здание типично для эпохи архитектурной эклектики (сочетание элементов позднего классицизма и неоренессанса).","title":"Дворец Нарышкиных-Шуваловых","revision":155442245,"qid":"Q4155887","license":"CC BY-SA 4.0"},"spb-oa977e5280590":{"text":"Дом голландской реформатской церкви или Голландская церковь — бывший храм голландской реформатской церкви, памятник архитектуры позднего русского классицизма, построенный в 1834—1839 годах по проекту Павла Жако. Расположен в Санкт-Петербурге по трём адресам: Невский проспект, 20, Набережная реки Мойки, 44 и Большая Конюшенная улица, 31.","title":"Дом голландской реформатской церкви","revision":155300366,"qid":"Q1978478","license":"CC BY-SA 4.0"},"spb-o8adf7a9c03aa":{"text":"Дача Черно́ва, или Сосно́вка, — памятник периода архитектурной эклектики в Невском районе Санкт-Петербурга на правом берегу реки Невы, выше Володарского моста, напротив когда-то стоявшего Речного вокзала. Адрес: Октябрьская набережная, дом № 72. Включает в себя особняк площадью 2000 м2, 22,9 га верхнего парка с сохранившейся гидротехнической системой…","title":"Дача Чернова","revision":156102790,"qid":"Q4155408","license":"CC BY-SA 4.0"},"spb-o537a7bd0758c":{"text":"АО «Ижорский трубный завод» (ИТЗ) — российское трубосварочное предприятие в Колпине, г. Санкт-Петербург. Продукцией ИТЗ являются одношовные прямошовные электросварные трубы с наружным и внутренним покрытием ( диаметр 610-1420 мм; максимальная длина трубы — 18,3 метра), объём производства до 600 тыс. тонн в год.","title":"Ижорский трубный завод","revision":150465739,"qid":"Q4198225","license":"CC BY-SA 4.0"},"spb-oe6846cff1d71":{"text":"Инженерный дом (Инженерный деловой дом) — памятник архитектуры. Расположен в Санкт-Петербурге, современный адрес дома — Петропавловская крепость, 2. Одноэтажное розовое здание с высокой кровлей и с внутренним двором, неправильный четырёхугольник в плане. Ранее называлось Цейхгаузом или Инженерным деловым двором с цейхгаузами. У дома было два корпуса:…","title":"Инженерный дом","revision":137584595,"qid":"Q122924591","license":"CC BY-SA 4.0"},"spb-ocff25dcae523":{"text":"Малоо́хтинский парк — парк в Красногвардейском районе Санкт-Петербурга.","title":"Малоохтинский парк","revision":146242484,"qid":"Q4278389","license":"CC BY-SA 4.0"},"spb-o0930cccb1151":{"text":"«Кра́сный вы́боржец» (АО «Завод „Красный выборжец“») — советское и российское предприятие по обработке цветных металлов, выпускающее более 12 тысяч наименований плоского и круглого проката, располагающееся в Санкт-Петербурге (Свердловская набережная, дом 12). Основано в 1857 году Ф. Ф. Гошем. Нынешнее название носит с 1922 года.","title":"Красный выборжец","revision":153450137,"qid":"Q4239673","license":"CC BY-SA 4.0"},"spb-oce762d6c1a82":{"text":"Сад дворца Юсуповых — небольшой городской парк в Санкт-Петербурге, входит в комплекс дворца Юсуповых на Мойке. Адрес: улица Декабристов, д. 21. «Самый райский уголок» усадьбы. Вход в сад свободный. Обустроен в пейзажном стиле. Рельеф сада ровный, исключение — сохранившаяся в саду насыпная горка в северо-западной части сада, сохранился ступенчатый спуск.…","title":"Сад дворца Юсуповых","revision":156070041,"qid":"Q142082118","license":"CC BY-SA 4.0"},"spb-o1af49970ad22":{"text":"Храм Спаса Преображения Господня лейб-гвардии Гренадерского полка — православный храм на Аптекарском острове в Санкт-Петербурге. Относится к Петроградскому благочинию Санкт-Петербургской епархии Русской православной церкви.","title":"Храм Преображения Господня на Аптекарском острове","revision":155909128,"qid":"Q4500883","license":"CC BY-SA 4.0"},"spb-o1e6dbabe0c84":{"text":"Охтинский пороховой завод — старейшее предприятие Санкт-Петербурга по производству порохов, взрывчатых веществ, научная и экспериментальная база в области взрывчатых веществ и ракетостроения. Ансамбль Охтинского порохового завода сочетает в себе черты разных периодов. Большой район носит название «Пороховые» по расположенным здесь постройкам Охтинского…","title":"Охтинский пороховой завод","revision":153439349,"qid":"Q4340575","license":"CC BY-SA 4.0"},"spb-o499bf4a3bc91":{"text":"Дом по адресу Невский проспект, 68/ наб. реки Фонтанки, 40, также известный как Дом Лопатина и Литературный дом, — историческое здание, находившееся в центре Санкт-Петербурга, один из домов на Невском проспекте, частично разрушенных во время блокады Ленинграда. Центральная часть здания, выходящего на Невский, была перестроена после войны. Первый конкурс на…","title":"Литературный дом","revision":152223377,"qid":"Q4263832","license":"CC BY-SA 4.0"},"spb-od0f754b42b12":{"text":"Дача Громова — старинная усадьба в Лопухинском саду на Аптекарском острове Санкт-Петербурга.","title":"Дача Громова","revision":147803301,"qid":"Q134250217","license":"CC BY-SA 4.0"},"spb-ocb5068bde30d":{"text":"Дача Салтыко́вой (дача Салтыко́вых) — здание в Приморском районе Санкт-Петербурга (ул. Академика Крылова, 4), вблизи станции метро «Чёрная речка». Памятник архитектуры, один из немногих сохранившихся в Санкт-Петербурге образцов загородной постройки середины XIX века. Здание особняка и его служебные корпуса (по адресу ул. Савушкина, д. 4, 6, 8 и 10) —…","title":"Дача Салтыковой","revision":152215524,"qid":"Q4155405","license":"CC BY-SA 4.0"},"spb-od4293eddfc0f":{"text":"Дача Салтыко́вой (дача Салтыко́вых) — здание в Приморском районе Санкт-Петербурга (ул. Академика Крылова, 4), вблизи станции метро «Чёрная речка». Памятник архитектуры, один из немногих сохранившихся в Санкт-Петербурге образцов загородной постройки середины XIX века. Здание особняка и его служебные корпуса (по адресу ул. Савушкина, д. 4, 6, 8 и 10) —…","title":"Дача Салтыковой","revision":152215524,"qid":"Q4155405","license":"CC BY-SA 4.0"},"spb-o74cb188cd2e8":{"text":"Колоннада Аполлона (Храм Аполлона) — архитектурное сооружение в Павловском парке Санкт-Петербурга на территории одноимённого государственного музея-заповедника. Построена Чарльзом Камероном по проекту 1780 года на берегу реки Славянки. Колоннада посвящена древнегреческому и древнеримскому бога солнечного света Аполлону.","title":"Колоннада Аполлона","revision":154235902,"qid":"Q118121952","license":"CC BY-SA 4.0"},"spb-o26a4e4d3ed72":{"text":"Дежу́рные коню́шни — историческое здание в Пушкине. Построено в 1822—1823 гг. Объект культурного наследия федерального значения. Расположено на Садовой улице, дом 8. В настоящее время занято постоянной выставкой «Придворный экипаж в Царском Селе».","title":"Дежурные конюшни","revision":152219338,"qid":"Q55344861","license":"CC BY-SA 4.0"},"spb-o1e3e65ffe779":{"text":"Левашо́вская пу́стошь (также Левашовское мемориа́льное кла́дбище) — урочище в пригороде Санкт-Петербурга вблизи посёлка Левашово, служившее местом захоронения жертв советских политических репрессий с 1937 по 1955 год. По разным подсчётам в нём находятся останки от 19 450 до 46 771 человека. За прошедшие со времени захоронений годы пустошь превратилась в…","title":"Левашовская пустошь","revision":154133670,"qid":"Q2429621","license":"CC BY-SA 4.0"},"spb-o3e0cbe3de848":{"text":"На́бережная Лейтена́нта Шми́дта (в 1887—1923 — Никола́евская набережная) — правая набережная Большой Невы в Санкт-Петербурге. Пролегает от Благовещенского моста до 22—23 линий В. О. Расположена на Васильевском острове.","title":"Набережная Лейтенанта Шмидта","revision":156311514,"qid":"Q4311099","license":"CC BY-SA 4.0"},"ekb-od7a38cae759e":{"text":"Свердло́вская госуда́рственная филармо́ния (ГАУК СО «Свердловская ордена Трудового Красного Знамени государственная академическая филармония») — государственное (областное) учреждение культуры в Екатеринбурге. С 1998 года получила статус академической.","title":"Свердловская филармония","revision":155681418,"qid":"Q4410142","license":"CC BY-SA 4.0"},"kzn-oace68465ea77":{"text":"Татарский государственный академический театр имени Галиасгара Камала (ТГАТ, тат. Галиәсгәр Камал исемендәге Татар дәүләт академия театры) — театр в Казани, на улице Татарстан и одноимённой площади.","title":"Татарский театр имени Галиасгара Камала","revision":156199602,"qid":"Q4452511","license":"CC BY-SA 4.0"},"msk-o7569fd86e3cf":{"text":"Госуда́рственный биологи́ческий музе́й и́мени К. А. Тимиря́зева в Москве — естественнонаучный музей, основанный 24 апреля 1922 года и расположенный в зданиях бывшего Щукинского музея по адресу Малая Грузинская улица, дом 15.","title":"Биологический музей имени К. А. Тимирязева","revision":156028550,"qid":"Q4146788","license":"CC BY-SA 4.0"},"msk-o0f6feb4f4008":{"text":"Госуда́рственный музе́й искусства народов Восто́ка (Музей восточных культур, Музей Востока) — музей, посвящённый искусству народов Дальнего и Ближнего Востока, Средней Азии, Кавказа, Закавказья, Бурятии и Чукотки. Музей искусств Востока основан в 1918 году в рамках национальной политики Советской России, направленной на развитие культур автономных…","title":"Музей Востока","revision":153810362,"qid":"Q1056108","license":"CC BY-SA 4.0"},"msk-o711f017f2112":{"text":"Московский областной государственный театр кукол (МОГТК) — один из старейших странствующих театров кукол в России. Он был организован в 1933 году при Московском областном Доме художественного воспитания детей известным режиссёром и драматургом Виктором Александровичем Швембергером, соратником выдающихся деятелей театра кукол России — Сергея Образцова,…","title":"Московский областной театр кукол","revision":155658852,"qid":"Q4304227","license":"CC BY-SA 4.0"},"msk-oed32a8de80b3":{"text":"Московский академический театр сатиры — драматический театр в Москве. Расположен возле станции метро «Маяковская» на Триумфальной площади в Тверском районе Центрального административного округа. Открылся 1 октября 1924 года в подвальном помещении дома № 10 в Большом Гнездниковском переулке.","title":"Театр сатиры (Москва)","revision":154414760,"qid":"Q4304032","license":"CC BY-SA 4.0"},"msk-o3b40e95b7dda":{"text":"Кре́мль в Изма́йлове — культурно-развлекательный комплекс, построенный в 1998—2007 годах поблизости от исторической царской усадьбы Измайлово. Представляет собой деревянные постройки, стилизованные под русское зодчество XVI—XVII веков (неоисторизм). По состоянию на 2018 год Кремль в Измайлове состоит из девяти музеев и выставочных площадок: музея русской…","title":"Кремль в Измайлове","revision":155207930,"qid":"Q25589","license":"CC BY-SA 4.0"},"msk-o2e3e9233a988":{"text":"Московская государственная академическая филармония (сокр. МГАФ) — одна из крупнейших концертных организаций мира, проводящая более 3000 концертов в год на концертных площадках Москвы, а также в регионах России и за рубежом.","title":"Московская государственная академическая филармония","revision":155681431,"qid":"Q4303887","license":"CC BY-SA 4.0"},"msk-o2b5c45f6296b":{"text":"Музе́й Михаи́ла Булга́кова — государственный музей в Москве, посвящённый жизни и деятельности писателя Михаила Булгакова. Открытие состоялось в 2007 году в пространстве легендарной коммунальной квартиры № 50 в доме 10 на Большой Садовой улице, в одной из комнат которой Булгаков проживал с 1921 по 1924 год. Эта квартира стала прообразом «нехорошей…","title":"Музей Михаила Булгакова","revision":150516137,"qid":"Q4146884","license":"CC BY-SA 4.0"},"nn-oe2c08462f08d":{"text":"Нижегородский государственный академический театр оперы и балета имени А. С. Пушкина (также — Оперный театр) — нижегородский театр, основанный в 1935 году как Горьковский театр оперы и балета. Расположен в Советском районе Нижнего Новгорода. Количество мест в зрительном зале — 1152.","title":"Нижегородский театр оперы и балета имени А. С. Пушкина","revision":153686162,"qid":"Q172218","license":"CC BY-SA 4.0"},"nn-odbcf0f5eda84":{"text":"Нижегоро́дская госуда́рственная консервато́рия им. М. И. Гли́нки — российская консерватория, расположенная в Нижнем Новгороде. В настоящее время представляет собой один из центров музыкальной культуры России и крупнейший центр музыкальной культуры Приволжского федерального округа.","title":"Нижегородская государственная консерватория имени М. И. Глинки","revision":144827817,"qid":"Q4318618","license":"CC BY-SA 4.0"},"nn-o87b68519dd8b":{"text":"Государственный ордена Знак Почёта музей А. М. Горького — учреждение культуры Нижнего Новгорода. Представляет собой объединение трёх музеев (филиалов) : Литературный музей, ул. Минина, 26. Музей-квартира А. М. Горького, ул. Семашко, 19. Музей детства А. М. Горького «Домик Каширина», Почтовый съезд, 21. Администрация находится по адресу Нижний Новгород, ул.…","title":"Государственный музей А. М. Горького","revision":147821497,"qid":"Q71209135","license":"CC BY-SA 4.0"},"ru-02e9c019ab4d-o5e7eee843625":{"text":"Белгоро́дский госуда́рственный академи́ческий теа́тр и́мени М. С. Щепкина — драматический, академический театр в Белгороде. Основан в 1936 году. Здание театра является объектом культурного наследия народов России регионального значения и охраняется государством.","title":"Белгородский академический драматический театр имени М. С. Щепкина","revision":155790382,"qid":"Q853170","license":"CC BY-SA 4.0"},"ru-0839d751b940-oc336c065098e":{"text":"Национальный музей Республики Алтай имени А. В. Анохина (алт. А. В. Анохинниҥ адыла адалган эл музей) — одно из первых национальных научных и культурно-просветительских учреждений Республики Алтай. Андрей Викторович Анохин, именем которого называется музей — один из организаторов музея и первый его заведующий, российский и советский учёный-этнограф,…","title":"Национальный музей имени А. В. Анохина","revision":150966779,"qid":"Q13107545","license":"CC BY-SA 4.0"},"ru-0ca8280c89cb-o2b9f5cbade61":{"text":"Ессентукский историко-краеведческий музей им. В. П. Шпаковского (бывш. Ессентукский народный музей) — государственный музей историко-художественной направленности. Располагается в центральной части города Ессентуки в старинном особняке, принадлежавшем священнику Д. Я. Карагачёву и являющимся памятником архитектуры регионального значения.","title":"Ессентукский историко-краеведческий музей имени В. П. Шпаковского","revision":155538202,"qid":"Q21663789","license":"CC BY-SA 4.0"},"ru-0f9fb6878d03-oc18d6effe28c":{"text":"Камышинский историко-краеведческий музей — музей в городе Камышин Волгоградской области России.","title":"Камышинский историко-краеведческий музей","revision":156085405,"qid":"Q53582048","license":"CC BY-SA 4.0"},"ru-140e31da27bf-ob421a9862f14":{"text":"«Омский государственный музыкальный театр» — один из ведущих театров города Омска, в репертуаре которого музыкальные произведения разных жанров, от классической оперы до новаторского балета.","title":"Омский государственный музыкальный театр","revision":155911124,"qid":"Q30894094","license":"CC BY-SA 4.0"},"ru-140e31da27bf-o3fb9b2affc1b":{"text":"Омский государственный театр куклы, актёра, маски «Арлекин» — один из старейших детских театров России, ведущий свою историю с апреля 1936 года. В репертуаре театра многочисленные постановки для зрителей разного возраста, начиная с двух лет. Спектакли театра отмечены различными призами на российских и международных фестивалях, в том числе престижной…","title":"Арлекин (театр, Омск)","revision":155717003,"qid":"Q4334720","license":"CC BY-SA 4.0"},"ru-140e31da27bf-o4823fc633f79":{"text":"О́мский госуда́рственный драмати́ческий теа́тр «Галёрка» — один из театров Омска, создан в 1990 году. Его создателем и бессменным художественным руководителем является Владимир Фёдорович Витько — заслуженный деятель искусств России, заслуженный артист России. Театр был основан при строительном кооперативе и первоначально арендовал помещения в омском Доме…","title":"Галёрка (театр)","revision":148396520,"qid":"Q4334717","license":"CC BY-SA 4.0"},"ru-1ccfdc3cbe0f-o51d67710c749":{"text":"Мордо́вский республика́нский объединённый краеве́дческий музе́й и́мени И. Д. Воро́нина — краеведческий музей в Саранске, одно из старейших учреждений культуры Республики Мордовия.","title":"Мордовский республиканский объединённый краеведческий музей имени И. Д. Воронина","revision":151305072,"qid":"Q4302553","license":"CC BY-SA 4.0"},"ru-40c6863e2a5f-o6b6094f9bfdf":{"text":"Ивановский государственный историко-краеведческий музей имени Д. Г. Бурылина — музей в городе Иваново, один из старейших музеев региона. В коллекциях музея находятся книги, оружие, произведения живописи и скульптуры, монеты, ордена и медали, предметы культуры и быта, археологические находки и многое другое; экспозиции охватывают период с античных времён до…","title":"Ивановский государственный историко-краеведческий музей имени Д. Г. Бурылина","revision":154978241,"qid":"Q24578354","license":"CC BY-SA 4.0"},"ru-42a02e11a337-o2a821c79cf29":{"text":"Русский академический театр имени М. Ю. Лермонтова основан в 1939 году.","title":"Русский академический театр имени М. Ю. Лермонтова","revision":155658832,"qid":"Q18399418","license":"CC BY-SA 4.0"},"ru-44388ad006aa-o33077182913b":{"text":"Сахали́нский областно́й краеве́дческий музе́й — центральный музей Сахалинской области в Южно-Сахалинске. Занимает японское здание 1935—1937 годов постройки — единственный в своём роде пример национального стиля тэйкан на территории как Сахалина, так и всей России. Считает себя преемником первого сахалинского музея, основанного в 1896 году.","title":"Сахалинский областной краеведческий музей","revision":155907342,"qid":"Q4409417","license":"CC BY-SA 4.0"},"ru-4bae8c68e107-o1b5bd5860a5a":{"text":"Звенигородский городок — кремль города Звенигорода Московского, бывшая резиденция звенигородских удельных князей. Звенигородцы издавна называют это место городком.","title":"Звенигородский городок","revision":153689863,"qid":"Q4189482","license":"CC BY-SA 4.0"},"ru-6b1bab7dee45-ofa8a2f2f221f":{"text":"Кра́сная пло́щадь (бывшая Семёновская площадь) — площадь в историческом центре города Ярославля. Образована при перестройке города по регулярному плану 1778 года.","title":"Красная площадь (Ярославль)","revision":149286191,"qid":"Q4238141","license":"CC BY-SA 4.0"},"ru-6b1bab7dee45-o6483bf751c36":{"text":"Яросла́вский госуда́рственный исто́рико-архитекту́рный и худо́жественный музе́й-запове́дник — одно из крупнейших учреждений культуры и объектов туризма Ярославля. С 1959 года музей-заповедник располагается в самом центре города, на территории упразднённого в 1787 году Спасо-Преображенского мужского монастыря. Музею принадлежит богатая коллекция икон и…","title":"Ярославский музей-заповедник","revision":155273433,"qid":"Q4538889","license":"CC BY-SA 4.0"},"ru-727cdf1e1b70-o5c8c20673fb4":{"text":"Дагестанский государственный театр оперы и балета — государственный театр Дагестана.","title":"Дагестанский театр оперы и балета","revision":148356595,"qid":"Q4153933","license":"CC BY-SA 4.0"},"ru-7339e8342cb4-oe240c959a998":{"text":"Уфимский государственный татарский театр «Нур» (баш. Өфө «Нур» татар дәүләт театры, тат. Уфа дәүләт «Нур» татар театры) — драматический театр в городе Уфе. Располагается по адресу: ул. 50 лет СССР, д.36.","title":"Нур (театр)","revision":152733694,"qid":"Q4479107","license":"CC BY-SA 4.0"},"ru-7339e8342cb4-o520e18afcd17":{"text":"«Башкортоста́н» (ранее — Дворец культуры «Нефтяник») — государственный концертный зал на улице Ленина в Новой Уфе Кировского района города Уфы, одно из самых крупных сооружений Башкортостана — площадь всех его помещений составляет более 15000 м2. Напротив расположено здание КГБ Башкирской АССР, с которым концертный зал создают единый ансамбль.","title":"Башкортостан (концертный зал)","revision":146946200,"qid":"Q114210067","license":"CC BY-SA 4.0"},"ru-7339e8342cb4-oc6f8e43b8397":{"text":"Башкирская государственная филармония им. Х. Ахметова (баш. Х.Әхмәтов исемендәге Башҡорт дәүләт филармонияһы) — филармония в Уфе, Республика Башкортостан. Названа в честь композитора Хусаина Файзулловича Ахметова.","title":"Башкирская государственная филармония имени Хусаина Ахметова","revision":152216299,"qid":"Q4080153","license":"CC BY-SA 4.0"},"ru-7b6de6a586d0-od9368459bba7":{"text":"Государственный объединённый музей-заповедник истории Дальнего Востока имени В. К. Арсеньева (Музей-заповедник истории Дальнего Востока) — крупнейший федеральный музей-заповедник на Дальнем Востоке, первый краеведческий музей Приморья. В музее представлена история и природа Приморского края, собраны коллекции материалов о деятельности исследователей края —…","title":"Музей истории Дальнего Востока имени В. К. Арсеньева","revision":154494849,"qid":"Q4378712","license":"CC BY-SA 4.0"},"ru-7b6de6a586d0-oec5fda1e0f04":{"text":"Приморская государственная картинная галерея — музей изобразительных искусств во Владивостоке.","title":"Приморская государственная картинная галерея","revision":146797381,"qid":"Q30889527","license":"CC BY-SA 4.0"},"ru-86e5bae4ef58-o12868f7dc54b":{"text":"Рязанский музыкальный театр — государственный театр в Рязани, основанный в 2004 году.","title":"Рязанский музыкальный театр","revision":152801179,"qid":"Q28758255","license":"CC BY-SA 4.0"},"ru-86e5bae4ef58-obff32f6b6d21":{"text":"Ряза́нский госуда́рственный областно́й худо́жественный музе́й имени И. П. Пожа́лостина — один из старейших художественных музеев России. Собрание музея насчитывает около 12 тысяч произведений отечественного и западноевропейского искусства конца XV—XX веков: живопись, графика, скульптура, декоративно-прикладное и народное искусство. Коллекция…","title":"Рязанский государственный областной художественный музей имени И. П. Пожалостина","revision":153595885,"qid":"Q16693441","license":"CC BY-SA 4.0"},"ru-86e5bae4ef58-o895539c313c2":{"text":"Ряза́нский кре́мль — древнейшая часть Рязани, историко-архитектурный музей-заповедник под открытым небом, место, откуда начинался город. При основании кремль назывался Переяславльским, пока в 1778 году Екатерина II не переименовала город в Рязань. Согласно Следованой псалтыри — был основан в 1095 году на высоком холме, при слиянии рек Трубежа и Лыбеди как…","title":"Рязанский кремль","revision":155590883,"qid":"Q4402653","license":"CC BY-SA 4.0"},"ru-86e5bae4ef58-o1cbef0f5e3cd":{"text":"Рязанский государственный областной театр кукол — театр кукол в Рязани.","title":"Рязанский областной театр кукол","revision":155519184,"qid":"Q4402648","license":"CC BY-SA 4.0"},"ru-8dea00e39aab-o82149c58aeca":{"text":"Новосиби́рский госуда́рственный краеве́дческий музе́й — один из ведущих музеев Новосибирска.","title":"Новосибирский государственный краеведческий музей","revision":149557811,"qid":"Q4325462","license":"CC BY-SA 4.0"},"ru-8dea00e39aab-oc9cda09b7b5a":{"text":"Новосиби́рская госуда́рственная консервато́рия имени М. И. Глинки — высшее музыкальное учебное заведение в Новосибирске. Основана в 1956 году распоряжением совмина РСФСР и указом министерства культуры РСФСР. Новосибирская консерватория стала первым музыкальным высшим учебным заведением в Сибири и до сих пор остаётся единственной консерваторией за Уралом.","title":"Новосибирская государственная консерватория имени М. И. Глинки","revision":153641453,"qid":"Q4325442","license":"CC BY-SA 4.0"},"ru-8df8c56fa46e-o36304334fbe9":{"text":"Национальный музей Республики Тыва или Национальный музей им. Алдан-Маадыр — первый музей в истории Республики Тыва, официально основан 13 мая 1929 года. Первым директором музея является Владимир Ермолаев, который сыграл большую роль в сохранении историко-культурного наследия Тувы, будучи первым фотолетописцем в республике. Национальный музей им.…","title":"Национальный музей Республики Тыва","revision":152812909,"qid":"Q14623994","license":"CC BY-SA 4.0"},"ru-8eeed22272e7-o0b945c2ec2e4":{"text":"Ирку́тский академи́ческий драмати́ческий теа́тр имени Н. П. Охлопкова — театр драмы в городе Иркутске. Один из старейших драматических театров России, основан в 1850 году.","title":"Иркутский академический драматический театр имени Н. П. Охлопкова","revision":152940823,"qid":"Q4203301","license":"CC BY-SA 4.0"},"ru-8eeed22272e7-o490ae5017bc1":{"text":"Ирку́тский областно́й теа́тр ку́кол «Аистёнок» — театр в городе Иркутск, основанный в 1935 году как Восточно-Сибирский государственный театр кукол и марионеток.","title":"Аистёнок (театр)","revision":150507447,"qid":"Q16656158","license":"CC BY-SA 4.0"},"ru-9b0efbd022bb-oa03aa87c08a8":{"text":"Государственный музей-заповедник М. Ю. Лермонтова — государственное бюджетное учреждение культуры Ставропольского края, литературно-мемориальный музейный комплекс в Пятигорске, созданный на основе дома, где провёл последние месяцы жизни М. Ю. Лермонтов, и куда было доставлено его тело после дуэли. Первый музей поэта. Музей имеет статус исторического…","title":"Государственный музей-заповедник М. Ю. Лермонтова","revision":154999722,"qid":"Q85859324","license":"CC BY-SA 4.0"},"ru-9fdcc25fa3d0-o9581f7b9b0f1":{"text":"Буря́тский госуда́рственный академи́ческий теа́тр о́перы и бале́та имени народного артиста СССР Г. Цыдынжа́пова (бур. Г. Сэдэнжабовай нэрэмжэтэ Буряадай гγрэнэй дуури бγжэгэй эрдэмэй театр) — театр оперы и балета в городе Улан-Удэ. Основан в 1939 году путём реорганизации Бурятского драматического театра.","title":"Бурятский театр оперы и балета имени Г. Ц. Цыдынжапова","revision":152294094,"qid":"Q4100061","license":"CC BY-SA 4.0"},"ru-a309e4ce2f36-o24e479552e14":{"text":"Пермский театр оперы и балета (полное название — Пермский государственный ордена Трудового Красного Знамени академический театр оперы и балета им. П. И. Чайковского) — один из старейших музыкальных театров России, инициатор Дягилевского фестиваля и Конкурса артистов балета «Арабеск» имени Екатерины Максимовой. Один из основных творческих принципов театра —…","title":"Пермский театр оперы и балета имени П. И. Чайковского","revision":151927499,"qid":"Q115035","license":"CC BY-SA 4.0"},"ru-a52b73890cfe-o07354b7c8ff3":{"text":"Историко-этнографический и архитектурный музей-заповедник «Старая Сарепта» — крупный культурный, интересный, туристический, научно-исследовательский и методический центр Волгограда. Выставочный комплекс «Старой Сарепты» занимает площадь в 7,1 га, включает 27 строений, из которых 23 — федеральные памятники XVIII–XIX веков, постоянные исторические и…","title":"Старая Сарепта (музей-заповедник)","revision":154793606,"qid":"Q16656355","license":"CC BY-SA 4.0"},"ru-ac45dd9133c1-o543a34009705":{"text":"Вышневолоцкий краеведческий музей им. Г. Г. Монаховой — важный культурный центр не только Вышневолоцкого края, но и всей Тверской области. С 1977 года является филиалом Тверского государственного объединённого музея.","title":"Вышневолоцкий краеведческий музей","revision":150544738,"qid":"Q110259741","license":"CC BY-SA 4.0"},"ru-b0122c31eb1c-o6a250377a418":{"text":"Не́нецкий краеве́дческий музе́й — крупнейший музей Ненецкого автономного округа. Находится в центральной части Нарьян-Мара на улице Победы.","title":"Ненецкий краеведческий музей","revision":146554552,"qid":"Q16680304","license":"CC BY-SA 4.0"},"ru-b0122c31eb1c-od47c8e5496b1":{"text":"Историко-культурный и ландшафтный музей-заповедник «Пустозерск» расположен в Ненецком автономном округе. Находится в центральной части Нарьян-Мара в «Доме Шевелёвых» по адресу: улица Тыко Вылки, д. 4. Является филиалом государственного бюджетного учреждения культуры «Музейное объединение Ненецкого автономного округа»","title":"Пустозерск (музей-заповедник)","revision":146809114,"qid":"Q24936094","license":"CC BY-SA 4.0"},"ru-bb035cc31dc2-ob747991ddc81":{"text":"Самарский областной историко-краеведческий музей — один из старейших музеев Поволжья, расположенный в Самаре.","title":"Самарский областной историко-краеведческий музей имени П. В. Алабина","revision":153023156,"qid":"Q4406416","license":"CC BY-SA 4.0"},"ru-bebfd75da0da-o54de54a695d4":{"text":"Областное государственное бюджетное учреждение культуры «Ульяновский областной краеведческий музей имени И. А. Гончарова» — краеведческий музей в городе Ульяновске. Расположен на первом этаже Дома-памятника, в одном здании с Ульяновским областным художественным музеем, второй этаж.","title":"Ульяновский областной краеведческий музей","revision":154648830,"qid":"Q4475196","license":"CC BY-SA 4.0"},"ru-bf465fda7834-o13275b754589":{"text":"Сара́товский госуда́рственный худо́жественный музе́й и́мени А. Н. Ради́щева (сокр. СГХМ), Ради́щевский музе́й — музей в Саратове, один из наиболее значительных художественных музеев в России. Музей был открыт в 1885 году и был первым общедоступным художественным музеем в Российской империи. Основой экспозиции стало собрание художника-мариниста Алексея…","title":"Саратовский художественный музей имени А. Н. Радищева","revision":155095094,"qid":"Q1270949","license":"CC BY-SA 4.0"},"ru-bf465fda7834-o1b29ce9d2f50":{"text":"Сара́товский госуда́рственный академи́ческий драмати́ческий теа́тр и́мени И. А. Сло́нова — один из старейших театров Российской Федерации, основанный в 1803 году в городе Саратове Саратовской губернии Российской империи. С 1918 года по 21 декабря 2003 года носил имя Карла Маркса.","title":"Саратовский академический театр драмы имени И. А. Слонова","revision":152897372,"qid":"Q1255617","license":"CC BY-SA 4.0"},"ru-c1cfe4b9f7c2-oeab25b1ea713":{"text":"Ростовский-на-Дону академический молодёжный театр (РАМТ) (бывший Ростовский ТЮЗ им. Ленинского комсомола) — театр в городе Ростов-на-Дону.","title":"Ростовский молодёжный театр","revision":151433943,"qid":"Q4398504","license":"CC BY-SA 4.0"},"ru-cc73d6af6e2e-o7f3a0bd26546":{"text":"Нижнетагильский музей-заповедник «Горнозаводской Урал» — объединение музейных учреждений и культурных объектов города Нижнего Тагила, включающих в себя комплекс памятников наследия, истории и культуры. Музей располагается в историческом центре города, в Ленинском районе, на пересечении проспекта Ленина и улицы Островского, в здании бывшего Горсовета.…","title":"Горнозаводской Урал","revision":154246720,"qid":"Q19788472","license":"CC BY-SA 4.0"},"ru-ccc344878fd4-o62fdf5e636ae":{"text":"«Кижи» — государственный историко-архитектурный и этнографический музей-заповедник, расположенный в Республике Карелия Российской Федерации. Название музея дано по острову Кижи, где расположена основная часть экспозиции музея. Объекты музея также расположены в Петрозаводске и в ряде населённых пунктов Медвежьегорского района. Все храмы, находящиеся на…","title":"Кижи (музей-заповедник)","revision":147198476,"qid":"Q4220287","license":"CC BY-SA 4.0"},"ru-d2944a73daf4-ob018c10467a4":{"text":"Государственный академический театр оперы и балета Республики Коми (Коми Опера, коми Коми Республикаса опера да балет театр) — театр оперы и балета в городе Сыктывкаре. Расположен по адресу Коммунистическая улица, дом 32.","title":"Театр оперы и балета Республики Коми","revision":153521862,"qid":"Q60851777","license":"CC BY-SA 4.0"},"ru-d2944a73daf4-o51141b345115":{"text":"Государственный академический театр драмы им. В. Савина (коми Войтыръяслӧн Ёрталун ордена Виктор Савин нима канмуса академическӧй Драма театр) — Коми республиканский драматический театр. 22 ноября 1978 года постановлением Совета Министров Коми АССР Республиканскому драматическому театру было присвоено имя его основателя, Виктора Алексеевича Савина. 25…","title":"Драматический театр имени В. Савина","revision":151371500,"qid":"Q16639020","license":"CC BY-SA 4.0"},"ru-d414a2e89e1e-o35b7c43f6b29":{"text":"Смоле́нский госуда́рственный академи́ческий драмати́ческий теа́тр имени А. С. Грибоедова — театр в городе Смоленске, один из старейших действующих драматических театров России. Основан в 1780 году.","title":"Смоленский академический драматический театр имени А. С. Грибоедова","revision":152728660,"qid":"Q4424972","license":"CC BY-SA 4.0"},"ru-d790c72e479b-odd695728d22c":{"text":"Курский государственный цирк — культурный развлекательный центр в Курске.","title":"Курский государственный цирк","revision":145195746,"qid":"Q4248855","license":"CC BY-SA 4.0"},"ru-d790c72e479b-o52c89f13c66d":{"text":"Курский государственный драматический театр имени А. С. Пушкина — театр в Курске, один из старейших театров России, основан в 1792 году.","title":"Курский государственный драматический театр имени А. С. Пушкина","revision":153326307,"qid":"Q4248852","license":"CC BY-SA 4.0"},"ru-dd8caeabc685-o1c031a755099":{"text":"Чува́шский госуда́рственный академи́ческий драмати́ческий теа́тр и́мени К. В. Ивано́ва (чуваш. Чăваш патшалăх К. В. Иванов ячĕллĕ академи драма театрĕ) — старейший театр Чувашской Республики, один из первых национальных театров страны. Художественный руководитель — народный артист СССР Валерий Яковлев, директор театра — заслуженный работник культуры…","title":"Чувашский драматический театр имени К. В. Иванова","revision":155926573,"qid":"Q2396090","license":"CC BY-SA 4.0"},"ru-eacb5f151a2e-o0cff0b15d6b7":{"text":"Ли́пецкий госуда́рственный теа́тр ку́кол — театр в Липецке. Находится в Правобережном округе на улице Гагарина, 74. Основан в 1962 году. Артисты театра выступали на разных сценах, так как стационарной не было. Она появилась лишь в феврале 1998 года. Под Театр кукол отдали Дворец культуры Трубного завода на улице Гагарина, 74. Здание было построено в 1950…","title":"Липецкий театр кукол","revision":147806473,"qid":"Q7239558","license":"CC BY-SA 4.0"},"ru-f02dbf6d57ad-o16eccac1e7c6":{"text":"Михайловский краеведческий музей — муниципальный музей краеведческого профиля, посвящённый истории города Михайловка Волгоградской области и Михайловского района.","title":"Михайловский краеведческий музей (Волгоградская область)","revision":147199256,"qid":"Q110817255","license":"CC BY-SA 4.0"},"ru-ff3292b1a1d2-o73b99bf2235d":{"text":"Пензенская областная картинная галерея имени К. А. Савицкого — российский государственный художественный музей в Пензе, крупнейший и один из самых известных музеев Пензенской области. Основан в 1892 году.","title":"Пензенская областная картинная галерея имени К. А. Савицкого","revision":156064506,"qid":"Q4348467","license":"CC BY-SA 4.0"},"spb-ob7879e03b5e6":{"text":"Теа́тр «Буфф» имени И. Р. Штокбанта — театр Санкт-Петербурга, основу репертуара которого составляют музыкальные и драматические спектакли.","title":"Буфф (театр, Санкт-Петербург)","revision":155374217,"qid":"Q4407729","license":"CC BY-SA 4.0"},"spb-oc5f876506eb8":{"text":"Театр-студия Санкт-Петербургского государственного университета — коллектив художественной самодеятельности. Организован в Ленинградском государственном университете в 1944 году актрисой, режиссёром и педагогом Е. В. Карповой. На сцене Театра-студии начинали свой творческий путь Игорь Горбачёв, Нелли Подгорная, Сергей Юрский, Леонид Харитонов, Вадим…","title":"Театр-студия Санкт-Петербургского государственного университета","revision":148076225,"qid":"Q4453391","license":"CC BY-SA 4.0"},"spb-o0e1d292ad19b":{"text":"Реставрацио́нно-храни́тельский це́нтр Госуда́рственного Эрмита́жа «Ста́рая Дере́вня» (Фондохранилище Государственного Эрмитажа, РХЦ) — комплекс зданий Государственного Эрмитажа общей площадью 35 000 кв. м., включающий в себя фондохранилище, выставочно-лекционный, реставрационный, инженерный и административный корпуса.","title":"Старая Деревня (Эрмитаж)","revision":153331296,"qid":"Q4439665","license":"CC BY-SA 4.0"},"spb-o19364eb122df":{"text":"Санкт-Петербургская государственная консерватория имени Николая Андреевича Римского-Корсакова — высшее музыкальное учебное заведение в Санкт-Петербурге, первая по старшинству консерватория в России. Основана Высочайшим указом от 17 (29) октября 1861 года в качестве училища на базе Музыкальных классов Русского музыкального общества, открытых двумя годами…","title":"Санкт-Петербургская консерватория имени Н. А. Римского-Корсакова","revision":156100441,"qid":"Q178416","license":"CC BY-SA 4.0"},"spb-o9cbf75a869ec":{"text":"Филармония джазовой музыки (Санкт-Петербург) — единственная в России филармония, деятельность которой сосредоточена целиком на джазовой музыке. Основана Давидом Голощёкиным. Является одной из виднейших джазовых площадок страны. В залах филармонии выступали выдающиеся джазовые музыканты всего мира.","title":"Филармония джазовой музыки","revision":155916128,"qid":"Q4483741","license":"CC BY-SA 4.0"},"spb-od30aee97036c":{"text":"Музей «Царскосельская коллекция» — государственный художественный музей изобразительного искусства в городе Пушкин, Санкт-Петербург. Открыт в 1990 году в особняке вдовы статского советника Марии Стеткевич, построенном в 1909 году по проекту архитектора Густава фон Голи.","title":"Царскосельская коллекция","revision":143711688,"qid":"Q24932048","license":"CC BY-SA 4.0"},"spb-o35a3d1cfc6ae":{"text":"Солове́цкий ка́мень в Санкт-Петербурге — памятник жертвам политических репрессий в СССР и борцам за свободу. Он находится на Петроградской стороне в историческом центре города, на его старейшей площади — Троицкой. Этот сквер расположен рядом с местами, непосредственно связанными с политическими репрессиями в СССР — Домом политкаторжан, тюрьмой Трубецкого…","title":"Соловецкий камень (Санкт-Петербург)","revision":155825377,"qid":"Q4427943","license":"CC BY-SA 4.0"}};
